(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pausanias-5-e", [{"sp": "HDR", "t": "Ἑλλάδος Περιήγησις"}, {"sp": "HDR", "t": "Βιβλίον Θʹ — Βοιωτικά", "st": "9"}, {"sp": "N", "t": "Ἀθηναίοις δὲ ἡ Βοιωτία καὶ κατὰ ἄλλα τῆς Ἀττικῆς ἐστιν ὅμορος, πρὸς δὲ Ἐλευθερῶν οἱ Πλαταιεῖς. Βοιωτοὶ δὲ τὸ μὲν πᾶν ἔθνος ἀπὸ Βοιωτοῦ τὸ ὄνομα ἔσχηκεν, ὃν Ἰτώνου παῖδα καὶ νύμφης δὴ Μελανίππης, Ἴτωνον δὲ Ἀμφικτύονος εἶναι λέγουσι· καλοῦνται δὲ κατὰ πόλεις ἀπό τε ἀνδρῶν καὶ τὰ πλείω γυναικῶν. οἱ δὲ Πλαταιεῖς τὸ ἐξ ἀρχῆς ἐμοὶ δοκεῖν εἰσιν αὐτόχθονες· ὄνομα δέ σφισιν ἀπὸ Πλαταίας, ἣν θυγατέρα εἶναι ⟨Ἀσωποῦ⟩ τοῦ ποταμοῦ νομίζουσιν.", "st": "9.1"}, {"sp": "N", "t": "ὅτι μὲν δὴ καὶ οὗτοι τὸ ἀρχαῖον ἐβασιλεύοντο, δῆλά ἐστι· βασιλεῖαι γὰρ πανταχοῦ τῆς Ἑλλάδος καὶ οὐ δημοκρατίαι πάλαι καθεστήκεσαν. τῶν δὲ βασιλέων ἄλλον μὲν οὐδένα οἱ Πλαταιεῖς ἴσασι, μόνον δὲ Ἀσωπὸν καὶ ἔτι πρότερον Κιθαιρῶνα· καὶ τὸν μὲν ἀφ’ αὑτοῦ θέσθαι τῷ ὄρει τὸ ὄνομα, τὸν δὲ τῷ ποταμῷ λέγουσι. δοκῶ δὲ καὶ τὴν Πλάταιαν, ἀφ’ ἧς κέκληται [καὶ] ἡ πόλις, βασιλέως Ἀσωποῦ καὶ οὐ τοῦ ποταμοῦ παῖδα εἶναι.", "st": "9.1"}, {"sp": "N", "t": "Πλαταιεῦσι δὲ πρὸ μὲν τῆς μάχης, ἣν Ἀθηναῖοι Μαραθῶνι ἐμαχέσαντο, οὐδὲν ὑπῆρχεν ἐς δόξαν· μετασχόντες δὲ τοῦ Μαραθῶνι ἀγῶνος ὕστερον καταβεβηκότος ἤδη Ξέρξου καὶ ἐς τὰς ναῦς ἐτόλμησαν μετ’ Ἀθηναίων ἐσβῆναι, Μαρδόνιον δὲ τὸν Γωβρύου Ξέρξῃ στρατηγοῦντα ἠμύναντο ἐν τῇ σφετέρᾳ. δὶς δὲ σφᾶς κατέλαβε γενέσθαι τε ἀναστάτους καὶ αὖθις ἐς Βοιωτίαν καταχθῆναι.", "st": "9.1"}, {"sp": "N", "t": "ἐπὶ μὲν γὰρ τοῦ πολέμου τοῦ Πελοποννησίοις πρὸς Ἀθηναίους γενομένου Λακεδαιμόνιοι πολιορκίᾳ Πλάταιαν ἐξεῖλον· ἀνοικισθείσης δὲ ἐπὶ τῆς εἰρήνης, ἣν πρὸς βασιλέα τῶν Περσῶν γενέσθαι τοῖς Ἕλλησιν ἔπραξεν Ἀνταλκίδας ἀνὴρ Σπαρτιάτης, καὶ τῶν Πλαταιέων κατελθόντων ἐξ Ἀθηνῶν, τοὺς δὲ αὖθις ἔμελλεν ἐπιλήψεσθαι κακὸν δεύτερον. ἐκ μέν γε τοῦ ἐμφανοῦς πόλεμος πρὸς τοὺς Θηβαίους οὐκ ἦν συνεστηκώς, ἀλλὰ οἱ Πλαταιεῖς μένειν τὴν εἰρήνην σφίσιν ἔφασαν, ὅτι τὴν Καδμείαν Λακεδαιμονίοις κατασχοῦσιν οὔτε βουλεύματος οὔτε ἔργου μετεσχήκεσαν·", "st": "9.1"}, {"sp": "N", "t": "Θηβαῖοι δὲ ἀπέφαινον τήν τε εἰρήνην Λακεδαιμονίους εἶναι τοὺς πράξαντας καὶ ὕστερον παραβάντων ἐκείνων λελύσθαι καὶ ἅπασιν ἠξίουν τὰς σπονδάς. οὐκ ἀνύποπτα οὖν ἡγούμενοι οἱ Πλαταιεῖς τὰ ἐκ τῶν Θηβαίων διὰ φυλακῆς εἶχον ἰσχυρᾶς τὴν πόλιν· καὶ ἐς τοὺς ἀγρούς, ὁπόσοι ἀπωτέρω τοῦ ἄστεως ἦσαν, οὐδὲ ἐς τούτους ἀνὰ πᾶσαν ἤρχοντο τὴν ἡμέραν, ἀλλὰ— ἠπίσταντο γὰρ τοὺς Θηβαίους ⟨ὡς⟩ πανδημεὶ καὶ ἅμα ἐπὶ πλεῖστον εἰώθεσαν βουλεύεσθαι—παρεφύλασσον τὰς ἐκκλησίας αὐτῶν, καὶ ἐν τῷ τοσούτῳ καθ’ ἡσυχίαν ἐφεώρων τὰ ἑαυτῶν καὶ οἱ ἔσχατοι γεωργοῦντες.", "st": "9.1"}, {"sp": "N", "t": "Νεοκλῆς δὲ ὃς τότε βοιωταρχῶν ἔτυχεν ἐν Θήβαις—οὐ γὰρ αὐτὸν οἱ Πλαταιεῖς ἐλελήθεσαν ἐπὶ τῇ τέχνῃ— προεῖπε τῶν Θηβαίων ἕκαστόν τέ τινα ἰέναι πρὸς τὴν ἐκκλησίαν ὁμοῦ τοῖς ὅπλοις καὶ σφᾶς αὐτίκα οὐ τὴν εὐθεῖαν ἀπὸ τῶν Θηβῶν τὴν πεδιάδα, τὴν δὲ ἐπὶ Ὑσιῶν ἦγε πρὸς Ἐλευθερῶν τε καὶ τῆς Ἀττικῆς, ᾗ μηδὲ σκοπὸς ἐτέτακτο ὑπὸ τῶν Πλαταιέων· γενήσεσθαι δὲ περὶ τὰ τείχη περὶ μεσοῦσαν μάλιστα ἔμελλε τὴν ἡμέραν.", "st": "9.1"}, {"sp": "N", "t": "Πλαταιεῖς δὲ ἄγειν Θηβαίους ἐκκλησίαν νομίζοντες ἐς τοὺς ἀγροὺς ἀποκεκλειμένοι τῶν πυλῶν ἦσαν· πρὸς δὲ τοὺς ἐγκαταληφθέντας ἐποιήσαντο οἱ Θηβαῖοι σπονδάς, ἀπελθεῖν σφᾶς πρὸ ἡλίου δύντος ἄνδρας μὲν σὺν ἑνί, γυναῖκας δὲ δύο ἱμάτια ἑκάστην ἔχουσαν. συνέβη τε ἐναντία τοῖς Πλαταιεῦσιν ἐν τῷ τότε ἡ τύχη ἢ ὡς ὑπὸ Ἀρχιδάμου καὶ Λακεδαιμονίων τὸ πρότερον ἥλωσαν· Λακεδαιμόνιοι ⟨μέν⟩ γ’ αὐτοὺς ἐξεπολιόρκησαν ἀπείργοντες διπλῷ τείχει μὴ ἐξελθεῖν τοῦ ἄστεως, Θηβαῖοι δὲ ἐν τῷ τότε ἀφελόμενοι μὴ ἐσελθεῖν σφᾶς ἐς τὸ τεῖχος.", "st": "9.1"}, {"sp": "N", "t": "ἐγένετο δὲ ἡ ἅλωσις Πλαταίας ἡ δευτέρα μάχης μὲν τρίτῳ τῆς ἐν Λεύκτροις ἔτει πρότερον, Ἀστείου δὲ Ἀθήνῃσιν ἄρχοντος. καὶ ἡ μὲν πόλις ὑπὸ τῶν Θηβαίων καθῃρέθη πλὴν τὰ ἱερά, τοῖς δὲ Πλαταιεῦσιν ὁ τρόπος τῆς ἁλώσεως σωτηρίαν παρέσχεν ἐν ἴσῳ πᾶσιν· ἐκπεσόντας δὲ σφᾶς ἐδέξαντο αὖθις οἱ Ἀθηναῖοι. Φιλίππου δέ, ὡς ἐκράτησεν ἐν Χαιρωνείᾳ, φρουράν τε ἐσαγαγόντος ἐς Θήβας καὶ ἄλλα ἐπὶ καταλύσει τῶν Θηβαίων πράσσοντος, οὕτω καὶ οἱ Πλαταιεῖς ὑπ’ αὐτοῦ κατήχθησαν.", "st": "9.1"}, {"sp": "N", "t": "γῆς δὲ τῆς Πλαταιίδος ἐν τῷ Κιθαιρῶνι ὀλίγον τῆς εὐθείας ἐκτραπεῖσιν ἐς δεξιὰ Ὑσιῶν καὶ Ἐρυθρῶν ἐρείπιά ἐστι. πόλεις δέ ποτε τῶν Βοιωτῶν ἦσαν, καὶ νῦν ἔτι ἐν τοῖς ἐρειπίοις τῶν Ὑσιῶν ναός ἐστιν Ἀπόλλωνος ἡμίεργος καὶ φρέαρ ἱερόν· πάλαι δὲ ἐκ τοῦ φρέατος κατὰ τὸν Βοιωτῶν λόγον ἐμαντεύοντο πίνοντες.", "st": "9.2"}, {"sp": "N", "t": "ἐπανελθοῦσι δὲ ἐς τὴν λεωφόρον ἐστὶν αὖθις ἐν δεξιᾷ Μαρδονίου λεγόμενον μνῆμα εἶναι. καὶ ὅτι μὲν εὐθὺς ἦν μετὰ τὴν μάχην ἀφανὴς ὁ Μαρδονίου νεκρός, ἔστιν ὡμολογημένον· τὸν δὲ θάψαντα οὐ κατὰ ταὐτά, ὅστις ἦν, λέγουσι· φαίνεται δὲ Ἀρτόντης ὁ Μαρδονίου πλεῖστα μὲν δοὺς Διονυσοφάνει δῶρα ἀνδρὶ Ἐφεσίῳ, δοὺς μέντοι καὶ ἄλλοις Ἰώνων ὡς οὐδὲ ἐκείνοις ἀμελὲς γενόμενον ταφῆναι Μαρδόνιον.", "st": "9.2"}, {"sp": "N", "t": "αὕτη μὲν ἀπ’ Ἐλευθερῶν ἐς Πλάταιαν ἄγει, τοῖς δὲ ἐκ Μεγάρων ἰοῦσι πηγή τέ ἐστιν ἐν δεξιᾷ καὶ προελθοῦσιν ὀλίγον πέτρα· καλοῦσι δὲ τὴν μὲν Ἀκταίωνος κοίτην, ἐπὶ ταύτῃ καθεύδειν φάμενοι τῇ πέτρᾳ τὸν Ἀκταίωνα ὁπότε κάμοι θηρεύων, ἐς δὲ τὴν πηγὴν ἐνιδεῖν λέγουσιν αὐτὸν λουμένης Ἀρτέμιδος ἐν τῇ πηγῇ. Στησίχορος δὲ ὁ Ἱμεραῖος ἔγραψεν ἐλάφου περιβαλεῖν δέρμα Ἀκταίωνι τὴν θεόν, παρασκευάζουσάν οἱ τὸν ἐκ τῶν κυνῶν θάνατον, ἵνα δὴ μὴ γυναῖκα Σεμέλην λάβοι.", "st": "9.2"}, {"sp": "N", "t": "ἐγὼ δὲ ἄνευ θεοῦ πείθομαι νόσον λύσσαν τοῦ Ἀκταίωνος ἐπιλαβεῖν τοὺς κύνας· μανέντες δὲ καὶ οὐ διαγινώσκοντες διαφορήσειν ἔμελλον πάντα τινὰ ὅτῳ περιτύχοιεν. καθότι δὲ τοῦ Κιθαιρῶνος Πενθεῖ τῷ Ἐχίονος ἐγένετο ἡ συμφορὰ ἢ Οἰδίποδα ὅπῃ τεχθέντα ἐξέθεσαν, οἶδεν οὐδείς, καθάπερ γε ἴσμεν τὴν Σχιστὴν ὁδὸν τὴν ἐπὶ Φωκέων, ἐφ’ ᾗ τὸν πατέρα Οἰδίπους ἀπέκτεινεν, [ὁ δὲ Κιθαιρὼν τὸ ὄρος Διὸς ἱερὸν Κιθαιρωνίου ἐστίν] ἃ δὴ καὶ ἐς πλέον ἐπέξειμι, ἐπειδὰν ἐς αὐτὰ ὁ λόγος καθήκῃ μοι.", "st": "9.2"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἔσοδον μάλιστα τὴν ἐς Πλάταιαν τάφοι τῶν πρὸς Μήδους μαχεσαμένων εἰσί. τοῖς μὲν οὖν λοιποῖς ἐστιν Ἕλλησι μνῆμα κοινόν· Λακεδαιμονίων δὲ καὶ Ἀθηναίων τοῖς πεσοῦσιν ἰδίᾳ τέ εἰσιν οἱ τάφοι καὶ ἐλεγεῖά ἐστι Σιμωνίδου γεγραμμένα ἐπ’ αὐτοῖς. οὐ πόρρω δὲ ἀπὸ τοῦ κοινοῦ τῶν Ἑλλήνων Διός ἐστιν Ἐλευθερίου βωμὸς … τοῦτον μὲν δὴ χαλκοῦ, τοῦ Διὸς δὲ τόν τε βωμὸν καὶ τὸ ἄγαλμα ἐποίησεν λευκοῦ λίθου.", "st": "9.2"}, {"sp": "N", "t": "ἄγουσι δὲ καὶ νῦν ἔτι ἀγῶνα διὰ ἔτους πέμπτου τὰ [δὲ] Ἐλευθέρια, ἐν ᾧ μέγιστα γέρα πρόκειται δρόμου· θέουσι δὲ ὡπλισμένοι πρὸ τοῦ βωμοῦ. τρόπαιον δέ, ὃ τῆς μάχης τῆς Πλαταιᾶσιν ἀνέθεσαν οἱ Ἕλληνες, πεντεκαίδεκα σταδίοις μάλιστα ἕστηκεν ἀπωτέρω τῆς πόλεως.", "st": "9.2"}, {"sp": "N", "t": "ἐν αὐτῇ δὲ τῇ πόλει προϊοῦσιν ἀπὸ τοῦ βωμοῦ καὶ τοῦ ἀγάλματος ἃ τῷ Διὶ πεποίηται τῷ Ἐλευθερίῳ, Πλαταίας ἐστὶν ἡρῷον· καί μοι τὰ ἐς αὐτὴν ἤδη, τὰ λεγόμενα καὶ ὁποῖα αὐτὸς εἴκαζον, ἔστιν εἰρημένα. Πλαταιεῦσι δὲ ναός ἐστιν Ἥρας, θέας ἄξιος μεγέθει τε καὶ ἐς τῶν ἀγαλμάτων τὸν κόσμον. ἐσελθοῦσι μὲν Ῥέα τὸν πέτρον κατειλημένον σπαργάνοις, οἷα δὴ τὸν παῖδα ὃν ἔτεκε, Κρόνῳ κομίζουσά ἐστι· τὴν δὲ Ἥραν Τελείαν καλοῦσι, πεποίηται δὲ ὀρθὸν μεγέθει ἄγαλμα μέγα· λίθου δὲ ἀμφότερα τοῦ Πεντελησίου, Πραξιτέλους δέ ἐστιν ἔργα. ἐνταῦθα καὶ ἄλλο Ἥρας ἄγαλμα καθήμενον Καλλίμαχος ἐποίησε· Νυμφευομένην δὲ τὴν θεὸν ἐπὶ λόγῳ τοιῷδε ὀνομάζουσιν.", "st": "9.2"}, {"sp": "N", "t": "Ἥραν ἐφ’ ὅτῳ δὴ πρὸς τὸν Δία ὠργισμένην ἐς Εὔβοιάν φασιν ἀναχωρῆσαι, Δία δέ, ὡς οὐκ ἔπειθεν αὐτήν, παρὰ Κιθαιρῶνα λέγουσιν ἐλθεῖν δυναστεύοντα ἐν Πλαταιαῖς τότε· εἶναι γὰρ τὸν Κιθαιρῶνα οὐδενὸς σοφίαν ὕστερον. οὗτος οὖν κελεύει τὸν Δία ἄγαλμα ξύλου ποιησάμενον ἄγειν ἐπὶ βοῶν ζεύγους ἐγκεκαλυμμένον, λέγειν δὲ ὡς ἄγοιτο γυναῖκα Πλάταιαν τὴν Ἀσωποῦ.", "st": "9.3"}, {"sp": "N", "t": "καὶ ὁ μὲν ἔπρασσε κατὰ τὴν παραίνεσιν τοῦ Κιθαιρῶνος· Ἥρα δὲ ἐπέπυστό τε αὐτίκα καὶ αὐτίκα ἀφίκετο. ὡς δὲ ἐπλησίαζε τῇ ἁμάξῃ καὶ τοῦ ἀγάλματος τὴν ἐσθῆτα περιέρρηξεν, ἥσθη τε τῇ ἀπάτῃ ξόανον εὑροῦσα ἀντὶ νύμφης γυναικὸς καὶ διαλλαγὰς ποιεῖται πρὸς τὸν Δία. ἐπὶ ταύταις ταῖς διαλλαγαῖς Δαίδαλα ἑορτὴν ἄγουσιν, ὅτι οἱ πάλαι τὰ ξόανα ἐκάλουν δαίδαλα· ἐκάλουν δὲ ἐμοὶ δοκεῖν πρότερον ἔτι ἢ Δαίδαλος ὁ Παλαμάονος ἐγένετο Ἀθήνῃσι, τούτῳ δὲ ὕστερον ἀπὸ τῶν δαιδάλων ἐπίκλησιν γενέσθαι δοκῶ καὶ οὐκ ἐκ γενετῆς τεθῆναι τὸ ὄνομα.", "st": "9.3"}, {"sp": "N", "t": "Δαίδαλα οὖν ἄγουσιν οἱ Πλαταιεῖς ἑορτὴν δι’ ἔτους ἑβδόμου μέν, ὡς ἔφασκεν ὁ τῶν ἐπιχωρίων ἐξηγητής, ἀληθεῖ μέντοι λόγῳ δι’ ἐλάσσονος καὶ οὐ τοσούτου χρόνου· ἐθελήσαντες δὲ ἀπὸ Δαιδάλων ἐς Δαίδαλα ἕτερα ἀναριθμῆσαι τὸν μεταξὺ χρόνον ἐς τὸ ἀκριβέστατον οὐκ ἐγενόμεθα οἷοί τε. ἄγουσι δὲ οὕτω τὴν ἑορτήν.", "st": "9.3"}, {"sp": "N", "t": "δρυμός ἐστιν Ἀλαλκομενῶν οὐ πόρρω· μέγιστα τῶν ἐν Βοιωτίᾳ στελέχη δρυῶν ἐστιν ἐνταῦθα. ἐς τοῦτον οἱ Πλαταιεῖς ἀφικόμενοι τὸν δρυμὸν προτίθενται μοίρας κρεῶν ἑφθῶν. ὄρνιθες δὲ οἱ μὲν ἄλλοι σφίσιν ἥκιστά εἰσι δι’ ὄχλου, τῶν κοράκων δὲ—οὗτοι γάρ σφισιν ἐπιφοιτῶσιν—ἔχουσιν ἀκριβῆ τὴν φρουράν. τὸν δὲ αὐτῶν ἁρπάσαντα κρέας, ἐφ’ ὅτῳ τῶν δένδρων καθεδεῖται, φυλάσσουσιν. ἐφ’ οὗ δ’ ἂν καθεσθῇ, τεμόντες ποιοῦσιν ἀπὸ τούτου τὸ δαίδαλον· δαίδαλον γὰρ δὴ καὶ τὸ ξόανον αὐτὸ ὀνομάζουσι.", "st": "9.3"}, {"sp": "N", "t": "ταύτην μὲν ἰδίᾳ οἱ Πλαταιεῖς ἑορτὴν ἄγουσι, Δαίδαλα μικρὰ ὀνομάζοντες· Δαιδάλων δὲ ἑορτὴν τῶν μεγάλων καὶ Βοιωτοί σφισι συνεορτάζουσι, δι’ ἑξηκοστοῦ δὲ ἄγουσιν ἔτους· ἐκλιπεῖν γὰρ τοσοῦτον χρόνον τὴν ἑορτήν φασιν, ἡνίκα οἱ Πλαταιεῖς ἔφευγον. ξόανα δὲ τεσσαρεσκαίδεκα ἕτοιμά σφισίν ἐστι κατ’ ἐνιαυτὸν ἕκαστον παρασκευασθέντα ἐν Δαιδάλοις τοῖς μικροῖς.", "st": "9.3"}, {"sp": "N", "t": "ταῦτα ἀναιροῦνται κλήρῳ Πλαταιεῖς Κορωναῖοι Θεσπιεῖς Ταναγραῖοι Χαιρωνεῖς Ὀρχομένιοι Λεβαδεῖς Θηβαῖοι· διαλλαγῆναι γὰρ καὶ οὗτοι Πλαταιεῦσιν ἠξίωσαν καὶ συλλόγου μετασχεῖν κοινοῦ καὶ ἐς Δαίδαλα θυσίαν ἀποστέλλειν, ὅτε Κάσσανδρος ὁ Ἀντιπάτρου τὰς Θήβας ἀνῴκισε. τῶν δὲ πολισμάτων ὁπόσα ἐστὶν ἐλάσσονος λόγου, συντέλειαν αἱροῦνται.", "st": "9.3"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα κομίσαντες παρὰ τὸν Ἀσωπὸν καὶ ἀναθέντες ἐπὶ ἅμαξαν, γυναῖκα ἐφιστᾶσι νυμφεύτριαν· οἱ δὲ αὖθις κληροῦνται καθ’ ἥντινα τάξιν τὴν πομπὴν ἀνάξουσι· τὸ δὲ ἐντεῦθεν τὰς ἁμάξας ἀπὸ τοῦ ποταμοῦ πρὸς ἄκρον τὸν Κιθαιρῶνα ἐλαύνουσιν. εὐτρέπισται δέ σφισιν ἐπὶ τῇ κορυφῇ τοῦ ὄρους βωμός, ποιοῦσι δὲ τρόπῳ τοιῷδε τὸν βωμόν· ξύλα τετράγωνα ἁρμόζοντες πρὸς ἄλληλα συντιθέασι κατὰ ταὐτὰ καὶ εἰ λίθων ἐποιοῦντο οἰκοδομίαν, ἐξάραντες δὲ ἐς ὕψος φρύγανα ἐπιφέρουσιν.", "st": "9.3"}, {"sp": "N", "t": "αἱ μὲν δὴ πόλεις καὶ τὰ τέλη θήλειαν θύσαντες τῇ Ἥρᾳ βοῦν ἕκαστοι καὶ ταῦρον τῷ Διὶ τὰ ἱερεῖα οἴνου καὶ θυμιαμάτων πλήρη καὶ τὰ δαίδαλα ὁμοῦ καθαγίζουσιν ἐπὶ τοῦ βωμοῦ, ἰδιῶται δὲ ὁπόσα ⟨δὴ⟩ θύουσιν οἱ πλούσιοι· τοῖς δὲ οὐχ ὁμοίως δυναμ⟨ένο⟩ις τὰ λεπτότερα τῶν προβάτων θύειν καθέστηκε, καθαγίζειν δὲ τὰ ἱερεῖα ὁμοίως πάντα. σὺν δέ σφισι καὶ αὐτὸν τὸν βωμὸν ἐπιλαβὸν τὸ πῦρ ἐξανήλωσε· μεγίστην δὲ ταύτην φλόγα καὶ ἐκ μακροτάτου σύνοπτον οἶδα ἀρθεῖσαν.", "st": "9.3"}, {"sp": "N", "t": "ὑπὸ δὲ τῆς κορυφῆς, ἐφ’ ᾗ τὸν βωμὸν ποιοῦνται, πέντε που μάλιστα καὶ δέκα ὑποκαταβάντι σταδίους νυμφῶν ἐστιν ἄντρον Κιθαιρωνίδων, Σφραγίδιον μὲν ὀνομαζόμενον, μαντεύεσθαι δὲ τὰς νύμφας τὸ ἀρχαῖον αὐτόθι ἔχει λόγος.", "st": "9.3"}, {"sp": "N", "t": "Πλαταιεῦσι δὲ Ἀθηνᾶς ἐπίκλησιν Ἀρείας ἐστὶν ἱερόν· ᾠκοδομήθη δὲ ἀπὸ λαφύρων ἃ τῆς μάχης σφίσιν Ἀθηναῖοι τῆς Μαραθῶνι ἀπένειμαν. τὸ μὲν δὴ ἄγαλμα ξόανόν ἐστιν ἐπίχρυσον, πρόσωπον δέ οἱ καὶ χεῖρες ἄκραι καὶ πόδες λίθου τοῦ Πεντελησίου εἰσί· μέγεθος μὲν οὐ πολὺ δή τι ἀποδεῖ τῆς ἐν ἀκροπόλει χαλκῆς, ἣν καὶ αὐτὴν Ἀθηναῖοι τοῦ Μαραθῶνι ἀπαρχὴν ἀγῶνος ἀνέθηκαν, Φειδίας δὲ καὶ Πλαταιεῦσιν ἦν ὁ τῆς Ἀθηνᾶς τὸ ἄγαλμα ποιήσας.", "st": "9.4"}, {"sp": "N", "t": "γραφαὶ δέ εἰσιν ἐν τῷ ναῷ Πολυγνώτου μὲν Ὀδυσσεὺς τοὺς μνηστῆρας ἤδη κατειργασμένος, Ὀνασία δὲ Ἀδράστου καὶ Ἀργείων ἐπὶ Θήβας ἡ προτέρα στρατεία. αὗται μὲν δή εἰσιν ἐπὶ τοῦ προνάου τῶν τοίχων αἱ γραφαί, κεῖται δὲ τοῦ ἀγάλματος πρὸς τοῖς ποσὶν εἰκὼν Ἀριμνήστου· ὁ δὲ Ἀρίμνηστος ἔν τε τῇ πρὸς Μαρδόνιον μάχῃ καὶ ἔτι πρότερον ἐς Μαραθῶνα Πλαταιεῦσιν ἡγήσατο.", "st": "9.4"}, {"sp": "N", "t": "ἔστι δὲ καὶ Δήμητρος ἐπίκλησιν Ἐλευσινίας ἱερὸν ἐν Πλαταιαῖς καὶ Ληίτου μνῆμα· τῶν δὲ ἡγεμόνων, οἳ Βοιωτοὺς ἐς Τροίαν ἤγαγον, μόνος ἀνέστρεψεν οἴκαδε οὗτος ὁ Λήιτος. τὴν δὲ κρήνην τὴν Γαργαφίαν Μαρδόνιος καὶ ἡ ἵππος συνέχεεν ἡ Περσῶν, ὅτι τὸ Ἑλλήνων στράτευμα τὸ ἀντικαθήμενόν σφισιν ἀπ’ αὐτῆς ἔπινεν· ὕστερον μέντοι τὸ ὕδωρ ἀνεσώσαντο οἱ Πλαταιεῖς.", "st": "9.4"}, {"sp": "N", "t": "ἐκ Πλαταίας δὲ ἰοῦσιν ἐς Θήβας ποταμός ἐστιν Ὠερόη· θυγατέρα δὲ εἶναι τὴν Ὠερόην τοῦ Ἀσωποῦ λέγουσι. πρὶν δὲ ἢ διαβῆναι τὸν Ἀσωπόν, παρ’ αὐτὸ τὸ ῥεῦμα ἀποτραπεῖσιν ἐς τὰ κάτω καὶ προελθοῦσιν ὅσον τεσσαράκοντα στάδια ἔστιν ἐρείπια Σκώλου· Δήμητρος δὲ καὶ Κόρης ἐν τοῖς ἐρειπίοις οὐκ ἐξειργασμένος ὁ ναός, ἡμίεργα δὲ καὶ ταῖς θεαῖς ἐστι τὰ ἀγάλματα. ἀποκρίνει δὲ καὶ νῦν ἔτι ἀπὸ τῆς Θηβαίων τὴν Πλαταιίδα ὁ Ἀσωπός.", "st": "9.4"}, {"sp": "N", "t": "γῆν δὲ τὴν Θηβαΐδα οἰκῆσαι πρῶτον λέγουσιν Ἔκτηνας, βασιλέα δὲ εἶναι τῶν Ἐκτήνων ἄνδρα αὐτόχθονα Ὤγυγον· καὶ ἀπὸ τούτου τοῖς πολλοῖς τῶν ποιητῶν ἐπίκλησις ἐς τὰς Θήβας ἐστὶν Ὠγύγιαι. καὶ τούτους μὲν ἀπολέσθαι λοιμώδει νόσῳ φασίν, ἐσοικίσασθαι δὲ μετὰ τοὺς Ἔκτηνας ἐς τὴν χώραν Ὕαντας καὶ Ἄονας, Βοιώτια ἐμοὶ δοκεῖν γένη καὶ οὐκ ἐπηλύδων ἀνθρώπων. Κάδμου δὲ καὶ τῆς Φοινίκων στρατιᾶς ἐπελθούσης μάχῃ νικηθέντες οἱ μὲν Ὕαντες ἐς τὴν νύκτα τὴν ἐπερχομένην ἐκδιδράσκουσι, τοὺς δὲ Ἄονας ὁ Κάδμος γενομένους ἱκέτας καταμεῖναι καὶ ἀναμιχθῆναι τοῖς Φοίνιξιν εἴασε.", "st": "9.5"}, {"sp": "N", "t": "τοῖς μὲν οὖν Ἄοσι κατὰ κώμας ἔτι ἦσαν αἱ οἰκήσεις· Κάδμος δὲ τὴν πόλιν τὴν καλουμένην ἔτι καὶ ἐς ἡμᾶς Καδμείαν ᾤκισεν. αὐξηθείσης δὲ ὕστερον τῆς πόλεως, οὕτω τὴν Καδμείαν ἀκρόπολιν συνέβη τῶν κάτω γενέσθαι Θηβῶν. Κάδμῳ δὲ γάμος τε ἐπιφανὴς ὑπῆρξεν, εἰ δὴ θυγατέρα Ἀφροδίτης καὶ Ἄρεως κατὰ λόγον τὸν Ἑλλήνων ἔσχε, καὶ αἱ θυγατέρες εἰλήφασιν αὐτῷ φήμην, Σεμέλη μὲν τεκεῖν ἐκ Διός, Ἰνὼ δὲ θεῶν εἶναι τῶν θαλασσίων.", "st": "9.5"}, {"sp": "N", "t": "ἐπὶ μὲν δὴ Κάδμου μέγιστον μετά γε αὐτὸν Κάδμον ἠδύναντο οἱ Σπαρτοί, Χθόνιος καὶ Ὑπερήνωρ καὶ Πέλωρος καὶ Οὐδαῖος· Ἐχίονα δὲ ὡς προέχοντα κατ’ ἀνδραγαθίαν γαμβρὸν ἠξίωσεν ὁ Κάδμος ποιήσασθαι. τοὺς δὲ ἄνδρας τούτους—οὐ γάρ τι ἠδυνάμην ἐς αὐτοὺς παρευρεῖν—ἕπομαι τῷ μύθῳ Σπαρτοὺς διὰ τὸν τρόπον ὅντινα ἐγένοντο ὀνομασθῆναι. Κάδμου δὲ ἐς Ἰλλυριοὺς καὶ Ἰλλυριῶν ἐς τοὺς καλουμένους Ἐγχελέας μετοικήσαντος Πολύδωρος ὁ Κάδμου τὴν ἀρχὴν ἔσχε.", "st": "9.5"}, {"sp": "N", "t": "Πενθεὺς δὲ ὁ Ἐχίονος ἴσχυε μὲν καὶ αὐτὸς κατὰ γένους ἀξίωμα καὶ φιλίᾳ τοῦ βασιλέως· ὢν δὲ ἐς τὰ λοιπὰ ὑβριστὴς καὶ ἀσεβὴς Διονύσου, δίκην ἔσχεν ἐκ τοῦ θεοῦ. Πολυδώρου δὲ ἦν Λάβδακος· ἔμελλε δὲ ἄρα αὐτόν, ὥς οἱ παρίστατο ἡ τελευτή, παῖδα ἔτι ἀπολείψειν, καὶ ἐπιτρέπει τόν τε υἱὸν καὶ τὴν ἀρχὴν Νυκτεῖ.", "st": "9.5"}, {"sp": "N", "t": "τὰ δὲ ἐφεξῆς μοι τοῦ λόγου προεδήλωσεν ἡ Σικυωνία συγγραφή, τοῦ τε Νυκτέως τὸν θάνατον, ὅντινα γένοιτο τρόπον, καὶ ὡς ἐς Λύκον ἀδελφὸν Νυκτέως ἥ τε ἐπιμέλεια τοῦ παιδὸς περιῆλθε καὶ ἡ Θηβαίων δυναστεία. Λύκος δὲ παρέδωκε μὲν αὐξηθέντι Λαβδάκῳ τὴν ἀρχήν· γενομένης δὲ οὐ μετὰ πολὺ καὶ τούτῳ τῆς τελευτῆς, ὁ δὲ ἐπετρόπευσεν αὖθις Λάιον Λαβδάκου παῖδα.", "st": "9.5"}, {"sp": "N", "t": "Λύκου δὲ ἐπιτροπεύοντος δεύτερον κατίασιν Ἀμφίων καὶ Ζῆθος δύναμιν ἀγείραντες. καὶ Λάιον μὲν ὑπεκκλέπτουσιν οἷς ἦν ἐπιμελὲς μὴ γενέσθαι τὸ Κάδμου γένος ἐς τοὺς ἔπειτα ἀνώνυμον, Λάκου δὲ οἱ τῆς Ἀντιόπης παῖδες τῇ μάχῃ κρατοῦσιν· ὡς δὲ ἐβασίλευσαν, τὴν πόλιν τὴν κάτω προσῴκισαν τῇ Καδμείᾳ καὶ Θήβας ὄνομα ἔθεντο κατὰ συγγένειαν τὴν Θήβης.", "st": "9.5"}, {"sp": "N", "t": "μαρτυρεῖ δέ μοι τῷ λόγῳ καὶ Ὅμηρος ἐν τῇ Ὀδυσσείᾳ·<br>οἳ πρῶτοι Θήβης ἕδος ἔκτισαν ἑπταπύλοιο<br>πύργωσάν τ’, ἐπεὶ οὐ μὲν ἀπύργωτόν γ’ ἐδύναντο<br>ναιέμεν εὐρύχορον Θήβην, κρατερώ περ ἐόντε.<br>ὅτι δὲ Ἀμφίων ᾖδε καὶ τὸ τεῖχος ἐξειργάζετο πρὸς τὴν λύραν, οὐδένα ἐποιήσατο λόγον ἐν τοῖς ἔπεσι· δόξαν δὲ ἔσχεν Ἀμφίων ἐπὶ μουσικῇ, τήν τε ἁρμονίαν τὴν Λυδῶν κατὰ κῆδος τὸ Ταντάλου παρ’ αὐτῶν μαθὼν καὶ χορδὰς ἐπὶ τέσσαρσι ταῖς πρότερον τρεῖς ἀνευρών.", "st": "9.5"}, {"sp": "N", "t": "ὁ δὲ τὰ ἔπη τὰ ἐς Εὐρώπην ποιήσας φησὶν Ἀμφίονα χρήσασθαι λύρᾳ πρῶτον Ἑρμοῦ διδάξαντος· πεποίηκε δὲ καὶ ⟨περὶ⟩ λίθων καὶ θηρίων, ὅτι καὶ ταῦτα ᾄδων ἦγε. Μυρὼ δὲ Βυζαντία, ποιήσασα ἔπη καὶ ἐλεγεῖα, Ἑρμῇ βωμόν φησιν ἱδρύσασθαι πρῶτον Ἀμφίονα καὶ ἐπὶ τούτῳ λύραν παρ’ αὐτοῦ λαβεῖν. λέγεται δὲ καὶ ὡς ἐν Ἅιδου δίκην δίδωσιν ὁ Ἀμφίων ὧν ἐς Λητὼ καὶ τοὺς παῖδας καὶ αὐτὸς ἀπέρριψε·", "st": "9.5"}, {"sp": "N", "t": "κατὰ δὲ τὴν τιμωρίαν τοῦ Ἀμφίονος ἔστιν ⟨ἔπη⟩ ποιήσεως Μινυάδος, ἔχει δὲ ἐς Ἀμφίονα κοινῶς καὶ ἐς τὸν Θρᾷκα Θάμυριν. ὡς δὲ τὸν οἶκον τὸν Ἀμφίονος καὶ Ζήθου τὸν μὲν ἡ νόσος ἡ λοιμώδης ἠρήμωσε, Ζήθῳ δὲ τὸν παῖδα ἀπέκτεινεν ἡ τεκοῦσα κατὰ δή τινα ἁμαρτίαν, ἐτεθνήκει δὲ ὑπὸ λύπης καὶ αὐτὸς ὁ Ζῆθος, οὕτω Λάιον ἐπὶ βασιλείᾳ κατάγουσιν οἱ Θηβαῖοι.", "st": "9.5"}, {"sp": "N", "t": "Λαΐῳ δὲ βασιλεύοντι καὶ γυναῖκα ἔχοντι Ἰοκάστην μάντευμα ἦλθεν ἐκ Δελφῶν ἐκ τοῦ παιδός οἱ τὴν τελευτήν, εἰ τέκοι τινὰ Ἰοκάστη, γενήσεσθαι. καὶ ὁ μὲν ἐπὶ τούτῳ τὸν Οἰδίποδα ἐκτίθησιν· ὁ δὲ καὶ τὸν πατέρα ἀποκτενεῖν ἔμελλεν, ὡς ηὐξήθη, καὶ τὴν μητέρα ἔγημε. παῖδας δὲ ἐξ αὐτῆς οὐ δοκῶ οἱ γενέσθαι, μάρτυρι Ὁμήρῳ χρώμενος, ὃς ἐποίησεν ἐν Ὀδυσσείᾳ", "st": "9.5"}, {"sp": "N", "t": "μητέρα τ’ Οἰδιπόδαο ἴδον, καλὴν Ἐπικάστην,<br>ἣ μέγα ἔργον ἔρεξεν ἀιδρείῃσι νόοιο<br>γημαμένη ᾧ υἱεῖ· ὁ δ’ ὃν πατέρ’ ἐξεναρίξας<br>γῆμεν· ἄφαρ δ’ ἀνάπυστα θεοὶ θέσαν ἀνθρώποισιν.<br>πῶς οὖν ἐποίησαν ἀνάπυστα ἄφαρ, εἰ δὴ τέσσαρες [γενεαὶ] ἐκ τῆς Ἐπικάστης ἐγένοντο παῖδες τῷ Οἰδίποδι; ἐξ Εὐρυγανείας δὲ τῆς Ὑπέρφαντος ἐγεγόνεσαν. δηλοῖ δὲ καὶ ὁ τὰ ἔπη ποιήσας ἃ Οἰδιπόδια ὀνομάζουσι· καὶ Ὀνασίας Πλαταιᾶσιν ἔγραψε κατηφῆ τὴν Εὐρυγάνειαν ἐπὶ τῇ μάχῃ τῶν παίδων.", "st": "9.5"}, {"sp": "N", "t": "Πολυνείκης δὲ περιόντος μὲν καὶ ἄρχοντος Οἰδίποδος ὑπεξῆλθεν ἐκ Θηβῶν δέει μὴ τελεσθεῖεν ἐπὶ σφίσιν αἱ κατᾶραι τοῦ πατρός· ἀφικόμενος δὲ ἐς Ἄργος καὶ θυγατέρα Ἀδράστου λαβὼν κατῆλθεν ἐς Θήβας μετάπεμπτος ὑπὸ Ἐτεοκλέους μετὰ τὴν τελευτὴν Οἰδίποδος. κατελθὼν δὲ ἐς διαφορὰν προήχθη τῷ Ἐτεοκλεῖ, καὶ οὕτω τὸ δεύτερον ἔφυγε· δεηθεὶς δὲ Ἀδράστου δοῦναί οἱ δύναμιν τὴν κατάξουσαν, τήν τε στρατιὰν ἀπόλλυσι καὶ πρὸς τὸν Ἐτεοκλέα αὐτὸς μονομαχεῖ κατὰ πρόκλησιν.", "st": "9.5"}, {"sp": "N", "t": "καὶ οἱ μὲν μονομαχοῦντες ἀποθνήσκουσιν, ἐς δὲ Λαοδάμαντα τὸν Ἐτεοκλέους καθηκούσης τῆς βασιλείας Κρέων ὁ Μενοικέως ἐδυνάστευεν ἐπιτροπεύων τὸν παῖδα. ἤδη δὲ Λαοδάμαντος ηὐξημένου καὶ ἔχοντος τὴν ἀρχήν, δεύτερον τότε ἄγουσι τὴν στρατιὰν ἐπὶ τὰς Θήβας· ἀντεστρατοπεδευμένων δὲ καὶ τῶν Θηβαίων περὶ Γλίσαντα, ὡς ἐς χεῖρας συνῆλθον, Αἰγιαλέα μὲν τὸν Ἀδράστου Λαοδάμας ἀποκτίννυσι, κρατησάντων δὲ τῇ μάχῃ τῶν Ἀργείων Λαοδάμας σὺν τοῖς ἐθέλουσιν ἕπεσθαι Θηβαίων ὑπὸ τὴν ἐπιοῦσαν νύκτα ἀπεχώρησεν ἐς Ἰλλυριούς.", "st": "9.5"}, {"sp": "N", "t": "τὰς δὲ Θήβας ἑλόντες οἱ Ἀργεῖοι παραδιδόασι Θερσάνδρῳ Πολυνείκους παιδί. ὡς δὲ τοῖς σὺν Ἀγαμέμνονι ἐς Τροίαν στρατεύουσιν ἡ διαμαρτία τοῦ πλοῦ γίνεται καὶ ἡ πληγὴ ⟨ἡ⟩ περὶ Μυσίαν, ἐνταῦθα καὶ τὸν Θέρσανδρον κατέλαβεν ⟨ἀποθανεῖν⟩ ὑπὸ Τηλέφου, μάλιστα Ἑλλήνων ἀγαθὸν γενόμενον ἐν τῇ μάχῃ· καί οἱ τὸ μνῆμα ἐς Καΐκου πεδίον ἐλαύνοντί ἐστιν ἐν Ἐλαίᾳ πόλει, λίθος ὁ ἐν τῷ ὑπαίθρῳ τῆς ἀγορᾶς·", "st": "9.5"}, {"sp": "N", "t": "καὶ ἐναγίζειν οἱ ἐπιχώριοί φασιν αὐτῷ. τελευτήσαντος δὲ Θερσάνδρου καὶ δεύτερα ἐπί τε Ἀλέξανδρον καὶ ἐς Ἴλιον ἀθροιζομένου στόλου Πηνέλεων ἄρχοντα εἵλοντο, ὅτι οὐκ ἐν ἡλικίᾳ πω Τισαμενὸς ἦν ὁ Θερσάνδρου· Πηνέλεω δὲ ἀποθανόντος ὑπὸ Εὐρυπύλου τοῦ Τηλέφου Τισαμενὸν βασιλέα αἱροῦνται, Θερσάνδρου τε ὄντα καὶ Δημωνάσσης τῆς Ἀμφιαράου. τῶν δὲ Ἐρινύων τῶν Λαΐου καὶ Οἰδίποδος Τισαμενῷ μὲν οὐκ ἐγένετο μήνιμα, Αὐτεσίωνι δὲ τῷ Τισαμενοῦ, ὥστε καὶ παρὰ τοὺς Δωριέας μετῴκησε τοῦ θεοῦ χρήσαντος.", "st": "9.5"}, {"sp": "N", "t": "Αὐτεσίωνος δὲ ἀπελθόντος, οὕτω βασιλέα εἵλοντο Δαμασίχθονα Ὀφέλτου τοῦ Πηνέλεω. τούτου δὲ ἦν τοῦ Δαμασίχθονος Πτολεμαῖος, τοῦ δὲ Ξάνθος, ὃν Ἀνδρόπομπος μονομαχήσαντά οἱ δόλῳ καὶ οὐ σὺν τῷ δικαίῳ κτείνει. τὸ δὲ ἐντεῦθεν διὰ πλειόνων πολιτεύεσθαι μηδὲ ἀπ’ ἀνδρὸς ἑνὸς ἠρτῆσθαι τὰ πάντα ἄμεινον ἐφαίνετο τοῖς Θηβαίοις.", "st": "9.5"}, {"sp": "N", "t": "τῶν δέ σφισιν ἐν ἀγῶσι πολέμου γενομένων εὐτυχημάτων, καὶ ὡς ἑτέρως, τοσάδε φανερώτατα ὄντα εὕρισκον. ἐκρατήθησαν ὑπὸ Ἀθηναίων μάχῃ Πλαταιεῦσιν ἀμυνάντων, ὅτε σφᾶς ἐπέλαβεν ὑπὲρ τῶν ὅρων πολεμῆσαι τῆς χώρας· προσέπταισαν δὲ καὶ δεύτερον Ἀθηναίοις ἀντιταξάμενοι περὶ Πλάταιαν, ἡνίκα δοκοῦσιν ἑλέσθαι τὰ βασιλέως Ξέρξου πρὸ τῶν Ἑλληνικῶν.", "st": "9.6"}, {"sp": "N", "t": "τῆς δὲ αἰτίας ταύτης δημοσίᾳ σφίσιν οὐ μέτεστιν, ὅτι ἐν ταῖς Θήβαις ὀλιγαρχία καὶ οὐχὶ ἡ πάτριος πολιτεία τηνικαῦτα ἴσχυεν· εἰ γοῦν Πεισιστράτου τυραννοῦντος ἔτι ἢ τῶν παίδων Ἀθήνῃσιν ἀφίκετο ἐπὶ τὴν Ἑλλάδα ὁ βάρβαρος, οὐκ ἔστιν ὅπως οὐ καὶ Ἀθηναίους κατέλαβεν ἂν ἔγκλημα μηδισμοῦ.", "st": "9.6"}, {"sp": "N", "t": "ὕστερον μέντοι καὶ Θηβαίοις νίκη κατ’ Ἀθηναίων ἐπὶ Δηλίῳ τῷ Ταναγραίων ἐγένετο, καὶ Ἱπποκράτης τε ὁ Ἀρίφρονος, ὃς στρατηγὸς ἦν Ἀθηναίοις, καὶ τῆς ἄλλης στρατιᾶς τὸ πολὺ ἔπεσε. Λακεδαιμονίοις δὲ παραυτίκα μὲν ἀπελθόντος τοῦ Μήδου καὶ ἄχρι τοῦ Πελοποννησίων πρὸς Ἀθηναίους πολέμου τὰ ἐκ Θηβῶν εἶχεν ἐπιτηδείως· διαπολεμηθέντος δὲ τοῦ πολέμου καὶ Ἀθηναίοις καταλυθέντος τοῦ ναυτικοῦ, μετ’ οὐ πολὺ Θηβαῖοι μετὰ Κορινθίων ἐς τὸν πρὸς Λακεδαιμονίους πόλεμον προήχθησαν.", "st": "9.6"}, {"sp": "N", "t": "κρατηθέντες δὲ μάχῃ περὶ Κόρινθόν τε καὶ ἐν Κορωνείᾳ, νικῶσιν αὖθις ἐν Λεύκτροις ἐπιφανεστάτην νίκην ὁπόσας γενομένας Ἕλλησιν ἴσμεν κατὰ Ἑλλήνων· καὶ δεκαδαρχίας τε, ἃς Λακεδαιμόνιοι κατέστησαν ἐν ταῖς πόλεσιν, ἔπαυσαν καὶ ἁρμοστὰς τοὺς Σπαρτιάτας ἐκβάλλουσιν. ὕστερον δὲ καὶ τὸν Φωκικὸν πόλεμον, ὀνομαζόμενον δὲ ὑπὸ Ἑλλήνων ἱερόν, συνεχῶς δέκα ἔτεσιν ἐπολέμησαν.", "st": "9.6"}, {"sp": "N", "t": "εἴρηται δέ μοι καὶ ἐν τῇ Ἀτθίδι συγγραφῇ τὸ ἐν Χαιρωνείᾳ σφάλμα συμφορὰν γενέσθαι τοῖς πᾶσιν Ἕλλησι· Θηβαίους δὲ καὶ ἐς πλέον κατέλαβεν, οἷς γε καὶ ἐσήχθη ἐς τὴν πόλιν φρουρά. Φιλίππου δὲ ἀποθανόντος καὶ ἐς Ἀλέξανδρον ἡκούσης τῆς Μακεδόνων ἀρχῆς, Θηβαίοις ἐπῆλθεν ἐξελεῖν τὴν φρουράν· ποιήσασι δὲ ταῦτα προεσήμαινεν αὐτίκα ὁ θεὸς τὸν ἐπιόντα ὄλεθρον, καί σφισιν ἐν Δήμητρος ἱερῷ Θεσμοφόρου σημεῖα ἐγένετο ἐναντία ἢ πρὸ τοῦ ἔργου τοῦ ἐν Λεύκτροις·", "st": "9.6"}, {"sp": "N", "t": "τότε μὲν γὰρ τοῦ ἱεροῦ τὰς θύρας ὑφάσματι ἀράχναι λευκῷ, κατὰ δὲ τὴν Ἀλεξάνδρου καὶ Μακεδόνων ἔφοδον μέλανι ἐξύφηναν. λέγεται δὲ καὶ Ἀθηναίοις ὗσαι τέφραν ὁ θεὸς ἐνιαυτῷ πρότερον πρὶν ἢ τὸν πόλεμον τὸν ἐπαχθέντα ὑπὸ Σύλλα τὰ μεγάλα σφίσιν ἐνεγκεῖν παθήματα.", "st": "9.6"}, {"sp": "N", "t": "τότε δὲ τοὺς Θηβαίους γενομένους ἀναστάτους ὑπὸ Ἀλεξάνδρου καὶ διαπεσόντας ἐς Ἀθήνας ὕστερον Κάσσανδρος ὁ Ἀντιπάτρου κατήγαγεν. ἐς δὲ τῶν Θηβῶν τὸν οἰκισμὸν προθυμότατοι μὲν ἐγένοντο Ἀθηναῖοι, συνεπελάβοντο δὲ καὶ Μεσσήνιοι καὶ Ἀρκάδων οἱ Μεγάλην πόλιν ἔχοντες.", "st": "9.7"}, {"sp": "N", "t": "δοκεῖ δέ μοι τὰς Θήβας οἰκίσαι ὁ Κάσσανδρος κατὰ ἔχθος Ἀλεξάνδρου μάλιστα· ἐπεξῆλθε δὲ καὶ τὸν πάντα οἶκον Ἀλεξάνδρου φθείρων, ὃς Ὀλυμπιάδα γε παρέβαλε καταλεῦσαι τοῖς ἐπ’ αὐτὴν Μακεδόνων παρωξυσμένοις καὶ τοὺς παῖδας Ἀλεξάνδρου τόν τε ἐκ Βαρσίνης Ἡρακλέα καὶ Ἀλέξανδρον τὸν ἐκ Ῥωξάνης ἀπέκτεινεν ὑπὸ φαρμάκων. οὐ μὴν οὐδὲ αὐτὸς χαίρων τὸν βίον κατέστρεψεν· ἐπλήσθη γὰρ ὑδέρῳ, καὶ ἀπ’ αὐτοῦ ζῶντι ἐγένοντο εὐλαί.", "st": "9.7"}, {"sp": "N", "t": "τῶν δέ οἱ παίδων Φίλιππον μὲν τὸν πρεσβύτατον, ὡς μετ’ οὐ πολὺ παρέλαβε τὴν ἀρχήν, ἀπήγαγεν ὑπολαβοῦσα νόσος φθινώδης, Ἀντίπατρος δὲ ⟨ὁ⟩ μετ’ ἐκεῖνον Θεσσαλονίκην τὴν μητέρα ἀποκτίννυσι, Φιλίππου τε οὖσαν τοῦ Ἀμύντου καὶ Νικασιπόλιδος· ἀπέκτεινε δὲ Ἀλεξάνδρῳ νέμειν πλέον εὐνοίας αἰτιασάμενος. ὁ δὲ Ἀλέξανδρος ἦν νεώτατος τῶν Κασσάνδρου παίδων· ἐπαγαγόμενος δὲ Δημήτριον τὸν Ἀντιγόνου καθεῖλε μὲν δι’ ἐκείνου καὶ ἐτιμωρήσατο τὸν ἀδελφὸν Ἀντίπατρον, ἀνεφάνη μέντοι φονέα ἐξευρηκὼς ἑαυτῷ καὶ οὐ σύμμαχον.", "st": "9.7"}, {"sp": "N", "t": "Κασσάνδρῳ μὲν ὅστις δὴ θεῶν τὴν δίκην ἔμελλεν ἀποδώσειν· Θηβαίοις δὲ ἐπὶ μὲν Κασσάνδρου πᾶς ὁ ἀρχαῖος περίβολος ἀνῳκίσθη, ἔδει δὲ ἄρα καὶ ὕστερον κακῶν σφᾶς μεγάλων γεύσασθαι. Μιθριδάτῃ γὰρ καταστάντι ἐς τὸν πρὸς Ῥωμαίους πόλεμον προσεχώρησαν Θηβαῖοι κατ’ ἄλλο ἐμοὶ δοκεῖν οὐδέν, τοῦ δὲ Ἀθηναίων δήμου φιλίᾳ. Σύλλα δὲ ἐσβαλόντος ἐς τὴν Βοιωτίαν δεῖμα ἔσχε τοὺς Θηβαίους, καὶ ἐγνωσιμάχησάν τε αὐτίκα καὶ ἐτράποντο αὖθις ἐς τὴν Ῥωμαίων φιλίαν.", "st": "9.7"}, {"sp": "N", "t": "Σύλλας δὲ ἐς αὐτοὺς ἐχρῆτο ὅμως τῷ θυμῷ, καὶ ἄλλα τε ἐξεῦρεν ἐπὶ λύμῃ τῶν Θηβαίων καὶ τὴν ἡμίσειαν ἀπετέμετο αὐτῶν τῆς χώρας κατὰ πρόφασιν τοιαύτην. ἡνίκα ἤρχετο τοῦ πρὸς Μιθριδάτην πολέμου, χρημάτων ἐσπάνιζε· συνέλεξεν οὖν ἔκ τε Ὀλυμπίας ἀναθήματα καὶ τὰ ἐξ Ἐπιδαύρου καὶ τὰ ἐκ Δελφῶν, ὁπόσα ὑπελίποντο οἱ Φωκεῖς·", "st": "9.7"}, {"sp": "N", "t": "ταῦτα μὲν δὴ διένειμε τῇ στρατιᾷ, τοῖς θεοῖς δὲ ἀντέδωκεν ἀντὶ τῶν χρημάτων γῆς τὴν ἡμίσειαν τῆς Θηβαΐδος. τὴν μὲν δὴ ἀφαίρετον χώραν ὕστερον Ῥωμαίων χάριτι ἀνεσώσαντο οἱ Θηβαῖοι, τὰ δὲ ἄλλα ἐς τὸ ἀσθενέστατον ἀπ’ ἐκείνου προήχθησαν· καί σφισιν ἡ μὲν κάτω πόλις πᾶσα ἔρημος ἦν ἐπ’ ἐμοῦ πλὴν τὰ ἱερά, τὴν δὲ ἀκρόπολιν οἰκοῦσι Θήβας καὶ οὐ Καδμείαν καλουμένην.", "st": "9.7"}, {"sp": "N", "t": "διαβεβηκότι δὲ ἤδη τὸν Ἀσωπὸν καὶ τῆς πόλεως δέκα μάλιστα ἀφεστηκότι σταδίους Ποτνιῶν ἐστιν ἐρείπια καὶ ἐν αὐτοῖς ἄλσος Δήμητρος καὶ Κόρης. τὰ δὲ ἀγάλματα ἐν τῷ ποταμῷ τῷ παρὰ τὰς Ποτνιὰς … τὰς θεὰς ὀνομάζουσιν. ἐν χρόνῳ δὲ εἰρημένῳ δρῶσι καὶ ἄλλα ὁπόσα καθέστηκέ σφισι καὶ ἐς τὰ μέγαρα καλούμενα ἀφιᾶσιν ὗς τῶν νεογνῶν· τοὺς δὲ ὗς τούτους ἐς τὴν ἐπιοῦσαν τοῦ ἔτους ὥραν ἐν Δωδώνῃ φασὶν ἐπὶ … λόγῳ τῷδε ἄλλος πού τις πεισθήσεται.", "st": "9.8"}, {"sp": "N", "t": "ἐνταῦθα καὶ Διονύσον ναός ἐστιν Αἰγοβόλου. θύοντες γὰρ τῷ θεῷ προήχθησάν ποτε ὑπὸ μέθης ἐς ὕβριν, ὥστε καὶ τοῦ Διονύσου τὸν ἱερέα ἀποκτείνουσιν· ἀποκτείναντας δὲ αὐτίκα ἐπέλαβε νόσος λοιμώδης, καί σφισιν ἀφίκετο ἴαμα ἐκ Δελφῶν τῷ Διονύσῳ θύειν παῖδα ὡραῖον· ἔτεσι δὲ οὐ πολλοῖς ὕστερον τὸν θεόν φασιν αἶγα ἱερεῖον ὑπαλλάξαι σφίσιν ἀντὶ τοῦ παιδός. δείκνυται δὲ ἐν Ποτνιαῖς καὶ φρέαρ· τὰς δὲ ἵππους τὰς ἐπιχωρίους τοῦ ὕδατος πιούσας τούτου μανῆναι λέγουσιν.", "st": "9.8"}, {"sp": "N", "t": "ἐκ δὲ τῶν Ποτνιῶν ἰοῦσιν ἐς Θήβας ἔστιν ἐν δεξιᾷ περίβολος τῆς ὁδοῦ [τε] οὐ μέγας καὶ κίονες ἐν αὐτῷ· διαστῆναι δὲ Ἀμφιαράῳ τὴν γῆν ταύτῃ νομίζουσιν, ἐπιλέγοντες καὶ τάδε ἔτι, μήτε ὄρνιθας ἐπὶ τῶν κιόνων καθέζεσθαι τούτων μήτε πόαν τὴν ἐνταῦθα μήτε ἥμερον ζῷον μήτε τῶν ἀγρίων νέμεσθαι.", "st": "9.8"}, {"sp": "N", "t": "Θηβαίοις δὲ ἐν τῷ περιβόλῳ τοῦ ἀρχαίου τείχους ἑπτὰ ἀριθμὸν ἦσαν πύλαι, μένουσι δὲ καὶ ἐς ἡμᾶς ἔτι. τεθῆναι δὲ τὰ ὀνόματα ἐπυνθανόμην σφίσιν ἀπό τε Ἠλέκτρας ἀδελφῆς Κάδμου καὶ Προιτίσιν ἀπὸ ἀνδρὸς τῶν ἐπιχωρίων· ἡλικίαν δὲ Προίτου καὶ τὸ ἀνωτέρω γένος χαλεπὰ ἦν εὑρεῖν. τὰς δὲ Νηίστας ὀνομασθῆναί φασιν ἐπὶ τῷδε. ἐν ταῖς χορδαῖς νήτην καλοῦσι τὴν ἐσχάτην· ταύτην οὖν τὴν χορδὴν Ἀμφίονα ἐπὶ ταῖς πύλαις ταύταις ἀνευρεῖν λέγουσιν. ἤδη δὲ ἤκουσα καὶ ὡς Ζήθου τοῦ ἀδελφοῦ τοῦ Ἀμφίονος τῷ παιδὶ ὄνομα Νῆις γένοιτο, ἀπὸ τούτου δὲ τοῦ Νήϊδος τὰς πύλας κληθῆναι ταύτας.", "st": "9.8"}, {"sp": "N", "t": "πύλας δὲ Κρηναίας, τὰς δὲ Ὑψίστας ἐπὶ λόγῳ τοιῷδε ὀνομάζουσι· … πρὸς δὲ ταῖς Ὑψίσταις Διὸς ἱερὸν ἐπίκλησίν ἐστιν Ὑψίστου. τὰς δὲ ἐπὶ ταύταις πύλας ὀνομάζουσιν Ὠγυγίας, τελευταῖαι δέ εἰσιν Ὁμολωίδες· ἐφαίνετο δὲ εἶναί μοι καὶ τὸ ὄνομα νεώτατον ταῖς πύλαις ταύταις, αἱ δὲ Ὠγύγιαι τὸ ἀρχαιότατον.", "st": "9.8"}, {"sp": "N", "t": "τὰς δὲ Ὁμολωίδας κληθῆναί φασιν ἐπὶ τοιῷδε. ἡνίκα ὑπὸ Ἀργείων μάχῃ πρὸς Γλίσαντι ἐκρατήθησαν, τότε ὁμοῦ Λαοδάμαντι τῷ Ἐτεοκλέους ὑπεξίασιν οἱ πολλοί· τούτων οὖν μοῖρα τὴν μὲν ἐς τοὺς Ἰλλυριοὺς πορείαν ἀπώκνησε, τραπόμενοι δὲ ἐς Θεσσαλοὺς καταλαμβάνουσιν Ὁμόλην, ὀρῶν τῶν Θεσσαλικῶν καὶ εὔγεων μάλιστα καὶ ὕδασιν ἐπιρρεομένην.", "st": "9.8"}, {"sp": "N", "t": "Θερσάνδρου δὲ τοῦ Πολυνείκους ἀνακαλεσαμένου σφᾶς ἐπὶ τὰ οἰκεῖα, τὰς πύλας διὰ ὧν τὴν κάθοδον ἐποιοῦντο ἀπὸ τῆς Ὁμόλης ὀνομάζουσιν Ὁμολωίδας. ἐρχομένῳ δὲ ἐκ Πλαταίας ἔσοδος ἐς τὰς Θήβας κατὰ πύλας ἐστὶν Ἠλέκτρας, καὶ ταύτῃ Καπανέα τὸν Ἱππόνου βιαιοτέρας ποιούμενον πρὸς τὸ τεῖχος τὰς προσβολὰς βληθῆναι κεραυνῷ λέγουσι.", "st": "9.8"}, {"sp": "N", "t": "τὸν δὲ πόλεμον τοῦτον, ὃν ἐπολέμησαν Ἀργεῖοι, νομίζω πάντων, ὅσοι πρὸς Ἕλληνας ἐπὶ τῶν καλουμένων ἡρώων ἐπολεμήθησαν ὑπὸ Ἑλλήνων, γενέσθαι λόγου μάλιστα ἄξιον. ὁ μέν γε Ἐλευσινίων πρὸς Ἀθηναίους τοὺς ἄλλους, ὡσαύτως δὲ καὶ Θηβαίων πρὸς Μινύας, τήν τε ἔφοδον δι’ ὀλίγου τῶν ἐπιστρατευσαμένων καὶ ἐν μάχῃ παρέσχοντο μιᾷ τὴν κρίσιν, ἐς ὁμολογίας τε αὐτίκα ἐτράποντο καὶ σπονδάς·", "st": "9.9"}, {"sp": "N", "t": "ὁ δὲ Ἀργείων στρατὸς ἐς Βοιωτίαν τε μέσην ἀφίκετο ἐκ μέσης Πελοποννήσου καὶ ὁ Ἄδραστος ἐξ Ἀρκαδίας καὶ παρὰ Μεσσηνίων συμμαχικὰ ἤθροισεν, ὡσαύτως δὲ καὶ τοῖς Θηβαίοις μισθοφορικὰ ἦλθε παρὰ Φωκέων καὶ ἐκ τῆς Μινυάδος χώρας οἱ Φλεγύαι. γενομένης δὲ πρὸς τῷ Ἰσμηνίῳ μάχης ἐκρατήθησαν οἱ Θηβαῖοι τῇ συμβολῇ, καὶ ὡς ἐτράποντο, καταφεύγουσιν ἐς τὸ τεῖχος·", "st": "9.9"}, {"sp": "N", "t": "ἅτε δὲ οὐκ ἐπισταμένων τῶν Πελοποννησίων μάχεσθαι πρὸς τὸ τεῖχος, ποιουμένων δὲ θυμῷ μᾶλλον ἢ σὺν ἐπιστήμῃ τὰς προσβολάς, πολλοὺς μὲν ἀπὸ τοῦ τείχους βάλλοντες φονεύουσιν αὐτῶν οἱ Θηβαῖοι, κρατοῦσι δὲ ὕστερον καὶ τοὺς ἄλλους ἐπεξελθόντες τεταραγμένοις, ὡς τὸ σύμπαν στράτευμα πλὴν Ἀδράστου φθαρῆναι. ἐγένετο δὲ καὶ αὐτοῖς τὸ ἔργον οὐκ ἄνευ κακῶν μεγάλων, καὶ ἀπ’ ἐκείνου τὴν σὺν ὀλέθρῳ τῶν κρατησάντων Καδμείαν ὀνομάζουσι νίκην.", "st": "9.9"}, {"sp": "N", "t": "ἔτεσι δὲ οὐ πολλοῖς ὕστερον ὁμοῦ Θερσάνδρῳ στρατεύουσιν ἐπὶ τὰς Θήβας οὓς Ἐπιγόνους καλοῦσιν Ἕλληνες· δῆλοι δέ εἰσι καὶ τούτοις οὐ τὸ Ἀργολικὸν μόνον οὐδὲ οἱ Μεσσήνιοι καὶ Ἀρκάδες ἠκολουθηκότες, ἀλλὰ καὶ ἔτι ἐκ Κορίνθου καὶ Μεγαρέων ἐπικληθέντες ἐς τὴν συμμαχίαν· ἤμυναν δὲ καὶ Θηβαίοις οἱ πρόσοικοι, καὶ μάχη πρὸς Γλίσαντι ἀπὸ ἀμφοτέρων ἐγένετο ἰσχυρά.", "st": "9.9"}, {"sp": "N", "t": "τῶν δὲ Θηβαίων οἱ μὲν αὐτίκα ὡς ἡττήθησαν ὁμοῦ Λαοδάμαντι ἐκδιδράσκουσιν, οἱ δὲ ὑπολειφθέντες πολιορκίᾳ παρέστησαν. ἐποιήθη δὲ ἐς τὸν πόλεμον τοῦτον καὶ ἔπη Θηβαΐς· τὰ δὲ ἔπη ταῦτα Καλλῖνος ἀφικόμενος αὐτῶν ἐς μνήμην ἔφησεν Ὅμηρον τὸν ποιήσαντα εἶναι, Καλλίνῳ δὲ πολλοί τε καὶ ἄξιοι λόγου κατὰ ταὐτὰ ἔγνωσαν· ἐγὼ δὲ τὴν ποίησιν ταύτην μετά γε Ἰλιάδα καὶ τὰ ἔπη τὰ ἐς Ὀδυσσέα ἐπαινῶ μάλιστα. πολέμου μὲν δή, ὃν Ἀργεῖοι καὶ Θηβαῖοι τῶν Οἰδίποδος παίδων ἕνεκα ἐπολέμησαν, ἐς τοσόνδε ἔστω μνήμη·", "st": "9.9"}, {"sp": "N", "t": "πολυάνδριον δὲ οὐ μακρὰν ἀπὸ τῶν πυλῶν ἐστι· κεῖνται δὲ ὁπόσους κατέλαβεν ἀποθανεῖν Ἀλεξάνδρῳ καὶ Μακεδόσιν ἀντιτεταγμένους. οὐ πόρρω δὲ ἀποφαίνουσι χωρίον ἔνθα Κάδμον λέγουσιν— ὅτῳ πιστά—τοῦ δράκοντος, ὃν ἀπέκτεινεν ἐπὶ τῇ κρήνῃ, τοὺς ὀδόντας σπείραντα, ἄνδρας δὲ ἀπὸ τῶν ὀδόντων ἀνεῖναι τὴν γῆν.", "st": "9.10"}, {"sp": "N", "t": "ἔστι δὲ λόφος ἐν δεξιᾷ τῶν πυλῶν ἱερὸς Ἀπόλλωνος· καλεῖται δὲ ὅ τε λόφος καὶ ὁ θεὸς Ἰσμήνιος, παραρρέοντος τοῦ ποταμοῦ ταύτῃ τοῦ Ἰσμηνοῦ. πρῶτα μὲν δὴ λίθου κατὰ τὴν ἔσοδόν ἐστιν Ἀθηνᾶ καὶ Ἑρμῆς, ὀνομαζόμενοι Πρόναοι· ποιῆσαι δὲ αὐτὸν Φειδίας, τὴν δὲ Ἀθηνᾶν λέγεται Σκόπας· μετὰ δὲ ὁ ναὸς ᾠκοδόμηται. τὸ δὲ ἄγαλμα μεγέθει τε ἴσον τῷ ἐν Βραγχίδαις ἐστὶ καὶ τὸ εἶδος οὐδὲν διαφόρως ἔχον· ὅστις δὲ τῶν ἀγαλμάτων τούτων τὸ ἕτερον εἶδε καὶ τὸν εἰργασμένον ἐπύθετο, οὐ μεγάλη οἱ σοφία καὶ τὸ ἕτερον θεασαμένῳ Κανάχου ποίημα ὂν ἐπίστασθαι. διαφέρουσι δὲ τοσόνδε· ὁ μὲν γὰρ ἐν Βραγχίδαις χαλκοῦ, ὁ δὲ Ἰσμήνιός ἐστι κέδρου.", "st": "9.10"}, {"sp": "N", "t": "ἔστι δ’ ἐνταῦθα λίθος ἐφ’ ᾧ Μαντώ φασι τὴν Τειρεσίου καθέζεσθαι. οὗτος μὲν πρὸ τῆς ἐσόδου κεῖται, καί οἱ τὸ ὄνομά ἐστι καὶ ἐς ἡμᾶς ἔτι Μαντοῦς δίφρος· ἐν δεξιᾷ δὲ τοῦ ναοῦ λίθου πεποιημένας εἰκόνας Ἡνιόχης εἶναι, τὴν δὲ Πύρρας λέγουσι, θυγατέρας δὲ αὐτὰς εἶναι Κρέοντος, ὃς ἐδυνάστευεν ἐπιτροπεύων Λαοδάμαντα τὸν Ἐτεοκλέους.", "st": "9.10"}, {"sp": "N", "t": "τόδε γε καὶ ἐς ἐμὲ ἔτι γινόμενον οἶδα ἐν Θήβαις· τῷ Ἀπόλλωνι τῷ Ἰσμηνίῳ παῖδα οἴκου τε δοκίμου καὶ αὐτὸν εὖ μὲν εἴδους, εὖ δὲ ἔχοντα καὶ ῥώμης, ἱερέα ἐνιαύσιον ποιοῦσιν· ἐπίκλησις δέ ἐστίν οἱ δαφναφόρος, στεφάνους γὰρ φύλλων δάφνης φοροῦσιν οἱ παῖδες. εἰ μὲν οὖν πᾶσιν ὁμοίως καθέστηκεν ἀναθεῖναι δαφνηφορήσαντας χαλκοῦν τῷ θεῷ τρίποδα, οὐκ ἔχω δηλῶσαι, δοκῶ δὲ οὐ πᾶσιν εἶναι νόμον· οὐ γὰρ δὴ πολλοὺς ἑώρων αὐτόθι ἀνακειμένους· οἱ δ’ οὖν εὐδαιμονέστεροι τῶν παίδων ἀνατιθέασιν. ἐπιφανὴς δὲ μάλιστα ἐπί τε ἀρχαιότητι καὶ τοῦ ἀναθέντος τῇ δόξῃ τρίπους ἐστὶν Ἀμφιτρύωνος ἀνάθημα ἐπὶ Ἡρακλεῖ δαφνηφορήσαντι.", "st": "9.10"}, {"sp": "N", "t": "ἀνωτέρω δὲ τοῦ Ἰσμηνίου τὴν κρήνην ἴδοις ἄν, ἥντινα Ἄρεώς φασιν ἱερὰν εἶναι καὶ δράκοντα ὑπὸ τοῦ Ἄρεως ἐπιτετάχθαι φύλακα τῇ πηγῇ. πρὸς ταύτῃ τῇ κρήνῃ τάφος ἐστὶ Καάνθου· Μελίας δὲ ἀδελφὸν καὶ Ὠκεανοῦ παῖδα εἶναι Κάανθον λέγουσι, σταλῆναι δὲ ὑπὸ τοῦ πατρὸς ζητήσοντα ἡρπασμένην τὴν ἀδελφήν. ὡς δὲ Ἀπόλλωνα εὑρὼν ἔχοντα τὴν Μελίαν οὐκ ἐδύνατο ἀφελέσθαι, πῦρ ἐτόλμησεν ἐς τὸ τέμενος ἐνεῖναι τοῦ Ἀπόλλωνος τοῦτο ὃ νῦν καλοῦσιν Ἰσμήνιον· καὶ αὐτὸν ὁ θεός, καθά φασιν οἱ Θηβαῖοι, τοξεύει.", "st": "9.10"}, {"sp": "N", "t": "Καάνθου μὲν ἐνταῦθά ἐστι μνῆμα, Ἀπόλλωνι δὲ παῖδας ἐκ Μελίας γενέσθαι λέγουσι Τήνερον καὶ Ἰσμηνόν· Τηνέρῳ μὲν Ἀπόλλων μαντικὴν δίδωσι, τοῦ δὲ Ἰσμηνίου τὸ ὄνομα ἔσχεν ὁ ποταμός. οὐ μὴν οὐδὲ τὰ πρότερα ἦν ἀνώνυμος, εἰ δὴ καὶ Λάδων ἐκαλεῖτο πρὶν Ἰσμηνὸν γενέσθαι τὸν Ἀπόλλωνος.", "st": "9.10"}, {"sp": "N", "t": "ἐν ἀριστερᾷ δὲ τῶν πυλῶν, ἃς ὀνομάζουσιν Ἠλέκτρας, οἰκίας ἐστὶν ἐρείπια ἔνθα οἰκῆσαί φασιν Ἀμφιτρύωνα διὰ τὸν Ἠλεκτρύωνος θάνατον φεύγοντα ἐκ Τίρυνθος· καὶ τῆς Ἀλκμήνης ἐστὶν ἔτι ὁ θάλαμος ἐν τοῖς ἐρειπίοις δῆλος. οἰκοδομῆσαι δὲ αὐτὸν τῷ Ἀμφιτρύωνι Τροφώνιόν φασι καὶ Ἀγαμήδην, καὶ ἐπίγραμμα ἐπ’ αὐτῷ ἐπιγραφῆναι τόδε·<br>Ἀμφιτρύων ὅτ’ ἔμελλ’ ἀγαγέσθαι δεῦρο γυναῖκα<br>Ἀλκμήνην, θάλαμόν γ’ εἱλίξατο τοῦτον ἑαυτῷ·<br>Ἀγχάσιος δ’ ἐποίησε Τροφώνιος ἠδ’ Ἀγαμήδης.", "st": "9.11"}, {"sp": "N", "t": "τοῦτο μὲν ἐνταῦθα οἱ Θηβαῖοι γραφῆναι λέγουσιν· ἐπιδεικνύουσι δὲ Ἡρακλέους τῶν παίδων τῶν ἐκ Μεγάρας μνῆμα, οὐδέν τι ἀλλοίως τὰ ἐς τὸν θάνατον λέγοντες ἢ Στησίχορος ὁ Ἱμεραῖος καὶ Πανύασσις ἐν τοῖς ἔπεσιν ἐποίησαν. Θηβαῖοι δὲ καὶ τάδε ἐπιλέγουσιν, ὡς Ἡρακλῆς ὑπὸ τῆς μανίας καὶ Ἀμφιτρύωνα ἔμελλεν ἀποκτιννύναι, πρότερον δὲ ἄρα ὕπνος ἐπέλαβεν αὐτὸν ὑπὸ τοῦ λίθου τῆς πληγῆς· Ἀθηνᾶν δὲ εἶναι τὴν ἐπαφεῖσάν οἱ τὸν λίθον τοῦτον ὅντινα Σωφρονιστῆρα ὀνομάζουσιν.", "st": "9.11"}, {"sp": "N", "t": "ἐνταῦθά εἰσιν ἐπὶ τύπου γυναικῶν εἰκόνες· ἀμυδρότερα ἤδη τὰ ἀγάλματα· ταύτας καλοῦσιν οἱ Θηβαῖοι Φαρμακίδας, πεμφθῆναι δὲ ὑπὸ τῆς Ἤρας φασὶν ἐμπόδια εἶναι ταῖς ὠδῖσιν Ἀλκμήνης. αἱ μὲν δὴ ἐπεῖχον Ἀλκμήνην μὴ τεκεῖν· Τειρεσίου δὲ θυγατρὶ Ἱστορίδι σόφισμα ἔπεισιν ἐς τὰς Φαρμακίδας, ⟨ἐς⟩ ἐπήκοον αὐτῶν ὀλολύξαι, τετοκέναι γὰρ τὴν Ἀλκμήνην· οὕτω τὰς μὲν ἀπατηθείσας ἀπελθεῖν, τὴν δὲ Ἀλκμήνην τεκεῖν φασιν.", "st": "9.11"}, {"sp": "N", "t": "ἐνταῦθα Ἡρακλεῖόν ἐστιν, ἄγαλμα δὲ τὸ μὲν λίθου λευκοῦ Πρόμαχος καλούμενον, ἔργον δὲ Ξενοκρίτου καὶ Εὐβίου Θηβαίων· τὸ δὲ ξόανον τὸ ἀρχαῖον Θηβαῖοί τε εἶναι Δαιδάλου νενομίκασι καὶ αὐτῷ μοι παρίστατο ἔχειν οὕτω. τοῦτον ἀνέθηκεν αὐτός, ὡς λέγεται, Δαίδαλος ἐκτίνων εὐεργεσίας χάριν. ἡνίκα γὰρ ἔφευγεν ἐκ Κρήτης πλοῖα οὐ μεγάλα αὑτῷ καὶ τῷ παιδὶ Ἰκάρῳ ποιησάμενος, πρὸς δὲ καὶ ταῖς ναυσίν, ὃ μή πω τοῖς τότε ἐξεύρητο, ἱστία ἐπιτεχνησάμενος, ὡς τοῦ Μίνω ναυτικοῦ τὴν εἰρεσίαν φθάνοιεν ἐπιφόρῳ τῷ ἀνέμῳ χρώμενοι, τότε αὐτὸς μὲν σώζεται Δαίδαλος,", "st": "9.11"}, {"sp": "N", "t": "Ἰκάρῳ δὲ κυβερνῶντι ἀμαθέστερον ἀνατραπῆναι τὴν ναῦν λέγουσιν· ἀποπνιγέντα δὲ ἐξήνεγκεν ὁ κλύδων ἐς τὴν ὑπὲρ Σάμου νῆσον ἔτι οὖσαν ἀνώνυμον. ἐπιτυχὼν δὲ Ἡρακλῆς γνωρίζει τὸν νεκρόν, καὶ ἔθαψεν ἔνθα καὶ νῦν ἔτι αὐτῷ χῶμα οὐ μέγα ἐπὶ ἄκρας ἐστὶν ἀνεχούσης ἐς τὸ Αἰγαῖον. ἀπὸ δὲ τοῦ Ἰκάρου τούτου ὄνομα ἥ τε νῆσος καὶ ἡ περὶ αὐτὴν θάλασσα ἔσχηκε.", "st": "9.11"}, {"sp": "N", "t": "Θηβαίοις δὲ τὰ ἐν τοῖς ἀετοῖς Πραξιτέλης ἐποίησε τὰ πολλὰ τῶν δώδεκα καλουμένων ἄθλων· καί σφισι τὰ ἐς τὰς ὄρνιθας ἐνδεῖ τὰς ἐπὶ Στυμφάλῳ καὶ ὡς ἐκάθηρεν Ἡρακλῆς τὴν Ἠλείαν χώραν, ἀντὶ τούτων δὲ ἡ πρὸς Ἀνταῖον πάλη πεποίηται. Θρασύβουλος δὲ ὁ Λύκου καὶ Ἀθηναίων οἱ σὺν αὐτῷ τυραννίδα τὴν τῶν τριάκοντα καταλύσαντες—ὁρμηθεῖσι γάρ σφισιν ἐκ Θηβῶν ἐγένετο ἡ κάθοδος—Ἀθηνᾶν καὶ Ἡρακλέα κολοσσοὺς ἐπὶ λίθου τύπου τοῦ Πεντελῆσιν, ἔργα δὲ Ἀλκαμένους, ἀνέθηκαν ἐς τὸ Ἡρακλεῖον.", "st": "9.11"}, {"sp": "N", "t": "τοῦ δὲ Ἡρακλείου γυμνάσιον ἔχεται καὶ στάδιον, ἀμφότερα ἐπώνυμα τοῦ θεοῦ. ὑπὲρ δὲ τὸν Σωφρονιστῆρα λίθον βωμός ἐστιν Ἀπόλλωνος ἐπίκλησιν Σποδίου, πεποίηται δὲ ἀπὸ τῆς τέφρας τῶν ἱερείων. μαντικὴ δὲ καθέστηκεν αὐτόθι ἀπὸ κληδόνων, ᾗ δὴ καὶ Σμυρναίους μάλιστα Ἑλλήνων χρωμένους οἶδα· ἔστι γὰρ καὶ Σμυρναίοις ὑπὲρ τὴν πόλιν κατὰ τὸ ἐκτὸς τοῦ τείχους Κληδόνων ἱερόν.", "st": "9.11"}, {"sp": "N", "t": "τῷ δὲ Ἀπόλλωνι Θηβαῖοι τῷ Σποδίῳ ταύρους ἔθυον τὸ ἀρχαῖον· καί ποτε παρούσης σφίσι τῆς ἑορτῆς ἥ τε ὥρα κατήπειγε τῆς θυσίας καὶ οἱ πεμφθέντες ἐπὶ τὸν ταῦρον οὐχ ἧκον· οὕτω δὴ παρατυχούσης ἁμάξης τὸν ἕτερον τῶν βοῶν τῷ θεῷ θύουσι καὶ ἀπ’ ἐκείνου ἐργάτας βοῦς θύειν νομίζουσι. λέγεται δὲ καὶ ὅδε ὑπ’ αὐτῶν λόγος, ⟨ὡς⟩ ἀπιόντι ἐκ Δελφῶν Κάδμῳ τὴν ἐπὶ Φωκέων βοῦς γένοιτο ἡγεμὼν τῆς πορείας, τὴν δὲ βοῦν ταύτην παρὰ βουκόλων εἶναι τῶν Πελάγοντος ὠνητήν· ἐπὶ δὲ ἑκατέρᾳ τῆς βοὸς πλευρᾷ σημεῖον ἐπεῖναι λευκὸν εἰκασμένον κύκλῳ τῆς σελήνης, ὁπότε εἴη πλήρης.", "st": "9.12"}, {"sp": "N", "t": "ἔδει δὲ ἄρα Κάδμον καὶ τὸν σὺν αὐτῷ στρατὸν ἐνταῦθα οἰκῆσαι κατὰ τοῦ θεοῦ τὴν μαντείαν, ἔνθα ἡ βοῦς ἔμελλε καμοῦσα ὀκλάσειν· ἀποφαίνουσιν οὖν καὶ τοῦτο τὸ χωρίον. ἐνταῦθα ἔστι μὲν ἐν ὑπαίθρῳ βωμὸς καὶ ἄγαλμα ⟨Ἀθηνᾶς⟩· ἀναθεῖναι δὲ αὐτὸ Κάδμον λέγουσι. τοῖς οὖν νομίζουσιν ἐς γῆν ἀφικέσθαι Κάδμον τὴν Θηβαΐδα Αἰγύπτιον καὶ οὐ Φοίνικα ὄντα, ἔστιν ἐναντίον τῷ λόγῳ τῆς Ἀθηνᾶς ταύτης τὸ ὄνομα, ὅτι Ὄγγα κατὰ γλῶσσαν τὴν Φοινίκων καλεῖται καὶ οὐ Σάις κατὰ τὴν Αἰγυπτίων φωνήν.", "st": "9.12"}, {"sp": "N", "t": "φασὶ δὲ οἱ Θηβαῖοι, καθότι τῆς ἀκροπόλεως ἀγορά σφισιν ἐφ’ ἡμῶν πεποίηται, Κάδμου τὸ ἀρχαῖον οἰκίαν εἶναι· θαλάμων δὲ ἀποφαίνουσι τοῦ μὲν Ἁρμονίας ἐρείπια καὶ ὃν Σεμέλης φασὶν εἶναι, τοῦτον δὲ καὶ ἐς ἡμᾶς ἔτι ἄβατον φυλάσσουσιν ἀνθρώποις. Ἑλλήνων δὲ τοῖς ἀποδεχομένοις ᾆσαι Μούσας ἐς τὸν Ἁρμονίας γάμον τὸ χωρίον ἐστὶν ἐπὶ τῆς ἀγορᾶς, ἔνθα δή φασι τὰς θεὰς ᾆσαι.", "st": "9.12"}, {"sp": "N", "t": "λέγεται δὲ καὶ τόδε, ὡς ὁμοῦ τῷ κεραυνῷ βληθέντι ἐς τὸν Σεμέλης θάλαμον πέσοι ξύλον ἐξ οὐρανοῦ· Πολύδωρον δὲ τὸ ξύλον τοῦτο χαλκῷ λέγουσιν ἐπικοσμήσαντα Διόνυσον καλέσαι Κάδμον. πλησίον δὲ Διονύσου ἄγαλμα, καὶ τοῦτο Ὀνασιμήδης ἐποίησε δι’ ὅλου πλῆρες ὑπὸ τοῦ χαλκοῦ· τὸν βωμὸν δὲ οἱ παῖδες εἰργάσαντο οἱ Πραξιτέλους.", "st": "9.12"}, {"sp": "N", "t": "ἀνδριάς τέ ἐστι Προνόμου ἀνδρὸς αὐλήσαντος ἐπαγωγότατα ἐς τοὺς πολλούς. τέως μέν γε ἰδέας αὐλῶν τρεῖς ἐκτῶντο οἱ αὐληταὶ καὶ τοῖς μὲν αὔλημα ηὔλουν τὸ Δώριον, διάφοροι δὲ αὐτοῖς ἐς ἁρμονίαν τὴν Φρύγιον ἐπεποίηντο οἱ αὐλοί, τὸ δὲ καλούμενον Λύδιον ἐν αὐλοῖς ηὐλεῖτο ἀλλοίοις· Πρόνομος δὲ ἦν ὃς πρῶτος ἐπενόησεν αὐλοὺς ἐς ἅπαν ἁρμονίας εἶδος ἔχοντας ἐπιτηδείως, πρῶτος δὲ διάφορα ἐς τοσοῦτο μέλη ἐπ’ αὐλοῖς ηὔλησε τοῖς αὐτοῖς.", "st": "9.12"}, {"sp": "N", "t": "λέγεται δὲ ὡς καὶ τοῦ προσώπου τῷ σχήματι καὶ τῇ τοῦ παντὸς κινήσει σώματος περισσῶς δή τι ἔτερπε τὰ θέατρα· καί οἱ καὶ ᾆσμα πεποιημένον ἐστὶ [ἐς] προσόδιον ἐς Δῆλον τοῖς ἐπ’ Εὐρίπῳ Χαλκιδεῦσι. τοῦτόν τε οὖν ἐνταῦθα οἱ Θηβαῖοι καὶ Ἐπαμινώνδαν τὸν Πολύμνιδος ἀνέθεσαν.", "st": "9.12"}, {"sp": "N", "t": "τῷ δ’ Ἐπαμινώνδᾳ τὰ μὲν τῶν προγόνων ὑπῆρχεν ἐς γένους δόξαν, ὁ δέ οἱ πατὴρ χρημάτων ἕνεκα μέσου ἀνδρὸς ἀπέδει Θηβαίου· διδάγματα δὲ αὐτοῖς τά τε ἐπιχώρια ἔμαθεν ἐς τὸ ἀκριβέστατον καὶ ὡς ἤδη μειράκιον ἦν ἐφοίτησεν ὡς Λῦσιν, ἄνδρα γένος μὲν Ταραντῖνον, ἐπιστάμενον δὲ τοὺς Πυθαγόρου τοῦ Σαμίου λόγους. λέγεται δὲ ὁ Ἐπαμινώνδας, ἡνίκα ἐπολέμουν Λακεδαιμόνιοι Μαντινεῦσι, πεμφθῆναι σὺν ἄλλοις ἀνδράσιν ἐκ Θηβῶν Λακεδαιμονίοις ἐπαμύνειν· ἔχοντα δὲ τραύματα ἐν τῇ μάχῃ Πελοπίδαν ἐξέσωσεν ἐς ἅπαν ἀφικόμενος κινδύνου.", "st": "9.13"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον κατὰ πρεσβείαν ἐς Σπάρτην ἥκοντα Ἐπαμινώνδαν, ὅτε Λακεδαιμόνιοι συντίθεσθαι τοῖς Ἕλλησιν ἔφασαν εἰρήνην ⟨τὴν⟩ ἐπὶ Ἀνταλκίδου καλουμένην, τηνικαῦτα Ἐπαμινώνδαν ἤρετο Ἀγησίλαος, εἰ κατὰ πόλιν ὀμνύναι Βοιωτοὺς ἐάσουσιν ὑπὲρ τῆς εἰρήνης· “οὐ πρότερόν γε” εἶπεν “ὦ Σπαρτιᾶται, πρὶν ἢ καὶ τοὺς περιοίκους ὀμνύοντας κατὰ πόλιν ἴδωμεν τοὺς ὑμετέρους”.", "st": "9.13"}, {"sp": "N", "t": "ὡς δὲ ὁ Λακεδαιμονίων καὶ Θηβαίων ἐξῆρτο ἤδη πόλεμος καὶ οἱ Λακεδαιμόνιοι δυνάμει καὶ αὑτῶν καὶ τῶν συμμάχων ἐπὶ τοὺς Θηβαίους ᾔεσαν, Ἐπαμινώνδας μὲν ἔχων τοῦ στρατοῦ μοῖραν ἀντεκάθητο ὑπὲρ τῆς Κηφισίδος λίμνης ὡς ποιησομένων ταύτῃ Πελοποννησίων τὴν ἐσβολήν, Κλεόμβροτος δὲ ὁ Λακεδαιμονίων βασιλεὺς ἐπὶ Ἀμβρόσσου τρέπεται τῆς Φωκέων· ἀποκτείνας δὲ Χαιρέαν, ὃς φυλάσσειν διετέτακτο τὰς παρόδους, καὶ ἄλλους τοὺς σὺν αὐτῷ Θηβαίους, ὑπερέβη καὶ ἐς Λεῦκτρα ἀφικνεῖται τὰ Βοιώτια.", "st": "9.13"}, {"sp": "N", "t": "ἐνταῦθα καὶ αὐτῷ Κλεομβρότῳ καὶ Λακεδαιμονίων τῷ κοινῷ σημεῖα ἐγένετο ἐκ τοῦ θεοῦ. τοῖς βασιλεῦσιν αὐτῶν ἐς τὰς ἐξόδους πρόβατα εἵπετο θεοῖς τε εἶναι θυσίας καὶ πρὸ τῶν ἀγώνων καλλιερεῖν· ταῖς δὲ ποίμναις ἡγεμόνες τῆς πορείας ἦσαν αἶγες, κατοιάδας οἱ ποιμένες ὀνομάζουσιν αὐτάς. τότε οὖν ὁρμήσαντες ἐς τὴν ποίμνην λύκοι τοῖς μὲν προβάτοις ἐγίνοντο οὐδὲν βλάβος, οἱ δὲ τὰς αἶγας τὰς κατοιάδας ἔκτεινον.", "st": "9.13"}, {"sp": "N", "t": "ἐλέγετο δὲ καὶ μήνιμα ἐς τοὺς Λακεδαιμονίους ἐκ τῶν θυγατέρων εἶναι τῶν Σκεδάσου. Σκεδάσῳ γὰρ περὶ Λεῦκτρα οἰκοῦντι θυγατέρες Μολπία γίνεται καὶ Ἱππώ· ταύτας ἐς ὥραν ἤδη προηκούσας Λακεδαιμονίων ἄνδρες βιάζονται παρὰ θέμιδα[ς καὶ] Φρουραρχίδας καὶ Παρθένιος. καὶ αἵ τε παρθένοι παραυτίκα—οὐ γάρ σφισιν ἀνεκτὰ ἐφαίνετο εἶναι τὰ τῆς ὕβρεως—ἀπάγχουσιν αὑτάς· καὶ ὁ Σκέδασος, ὡς ἐς Λακεδαίμονα ἐλθόντι οὐδεμία ἐγένετο αὐτῷ δίκη, οὕτως ἐς τὰ Λεῦκτρα ἐπανήκων αὑτὸν διεργάζεται.", "st": "9.13"}, {"sp": "N", "t": "τότε δὲ ὁ Ἐπαμινώνδας Σκεδάσῳ καὶ ταῖς παισὶν ἐνήγιζέ τε καὶ εὔχετο, ὡς οὐ μᾶλλον ὑπὲρ σωτηρίας Θηβαίων ἢ καὶ τιμωρίας ἐκείνων τὸν ἀγῶνα ἐσόμενον. τῶν δὲ βοιωταρχούντων οὐ κατὰ ταὐτὰ ἐγίνοντο αἱ γνῶμαι, διεστηκυῖαι δὲ πολὺ ἀπ’ ἀλλήλων· Ἐπαμινώνδᾳ μὲν γὰρ ἤρεσκε καὶ Μάλγιδι καὶ Ξενοκράτει κατὰ τάχος πρὸς τοὺς Λακεδαιμονίους ποιεῖσθαι μάχην, Δαμοκλείδας δὲ καὶ Δαμόφιλος καὶ Σιμάγγελος συμβάλλειν μὲν οὐκ εἴων, ἐκέλευον δὲ ὑπεκθεμένους ἐς τὴν Ἀττικὴν γυναῖκας καὶ παῖδας ὡς πολιορκησομένους αὐτοὺς παρασκευάζεσθαι.", "st": "9.13"}, {"sp": "N", "t": "τῶν μὲν δὴ ἓξ ἐς τοσοῦτον ἦν κεχωρισμένα τὰ βουλεύματα· προσγενομένης δὲ ψήφου τοῖς περὶ τὸν Ἐπαμινώνδαν τοῦ ἑβδόμου τῶν Βοιωταρχῶν, ὃς ἐφρούρει μὲν τὴν κατὰ τὸν Κιθαιρῶνα ἐσβολήν, ὄνομα δὲ ἦν οἱ Βραχυλλίδης, τούτου τοῦ ἀνδρός, ὡς ἐπανῆλθεν ἐς τὸ στρατόπεδον, προσθεμένου τοῖς περὶ τὸν Ἐπαμινώνδαν, τότε καὶ πᾶσιν ἐδέδοκτο ἀγῶνι διακρίνεσθαι.", "st": "9.13"}, {"sp": "N", "t": "τῷ δὲ Ἐπαμινώνδᾳ καὶ ἐς ἄλλους Βοιωτῶν ὕποπτα ἦν, ἐς δὲ τοὺς Θεσπιεῖς καὶ περισσότερον· δείσας οὖν μὴ σφᾶς παρὰ τὸ ἔργον προδῶσιν, ἀποχώρησιν παρεῖχεν ἀπὸ στρατοπέδου τοῖς ἐθέλουσιν οἴκαδε· καὶ οἱ Θεσπιεῖς τε ἀπαλλάσσονται πανδημεὶ καὶ εἴ τισιν ἄλλοις Βοιωτῶν ὑπῆν δύσνοια ἐς τοὺς Θηβαίους.", "st": "9.13"}, {"sp": "N", "t": "ὡς δὲ ἐς χεῖρας συνῄεσαν, ἐνταῦθα οἱ σύμμαχοι τῶν Λακεδαιμονίων ἅτε αὐτοῖς καὶ τὸν πρὸ τοῦ χρόνον οὐκ ἀρεσκόμενοι τὸ ἔχθος μάλιστα ἐπεδείκνυντο, οὔτε κατὰ χώραν μένειν ἐθέλοντες, ἐνδιδόντες δὲ ὅπῃ σφίσιν οἱ πολέμιοι προσφέροιντο. αὐτοὺς δὲ Λακεδαιμονίους καὶ Θηβαίους ἐξ ἴσου καθίστη τοὺς μὲν ἐμπειρία τε ἡ προϋπάρχουσα καὶ ἅμα αἰδουμένους μὴ καταλῦσαι τῆς Σπάρτης τὸ ἀξίωμα, Θηβαῖοι δὲ ὑπὲρ τῆς πατρίδος καὶ πρὸ γυναικῶν καὶ παίδων τὸν κίνδυνον ἐφεστηκότα ἑώρων.", "st": "9.13"}, {"sp": "N", "t": "ὡς δὲ ἄλλοι τε Λακεδαιμονίων τῶν ἐν τέλει καὶ ὁ βασιλεὺς ἐτεθνήκει Κλεόμβροτος, ἐνταῦθα [καὶ] τοὺς Σπαρτιάτας καὶ ταλαιπωρουμένους ἐπελάμβανεν ἀνάγκη μὴ ἐνδιδόναι· παρὰ γὰρ τοῖς Λακεδαιμονίοις αἴσχιστον ἐδέδοκτο εἶναι βασιλέως νεκρὸν ἐπὶ ἀνδράσι πολεμίοις γενόμενον περιοφθῆναι.", "st": "9.13"}, {"sp": "N", "t": "Θηβαίοις μὲν ἡ νίκη κατείργαστο ἐπιφανέστατα πασῶν ὁπόσας κατὰ Ἑλλήνων ἀνείλοντο Ἕλληνες· Λακεδαιμόνιοι δὲ ἐς τὴν ὑστεραίαν τοὺς τεθνεῶτας διενοοῦντο ὡς θάψοντες καὶ ἀποστέλλουσι κήρυκα ἐς τοὺς Θηβαίους. Ἐπαμινώνδας δέ, ἐπιστάμενος ὡς ἐπικρύπτεσθαι τὰς συμφορὰς ἀεί ποτε οἱ Λακεδαιμόνιοι πεφύκασιν, ἔφασκεν ἀναίρεσιν τῶν νεκρῶν προτέροις αὐτῶν διδόναι τοῖς συμμάχοις, ἐπὶ δὲ ἐκείνοις ἀνελομένοις οὕτω καὶ τοὺς Λακεδαιμονίους ἠξίου θάπτειν τοὺς αὑτῶν.", "st": "9.13"}, {"sp": "N", "t": "ὡς δὲ τῶν συμμάχων οἱ μὲν οὐδὲ ἀρχὴν ἀνῃροῦντο ἅτε οὐ τεθνεῶτός σφισιν οὐδενός, τῶν δὲ ὀλίγον ἐφαίνετο εἶναι τὸ διεφθαρμένον, οὕτω Λακεδαιμόνιοί τε ἔθαπτον τοὺς αὑτῶν καὶ ἤδη Σπαρτιάτας ἐξελήλεγκτο εἶναι τοὺς κειμένους. ἀπέθανον δὲ Θηβαίων τε καὶ ὅσοι παρέμειναν Βοιωτῶν ἑπτὰ καὶ τεσσαράκοντα ἄνδρες, Λακεδαιμονίων δὲ αὐτῶν πλείους ἢ χίλιοι.", "st": "9.13"}, {"sp": "N", "t": "τὸ μὲν δὴ παραυτίκα ὁ Ἐπαμινώνδας μετὰ τὴν μάχην Πελοποννησίων τοῖς λοιποῖς ἀπιέναι προειπὼν ἐπὶ τὰ οἰκεῖα Λακεδαιμονίους ἐν τοῖς Λεύκτροις εἶχεν ἀπειλημμένους· ὡς δὲ ἤκουε τοὺς ἐκ τῆς πόλεως Σπαρτιάτας βοηθήσοντας τοῖς σφετέροις ἐς Λεῦκτρα ἰέναι πανδημεί, δίδωσιν οὕτω τοῖς ἀνδράσιν ἀπελθεῖν ὑποσπόνδους ἔφη τε ἄμεινον ἔσεσθαι τὸν πόλεμόν σφισιν ἐκ Βοιωτῶν ἐς τὴν Λακεδαίμονα ἀπώσασθαι.", "st": "9.14"}, {"sp": "N", "t": "Θεσπιεῦσι δέ, ὑφορωμένοις τήν τε ἐξ ἀρχῆς ἐκ τῶν Θηβαίων δυσμένειαν καὶ τὴν ἐν τῷ παρόντι αὐτῶν τύχην, τὴν μὲν πόλιν ἔδοξεν ἐκλιπεῖν, ἀναφεύγειν δὲ ἐς Κερησσόν. ἔστι δὲ ἐχυρὸν χωρίον ὁ Κερησσὸς ἐν τῇ Θεσπιέων, ἐς ὃ καὶ πάλαι ποτὲ ἀνεσκευάσαντο κατὰ τὴν ἐπιστρατείαν τὴν Θεσσαλῶν· οἱ Θεσσαλοὶ δὲ τότε, ὡς ἑλεῖν τὸν Κερησσόν σφισι πειρωμένοις ἐφαίνετο ἐλπίδος κρεῖσσον, ἀφίκοντο ἐς Δελφοὺς παρὰ τὸν θεόν, καὶ", "st": "9.14"}, {"sp": "N", "t": "αὐτοῖς γίνεται μάντευμα τοιόνδε·<br>Λεῦκτρά τέ μοι σκιόεντα μέλει καὶ Ἀλήσιον οὖδας,<br>καί μοι τὼ Σκεδάσου μέλετον δυσπενθέε κούρα.<br>ἔνθα μάχη πολύδακρυς ἐπέρχεται· οὐδέ τις αὐτήν<br>φράσσεται ἀνθρώπων, πρὶν κούριον ἀγλαὸν ἥβην<br>Δωριέες ὀλέσωσ’, ὅταν αἴσιμον ἦμαρ ἐπέλθῃ.<br>τουτάκι δ’ ἔστι Κερησσὸς ἁλώσιμος, ἄλλοτε δ’ οὐχί.", "st": "9.14"}, {"sp": "N", "t": "τότε δὲ ὁ Ἐπαμινώνδας ὡς τοὺς Θεσπιεῖς καταφεύγοντας ἐς τὸν Κερησσὸν ἐξεῖλε, πρὸς τὰ ἐν Πελοποννήσῳ παραυτίκα ἔσπευδεν ἅτε καὶ τῶν Ἀρκάδων προθύμως μεταπεμπομένων. ἐλθὼν δὲ Ἀργείους μὲν προσελάβετο ἑκουσίους συμμάχους, Μαντινέας δὲ κατὰ κώμας ὑπὸ Ἀγησιπόλιδος διῳκισμένους ἐς τὴν ἀρχαίαν συνήγαγεν αὖθις πόλιν· τὰ δὲ πολίσματα τὰ Ἀρκάδων ὁπόσα εἶχεν ἀσθενῶς καταλῦσαι πείσας τοὺς Ἀρκάδας, πατρίδα ἐν κοινῷ σφισιν ᾤκισεν, ἣ Μεγάλη καὶ ἐς ἡμᾶς ἔτι καλεῖται πόλις.", "st": "9.14"}, {"sp": "N", "t": "ὁ μὲν δὴ χρόνος βοιωταρχοῦντι Ἐπαμινώνδᾳ διήνυστο, τεθνάναι δὲ ἐτέτακτο ἐπιλαβόντα ἄνδρα τῆς ἀρχῆς· ὁ οὖν Ἐπαμινώνδας ὑπεριδὼν ὡς οὐκ ὄντα ἐν καιρῷ τὸν νόμον ἐβοιωτάρχει καὶ ἀφικόμενος τῷ στρατῷ πρὸς τὴν Σπάρτην, ὡς οὐκ ἀντεπῆγεν Ἀγησίλαος μαχούμενος, οὕτω πρὸς τὸν οἰκισμὸν τρέπεται Μεσσήνης. καὶ οἰκιστὴς Μεσσηνίοις τοῖς νῦν ἐστιν Ἐπαμινώνδας· καί μοι τὰ ἐς τὸν οἰκισμὸν ἐδήλωσε τὰ ἐς αὐτοὺς ἔχοντα Μεσσηνίους.", "st": "9.14"}, {"sp": "N", "t": "ἐν τούτῳ δὲ οἱ τῶν Θηβαίων σύμμαχοι κατέτρεχον διασκεδασθέντες χώραν τὴν Λακωνικὴν καὶ ἥρπαζον τὰ ἐξ αὐτῆς· τοῦτο Ἐπαμινώνδᾳ παρέστησεν ὀπίσω Θηβαίους ἐς Βοιωτίαν ἀπαγαγεῖν. καὶ ὡς προϊὼν τῷ στρατῷ κατὰ Λέχαιον ἐγίνετο καὶ διεξιέναι τῆς ὁδοῦ τὰ στενὰ καὶ δύσβατα ἔμελλεν, Ἰφικράτης ὁ Τιμοθέου πελταστὰς καὶ ἄλλην Ἀθηναίων ἔχων δύναμιν ἐπιχειρεῖ τοῖς Θηβαίοις.", "st": "9.14"}, {"sp": "N", "t": "Ἐπαμινώνδας δὲ τοὺς ἐπιθεμένους τρέπεται καὶ πρὸς αὐτὸ ἀφικόμενος Ἀθηναίων τὸ ἄστυ, ὡς ἐπεξιέναι μαχουμένους τοὺς Ἀθηναίους ἐκώλυεν Ἰφικράτης, ὁ δὲ αὖθις ἐς τὰς Θήβας ἀπήλαυνε. καὶ δίκην μὲν ἔφυγεν ὑπὲρ θανάτου, διότι ἐβοιωτάρχησεν ἐξήκοντος ἤδη τοῦ χρόνου· λέγονται δὲ οἱ δικάζειν λαχόντες οὐδὲ ἀρχὴν περὶ αὐτοῦ θέσθαι τὴν ψῆφον.", "st": "9.14"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἐν Θεσσαλίᾳ δυναστεύων Ἀλέξανδρος Πελοπίδαν ἐλθόντα—ἀφίκετο δὲ ὡς παρὰ ἄνδρα ἰδίᾳ τε εὔνουν αὑτῷ καὶ Θηβαίων φίλον τῷ κοινῷ— παραγενόμενον ⟨δὴ⟩ τὸν Πελοπίδαν ὁ Ἀλέξανδρος δήσας εἶχεν ὑπὸ ἀπιστίας τε καὶ ὕβρεως· Θηβαῖοι δὲ ἐπεξιέναι παραυτίκα ἐπὶ τὸν Ἀλέξανδρον ὥρμηντο. ἡγεμόνας μὲν οὖν τῆς ἐξόδου Κλεομένην καὶ Ὕπατον ἐποιήσαντο βοιωταρχοῦντας ἐν τῷ τότε· Ἐπαμινώνδᾳ δὲ συνέβαινεν ἐν τοῖς στρατευομένοις τετάχθαι.", "st": "9.15"}, {"sp": "N", "t": "γεγονυίας δὲ ἐκτὸς Πυλῶν οἱ τῆς δυνάμεως ἐπιτίθεταί σφισιν ἐν δυσχωρίαις λοχήσας ὁ Ἀλέξανδρος· ὡς δὲ ἐφαίνετο ἄπορα εἶναι τὰ τῆς σωτηρίας, οὕτω δὴ ὅ τε λοιπὸς στρατὸς ἡγεμόνα ποιοῦνται τὸν Ἐπαμινώνδαν καὶ οἱ Βοιωτάρχαι παραχωροῦσιν ἑκουσίως τῆς ἀρχῆς· Ἀλέξανδρος δὲ οὔτε ἔτι ἐθάρρει τὸν πόλεμον στρατηγοῦντα ὁρῶν τοῖς ἐναντίοις Ἐπαμινώνδαν καὶ ἑκὼν Πελοπίδαν ἀφίησιν.", "st": "9.15"}, {"sp": "N", "t": "ἐν ὅσῳ δὲ ἀπῆν ὁ Ἐπαμινώνδας, Ὀρχομενίους Θηβαῖοι ποιοῦσιν ἀναστάτους ἐκ τῆς χώρας· συμφορὰν δὲ τὴν ἀνάστασιν τὴν Ὀρχομενίων ἐνόμιζεν ὁ Ἐπαμινώνδας καὶ οὔ ποτ’ ἂν ἐξεργασθῆναι τόλμημα τοιοῦτον αὐτοῦ γε παρόντος ἔφασκεν ὑπὸ Θηβαίων.", "st": "9.15"}, {"sp": "N", "t": "ὡς δὲ βοιωταρχεῖν αὖθις ᾕρητο καὶ στρατῷ Βοιωτῶν ἀφίκετο αὖθις ἐς Πελοπόννησον, ἐκράτησε μὲν περὶ Λέχαιον Λακεδαιμονίους μάχῃ, σὺν δέ σφισιν Ἀχαιῶν Πελληνέας καὶ Ἀθηναίων οὓς Χαβρίας ἦγεν ἐξ Ἀθηνῶν. Θηβαίοις δὲ ἦν καθεστηκὸς τοὺς μὲν ἄλλους, ὁπόσους αἰχμαλώτους ἕλοιεν, ἀφιέναι χρημάτων, τοὺς δὲ ἐκ Βοιωτῶν φεύγοντας ζημιοῦν θανάτῳ· πόλισμα οὖν ἑλὼν Σικυωνίων Φοιβίαν, ἔνθα ἦσαν τὸ πολὺ οἱ Βοιώτιοι φυγάδες συνηγμένοι, ἀφίησι τοὺς ἐγκαταληφθέντας, ἄλλην σφίσιν ἣν ἔτυχε πατρίδα ἐπονομάζων ἑκάστῳ.", "st": "9.15"}, {"sp": "N", "t": "ὡς δὲ ἀφίκετο πρὸς Μαντίνειαν τῇ στρατιᾷ, νικῶν καὶ τότε ὑπὸ ἀνδρὸς ἀπέθανεν Ἀθηναίου· καὶ Ἀθήνῃσιν ἐν ἱππέων μάχῃ τὸν Ἐπαμινώνδαν ὁ ἀνὴρ οὗτος γέγραπται φονεύων Γρύλος ὁ Ξενοφῶντος, Ξενοφῶντος δὴ τοῦ Κύρῳ ὁδοῦ μετασχόντος ἐπὶ βασιλέα Ἀρταξέρξην καὶ ὀπίσω τοῖς Ἕλλησιν ἐπὶ θάλασσαν ἡγησαμένου.", "st": "9.15"}, {"sp": "N", "t": "τῷ δὲ ἀνδριάντι τοῦ Ἐπαμινώνδου καὶ ἐλεγεῖα ἔπεστιν ἄλλα τε ἐς αὐτὸν λέγοντα καὶ ὅτι Μεσσήνης γένοιτο οἰκιστὴς καὶ τοῖς Ἕλλησιν ὑπάρξειεν ἐλευθερία δι’ αὐτοῦ. καὶ οὕτως ἔχει τὰ ἐλεγεῖα·<br>ἡμετέραις βουλαῖς Σπάρτη μὲν ἐκείρατο δόξαν,<br>Μεσσήνη δ’ ἱερὴ τέκνα χρόνῳ δέχεται·<br>Θήβης δ’ ὅπλοισιν Μεγάλη πόλις ἐστεφάνωται,<br>αὐτόνομος δ’ Ἑλλὰς πᾶσ’ ἐν ἐλευθερίῃ.<br>τούτῳ μὲν τοσαῦτα ἦν ἐς δόξαν·", "st": "9.15"}, {"sp": "N", "t": "οὐ πόρρω δέ ἐστι ναὸς Ἄμμωνος, καὶ τὸ ἄγαλμα ἀνέθηκε μὲν Πίνδαρος, Καλάμιδος δέ ἐστιν ἔργον. ἀπέπεμψε δὲ ὁ Πίνδαρος καὶ Λιβύης ἐς Ἀμμωνίους τῷ Ἄμμωνι ὕμνον· οὗτος καὶ ἐς ἐμὲ ἦν ὁ ὕμνος ἐν τριγώνῳ στήλῃ παρὰ τὸν βωμόν, ὃν Πτολεμαῖος ὁ Λάγου τῷ Ἄμμωνι ἀνέθηκε. Θηβαίοις δὲ μετὰ τοῦ Ἄμμωνος τὸ ἱερὸν οἰωνοσκοπεῖόν τε Τειρεσίου καλούμενον καὶ πλησίον Τύχης ἐστὶν ἱερόν·", "st": "9.16"}, {"sp": "N", "t": "φέρει μὲν δὴ Πλοῦτον παῖδα· ὡς δὲ Θηβαῖοι λέγουσι, χεῖρας μὲν τοῦ ἀγάλματος καὶ πρόσωπον Ξενοφῶν εἰργάσατο Ἀθηναῖος, Καλλιστόνικος δὲ τὰ λοιπὰ ἐπιχώριος. σοφὸν μὲν δὴ καὶ τούτοις τὸ βούλευμα, ἐσθεῖναι Πλοῦτον ἐς τὰς χεῖρας ἅτε μητρὶ ἢ τροφῷ τῇ Τύχῃ, σοφὸν δὲ οὐχ ἧσσον τὸ Κηφισοδότου· καὶ γὰρ οὗτος τῆς Εἰρήνης τὸ ἄγαλμα Ἀθηναίοις Πλοῦτον ἔχουσαν πεποίηκεν.", "st": "9.16"}, {"sp": "N", "t": "Ἀφροδίτης δὲ Θηβαίοις ξόανά ἐστιν οὕτω δὴ ἀρχαῖα ὥστε καὶ ἀναθήματα Ἁρμονίας εἶναί φασιν [αὐτά], ἐργασθῆναι δὲ αὐτὰ ἀπὸ τῶν ἀκροστολίων, ἃ ταῖς Κάδμου ναυσὶν ἦν ξύλου πεποιημένα. καλοῦσι δὲ Οὐρανίαν, τὴν δὲ αὐτῶν Πάνδημον καὶ Ἀποστροφίαν τὴν τρίτην· ἔθετο δὲ τῇ Ἀφροδίτῃ τὰς ἐπωνυμίας ἡ Ἁρμονία, τὴν μὲν Οὐρανίαν ἐπὶ ἔρωτι καθαρῷ καὶ", "st": "9.16"}, {"sp": "N", "t": "ἀπηλλαγμένῳ πόθου σωμάτων, Πάνδημον δὲ ἐπὶ ταῖς μίξεσι, τρίτα δὲ Ἀποστροφίαν, ἵνα ἐπιθυμίας τε ἀνόμου καὶ ἔργων ἀνοσίων ἀποστρέφῃ τὸ γένος τῶν ἀνθρώπων· πολλὰ γὰρ τὰ μὲν ἐν βαρβάροις ἠπίστατο ἡ Ἁρμονία, τὰ δὲ καὶ παρ’ Ἕλλησιν ἤδη τετολμημένα, ὁποῖα καὶ ὕστερον ἐπὶ τῇ Ἀδώνιδος μητρὶ καὶ ἐς Φαίδραν τε τὴν Μίνω καὶ ἐς τὸν Θρᾷκα Τηρέα ᾄδεται.", "st": "9.16"}, {"sp": "N", "t": "τὸ δὲ τῆς Δήμητρος ἱερὸν τῆς Θεσμοφόρου Κάδμου καὶ τῶν ἀπογόνων οἰκίαν ποτὲ εἶναι λέγουσι· Δήμητρος δὲ ἄγαλμα ὅσον ἐς στέρνα ἐστὶν ἐν τῷ φανερῷ. καὶ ἀσπίδες ἐνταῦθα ἀνάκεινται χαλκαῖ· Λακεδαιμονίων δέ, ὁπόσοι τῶν ἐν τέλει περὶ Λεῦκτρα ἐτελεύτησαν, φασὶν εἶναι.", "st": "9.16"}, {"sp": "N", "t": "πρὸς δὲ ταῖς καλουμέναις πύλαις Προιτίσι θέατρον ᾠκοδόμηται, καὶ ἐγγυτάτω τοῦ θεάτρου Διονύσου ναός ἐστιν ἐπίκλησιν Λυσίου· Θηβαίων γὰρ αἰχμαλώτους ἄνδρας ἐχομένους ὑπὸ Θρᾳκῶν, ὡς ἀγόμενοι κατὰ τὴν Ἁλιαρτίαν ἐγίνοντο, ἔλυσεν ὁ θεὸς καὶ ἀποκτεῖναί σφισι τοὺς Θρᾷκας παρέδωκεν ὑπνωμένους. ἐνταῦθα οἱ Θηβαῖοι τὸ ἕτερον τῶν ἀγαλμάτων φασὶν εἶναι Σεμέλης· ἐνιαυτοῦ δὲ ἅπαξ ἑκάστου τὸ ἱερὸν ἀνοιγνύναι φασὶν ἐν ἡμέραις τακταῖς.", "st": "9.16"}, {"sp": "N", "t": "καὶ οἰκίας τῆς Λύκου [τὰ] ἐρείπια καὶ Σεμέλης μνῆμά ἐστιν, Ἀλκμήνης δὲ οὐ μνῆμα· γενέσθαι δὲ αὐτὴν ὡς ἀπέθανε λίθον φασὶν ἐξ ἀνθρώπου, καὶ Μεγαρεῦσι τὰ ἐς αὐτὴν οὐχ ὁμολογοῦσι· διάφορα δὲ καὶ τὰ λοιπὰ ὡς τὸ πολὺ ἀλλήλοις λέγουσιν Ἕλληνες. Θηβαίοις δὲ ἐνταῦθα καὶ τὰ μνήματα πεποίηται τῶν Ἀμφίονος παίδων, χωρὶς μὲν τῶν ἀρσένων, ἰδίᾳ δὲ ταῖς παρθένοις.", "st": "9.16"}, {"sp": "N", "t": "πλησίον δὲ Ἀρτέμιδος ναός ἐστιν Εὐκλείας· Σκόπα δὲ τὸ ἄγαλμα ἔργον. ταφῆναι δὲ ἐντὸς τοῦ ἱεροῦ θυγατέρας Ἀντιποίνου λέγουσιν Ἀνδρόκλειάν τε καὶ Ἀλκίδα. μελλούσης γὰρ πρὸς Ὀρχομενίους γίνεσθαι μάχης Θηβαίοις καὶ Ἡρακλεῖ, λόγιόν σφισιν ἦλθεν ἔσεσθαι τοῦ πολέμου κράτος ἀποθανεῖν αὐτοχειρίᾳ θελήσαντος, ὃς ἂν τῶν ἀστῶν ἐπιφανέστατος κατὰ γένους ἀξίωμα ᾖ. Ἀντιποίνῳ μὲν οὖν—τούτῳ γὰρ τὰ ἐς τοὺς προγόνους μάλιστα ὑπῆρχεν ἔνδοξα—οὐχ ἡδὺ ἦν ἀποθνήσκειν πρὸ τοῦ δήμου, ταῖς δὲ Ἀντιποίνου θυγατράσιν ἤρεσκε· διεργασάμεναι δὲ αὑτὰς τιμὰς ἀντὶ τούτων ἔχουσι.", "st": "9.17"}, {"sp": "N", "t": "τοῦ ναοῦ δὲ τῆς Εὐκλείας Ἀρτέμιδος λέων ἐστὶν ἔμπροσθε λίθου πεποιημένος· ἀναθεῖναι δὲ ἐλέγετο Ἡρακλῆς Ὀρχομενίους καὶ τὸν βασιλέα αὐτῶν Ἐργῖνον τὸν Κλυμένου νικήσας τῇ μάχῃ. πλησίον δὲ Ἀπόλλων τέ ἐστιν ἐπίκλησιν Βοηδρόμιος καὶ Ἀγοραῖος Ἑρμῆς καλούμενος, Πινδάρου καὶ τοῦτο ἀνάθημα. ἀπέχει δὲ ἡ πυρὰ τῶν Ἀμφίονος παίδων ἥμισυ σταδίου μάλιστα ἀπὸ τῶν τάφων· μένει δὲ ἡ τέφρα καὶ ἐς τόδε ἔτι ἀπὸ τῆς πυρᾶς.", "st": "9.17"}, {"sp": "N", "t": "πλησίον δὲ Ἀμφιτρύωνος ⟨ἀνάθημα⟩ δύο ἀγάλματα λίθινα λέγουσιν Ἀθηνᾶς ἐπίκλησιν Ζωστηρίας· λαβεῖν γὰρ τὰ ὅπλα αὐτὸν ἐνταῦθα, ἡνίκα Εὐβοεῦσι καὶ Χαλκώδοντι ἔμελλεν ἀντιτάξεσθαι. τὸ δὲ ἐνδῦναι τὰ ὅπλα ἐκάλουν ἄρα οἱ παλαιοὶ ζώσασθαι· καὶ δὴ Ὅμηρον, Ἄρει τὸν Ἀγαμέμνονα ποιήσαντα ἐοικέναι τὴν ζώνην, τῶν ὅπλων τὴν σκευήν φασιν εἰκάζειν.", "st": "9.17"}, {"sp": "N", "t": "Ζήθῳ δὲ μνῆμα καὶ Ἀμφίονι ἐν κοινῷ γῆς χῶμά ἐστιν οὐ μέγα. ὑφαιρεῖσθαι δὲ ἐθέλουσιν ἀπ’ αὐτοῦ τῆς γῆς οἱ Τιθορέαν ἐν τῇ Φωκίδι ἔχοντες, ἐθέλουσι δέ, ἐπειδὰν τὸν ἐν τῷ οὐρανῷ ταῦρον ὁ ἥλιος διεξίῃ· τηνικαῦτα γὰρ ἢν ἀπ’ αὐτοῦ λαβόντες γῆν τῷ Ἀντιόπης μνήματι περιάψωσι, ⟨Τι⟩θορεεῦσιν οἴσει καρπὸν ἡ χώρα, Θηβαίοις δὲ οὐχ ὁμοίως. καὶ ἐπὶ τούτῳ φρουρὰν οἱ Θηβαῖοι τότε ἔχουσι τοῦ μνήματος.", "st": "9.17"}, {"sp": "N", "t": "ταῦτα δὲ αἱ πόλεις αὗται πεπιστεύκασιν ἐκ χρησμῶν τῶν Βάκιδος, ἔστι γὰρ καὶ τάδε ἐν τοῖς χρησμοῖς·<br>ἀλλ’ ὁπόταν Τιθορεὺς Ἀμφίονί τε Ζήθῳ τε<br>χύτλα καὶ εὐχωλὰς μειλίγματ’ ἐνὶ χθονὶ χεύῃ<br>θελγομένου ταύροιο κλυτοῦ μένει ἠελίοιο,<br>καὶ τότε δὴ πεφύλαξο πόλει κακὸν οὐκ ἀλαπαδνόν<br>ἐρχόμενον· καρποὶ γὰρ ἀποφθινύθουσιν ἐν αὐτῇ<br>γαίης δασσαμένων, Φώκου δ’ ἐπὶ σῆμα φερόντων.", "st": "9.17"}, {"sp": "N", "t": "Φώκου δὲ μνῆμα ὁ Βάκις εἴρηκεν ἐπὶ αἰτίᾳ τοιᾷδε. ἡ γυνὴ τοῦ Λύκου Διόνυσον θεῶν μάλιστα ἦγεν ἐν τιμῇ· παθούσης δὲ αὐτῆς τὰ λεγόμενα Διόνυσος νεμεσᾷ τῇ Ἀντιόπῃ. ἐπίφθονοι δὲ ἀεί πως παρὰ θεῶν αἱ ὑπερβολαὶ τῶν τιμωριῶν εἰσι· λέγουσιν Ἀντιόπην μανῆναι καὶ ἐκστᾶσαν τῶν φρενῶν κατὰ πᾶσαν πλανᾶσθαι τὴν Ἑλλάδα, Φῶκον δὲ τὸν Ὀρνυτίωνος τοῦ Σισύφου περιτυχεῖν αὐτῇ καὶ ἔχειν γυναῖκα ἰασάμενον· καὶ δὴ ὁ τάφος ἐν κοινῷ τῇ Ἀντιόπῃ καὶ Φώκῳ πεποίηται.", "st": "9.17"}, {"sp": "N", "t": "τοὺς δὲ παρὰ τὸ Ἀμφίονος μνῆμα λίθους, οἳ κάτωθεν ὑποβέβληνται μηδὲ ἄλλως εἰργασμένοι πρὸς τὸ ἀκριβέστατον, ἐκείνας εἶναί ⟨φασι⟩ τὰς πέτρας αἳ τῇ ᾠδῇ τοῦ Ἀμφίονος ἠκολούθησαν· τοιαῦτα δὲ ἕτερα λέγεται καὶ περὶ Ὀρφέως, ὡς κιθαρῳδοῦντι ἕποιτο αὐτῷ τὰ θηρία.", "st": "9.17"}, {"sp": "N", "t": "ἐκ Θηβῶν δὲ ὁδὸς ἐς Χαλκίδα κατὰ πύλας ταύτας ἐστὶ τὰς Προιτίδας. τάφος δὲ ἐπὶ τῇ λεωφόρῳ δείκνυται Μελανίππου, Θηβαίων ἐν τοῖς μάλιστα ἀγαθοῦ τὰ πολεμικά· καὶ ἡνίκα ἐπεστράτευσαν οἱ Ἀργεῖοι, Τυδέα ὁ Μελάνιππος οὗτος καὶ ἀδελφῶν τῶν Ἀδράστου Μηκιστέα ἀπέκτεινε, καί οἱ καὶ αὐτῷ τὴν τελευτὴν ὑπὸ Ἀμφιαράου γενέσθαι λέγουσι.", "st": "9.18"}, {"sp": "N", "t": "τούτου δὲ ἐγγύτατα τρεῖς εἰσιν ἀργοὶ λίθοι· Θηβαίων δὲ οἱ τὰ ἀρχαῖα μνημονεύοντες Τυδέα φασὶν εἶναι τὸν ἐνταῦθα κείμενον, ταφῆναι δὲ αὐτὸν ὑπὸ Μαίονος, καὶ ἐς μαρτυρίαν τοῦ λόγου παρέσχον τῶν ἐν Ἰλιάδι ἔπος<br>Τυδέος, ὃν Θήβῃσι χυτὴ κατὰ γαῖα καλύπτει.", "st": "9.18"}, {"sp": "N", "t": "ἑξῆς δέ ἐστι τῶν Οἰδίποδος παίδων μνήματα· ⟨καὶ τὰ⟩ ἐπ’ αὐτοῖς δρώμενα οὐ θεασάμενος πιστὰ ὅμως ὑπείληφα εἶναι. φασὶ γὰρ καὶ ἄλλοις οἱ Θηβαῖοι τῶν καλουμένων ἡρώων καὶ τοῖς παισὶν ἐναγίζειν τοῖς Οἰδίποδος· τούτοις δὲ ἐναγιζόντων αὐτῶν τὴν φλόγα, ὡσαύτως δὲ καὶ τὸν ἀπ’ αὐτῆς καπνὸν διχῇ διίστασθαι. ἐμὲ δὲ ἐπηγάγοντο ὧν λέγουσιν ἐς πίστιν ἰδόντα ἄλλο τοιόνδε.", "st": "9.18"}, {"sp": "N", "t": "ἐν Μυσίᾳ τῇ ὑπὲρ Καΐκου πόλισμά ἐστι Πιονίαι, τὸν δὲ οἰκιστὴν οἱ ἐνταῦθα Πίονιν τῶν τινα ἀπογόνων τῶν Ἡρακλέους φασὶν εἶναι· μελλόντων δὲ ἐναγίζειν αὐτῷ καπνὸς αὐτόματος ἄνεισιν ἐκ τοῦ τάφου. ταῦτα μὲν οὖν συμβαίνοντα εἶδον, Θηβαῖοι δὲ καὶ Τειρεσίου μνῆμα ἀποφαίνουσι, πέντε μάλιστα καὶ δέκα ἀπωτέρω σταδίοις ἢ Οἰδίποδος τοῖς παισίν ἐστιν ὁ τάφος· ὁμολογοῦντες δὲ καὶ οὗτοι συμβῆναι Τειρεσίᾳ τὴν τελευτὴν ἐν τῇ Ἁλιαρτίᾳ, τὸ παρὰ σφίσιν ἐθέλουσιν εἶναι κενὸν μνῆμα.", "st": "9.18"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἕκτορος Θηβαίοις τάφος τοῦ Πριάμου πρὸς Οἰδιποδίᾳ καλουμένῃ κρήνῃ, κομίσαι δὲ αὐτοῦ τὰ ὀστᾶ ἐξ Ἰλίου φασὶν ἐπὶ τοιῷδε μαντεύματι·<br>Θηβαῖοι Κάδμοιο πόλιν καταναιετάοντες,<br>αἴ κ’ ἐθέλητε πάτραν οἰκεῖν σὺν ἀμύμονι πλούτῳ,<br>Ἕκτορος ὀστέα Πριαμίδου κομίσαντες ἐς οἴκους<br>ἐξ Ἀσίης Διὸς ἐννεσίῃσ’ ἥρωα σέβεσθαι.", "st": "9.18"}, {"sp": "N", "t": "τῇ δὲ Οἰδιποδίᾳ κρήνῃ τὸ ὄνομα ἐγένετο, ὅτι ἐς αὐτὴν τὸ αἷμα ἐνίψατο Οἰδίπους τοῦ πατρῴου φόνου. πρὸς δὲ τῇ πηγῇ τάφος ἐστὶν Ἀσφοδίκου· καὶ ὁ Ἀσφόδικος οὗτος ἀπέκτεινεν ἐν τῇ μάχῃ τῇ πρὸς Ἀργείους Παρθενοπαῖον τὸν Ταλαοῦ, καθὰ οἱ Θηβαῖοι λέγουσιν, ἐπεὶ τά γε ἐν Θηβαΐδι ἔπη τὰ ἐς τὴν Παρθενοπαίου τελευτὴν Περικλύμενον τὸν ἀνελόντα φησὶν εἶναι.", "st": "9.18"}, {"sp": "N", "t": "ἐπὶ ταύτῃ τῇ λεωφόρῳ χωρίον ἐστὶ Τευμησσός· Εὐρώπην δὲ ὑπὸ Διὸς κρυφθῆναί φασιν ἐνταῦθα. ἕτερος δὲ ἐς ἀλώπεκα ἐπίκλησιν Τευμησσίαν λόγος ἐστίν, ὡς ἐκ μηνίματος Διονύσου τὸ θηρίον ἐπ’ ὀλέθρῳ τραφείη Θηβαίων, καὶ ὡς ὑπὸ τοῦ κυνός, ὃν Πρόκριδι τῇ Ἐρεχθέως ἔδωκεν Ἄρτεμις, ἁλίσκεσθαι μέλλουσα αὐτή τε λίθος ἐγένετο ἡ ἀλώπηξ καὶ ὁ κύων οὗτος. καὶ Ἀθηνᾶς ἐν Τευμησσῷ Τελχινίας ἐστὶν ἱερὸν ἄγαλμα οὐκ ἔχον· ἐς δὲ τὴν ἐπίκλησιν αὐτῆς ἔστιν εἰκάζειν ὡς τῶν ἐν Κύπρῳ ποτὲ οἰκησάντων Τελχίνων ἀφικομένη μοῖρα ἐς Βοιωτοὺς ἱερὸν ἱδρύσατο Ἀθηνᾶς Τελχινίας.", "st": "9.19"}, {"sp": "N", "t": "Τευμησσοῦ δὲ ἐν ἀριστερᾷ σταδίους προελθόντι ἑπτὰ Γλίσαντός ἐστιν ἐρείπια, πρὸ δὲ αὐτῶν ἐν δεξιᾷ τῆς ὁδοῦ χῶμα οὐ μέγα ὕλῃ τε ἀγρίᾳ σύσκιον καὶ ἡμέροις δένδροις. ἐτάφησαν δὲ αὐτόθι οἱ μετὰ Αἰγιαλέως ποιησάμενοι τοῦ Ἀδράστου τὴν ἐς Θήβας στρατείαν, ἄλλοι τε Ἀργείων τῶν ἐν τέλει καὶ Πρόμαχος ὁ Παρθενοπαίου· τῷ δὲ Αἰγιαλεῖ γενέσθαι τὸ μνῆμα ἐν Παγαῖς πρότερον ἔτι ἐν τῇ συγγραφῇ τῇ Μεγαρίδι ἐδήλωσα.", "st": "9.19"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς Γλίσαντα εὐθεῖαν ἐκ Θηβῶν λίθοις χωρίον περιεχόμενον λογάσιν Ὄφεως καλοῦσιν οἱ Θηβαῖοι κεφαλήν, τὸν ὄφιν τοῦτον—ὅστις δὴ ἦν—ἀνασχεῖν ἐνταῦθα ἐκ τοῦ φωλεοῦ λέγοντες τὴν κεφαλήν, Τειρεσίαν δὲ ἐπιτυχόντα ἀποκόψαι μαχαίρᾳ. τὸ μὲν δὴ χωρίον τοῦτο ἐπὶ λόγῳ καλεῖται τοιῷδε· ὑπὲρ δὲ Γλίσαντός ἐστιν ὄρος Ὕπατος καλούμενον, ἐπὶ δὲ αὐτῷ Διὸς Ὑπάτου ναὸς καὶ ἄγαλμα· τὸν δὲ ποταμὸν τὸν χείμαρρον Θερμώδοντα ὀνομάζουσιν. ἀναστρέψαντι δὲ ἐπί τε Τευμησσὸν καὶ ὁδὸν τὴν ἐς Χαλκίδα Χαλκώδοντος μνῆμά ἐστιν, ὃς ἀπέθανεν ὑπὸ Ἀμφιτρύωνος μάχης πρὸς Θηβαίους Εὐβοεῦσι γενομένης.", "st": "9.19"}, {"sp": "N", "t": "ἑξῆς δὲ πόλεων ἐρείπιά ἐστιν Ἅρματος καὶ Μυκαλησσοῦ· καὶ τῇ μὲν τὸ ὄνομα ἐγένετο ἀφανισθέντος, ὡς οἱ Ταναγραῖοί φασιν, ἐνταῦθα Ἀμφιαράῳ τοῦ ἅρματος καὶ οὐχ ὅπου λέγουσιν οἱ Θηβαῖοι· Μυκαλησσὸν δὲ ὁμολογοῦσιν ὀνομασθῆναι, διότι ἡ βοῦς ἐνταῦθα ἐμυκήσατο ἡ Κάδμον καὶ τὸν σὺν αὐτῷ στρατὸν ἄγουσα ἐς Θήβας. ὅντινα δὲ τρόπον ἐγένετο ἡ Μυκαλησσὸς ἀνάστατος, τὰ ἐς Ἀθηναίους ἔχοντα ἐδήλωσέ μοι τοῦ λόγου.", "st": "9.19"}, {"sp": "N", "t": "πρὸς θάλασσαν δὲ τῆς Μυκαλησσοῦ Δήμητρος Μυκαλησσίας ἐστὶν ἱερόν· κλείεσθαι δὲ αὐτὸ ἐπὶ νυκτὶ ἑκάστῃ καὶ αὖθις ἀνοίγεσθαί φασιν ὑπὸ Ἡρακλέους, τὸν δὲ Ἡρακλέα εἶναι τῶν Ἰδαίων καλουμένων Δακτύλων. δείκνυται δὲ αὐτόθι καὶ θαῦμα τοιόνδε· πρὸ τοῦ ἀγάλματος τῶν ποδῶν τιθέασιν ὅσα ἐν ὀπώρᾳ πέφυκε γίνεσθαι, ταῦτα δὲ διὰ παντὸς μένει τεθηλότα τοῦ ἔτους.", "st": "9.19"}, {"sp": "N", "t": "τοῦ δὲ Εὐρίπου τὴν Εὔβοιαν κατὰ τοῦτο ἀπὸ τῆς Βοιωτῶν διείργοντος τῆς τε Δήμητρος ἐν δεξιᾷ τὸ ἱερὸν τῆς Μυκαλησσίας καὶ ὀλίγον ἀπ’ αὐτοῦ προελθόντι ἐστὶν Αὐλίς· ὀνομασθῆναι δὲ ἀπὸ τῆς Ὠγύγου θυγατρός φασιν αὐτήν. ναὸς δὲ Ἀρτέμιδός ἐστιν ἐνταῦθα καὶ ἀγάλματα λίθου λευκοῦ, τὸ μὲν δᾷδας φέρον, τὸ δὲ ἔοικε τοξευούσῃ. φασὶ δὲ ἐπὶ τοῦ βωμοῦ μελλόντων ἐκ μαντείας τῆς Κάλχαντος Ἰφιγένειαν τῶν Ἑλλήνων θύειν, τὴν θεὸν ἀντ’ αὐτῆς ἔλαφον τὸ ἱερεῖον ποιῆσαι.", "st": "9.19"}, {"sp": "N", "t": "πλατάνου δέ, ἧς καὶ Ὅμηρος ἐν Ἰλιάδι ἐποιήσατο μνήμην, τὸ ἔτι τοῦ ξύλου περιὸν φυλάσσουσιν ἐν τῷ ναῷ. λέγεται δὲ ὡς ἐν Αὐλίδι πνεῦμα τοῖς Ἕλλησιν οὐκ ἐγίνετο ἐπίφορον, φανέντος δὲ ἐξαίφνης ἀνέμου σφίσιν οὐρίου θύειν τῇ Ἀρτέμιδι ὅ τι ἕκαστος εἶχε, θήλεά τε ἱερεῖα καὶ ἄρσενα ὁμοίως· καὶ ἀπ’ ἐκείνου διαμεμένηκεν ἐν Αὐλίδι πάντα τὰ ἱερεῖα εἶναι δόκιμα. δείκνυται δὲ καὶ ἡ πηγή, παρ’ ἣν ἡ πλάτανος ἐπεφύκει, καὶ ἐπὶ λόφου πλησίον τῆς Ἀγαμέμνονος σκηνῆς οὐδὸς χαλκοῦς·", "st": "9.19"}, {"sp": "N", "t": "φοίνικες δὲ πρὸ τοῦ ἱεροῦ πεφύκασιν, οὐκ ἐς ἅπαν ἐδώδιμον παρεχόμενοι καρπὸν ὥσπερ ἐν τῇ Παλαιστίνῃ, τοῦ δὲ ἐν Ἰωνίᾳ τῶν φοινίκων καρποῦ πεπανώτερον. ἄνθρωποι δὲ ἐν τῇ Αὐλίδι οἰκοῦσιν οὐ πολλοί, γῆς δέ εἰσιν οὗτοι κεραμεῖς· νέμονται δὲ Ταναγραῖοι ταύτην τε τὴν χώραν καὶ ὅση περὶ Μυκαλησσόν ἐστι καὶ Ἅρμα.", "st": "9.19"}, {"sp": "N", "t": "ἔστι δὲ τῆς Ταναγραίας ἐπὶ θαλάσσῃ καλούμενον Δήλιον· ἐν δὲ αὐτῷ καὶ Ἀρτέμιδος καὶ Λητοῦς ἐστιν ἀγάλματα. Ταναγραῖοι δὲ οἰκιστήν σφισι Ποίμανδρον γενέσθαι λέγουσι Χαιρησίλεω παῖδα τοῦ Ἰασίου τοῦ Ἐλευθῆρος, τὸν δ’ Ἀπόλλωνός τε καὶ Αἰθούσης εἶναι τῆς Ποσειδῶνος. Ποίμανδρον δὲ γυναῖκά φασιν ἀγαγέσθαι Τάναγραν θυγατέρα Αἰόλου· Κορίννῃ δέ ἐστιν ἐς αὐτὴν πεποιημένα Ἀσωποῦ παῖδα εἶναι.", "st": "9.20"}, {"sp": "N", "t": "ταύτης τοῦ βίου προελθούσης ἐπὶ μακρότατον τοὺς περιοίκους φασὶν ἀφελόντας τὸ ὄνομα τήν τε γυναῖκα αὐτὴν καλεῖν Γραῖαν καὶ ἀνὰ χρόνον τὴν πόλιν· διαμεῖναί τε τὸ ὄνομα ἐς τοσοῦτον ὡς καὶ Ὅμηρον ἐν καταλόγῳ ποιῆσαι<br>Θέσπειαν Γραῖάν τε καὶ εὐρύχορον Μυκαλησσόν.<br>χρόνῳ δὲ ὕστερον τὸ ὄνομα τὸ ἀρχαῖον ἀνεσώσαντο.", "st": "9.20"}, {"sp": "N", "t": "ἔστι δ’ Ὠρίωνος μνῆμα ἐν Τανάγρᾳ καὶ ὄρος Κηρύκιον, ἔνθα Ἑρμῆν τεχθῆναι λέγουσι, Πόλος τε ὀνομαζόμενον χωρίον· ἐνταῦθα Ἄτλαντα καθήμενον πολυπραγμονεῖν τά τε ὑπὸ γῆς φασι καὶ τὰ οὐράνια, πεποιῆσθαι δὲ καὶ Ὁμήρῳ περὶ τούτου,<br>Ἄτλαντος θυγάτηρ ὀλοόφρονος, ὅστε θαλάσσης<br>πάσης βένθεα οἶδεν, ἔχει δέ τε κίονας αὐτός<br>μακράς, αἳ γαῖάν τε καὶ οὐρανὸν ἀμφὶς ἔχουσιν.", "st": "9.20"}, {"sp": "N", "t": "ἐν δὲ τοῦ Διονύσου τῷ ναῷ θέας μὲν καὶ τὸ ἄγαλμα ἄξιον λίθου τε ὂν Παρίου καὶ ἔργον Καλάμιδος, θαῦμα δὲ παρέχεται μεῖζον ἔτι ὁ Τρίτων. ὁ μὲν δὴ σεμνότερος ἐς αὐτὸν λόγος τὰς γυναῖκάς φησι τὰς Ταναγραίων πρὸ τῶν Διονύσου ὀργίων ἐπὶ θάλασσαν καταβῆναι καθαρσίων ἕνεκα, νηχομέναις δὲ ἐπιχειρῆσαι τὸν Τρίτωνα καὶ τὰς γυναῖκας εὔξασθαι Διόνυσόν σφισιν ἀφικέσθαι βοηθόν, ὑπακοῦσαί τε δὴ τὸν θεὸν καὶ τοῦ Τρίτωνος κρατῆσαι τῇ μάχῃ·", "st": "9.20"}, {"sp": "N", "t": "ὁ δὲ ἕτερος λόγος ἀξιώματι μὲν ἀποδεῖ τοῦ προτέρου, πιθανώτερος δέ ἐστι. φησὶ γὰρ δὴ οὗτος, ὁπόσα ἐλαύνοιτο ἐπὶ θάλασσαν βοσκήματα, ὡς ἐλόχα τε ὁ Τρίτων καὶ ἥρπαζεν· ἐπιχειρεῖν δὲ αὐτὸν καὶ τῶν πλοίων τοῖς λεπτοῖς, ἐς ὃ οἱ Ταναγραῖοι κρατῆρα οἴνου προτιθέασιν αὐτῷ. καὶ τὸν αὐτίκα ἔρχεσθαι λέγουσιν ὑπὸ τῆς ὀσμῆς, πιόντα δὲ ἐρρῖφθαι κατὰ τῆς ᾐόνος ὑπνωμένον, Ταναγραῖον δὲ ἄνδρα πελέκει παίσαντα ἀποκόψαι τὸν αὐχένα αὐτοῦ· καὶ διὰ τοῦτο οὐκ ἔπεστιν αὐτῷ κεφαλή. ὅτι δὲ μεθυσθέντα εἷλον, ἐπὶ τούτῳ ὑπὸ Διονύσου νομίζουσιν ἀποθανεῖν αὐτόν.", "st": "9.20"}, {"sp": "N", "t": "εἶδον δὲ καὶ ἄλλον Τρίτωνα ἐν τοῖς Ῥωμαίων θαύμασι, μεγέθει τοῦ παρὰ Ταναγραίοις ἀποδέοντα. παρέχονται δὲ ἰδέαν οἱ Τρίτωνες· ἔχουσιν ἐπὶ τῇ κεφαλῇ κόμην οἷα τὰ βατράχια ⟨τὰ⟩ ἐν ταῖς λίμναις χρόαν τε καὶ ὅτι τῶν τριχῶν οὐκ ἂν ἀποκρίναις μίαν ἀπὸ τῶν ἄλλων, τὸ δὲ λοιπὸν σῶμα φολίδι λεπτῇ πέφρικέ σφισι κατὰ ἰχθὺν ῥίνην. βράγχια δὲ ὑπὸ τοῖς ὠσὶν ἔχουσι καὶ ῥῖνα ἀνθρώπου, στόμα δὲ εὐρύτερον καὶ ὀδόντας θηρίου· τὰ δὲ ὄμματα ἐμοὶ δοκεῖν γλαυκὰ καὶ χεῖρές εἰσιν αὐτοῖς καὶ δάκτυλοι καὶ ὄνυχες τοῖς ἐπιθέμασιν ἐμφερεῖς τῶν κόχλων· ὑπὸ δὲ τὸ στέρνον καὶ τὴν γαστέρα οὐρά σφισιν ἀντὶ ποδῶν οἵα περ τοῖς δελφῖσίν ἐστιν.", "st": "9.21"}, {"sp": "N", "t": "εἶδον δὲ καὶ ταύρους τούς τε Αἰθιοπικούς, οὓς ἐπὶ τῷ συμβεβηκότι ὀνομάζουσι ῥινόκερως, ὅτι σφίσιν ἐπ’ ἄκρᾳ τῇ ῥινὶ ἓν ἑκάστῳ κέρας καὶ ἄλλο ὑπὲρ αὐτὸ οὐ μέγα, ἐπὶ δὲ τῆς κεφαλῆς οὐδὲ ἀρχὴν κέρατά ἐστι, καὶ τοὺς ἐκ Παιόνων—οὗτοι δὲ οἱ ἐκ Παιόνων ἔς τε τὸ ἄλλο σῶμα δασεῖς καὶ ἀμφὶ τὸ στέρνον μάλιστά εἰσι καὶ τὴν γένυν—καμήλους τε Ἰνδικὰς χρῶμα εἰκασμένας παρδάλεσιν.", "st": "9.21"}, {"sp": "N", "t": "ἔστι δὲ ἄλκη καλούμενον θηρίον, εἶδος μὲν ἐλάφου καὶ καμήλου μεταξύ, γίνεται δὲ ἐν τῇ Κελτῶν γῇ. θηρίων δὲ ὧν ἴσμεν μόνην ἀνιχνεῦσαι καὶ προϊδεῖν οὐκ ἔστιν ἀνθρώπῳ, σταλεῖσι δὲ ἐς ἄγραν ἄλλων καὶ τήνδε ἐς χεῖρά ποτε δαίμων ἄγει· ὀσφρᾶται μὲν γὰρ ἀνθρώπου καὶ πολὺ ἔτι ἀπέχουσα, ὥς φασι, καταδύεται δὲ ἐς φάραγγας καὶ σπήλαια τὰ βαθύτατα. οἱ θηρεύοντες οὖν, ὁπότε ἐπὶ βραχύτατον, σταδίων τὴν πεδιάδα χιλίων ἢ καὶ ὄρος περιλαβόντες, τὸν κύκλον μὲν οὐκ ἔστιν ὅπως διαλύσουσιν, ἐπισυνιόντες δὲ ἀεὶ τὰ ἐντὸς γινόμενα τοῦ κύκλου πάντα αἱροῦσι τά τε ἄλλα καὶ τὰς ἄλκας· εἰ δὲ μὴ τύχοι ταύτῃ φωλεύουσα, ἑτέρα γε ἄλκην ἑλεῖν ἐστιν οὐδεμία μηχανή.", "st": "9.21"}, {"sp": "N", "t": "θηρίον δὲ ⟨τὸ⟩ ἐν τῷ Κτησίου λόγῳ τῷ ἐς Ἰνδοὺς—μαρτιχόρα ὑπὸ τῶν Ἰνδῶν, ὑπὸ δὲ Ἑλλήνων φησὶν ἀνδροφάγον λελέχθαι—εἶναι πείθομαι τὸν τίγριν· ὀδόντας δὲ αὐτὸ τριστοίχους καθ’ ἑκατέραν τὴν γένυν καὶ κέντρα ἐπὶ ἄκρας ἔχειν τῆς οὐρᾶς, τούτοις δὲ τοῖς κέντροις ἐγγύθεν ἀμύνεσθαι καὶ ἀποπέμπειν ἐς τοὺς πορρωτέρω τοξότου ἀνδρὸς ὀιστῷ ἴσον, ταύτην οὐκ ἀληθῆ τὴν φήμην οἱ Ἰνδοὶ δέξασθαι δοκοῦσί μοι παρ’ ἀλλήλων ὑπὸ τοῦ ἄγαν ἐς τὸ θηρίον δείματος.", "st": "9.21"}, {"sp": "N", "t": "ἠπατήθησαν δὲ καὶ ἐς τὴν χρόαν αὐτοῦ, καὶ ὁπότε κατὰ τοῦ ἡλίου φανείη σφίσιν ὁ τίγρις τὴν αὐγήν, ἐρυθρός τ’ ἐδόκει καὶ ὁμόχρους ἢ ὑπὸ τῆς ὠκύτητος ⟨ἢ⟩—εἰ μὴ θέοι— διὰ τὸ ἐν ταῖς ἐπιστροφαῖς συνεχές, ἄλλως τε καὶ οὐκ ἐγγύθεν γινομένης τῆς θέας. δοκῶ δέ, εἰ καὶ Λιβύης τις ἢ τῆς Ἰνδῶν ἢ Ἀράβων γῆς ἐπέρχοιτο τὰ ἔσχατα ἐθέλων θηρία ὁπόσα παρ’ Ἕλλησιν ἐξευρεῖν, τὰ μὲν οὐδὲ ἀρχὴν αὐτὸν εὑρήσειν, τὰ δὲ οὐ κατὰ ταὐτὰ ἔχειν φανεῖσθαί οἱ·", "st": "9.21"}, {"sp": "N", "t": "οὐ γὰρ δὴ ἄνθρωπος μόνον ὁμοῦ τῷ ἀέρι καὶ τῇ γῇ διαφόροις οὖσι διάφορον κτᾶται καὶ τὸ εἶδος, ἀλλὰ καὶ τὰ λοιπὰ τὸ αὐτὸ ἂν πάσχοι τοῦτο, ἐπεὶ καὶ τὰ θηρία αἱ ἀσπίδες τοῦτο μὲν ἔχουσιν αἱ Λίβυσσαι παρὰ τὰς Αἰγυπτίας τὴν χρόαν, τοῦτο δὲ ἐν Αἰθιοπίᾳ μελαίνας τὰς ἀσπίδας οὐ μεῖον ἢ καὶ τοὺς ἀνθρώπους ἡ γῆ τρέφει. οὕτω χρὴ πάντα τινὰ μήτε ἐπίδρομον τὴν γνώμην μήτε ἀπίστως ἔχειν ἐς τὰ σπανιώτερα, ἐπεί τοι καὶ ἐγὼ πτερωτοὺς ὄφεις οὐ θεασάμενος πείθομαι· ⟨πείθομαι⟩ δὲ ὅτι ἀνὴρ Φρὺξ ἤγαγεν ἐς Ἰωνίαν σκορπίον ταῖς ἀκρίσιν ὁμοιότατα πτερὰ ἔχοντα.", "st": "9.21"}, {"sp": "N", "t": "ἐν Τανάγρᾳ δὲ παρὰ τὸ ἱερὸν τοῦ Διονύσου Θέμιδός ἐστιν, ὁ δὲ Ἀφροδίτης, καὶ ὁ τρίτος τῶν ναῶν Ἀπόλλωνος, ὁμοῦ δὲ αὐτῷ [καὶ] Ἄρτεμίς τε καὶ Λητώ. ἐς δὲ τοῦ Ἑρμοῦ τὰ ἱερὰ τοῦ τε Κριοφόρου καὶ ὃν Πρόμαχον καλοῦσι, τοῦ μὲν ἐς τὴν ἐπίκλησιν λέγουσιν ὡς ὁ Ἑρμῆς σφισιν ἀποτρέψαι νόσον λοιμώδη περὶ τὸ τεῖχος κριὸν περιενεγκών, καὶ ἐπὶ τούτῳ Κάλαμις ἐποίησεν ἄγαλμα Ἑρμοῦ φέροντα κριὸν ἐπὶ τῶν ὤμων· ὃς δ’ ἂν εἶναι τῶν ἐφήβων προκριθῇ τὸ εἶδος κάλλιστος, οὗτος ἐν τοῦ Ἑρμοῦ τῇ ἑορτῇ περίεισιν ἐν κύκλῳ τὸ τεῖχος ἔχων ἄρνα ἐπὶ τῶν ὤμων·", "st": "9.22"}, {"sp": "N", "t": "τὸν δὲ Ἑρμῆν λέγουσι τὸν Πρόμαχον Ἐρετριέων ναυσὶν ἐξ Εὐβοίας ἐς τὴν Ταναγραίαν σχόντων τούς τε ἐφήβους ἐξαγαγεῖν ἐπὶ τὴν μάχην καὶ αὐτὸν ὅτε ἔφηβον στλεγγίδι ἀμυνόμενον μάλιστα ἐργάσασθαι τῶν Εὐβοέων τροπήν. κεῖται δὲ ἐν τοῦ Προμάχου τῷ ἱερῷ τῆς [τε] ἀνδράχνου τὸ ὑπόλοιπον· τραφῆναι δὲ ὑπὸ τῷ δένδρῳ τὸν Ἑρμῆν τούτῳ νομίζουσιν. οὐ πόρρω δὲ θέατρόν τε καὶ πρὸς αὐτῷ στοὰ πεποίηται. εὖ δέ μοι Ταναγραῖοι νομίσαι τὰ ἐς τοὺς θεοὺς μάλιστα δοκοῦσιν Ἑλλήνων· χωρὶς μὲν γὰρ αἱ οἰκίαι σφίσι, χωρὶς δὲ τὰ ἱερὰ ὑπὲρ αὐτὰς ἐν καθαρῷ τέ ἐστι καὶ ἐκτὸς ἀνθρώπων.", "st": "9.22"}, {"sp": "N", "t": "Κορίννης δέ, ἣ μόνη δὴ ἐν Τανάγρᾳ ᾄσματα ἐποίησε, ταύτης ἔστι μὲν μνῆμα ἐν περιφανεῖ τῆς πόλεως, ἔστι δὲ ἐν τῷ γυμνασίῳ γραφή, ταινίᾳ τὴν κεφαλὴν ἡ Κόριννα ἀναδουμένη τῆς νίκης ἕνεκα ἣν Πίνδαρον ᾄσματι ἐνίκησεν ἐν Θήβαις. φαίνεται δέ μοι νικῆσαι τῆς διαλέκτου τε ἕνεκα, ὅτι ᾖδεν οὐ τῇ φωνῇ τῇ Δωρίδι ὥσπερ ὁ Πίνδαρος ἀλλὰ ὁποίᾳ συνήσειν ἔμελλον Αἰολεῖς, καὶ ὅτι ἦν γυναικῶν τότε δὴ καλλίστη τὸ εἶδος, εἴ τι τῇ εἰκόνι δεῖ τεκμαίρεσθαι.", "st": "9.22"}, {"sp": "N", "t": "ἔστι δὲ καὶ γένη δύο ἐνταῦθα ἀλεκτρυόνων, οἵ τε μάχιμοι καὶ οἱ κόσσυφοι καλούμενοι. τούτων τῶν κοσσύφων μέγεθος μὲν κατὰ τοὺς Λυδούς ἐστιν ὄρνιθας, χρόα δὲ ἐμφερὴς κόρακι, κάλλαια δὲ καὶ ὁ λόφος κατὰ ἀνεμώνην μάλιστα· λευκὰ δὲ σημεῖα οὐ μεγάλα ἐπί τε ἄκρῳ τῷ ῥάμφει καὶ ἐπὶ ἄκρας ἔχουσι τῆς οὐρᾶς.", "st": "9.22"}, {"sp": "N", "t": "οὗτοι μὲν τοιοῦτο παρέχονται τὸ εἶδος, τῆς δὲ Βοιωτίας τὰ ἐν ἀριστερᾷ τοῦ Εὐρίπου Μεσσάπιον ὄρος καλούμενον καὶ ὑπ’ αὐτῷ Βοιωτῶν ἐπὶ θαλάσσης πόλις ἐστὶν Ἀνθηδών· γενέσθαι δὲ τῇ πόλει τὸ ὄνομα οἱ μὲν ἀπὸ Ἀνθηδόνος νύμφης, οἱ δὲ Ἄνθαν δυναστεῦσαι λέγουσιν ἐνταῦθα, Ποσειδῶνός τε παῖδα καὶ Ἀλκυόνης τῆς Ἄτλαντος. Ἀνθηδονίοις δὲ μάλιστά που κατὰ μέσον τῆς πόλεως Καβείρων ἱερὸν καὶ ἄλσος περὶ αὐτό ἐστι, πλησίον ⟨δὲ⟩ Δήμητρος καὶ τῆς παιδὸς ναὸς καὶ ἀγάλματα λίθου λευκοῦ·", "st": "9.22"}, {"sp": "N", "t": "Διονύσου τε ἱερὸν πεποίηται καὶ ἄγαλμα πρὸ τῆς πόλεως κατὰ τὸ ἐς τὴν ἤπειρον. ἐνταῦθά εἰσι μὲν τάφοι τῶν Ἰφιμεδείας καὶ Ἀλωέως παίδων· γενέσθαι δέ σφισι τοῦ βίου τὴν τελευτὴν ὑπὸ Ἀπόλλωνος κατὰ τὰ αὐτὰ Ὅμηρος πεποιήκασι καὶ Πίνδαρος, ⟨προστίθησι δὲ Πίνδαρος,⟩ ὡς ἐπιλάβοι τὸ χρεὼν αὐτοὺς ἐν Νάξῳ τῇ ὑπὲρ Πάρου κειμένῃ. τούτων τε δή ἐστι τῇ Ἀνθηδόνι μνήματα καὶ ἐπὶ τῇ θαλάσσῃ καλούμενον Γλαύκου πήδημα·", "st": "9.22"}, {"sp": "N", "t": "εἶναι δὲ αὐτὸν ἁλιέα, καὶ ἐπεὶ τῆς πόας ἔφαγε, δαίμονα ἐν θαλάσσῃ γενέσθαι καὶ ἀνθρώποις τὰ ἐσόμενα ἐς τόδε προλέγειν οἵ τε ἄλλοι πιστὰ ἥγηνται καὶ οἱ τὴν θάλασσαν πλέοντες πλεῖστα ἀνθρώπων ἐς τὴν Γλαύκου μαντικὴν κατὰ ἔτος ἕκαστον λέγουσι. Πινδάρῳ δὲ καὶ Αἰσχύλῳ πυνθανομένοις παρὰ Ἀνθηδονίων, τῷ μὲν οὐκ ἐπὶ πολὺ ἐπῆλθεν ᾆσαι τὰ ἐς Γλαῦκον, Αἰσχύλῳ δὲ καὶ ἐς ποίησιν δράματος ἐξήρκεσε.", "st": "9.22"}, {"sp": "N", "t": "Θηβαίοις δὲ πρὸ τῶν πυλῶν ἐστι τῶν Προιτίδων καὶ τὸ Ἰολάου καλούμενον γυμνάσιον καὶ στάδιον κατὰ ταὐτὰ τῷ τε ἐν Ὀλυμπίᾳ καὶ τῷ Ἐπιδαυρίων γῆς χῶμα· ἐνταῦθα δείκνυται καὶ ἡρῷον Ἰολάου. τελευτῆσαι δὲ ἐν Σαρδοῖ τόν τε Ἰόλαον αὐτὸν καὶ Ἀθηναίων καὶ Θεσπιέων τοὺς συνδιαβάντας ὁμολογοῦσι καὶ οἱ Θηβαῖοι.", "st": "9.23"}, {"sp": "N", "t": "ὑπερβάντι δὲ τοῦ σταδίου τὰ ἐν δεξιᾷ δρόμος ἵππων καὶ ἐν αὐτῷ Πινδάρου μνῆμά ἐστι. Πίνδαρον δὲ ἡλικίαν ὄντα νεανίσκον καὶ ἰόντα ἐς Θεσπιὰς [θέρους] ὥρᾳ καύματος περὶ μεσοῦσαν μάλιστα ἡμέραν κόπος καὶ ὕπνος ἀπ’ αὐτοῦ κατελάμβανεν· ὁ μὲν δὴ ὡς εἷχε κατακλίνεται βραχὺ ὑπὲρ τῆς ὁδοῦ, μέλισσαι δὲ αὐτῷ καθεύδοντι προσεπέτοντό τε καὶ ἔπλασσον πρὸς τὰ χείλη τοῦ κηροῦ.", "st": "9.23"}, {"sp": "N", "t": "ἀρχὴ μὲν Πινδάρῳ ποιεῖν ᾄσματα ἐγένετο τοιαύτη· εὐδοκιμοῦντα δὲ αὐτὸν ἤδη ἀνὰ πᾶσαν τὴν Ἑλλάδα ἐς πλέον δόξης ἦρεν ἡ Πυθία ἀνειποῦσα Δελφοῖς, ὁπόσων ἀπήρχοντο τῷ Ἀπόλλωνι, μοῖραν καὶ Πινδάρῳ τὴν ἴσην ἁπάντων νέμειν. λέγεται δὲ καὶ ὀνείρατος ὄψιν αὐτῷ γενέσθαι προήκοντι ἐς γῆρας· ἐπιστᾶσα ἡ Περσεφόνη οἱ καθεύδοντι οὐκ ἔφασκεν ὑμνηθῆναι μόνη θεῶν ὑπὸ Πινδάρου, ποιήσειν μέντοι καὶ ἐς αὐτὴν ᾆσμα Πίνδαρον ἐλθόντα ὡς αὐτήν.", "st": "9.23"}, {"sp": "N", "t": "τὸν μὲν αὐτίκα τὸ χρεὼν ἐπιλαμβάνει πρὶν ἐξήκειν ἡμέραν δεκάτην ἀπὸ τοῦ ὀνείρατος, ἦν δὲ ἐν Θήβαις γυνὴ πρεσβῦτις γένους ἕνεκα προσήκουσα Πινδάρῳ καὶ τὰ πολλὰ μεμελετηκυῖα ᾄδειν τῶν ᾀσμάτων· ταύτῃ Πίνδαρος ἐνύπνιον τῇ πρεσβύτιδι ἐπιστὰς ὕμνον ᾖσεν ἐς Περσεφόνην, ἡ δὲ αὐτίκα ὡς ἀπέλιπεν αὐτὴν ὁ ὕπνος, ἔγραψε ταῦτα ὁπόσα τοῦ ὀνείρατος ἤκουσεν ᾄδοντος. ἐν τούτῳ τῷ ᾄσματι ἄλλαι τε ἐς τὸν Ἅιδην εἰσὶν ἐπικλήσεις καὶ ὁ χρυσήνιος, δῆλα ὡς ἐπὶ τῆς Κόρης τῇ ἁρπαγῇ.", "st": "9.23"}, {"sp": "N", "t": "ἐντεῦθεν ἐς Ἀκραίφνιόν ἐστιν ὁδὸς τὰ πλείω πεδιάς. εἶναι δὲ ἐξ ἀρχῆς τε μοῖραν τῆς Θηβαΐδος τὴν πόλιν φασὶ καὶ ὕστερον διαπεσόντας Θηβαίων ἐς αὐτὴν ἄνδρας εὕρισκον, ἡνίκα Ἀλέξανδρος ἐποίει τὰς Θήβας ἀναστάτους· ὑπὸ δὲ ἀσθενείας καὶ γήρως οὐδὲ ἐς τὴν Ἀττικὴν ἀποσωθῆναι δυνηθέντες ἐνταῦθα ᾤκησαν. κεῖται μὲν τὸ πόλισμα ἐν ὄρει τῷ Πτώῳ, θέας δὲ ἄξια ἐνταῦθα Διονύσου ναός ἐστι καὶ ἄγαλμα.", "st": "9.23"}, {"sp": "N", "t": "προελθόντι δὲ ἀπὸ τῆς πόλεως ἐν δεξιᾷ πέντε που καὶ δέκα σταδίους τοῦ Ἀπόλλωνός ἐστι τοῦ Πτώου τὸ ἱερόν. εἶναι δὲ Ἀθάμαντος καὶ Θεμιστοῦς παῖδα τὸν Πτῶον, ἀφ’ οὗ τῷ τε Ἀπόλλωνι ἐπίκλησις καὶ τῷ ὄρει τὸ ὄνομα ἐγένετο, Ἄσιος ἐν τοῖς ἔπεσιν εἴρηκε. πρὸ δὲ τῆς Ἀλεξάνδρου καὶ Μακεδόνων ἐπιστρατείας καὶ ὀλέθρου τοῦ Θηβαίων μαντεῖον ἦν αὐτόθι ἀψευδές· καί ποτε ἄνδρα Εὐρωπέα—ὄνομα δέ οἱ εἶναι Μῦν—, τοῦτον ἀποσταλέντα ὑπὸ Μαρδονίου τὸν Μῦν ἐπερέσθαι τε φωνῇ τῇ σφετέρᾳ καί οἱ χρῆσαι τὸν θεόν, οὐχ ἑλληνίσαντα οὐδὲ αὐτόν, διαλέκτῳ τῇ Καρικῇ.", "st": "9.23"}, {"sp": "N", "t": "ὑπερβαλόντων δὲ τὸ ὄρος τὸ Πτῶον ἔστιν ἐπὶ θαλάσσης Βοιωτῶν πόλις Λάρυμνα, γενέσθαι δὲ αὐτῇ τὸ ὄνομά φασιν ἀπὸ Λαρύμνης τῆς Κύνου· τοὺς δὲ ἀνωτέρω προγόνους δηλώσει μοι τὰ ἔχοντα ἐς Λοκροὺς τοῦ λόγου. καὶ συνετέλει δὲ ἐς Ὀποῦντα ἡ Λάρυμνα τὸ ἀρχαῖον· Θηβαίων δὲ ἐπὶ μέγα ἰσχύος προελθόντων, τηνικαῦτα ἑκουσίως μετετάξαντο ἐς Βοιωτούς. Διονύσου δὲ ἐνταῦθα ναὸς καὶ ἄγαλμα ὀρθὸν πεποίηται. λιμὴν δέ σφισίν ἐστιν ἀγχιβαθής, καὶ τὰ ὄρη τὰ ὑπὲρ τὴν πόλιν ὑῶν παρέχεται θήραν ἀγρίων.", "st": "9.23"}, {"sp": "N", "t": "ἐξ Ἀκραιφνίου δὲ ἰόντι εὐθεῖαν ἐπὶ λίμνην τὴν Κηφισίδα—οἱ δὲ Κωπαΐδα ὀνομάζουσι τὴν αὐτήν— πεδίον καλούμενόν ἐστιν Ἀθαμάντιον· οἰκῆσαι δὲ Ἀθάμαντα ἐν αὐτῷ φασιν. ἐς δὲ τὴν λίμνην ὅ τε ποταμὸς ὁ Κηφισὸς ἐκδίδωσιν ἀρχόμενος ἐκ Λιλαίας τῆς Φωκέων καὶ διαπλεύσαντί εἰσι Κῶπαι. κεῖνται δὲ αἱ Κῶπαι πόλισμα ἐπὶ τῇ λίμνῃ, τούτου δὲ καὶ Ὅμηρος ἐποιήσατο ἐν καταλόγῳ μνήμην· ἐνταῦθα Δήμητρος καὶ Διονύσου καὶ Σαράπιδός ἐστιν ἱερά.", "st": "9.24"}, {"sp": "N", "t": "λέγουσι δὲ οἱ Βοιωτοὶ καὶ πολίσματα ἄλλα πρὸς τῇ λίμνῃ ποτὲ Ἀθήνας καὶ Ἐλευσῖνα οἰκεῖσθαι, καὶ ὡς ὥρᾳ χειμῶνος ἐπικλύσασα ἠφάνισεν αὐτὰ ἡ λίμνη. οἱ μὲν δὴ ἰχθῦς οἱ ἐν τῇ Κηφισίδι οὐδέν τι διάφορον ἐς ἄλλους ἰχθῦς τοὺς λιμναίους ἔχουσιν· αἱ δὲ ἐγχέλεις αὐτόθι καὶ μεγέθει μέγισται καὶ ἐσθίειν εἰσὶν ἥδισται.", "st": "9.24"}, {"sp": "N", "t": "Κωπῶν δὲ ἐν ἀριστερᾷ σταδίους προελθόντι ὡς δώδεκα εἰσὶν Ὄλμωνες, Ὀλμωνέων δὲ ἑπτά που στάδια Ὕηττος ἀφέστηκε κῶμαι νῦν τε οὖσαι καὶ εὐθὺς ἐξ ἀρχῆς· μοίρας δὲ ἐμοὶ δοκεῖν τῆς Ὀρχομενίας εἰσὶ καὶ αὗται καὶ πεδίον τὸ Ἀθαμάντιον. καὶ ὅσα μὲν ἐς Ὕηττον ἄνδρα Ἀργεῖον καὶ Ὄλμον τὸν Σισύφου λεγόμενα ἤκουον, προσέσται καὶ αὐτὰ τῇ Ὀρχομενίᾳ συγγραφῇ· θέας δὲ ἄξιον ἐν μὲν Ὄλμωσιν οὐδ’ ἐπὶ βραχύτατον παρεῖχον οὐδέν, ἐν Ὑήττῳ δὲ ναός ἐστιν Ἡρακλέους καὶ ἰάματα εὕρασθαι παρὰ τούτου τοῖς κάμνουσιν ἔστιν, ὄντος οὐχὶ ἀγάλματος σὺν τέχνῃ, λίθου δὲ ἀργοῦ κατὰ τὸ ἀρχαῖον.", "st": "9.24"}, {"sp": "N", "t": "Ὑήττου δὲ στάδια ὡς εἴκοσιν ἀπέχουσι Κύρτωνες· τὸ δὲ ἀρχαῖον ὄνομα τῷ πολίσματί φασιν εἶναι Κυρτώνην. ᾤκισται δὲ ἐπὶ ὄρους ὑψηλοῦ, καὶ Ἀπόλλωνός ἐστιν ἐνταῦθα ναός τε καὶ ἄλσος· ἀγάλματα δὲ ὀρθὰ Ἀπόλλωνος καὶ Ἀρτέμιδός ἐστιν. ἔστι δὲ αὐτόθι καὶ ὕδωρ ψυχρὸν ἐκ πέτρας ἀνερχόμενον· νυμφῶν δὲ ἱερὸν ἐπὶ τῇ πηγῇ καὶ ἄλσος οὐ μέγα ἐστίν, ἥμερα δὲ ὁμοίως πάντα ἐν τῷ ἄλσει δένδρα.", "st": "9.24"}, {"sp": "N", "t": "ἐκ δὲ Κυρτώνων ὑπερβάλλοντι τὸ ὄρος πόλισμά ἐστι Κορσεία, ὑπὸ δὲ αὐτῷ δένδρων ἄλσος οὐχ ἡμέρων· πρῖνοι τὸ πολύ εἰσιν. Ἑρμοῦ δὲ ἄγαλμα οὐ μέγα ἐν ὑπαίθρῳ τοῦ ἄλσους ἕστηκε. τοῦτο ἀπέχει Κορσείας ὅσον τε ἥμισυ σταδίου. καταβάντων δὲ ἐς τὸ χθαμαλὸν ποταμὸς Πλατάνιος καλούμενος ἐκδίδωσιν ἐς θάλασσαν· ἐν δεξιᾷ δὲ τοῦ ποταμοῦ Βοιωτῶν ἔσχατοι ταύτῃ πόλισμα οἰκοῦσιν Ἁλὰς ἐπὶ θαλάσσῃ, ἣ τὴν Λοκρίδα ἤπειρον ἀπὸ τῆς Εὐβοίας διείργει.", "st": "9.24"}, {"sp": "N", "t": "Θηβαίοις δὲ τῶν πυλῶν ἐστιν ἐγγύτατα τῶν Νηιστῶν Μενοικέως μνῆμα τοῦ Κρέοντος· ἀπέκτεινε δὲ ἑκουσίως αὑτὸν κατὰ τὸ μάντευμα τὸ ἐκ Δελφῶν, ἡνίκα Πολυνείκης καὶ ὁ σὺν αὐτῷ στρατὸς ἀφίκοντο ἐξ Ἄργους. τοῦ δὲ Μενοικέως ἐπιπέφυκε ῥοιὰ τῷ μνήματι· τοῦ καρποῦ δὲ ὄντος πεπείρου διαρρήξαντί σοι τὸ ἐκτὸς λοιπόν ἐστιν εὑρεῖν τὸ ἔνδον αἵματι ἐμφερές. αὕτη μὲν δὴ τεθηλὸς δένδρον ἐστὶν ἡ ῥοιά· ἄμπελον δὲ φῦναι μὲν οἱ Θηβαῖοι παρὰ σφίσι πρώτοις φασὶν ἀνθρώπων, ἀποφῆναι δὲ οὐδὲν ἔτι ἐς αὐτὴν ὑπόμνημα εἶχον.", "st": "9.25"}, {"sp": "N", "t": "τοῦ δὲ Μενοικέως οὐ πόρρω τάφου τοὺς παῖδας λέγουσιν Οἰδίποδος μονομαχήσαντας ἀποθανεῖν ὑπὸ ἀλλήλων· σημεῖον δὲ τῆς μάχης αὐτῶν κίων, καὶ ἀσπὶς ἔπεστιν ἐπ’ αὐτῷ λίθου. δείκνυται δέ τι χωρίον ἔνθα Ἥραν Θηβαῖοί φασιν Ἡρακλεῖ παιδὶ ἔτι ἐπισχεῖν γάλα κατὰ δή τινα ἀπάτην ἐκ Διός· καλεῖται δὲ ὁ σύμπας οὗτος ⟨τόπος⟩ Σῦρμα Ἀντιγόνης· ὡς γὰρ τὸν τοῦ Πολυνείκους ἄρασθαί οἱ προθυμουμένῃ νεκρὸν οὐδεμία ἐφαίνετο ῥᾳστώνη, δεύτερα ἐπενόησεν ἕλκειν αὐτόν, ἐς ὃ εἵλκυσέ τε καὶ ἐπέβαλεν ἐπὶ τοῦ Ἐτεοκλέους ἐξημμένην τὴν πυράν.", "st": "9.25"}, {"sp": "N", "t": "διαβάντων δὲ ποταμὸν καλούμενον ἀπὸ γυναικὸς τῆς Λύκου Δίρκην—ὑπὸ ταύτης δὲ ἔχει λόγος Ἀντιόπην κακοῦσθαι καὶ δι’ αὐτὸ ὑπὸ τῶν Ἀντιόπης παίδων συμβῆναι τῇ Δίρκῃ τὴν τελευτήν—, διαβᾶσιν οὖν τὴν Δίρκην οἰκίας τε ἐρείπια τῆς Πινδάρου καὶ μητρὸς Δινδυμήνης ἱερόν, Πινδάρου μὲν ἀνάθημα, τέχνη δὲ τὸ ἄγαλμα Ἀριστομήδους τε καὶ Σωκράτους Θηβαίων. μιᾷ δὲ ἐφ’ ἑκάστων ἐτῶν ἡμέρᾳ καὶ οὐ πέρα τὸ ἱερὸν ἀνοίγειν νομίζουσιν· ἐμοὶ δὲ ἀφικέσθαι τε ἐξεγεγόνει τὴν ἡμέραν ταύτην καὶ τὸ ἄγαλμα εἶδον λίθου τοῦ Πεντελῆσι καὶ αὐτὸ καὶ τὸν θρόνον.", "st": "9.25"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν ⟨τὴν⟩ ἀπὸ τῶν πυλῶν τῶν Νηιστῶν τὸ μὲν Θέμιδός ἐστιν ἱερὸν καὶ ἄγαλμα λευκοῦ λίθου, τὸ δὲ ἐφεξῆς Μοιρῶν, τὸ δὲ Ἀγοραίου Διός· οὗτος μὲν δὴ λίθου πεποίηται, ταῖς Μοίραις δὲ οὐκ ἔστιν ἀγάλματα. καὶ ἀπωτέρω μικρὸν Ἡρακλῆς ἕστηκεν ἐν ὑπαίθρῳ Ῥινοκολούστης ἐπωνυμίαν ἔχων, ὅτι τῶν κηρύκων, ὡς οἱ Θηβαῖοι λέγουσιν, ἀπέτεμεν ἐπὶ λώβῃ τὰς ῥῖνας, οἳ παρὰ Ὀρχομενίων ἀφίκοντο ἐπὶ τοῦ δασμοῦ τὴν ἀπαίτησιν.", "st": "9.25"}, {"sp": "N", "t": "σταδίους δὲ αὐτόθεν πέντε προελθόντι καὶ εἴκοσι Δήμητρος Καβειραίας καὶ Κόρης ἐστὶν ἄλσος· ἐσελθεῖν δὲ τοῖς τελεσθεῖσιν ἔστι. τούτου δὲ τοῦ ἄλσους ἑπτά που σταδίους τῶν Καβείρων τὸ ἱερὸν ἀφέστηκεν. οἵτινες δέ εἰσιν οἱ Κάβειροι καὶ ὁποῖά ἐστιν αὐτοῖς καὶ τῇ Μητρὶ τὰ δρώμενα, σιωπὴν ἄγοντι ὑπὲρ αὐτῶν συγγνώμη παρὰ ἀνδρῶν φιληκόων ἔστω μοι.", "st": "9.25"}, {"sp": "N", "t": "τοσοῦτο δὲ δηλῶσαί με καὶ ἐς ἅπαντας ἐκώλυσεν οὐδέν, ἥντινα λέγουσιν ἀρχὴν οἱ Θηβαῖοι γενέσθαι τοῖς δρωμένοις. πόλιν γάρ ποτε ἐν τούτῳ φασὶν εἶναι τῷ χωρίῳ καὶ ἄνδρας ὀνομαζομένους Καβείρους, Προμηθεῖ δὲ ἑνὶ τῶν Καβείρων καὶ Αἰτναίῳ τῷ Προμηθέως ἀφικομένην Δήμητρα ἐς γνῶσιν παρακαταθέσθαι σφίσιν· ἥτις μὲν δὴ ἦν ἡ παρακαταθήκη καὶ τὰ ἐς αὐτὴν γινόμενα, οὐκ ἐφαίνετο ὅσιόν μοι γράφειν, Δήμητρος δ’ οὖν Καβειραίοις δῶρόν ἐστιν ἡ τελετή.", "st": "9.25"}, {"sp": "N", "t": "κατὰ δὲ τὴν Ἐπιγόνων στρατείαν καὶ ἅλωσιν τῶν Θηβῶν ἀνέστησαν μὲν ὑπὸ τῶν Ἀργείων οἱ Καβειραῖοι, ἐξελείφθη δὲ ἐπὶ χρόνον τινὰ καὶ ἡ τελετή. Πελαργὴν δὲ ὕστερον τὴν Ποτνιέως καὶ Ἰσθμιάδην Πελαργῇ συνοικοῦντα καταστήσασθαι μὲν τὰ ὄργια αὐτοῦ λέγουσιν ἐξ ἀρχῆς, μετενεγκεῖν δὲ αὐτὰ ἐπὶ τὸν Ἀλεξιάρουν καλούμενον·", "st": "9.25"}, {"sp": "N", "t": "ὅτι δὲ τῶν ὅρων ἐκτὸς ἐμύησεν ἡ Πελαργὴ τῶν ἀρχαίων, Τηλώνδης καὶ ὅσοι γένους τοῦ Καβειριτῶν ἐλείποντο κατῆλθον αὖθις ἐς τὴν Καβειραίαν. Πελαργῇ μὲν δὴ κατὰ μάντευμα ἐκ Δωδώνης καὶ ἄλλα ἔμελλεν ἐς τιμὴν καταστήσασθαι καὶ ἡ θυσία, φέρον ἐν τῇ γαστρὶ ἱερεῖον· τὸ δὲ μήνιμα τὸ ἐκ τῶν Καβείρων ἀπαραίτητόν ἐστιν ἀνθρώποις, ὡς ἐπέδειξε δὴ πολλαχῇ.", "st": "9.25"}, {"sp": "N", "t": "τὰ γὰρ δὴ δρώμενα ἐν Θήβαις ἐτόλμησαν ἐν Ναυπάκτῳ κατὰ ταὐτὰ ἰδιῶται δρᾶσαι, καὶ σφᾶς οὐ μετὰ πολὺ ἐπέλαβεν ἡ δίκη. ὅσοι δὲ ὁμοῦ Μαρδονίῳ τῆς στρατιᾶς τῆς Ξέρξου περὶ Βοιωτίαν ἐλείφθησαν, τοῖς παρελθοῦσιν αὐτῶν ἐς τὸ ἱερὸν τῶν Καβείρων τάχα μέν που καὶ χρημάτων μεγάλων ἐλπίδι, τὸ πλέον δὲ ἐμοὶ δοκεῖν τῇ ἐς τὸ θεῖον ὀλιγωρίᾳ, τούτοις παραφρονῆσαί τε συνέπεσεν αὐτίκα καὶ ἀπώλοντο ἐς θάλασσάν τε καὶ ἀπὸ τῶν κρημνῶν ἑαυτοὺς ῥίπτοντες.", "st": "9.25"}, {"sp": "N", "t": "Ἀλεξάνδρου δέ, ὡς ἐνίκησε τῇ μάχῃ, Θήβας τε αὐτὰς καὶ σύμπασαν τὴν Θηβαΐδα διδόντος πυρί, ἄνδρες τῶν ἐκ Μακεδονίας ἐλθόντες ἐς τῶν Καβείρων τὸ ἱερὸν ἅτε ἐν γῇ τῇ πολεμίᾳ κεραυνοῖς τε ἐξ οὐρανοῦ καὶ ἀστραπαῖς ἐφθάρησαν.", "st": "9.25"}, {"sp": "N", "t": "οὕτω μὲν τὸ ἱερὸν τοῦτό ἐστιν ἐξ ἀρχῆς ἅγιον· τοῦ Καβειρίου δὲ ἐν δεξιᾷ πεδίον ἐστὶν ἐπώνυμον Τηνέρου μάντεως, ὃν Ἀπόλλωνος παῖδα εἶναι καὶ Μελίας νομίζουσι, καὶ Ἡρακλέους ἱερὸν μέγα ἐπίκλησιν Ἱπποδέτου· τούς τε γὰρ Ὀρχομενίους φασὶν ἐς τοῦτο ἀφῖχθαι στρατιᾷ καὶ τὸν Ἡρακλέα νύκτωρ τοὺς ἵππους λαβόντα συνδῆσαί σφισι τοὺς ὑπὸ τοῖς ἅρμασι.", "st": "9.26"}, {"sp": "N", "t": "προελθόντων δὲ τὸ ὄρος ἐστὶν ὅθεν τὴν Σφίγγα λέγουσιν ὁρμᾶσθαι ἐπ’ ὀλέθρῳ τῶν ἁρπαζομένων αἴνιγμα ᾄδουσαν· οἱ δὲ κατὰ λῃστείαν σὺν δυνάμει ναυτικῇ πλανωμένην φασὶν αὐτὴν ἐς τὴν πρὸς Ἀνθηδόνι σχεῖν θάλασσαν, καταλαβοῦσαν δὲ τὸ ὄρος τοῦτο ἁρπαγαῖς χρῆσθαι, πρὶν ἐξεῖλεν Οἰδίπους αὐτὴν ὑπερβαλόμενος πλήθει στρατιᾶς ἣν ἀφίκετο ἔχων ἐκ Κορίνθου.", "st": "9.26"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὡς νόθη Λαΐου θυγάτηρ εἴη, καὶ ὡς τὸν χρησμὸν τὸν Κάδμῳ δοθέντα ἐκ Δελφῶν διδάξειεν αὐτὴν κατὰ εὔνοιαν ὁ Λάιος· ἐπίστασθαι δὲ πλὴν τοὺς βασιλέας οὐδένα ἄλλον τὸ μάντευμα. ὁπότε οὖν τῇ Σφιγγὶ ἀμφισβητήσων τις ἀφίκοιτο τῆς ἀρχῆς—γενέσθαι γὰρ τῷ Λαΐῳ ἐκ παλλακῶν υἱοὺς καὶ τὰ χρησθέντα ἐκ Δελφῶν ἐς Ἐπικάστην μόνην καὶ τοὺς ἐξ ἐκείνης ἔχειν παῖδας—, τὴν οὖν Σφίγγα χρῆσθαι σοφίσμασιν ἐς τοὺς ἀδελφούς, ὡς τὸν Κάδμῳ γενόμενον χρησμὸν εἰδεῖεν ἂν Λαΐου γε ὄντες·", "st": "9.26"}, {"sp": "N", "t": "οὐκ ἔχοντας δὲ αὐτοὺς ἀποκρίνασθαι θανάτῳ ζημιοῦν, ἅτε οὐ προσηκόντως ἀμφισβητοῦντας γένους τε καὶ ἀρχῆς. Οἰδίπους δὲ ἄρα ἀφίκετο ὑπὸ ὀνείρατος δεδιδαγμένος τὸν χρησμόν.", "st": "9.26"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ ὄρους τούτου πέντε ἀπέχει καὶ δέκα σταδίους πόλεως ἐρείπια Ὀγχηστοῦ· φασὶ δὲ ἐνταῦθα οἰκῆσαι Ποσειδῶνος παῖδα Ὀγχηστόν. ἐπ’ ἐμοῦ δὲ ναός τε καὶ ἄγαλμα Ποσειδῶνος ἐλείπετο Ὀγχηστίου καὶ τὸ ἄλσος, ὃ δὴ καὶ Ὅμηρος ἐπῄνεσε.", "st": "9.26"}, {"sp": "N", "t": "τραπομένῳ δὲ ἀπὸ τοῦ Καβειρίου τὴν ἐν ἀριστερᾷ καὶ προελθόντι ὡς πεντήκοντα σταδίους Θέσπια ὑπὸ τὸ ὄρος τὸν Ἑλικῶνα ᾤκισται. θυγατέρα δὲ εἶναι Θέσπιαν λέγουσιν Ἀσωποῦ καὶ ἀπὸ ταύτης κληθῆναι τὴν πόλιν, οἱ δὲ Θέσπιόν φασιν ἐξ Ἀθηνῶν ἐλθόντα τὸ ὄνομα τῇ πόλει δοῦναι·", "st": "9.26"}, {"sp": "N", "t": "γεγονέναι δὲ ἀπὸ Ἐρεχθέως αὐτόν. Θεσπιεῦσι δὲ ἐν τῇ πόλει Σαώτου Διός ἐστι χαλκοῦν ἄγαλμα· ἐπιλέγουσι δὲ ὡς λυμαινομένου τὴν πόλιν ποτὲ αὐτοῖς δράκοντος προστάξειεν ὁ θεὸς τὸν κλήρῳ τῶν ἐφήβων κατὰ ἔτος ἕκαστον λαχόντα δίδοσθαι τῷ θηρίῳ. τῶν μὲν δὴ διαφθαρέντων μνημονεύειν τὰ ὀνόματα οὔ φασιν· ἐπὶ δὲ Κλεοστράτῳ λαχόντι τὸν ἐραστὴν αὐτοῦ Μενέστρατον λέγουσιν ἐπιτεχνήσασθαι.", "st": "9.26"}, {"sp": "N", "t": "χαλκοῦν θώρακα ἐποιήσατο ἔχοντα ἐπὶ ἑκάστῃ τῶν φολίδων ἄγκιστρον ἐς τὸ ἄνω νεῦον· τοῦτον τὸν θώρακα ἐνδὺς παρέδωκε τῷ δράκοντι ἑκουσίως αὑτόν, παραδοὺς δὲ ἀπολεῖσθαί τε καὶ αὐτὸς ἀπολεῖν ἔμελλε τὸ θηρίον. ἀντὶ τούτου μὲν τῷ Διὶ γέγονεν ἐπίκλησις Σαώτης· τὸ δὲ ἄγαλμα τὸ Διονύσου καὶ αὖθις Τύχης, ἑτέρωθι δὲ Ὑγείας …, τὴν δὲ Ἀθηνᾶν τὴν Ἐργάνην καὶ αὐτὴν καὶ Πλοῦτόν οἱ παρεστηκότα ἐποίησε ….", "st": "9.26"}, {"sp": "N", "t": "θεῶν δὲ οἱ Θεσπιεῖς τιμῶσιν Ἔρωτα μάλιστα ἐξ ἀρχῆς, καί σφισιν ἄγαλμα παλαιότατόν ἐστιν ἀργὸς λίθος. ὅστις δὲ ὁ καταστησάμενος Θεσπιεῦσιν Ἔρωτα θεῶν σέβεσθαι μάλιστα, οὐκ οἶδα. σέβονται δὲ οὐδέν τι ἧσσον καὶ Ἑλλησποντίων Παριανοί, τὸ μὲν ἀνέκαθεν ἐξ Ἰωνίας καὶ Ἐρυθρῶν ἀπῳκισμένοι, τὰ δὲ ἐφ’ ἡμῶν τελοῦντες ἐς Ῥωμαίους.", "st": "9.27"}, {"sp": "N", "t": "Ἔρωτα δὲ ἄνθρωποι μὲν οἱ πολλοὶ νεώτατον θεῶν εἶναι καὶ Ἀφροδίτης παῖδα ἥγηνται· Λύκιος δὲ Ὠλήν, ὃς καὶ τοὺς ὕμνους τοὺς ἀρχαιοτάτους ἐποίησεν Ἕλλησιν, οὗτος ὁ Ὠλὴν ἐν Εἰλειθυίας ὕμνῳ μητέρα Ἔρωτος τὴν Εἰλείθυιάν φησιν εἶναι. Ὠλῆνος δὲ ὕστερον Πάμφως τε ἔπη καὶ Ὀρφεὺς ἐποίησαν· καί σφισιν ἀμφοτέροις πεποιημένα ἐστὶν ἐς Ἔρωτα, ἵνα ἐπὶ τοῖς δρωμένοις Λυκομίδαι καὶ ταῦτα ᾄδωσιν· ἐγὼ δὲ ἐπελεξάμην ἀνδρὶ ἐς λόγους ⟨ἐλθὼν⟩ δᾳδουχοῦντι. καὶ τῶν μὲν οὐ πρόσω ποιήσομαι μνήμην· Ἡσίοδον δὲ ἢ τὸν Ἡσιόδῳ Θεογονίαν ἐσποιήσαντα οἶδα γράψαντα ὡς Χάος πρῶτον, ἐπὶ δὲ αὐτῷ Γῆ τε καὶ Τάρταρος καὶ Ἔρως γένοιτο·", "st": "9.27"}, {"sp": "N", "t": "Σαπφὼ δὲ ἡ Λεσβία πολλά τε καὶ οὐχ ὁμολογοῦντα ἀλλήλοις ἐς Ἔρωτα ᾖσε. Θεσπιεῦσι δὲ ὕστερον χαλκοῦν εἰργάσατο Ἔρωτα Λύσιππος, καὶ ἔτι πρότερον τούτου Πραξιτέλης λίθου τοῦ Πεντελῆσι. καὶ ὅσα μὲν εἶχεν ἐς Φρύνην καὶ τὸ ἐπὶ Πραξιτέλει τῆς γυναικὸς σόφισμα, ἑτέρωθι ἤδη μοι δεδήλωται· πρῶτον δὲ τὸ ἄγαλμα κινῆσαι τοῦ Ἔρωτος λέγουσι Γάιον δυναστεύσαντα ἐν Ῥώμῃ, Κλαυδίου δὲ ὀπίσω Θεσπιεῦσιν ἀποπέμψαντος Νέρωνα αὖθις δεύτερα ἀνάσπαστον ποιῆσαι.", "st": "9.27"}, {"sp": "N", "t": "καὶ τὸν μὲν φλὸξ αὐτόθι διέφθειρε· τῶν δὲ ἀσεβησάντων ἐς τὸν θεὸν ὁ μὲν ἀνθρώπῳ στρατιώτῃ διδοὺς ἀεὶ τὸ αὐτὸ σύνθημα μετὰ ὑπούλου χλευασίας ἐς τοσοῦτο προήγαγε θυμοῦ τὸν ἄνθρωπον ὥστε σύνθημα διδόντα αὐτὸν διεργάζεται, Νέρωνι δὲ παρὲξ ⟨ἢ⟩ τὰ ἐς τὴν μητέρα ἐστὶ καὶ ἐς γυναῖκας γαμετὰς ἐναγῆ τε καὶ ἀνέραστα τολμήματα. τὸν δὲ ἐφ’ ἡμῶν Ἔρωτα ἐν Θεσπιαῖς ἐποίησεν Ἀθηναῖος Μηνόδωρος, τὸ ἔργον τὸ Πραξιτέλους μιμούμενος.", "st": "9.27"}, {"sp": "N", "t": "ἐνταῦθα καὶ αὐτοῦ Πραξιτέλους Ἀφροδίτη καὶ Φρύνης ἐστὶν εἰκών, λίθου καὶ ἡ Φρύνη καὶ ἡ θεός. ἔστι δὲ καὶ ἑτέρωθι Ἀφροδίτης Μελαινίδος ἱερὸν καὶ θέατρόν τε καὶ ἀγορὰ θέας ἄξια· ἐνταῦθα Ἡσίοδος ἀνάκειται χαλκοῦς. τῆς ἀγορᾶς [τε] οὐ πόρρω Νίκη τε χαλκοῦ καὶ ναὸς Μουσῶν ἐστιν οὐ μέγας· ἀγάλματα δὲ ἐν αὐτῷ μικρὰ λίθου πεποιημένα.", "st": "9.27"}, {"sp": "N", "t": "καὶ Ἡρακλέους Θεσπιεῦσίν ἐστιν ἱερόν· ἱερᾶται δὲ αὐτοῦ παρθένος, ἔστ’ ἂν ἐπιλάβῃ τὸ χρεὼν αὐτήν. αἴτιον δὲ τούτου φασὶν εἶναι τοιόνδε, Ἡρακλέα ταῖς θυγατράσι πεντήκοντα οὔσαις ταῖς Θεστίου συγγενέσθαι πάσαις πλὴν μιᾶς ἐν τῇ αὐτῇ νυκτί· ταύτην δὲ οὐκ ἐθελῆσαί οἱ τὴν μίαν μιχθῆναι· ⟨τὸν δὲ ὑβρισθῆναι⟩ νομίζοντα δικάσαι μένειν παρθένον πάντα αὐτὴν τὸν βίον ἱερωμένην αὐτῷ.", "st": "9.27"}, {"sp": "N", "t": "ἐγὼ δὲ ἤκουσα μὲν καὶ ἄλλον λόγον, ὡς διὰ πασῶν ὁ Ἡρακλῆς τῶν Θεστίου παρθένων διεξέλθοι τῇ αὐτῇ νυκτὶ καὶ ὡς ἄρσενας παῖδας αὐτῷ πᾶσαι τέκοιεν, διδύμους δὲ ἥ τε νεωτάτη καὶ ἡ πρεσβυτάτη· ἐκεῖνο δὲ οὐκ ἔστιν ὅπως ἡγήσομαι πιστόν, Ἡρακλέα ἐπὶ τοσοῦτο ὀργῆς ἀνδρὸς φίλου θυγατρὶ ἀφικέσθαι· πρὸς δὲ καὶ ἡνίκα ἔτι ἦν μετ’ ἀνθρώπων, τιμωρούμενός τε ἄλλους ὑβρίζοντας καὶ μάλιστα ὅσοι θεῶν ἀσεβεῖς ἦσαν, οὐκ ἂν αὐτός γε κατεστήσατο αὑτῷ ναόν τε καὶ ἱέρειαν ὥσπερ δὴ θεός.", "st": "9.27"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἐφαίνετό μοι τὸ ἱερὸν τοῦτο ἀρχαιότερον ἢ κατὰ Ἡρακλέα εἶναι τὸν Ἀμφιτρύωνος, καὶ Ἡρακλέους τοῦ καλουμένου τῶν Ἰδαίων Δακτύλων, οὗ δὴ καὶ Ἐρυθραίους τοὺς ἐν Ἰωνίᾳ καὶ Τυρίους ἱερὰ ἔχοντας εὕρισκον. οὐ μὴν οὐδὲ οἱ Βοιωτοὶ τοῦ Ἡρακλέους ἠγνόουν τοῦτο τὸ ὄνομα, ὅπου γε αὐτοὶ τῆς Μυκαλησσίας Δήμητρος Ἡρακλεῖ τῷ Ἰδαίῳ τὸ ἱερὸν ἐπιτετράφθαι λέγουσιν.", "st": "9.27"}, {"sp": "N", "t": "ὁ δὲ Ἑλικὼν ὀρῶν τῶν ἐν τῇ Ἑλλάδι ἐν τοῖς μάλιστά ἐστιν εὔγεως καὶ δένδρων ἡμέρων ἀνάπλεως· καὶ οἱ τῆς ἀνδράχνου θάμνοι παρέχονται τῶν πανταχοῦ καρπὸν αἰξὶν ἥδιστον. λέγουσι δὲ οἱ περὶ τὸν Ἑλικῶνα οἰκοῦντες καὶ ἁπάσας ἐν τῷ ὄρει τὰς πόας καὶ τὰς ῥίζας ἥκιστα ἐπὶ ἀνθρώπου θανάτῳ φύεσθαι. καὶ δὴ καὶ τοῖς ὄφεσι τὸν ἰὸν ποιοῦσιν ἐνταῦθα ἀσθενέστερον αἱ νομαί, ὥστε καὶ διαφεύγουσι τὰ πολλὰ οἱ δηχθέντες, ἢν ἀνδρὶ Λίβυι γένους τοῦ Ψύλλων ἢ καὶ ἄλλως προσφόροις ἐπιτύχωσι τοῖς φαρμάκοις.", "st": "9.28"}, {"sp": "N", "t": "ἔστι μὲν δὴ ὁ ἰὸς τοῖς ἀγριωτάτοις τῶν ὄφεων καὶ ἄλλως ὀλέθριος ἔς τε ἀνθρώπους καὶ ζῷα ὁμοίως τὰ πάντα, συντελοῦσι δὲ οὐχ ἥκιστα ἐς ἰσχύν σφισι τοῦ ἰοῦ καὶ αἱ νομαί, ἐπεί τοι καὶ ἀνδρὸς ἀκούσας οἶδα Φοίνικος ὡς ἐν τῇ ὀρεινῇ τῇ Φοινίκης ἀγριωτέρους τοὺς ἔχεις ποιοῦσιν αἱ ῥίζαι. ἔφη δὲ ἄνθρωπον ἰδεῖν αὐτὸς ἀποφεύγοντα ὁρμὴν ἔχεως, καὶ τὸν μὲν ἐπί τι ἀναδραμεῖν δένδρον, τὸν δὲ ἔχιν, ὡς ἦλθεν ὕστερος, ἀποπνεῦσαι πρὸς τὸ δένδρον τοῦ ἰοῦ καὶ οὐ ζῆν ἔτι τὸν ἄνθρωπον.", "st": "9.28"}, {"sp": "N", "t": "τούτου μὲν τοιαῦτα ἤκουσα· ἐν δὲ τῇ χώρᾳ τῇ Ἀράβων ὅσοι τῶν ἔχεων περὶ τὰ δένδρα τὰ πάλσαμα οἰκοῦσι, τοιάδε ἄλλα ἐς αὐτοὺς συμβαίνοντα οἶδα. μέγεθος μὲν κατὰ μυρσίνης θάμνον τὰ πάλσαμά ἐστι, φύλλα δὲ αὐτοῖς κατὰ τὴν πόαν τὸ σάμψουχον· ἔχεων δὲ τῶν ἐν τῇ Ἀραβίᾳ κατὰ ποσοὺς καὶ πλείονες καὶ ἐλάσσονες ὑπὸ ἕκαστον αὐλίζονται δένδρον· τροφὴ γὰρ αὐτοῖς ὁ τῶν παλσάμων ἐστὶν ὀπὸς ἡδίστη, καὶ ἔτι καὶ ἄλλως τῇ σκιᾷ τῶν φυτῶν χαίρουσιν.", "st": "9.28"}, {"sp": "N", "t": "ἐπὰν οὖν συλλέγειν τοῦ παλσάμου τὸν ὀπὸν ἀφίκηται τοῖς Ἄραψιν ὥρα, ξύλων δύο ἕκαστος σκυτάλας ἐπὶ τοὺς ἔχεις ἐσφέρει, κροτοῦντες δὲ τὰ ξύλα ἀπελαύνουσι τοὺς ἔχεις· ἀποκτείνειν δὲ αὐτοὺς οὐκ ἐθέλουσιν ἱεροὺς τῶν παλσάμων νομίζοντες. ἢν δὲ καὶ ὑπὸ ἔχεων δηχθῆναί τῳ συμβῇ, τὸ μὲν τραῦμά ἐστιν ὁποῖον καὶ ὑπὸ σιδήρου, δεῖμα δὲ ἄπεστι τὸ ἀπὸ τοῦ ἰοῦ· ἅτε γὰρ σιτουμένοις τοῖς ἔχεσι μύρων τὸ εὐοσμότατον, μετακεράννυταί σφισιν ἐκ τοῦ θανατώδους ἐς τὸ ἠπιώτερον ὁ ἰός.", "st": "9.28"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἔχοντά ἐστιν οὕτω, θῦσαι δὲ ἐν Ἑλικῶνι Μούσαις πρώτους καὶ ἐπονομάσαι τὸ ὄρος ἱερὸν εἶναι Μουσῶν Ἐφιάλτην καὶ Ὦτον λέγουσιν, οἰκίσαι δὲ αὐτοὺς καὶ Ἄσκρην· καὶ δὴ καὶ Ἡγησίνους ἐπὶ τῷδε ἐν τῇ Ἀτθίδι ἐποίησεν,<br>Ἄσκρῃ δ’ αὖ παρέλεκτο Ποσειδάων ἐνοσίχθων,<br>ἣ δή οἱ τέκε παῖδα περιπλομένων ἐνιαυτῶν<br>Οἴοκλον, ὃς πρῶτος μετ’ Ἀλωέος ἔκτισε παίδων<br>Ἄσκρην, ἥ θ’ Ἑλικῶνος ἔχει πόδα πιδακόεντα.", "st": "9.29"}, {"sp": "N", "t": "ταύτην τοῦ Ἡγησίνου τὴν ποίησιν οὐκ ἐπελεξάμην, ἀλλὰ πρότερον ἄρα ἐκλελοιπυῖα ἦν πρὶν ἢ ἐμέ γενέσθαι· Κάλλιππος δὲ Κορίνθιος ἐν τῇ ἐς Ὀρχομενίους συγγραφῇ μαρτύρια ποιεῖται τῷ λόγῳ τὰ Ἡγησίνου ἔπη, ὡσαύτως δὲ καὶ ἡμεῖς πεποιήμεθα παρ’ αὐτοῦ Καλλίππου διδαχθέντες. Ἄσκρης μὲν δὴ πύργος εἷς ἐπ’ ἐμοῦ καὶ ἄλλο οὐδὲν ἐλείπετο ἐς μνήμην, οἱ δὲ τοῦ Ἀλωέως παῖδες ἀριθμόν τε Μούσας ἐνόμισαν εἶναι τρεῖς καὶ ὀνόματα αὐταῖς ἔθεντο Μελέτην καὶ Μνήμην καὶ Ἀοιδήν.", "st": "9.29"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερόν φασι Πίερον Μακεδόνα, ἀφ’ οὗ καὶ Μακεδόσιν ὠνόμασται τὸ ὄρος, τοῦτον ἐλθόντα ἐς Θεσπιὰς ἐννέα τε Μούσας καταστήσασθαι καὶ τὰ ὀνόματα τὰ νῦν μεταθέσθαι σφίσι. ταῦτα δὲ ἐνόμιζεν οὕτως ὁ Πίερος ἢ σοφώτερά οἱ εἶναι φανέντα ἢ κατά τι μάντευμα ἢ παρά του διδαχθεὶς τῶν Θρᾳκῶν· δεξιώτερον γὰρ τά τε ἄλλα ἐδόκει τοῦ Μακεδονικοῦ τὸ ἔθνος εἶναι πάλαι τὸ Θρᾴκιον καὶ οὐχ ὁμοίως ἐς τὰ θεῖα ὀλίγωρον.", "st": "9.29"}, {"sp": "N", "t": "εἰσὶ δ’ οἳ καὶ αὐτῷ θυγατέρας ἐννέα Πιέρῳ γενέσθαι λέγουσι καὶ τὰ ὀνόματα ἅπερ ταῖς θεαῖς τεθῆναι καὶ ταύταις, καὶ ὅσοι Μουσῶν παῖδες ἐκλήθησαν ὑπὸ Ἑλλήνων, θυγατριδοῦς εἶναι σφᾶς Πιέρου· Μίμνερμος δέ, ἐλεγεῖα ἐς τὴν μάχην ποιήσας τὴν Σμυρναίων πρὸς Γύγην τε καὶ Λυδούς, φησὶν ἐν τῷ προοιμίῳ θυγατέρας Οὐρανοῦ τὰς ἀρχαιοτέρας Μούσας, τούτων δὲ ἄλλας νεωτέρας εἶναι Διὸς παῖδας.", "st": "9.29"}, {"sp": "N", "t": "ἐν Ἑλικῶνι δὲ πρὸς τὸ ἄλσος ἰόντι τῶν Μουσῶν ἐν ἀριστερᾷ μὲν ἡ Ἀγανίππη πηγή —θυγατέρα δὲ εἶναι τὴν Ἀγανίππην τοῦ Τερμησσοῦ λέγουσι, ῥεῖ δὲ καὶ οὗτος ὁ Τερμησσὸς περὶ τὸν Ἑλικῶνα—, τὴν δὲ εὐθεῖαν ἐρχομένῳ πρὸς τὸ ἄλσος ἔστιν εἰκὼν Εὐφήμης ἐπειργασμένη λίθῳ· τροφὸν δὲ εἶναι τὴν Εὐφήμην λέγουσι τῶν Μουσῶν.", "st": "9.29"}, {"sp": "N", "t": "ταύτης τε οὖν εἰκὼν καὶ μετ’ αὐτὴν Λίνος ἐστὶν ἐν πέτρᾳ μικρᾷ σπηλαίου τρόπον εἰργασμένῃ· τούτῳ κατὰ ἔτος ἕκαστον πρὸ τῆς θυσίας τῶν Μουσῶν ἐναγίζουσι. λέγεται δὲ ὡς ὁ Λίνος οὗτος παῖς μὲν Οὐρανίας εἴη καὶ Ἀμφιμάρου τοῦ Ποσειδῶνος, μεγίστην δὲ τῶν τε ἐφ’ αὑτοῦ καὶ ὅσοι πρότερον ἐγένοντο λάβοι δόξαν ἐπὶ μουσικῇ, καὶ ὡς Ἀπόλλων ἀποκτείνειεν αὐτὸν ἐξισούμενον κατὰ τὴν ᾠδήν.", "st": "9.29"}, {"sp": "N", "t": "ἀποθανόντος δὲ τοῦ Λίνου τὸ ἐπ’ αὐτῷ πένθος διῆλθεν ἄρα καὶ ἄχρι τῆς βαρβάρου πάσης, ὡς καὶ Αἰγυπτίοις ᾆσμα γενέσθαι Λίνον· καλοῦσι δὲ τὸ ᾆσμα Αἰγύπτιοι τῇ ἐπιχωρίῳ φωνῇ Μανέρων. οἱ δὲ Ἕλλησιν ἔπη ποιήσαντες, Ὅμηρος μέν, ἅτε ᾆσμα Ἕλλησιν ὂν ἐπιστάμενος τοῦ Λίνου τὰ παθήματα, ἐπὶ τοῦ Ἀχιλλέως ἔφη τῇ ἀσπίδι ἄλλα τε ἐργάσασθαι τὸν Ἥφαιστον καὶ κιθαρῳδὸν παῖδα ᾄδοντα τὰ ἐς Λίνον·<br>τοῖσι δ’ ἐνὶ μέσσοισι πάις φόρμιγγι λιγείῃ<br>ἱμερόεν κιθάριζε, Λίνον δ’ ὑπὸ καλὸν ἄειδεν·", "st": "9.29"}, {"sp": "N", "t": "Πάμφως δέ, ὃς Ἀθηναίοις τῶν ὕμνων ἐποίησε τοὺς ἀρχαιοτάτους, οὗτος ἀκμάζοντος ἐπὶ τῷ Λίνῳ τοῦ πένθους Οἰτόλινον ἐκάλεσεν αὐτόν. Σαπφὼ δὲ ἡ Λεσβία τοῦ Οἰτολίνου τὸ ὄνομα ἐκ τῶν ἐπῶν τῶν Πάμφω μαθοῦσα Ἄδωνιν ὁμοῦ καὶ Οἰτόλινον ᾖσεν. Θηβαῖοι δὲ λέγουσι παρὰ σφίσι ταφῆναι τὸν Λίνον, καὶ ὡς μετὰ τὸ πταῖσμα τὸ ἐν Χαιρωνείᾳ τὸ Ἑλληνικὸν Φίλιππος ὁ Ἀμύντου κατὰ δή τινα ὄψιν ὀνείρατος τὰ ὀστᾶ ἀνελόμενος τοῦ Λίνου κομίσειεν ἐς Μακεδονίαν·", "st": "9.29"}, {"sp": "N", "t": "ἐκεῖνον μὲν δὴ αὖθις ἐξ ἐνυπνίων ἄλλων ὀπίσω τοῦ Λίνου τὰ ὀστᾶ ἐς Θήβας ἀποστεῖλαι, τὰ δὲ ἐπιθήματα τοῦ τάφου, καὶ ὅσα σημεῖα ἄλλα ἦν, ἀνὰ χρόνον φασὶν ἀφανισθῆναι. λέγεται δὲ καὶ ἄλλα τοιάδε ὑπὸ Θηβαίων, ὡς τοῦ Λίνου τούτου γένοιτο ὕστερον ἕτερος Λίνος καλούμενος Ἰσμηνίου καὶ ὡς Ἡρακλῆς ἔτι παῖς ὢν ἀποκτείνειεν αὐτὸν διδάσκαλον μουσικῆς ὄντα. ἔπη δὲ οὔτε ὁ Ἀμφιμάρου Λίνος οὔτε ὁ τούτου γενόμενος ὕστερον ἐποίησαν· ἢ καὶ ποιηθέντα ἐς τοὺς ἔπειτα οὐκ ἦλθεν.", "st": "9.29"}, {"sp": "N", "t": "ταῖς Μούσαις δὲ ἀγάλματα ⟨τὰ⟩ μὲν πρῶτά ἐστι Κηφισοδότου τέχνη πάσαις, προελθόντι δὲ οὐ πολὺ τρεῖς μέν εἰσιν αὖθις Κηφισοδότου, Στρογγυλίωνος δὲ ἕτερα τοσαῦτα, ἀνδρὸς βοῦς καὶ ἵππους ἄριστα εἰργασμένου· τὰς δὲ ὑπολοίπους τρεῖς ἐποίησεν Ὀλυμπιοσθένης. καὶ Ἀπόλλων χαλκοῦς ἐστιν ἐν Ἑλικῶνι καὶ Ἑρμῆς μαχόμενοι περὶ τῆς λύρας, καὶ Διόνυσος ὁ μὲν Λυσίππου, τὸ δὲ ἄγαλμα ἀνέθηκε Σύλλας τοῦ Διονύσου τὸ ὀρθόν, ἔργον τῶν Μύρωνος θέας μάλιστα ἄξιον μετά γε τὸν Ἀθήνῃσιν Ἐρεχθέα· ἀνέθηκε δὲ οὐκ οἴκοθεν, Ὀρχομενίους δὲ ἀφελόμενος τοὺς Μινύας. τοῦτό ἐστι τὸ ὑπὸ Ἑλλήνων λεγόμενον θυμιάμασιν ἀλλοτρίοις τὸ θεῖον σέβεσθαι.", "st": "9.30"}, {"sp": "N", "t": "ποιητὰς δὲ ἤ καὶ ἄλλως ἐπιφανεῖς ἐπὶ μουσικῇ, τοσῶνδε εἰκόνας ἀνέθεσαν· Θάμυριν μὲν αὐτόν τε ἤδη τυφλὸν καὶ λύρας κατεαγυίας ἐφαπτόμενον, Ἀρίων δὲ ὁ Μηθυμναῖός ἐστιν ἐπὶ δελφῖνος. ὁ δὲ Σακάδα τοῦ Ἀργείου τὸν ἀνδριάντα πλάσας, οὐ συνεὶς Πινδάρου τὸ ἐς αὐτὸν προοίμιον, ἐποίησεν οὐδὲν ἐς τὸ μῆκος τοῦ σώματος εἶναι τῶν αὐλῶν μείζονα τὸν αὐλητήν.", "st": "9.30"}, {"sp": "N", "t": "κάθηται δὲ καὶ Ἡσίοδος κιθάραν ἐπὶ τοῖς γόνασιν ἔχων, οὐδέν τι οἰκεῖον Ἡσιόδῳ φόρημα· δῆλα γὰρ δὴ καὶ ἐξ αὐτῶν τῶν ἐπῶν ὅτι ἐπὶ ῥάβδου δάφνης ᾖδε. περὶ δὲ Ἡσιόδου τε ἡλικίας καὶ Ὁμήρου πολυπραγμονήσαντι ἐς τὸ ἀκριβέστατον οὔ μοι γράφειν ἡδὺ ἦν, ἐπισταμένῳ τὸ φιλαίτιον ἄλλων τε καὶ οὐχ ἥκιστα ὅσοι κατ’ ἐμὲ ἐπὶ ποιήσει τῶν ἐπῶν καθεστήκεσαν.", "st": "9.30"}, {"sp": "N", "t": "Ὀρφεῖ δὲ τῷ Θρᾳκὶ πεποίηται μὲν παρεστῶσα αὐτῷ Τελετή, πεποίηται δὲ περὶ αὐτὸν λίθου τε καὶ χαλκοῦ θηρία ἀκούοντα ᾄδοντος. πολλὰ μὲν δὴ καὶ ἄλλα πιστεύουσιν οὐκ ὄντα Ἕλληνες καὶ δὴ καὶ Ὀρφέα Καλλιόπης τε εἶναι Μούσης καὶ οὐ τῆς Πιέρου καί οἱ τὰ θηρία ἰέναι πρὸς τὸ μέλος ψυχαγωγούμενα, ἐλθεῖν δὲ καὶ ἐς τὸν Ἅιδην ζῶντα αὐτὸν παρὰ τῶν κάτω θεῶν τὴν γυναῖκα αἰτοῦντα. ὁ δὲ Ὀρφεὺς ἐμοὶ δοκεῖν ὑπερεβάλετο ἐπῶν κόσμῳ τοὺς πρὸ αὐτοῦ καὶ ἐπὶ μέγα ἦλθεν ἰσχύος οἷα πιστευόμενος εὑρηκέναι τελετὰς θεῶν καὶ ἔργων ἀνοσίων καθαρμοὺς νόσων τε ἰάματα καὶ τροπὰς μηνιμάτων θείων.", "st": "9.30"}, {"sp": "N", "t": "τὰς δὲ γυναῖκάς φασι τῶν Θρᾳκῶν ἐπιβουλεύειν μὲν αὐτῷ θάνατον, ὅτι σφῶν τοὺς ἄνδρας ἀκολουθεῖν ἔπεισεν αὐτῷ πλανωμένῳ, φόβῳ δὲ τῶν ἀνδρῶν οὐ τολμᾶν· ὡς δὲ ἐνεφορήσαντο οἴνου, ἐξεργάζονται τὸ τόλμημα, καὶ τοῖς ἀνδράσιν ἀπὸ τούτου κατέστη μεθυσκομένους ἐς τὰς μάχας χωρεῖν. εἰσὶ δὲ οἵ φασι κεραυνωθέντι ὑπὸ τοῦ θεοῦ συμβῆναι τὴν τελευτὴν Ὀρφεῖ· κεραυνωθῆναι δὲ αὐτὸν τῶν λόγων ἕνεκα ὧν ἐδίδασκεν ἐν τοῖς μυστηρίοις οὐ πρότερον ἀκηκοότας ἀνθρώπους.", "st": "9.30"}, {"sp": "N", "t": "ἄλλοις δὲ εἰρημένον ἐστὶν ὡς προαποθανούσης οἱ τῆς γυναικὸς ἐπὶ τὸ Ἄορνον δι’ αὐτὴν τὸ ἐν τῇ Θεσπρωτίδι ἀφίκετο· εἶναι γὰρ πάλαι νεκυομαντεῖον αὐτόθι· νομίζοντα δέ οἱ ἕπεσθαι τῆς Εὐρυδίκης τὴν ψυχὴν καὶ ἁμαρτόντα ὡς ἐπεστράφη, αὐτόχειρα αὐτὸν ὑπὸ λύπης αὑτοῦ γενέσθαι. λέγουσι δὲ οἱ Θρᾷκες, ὅσαι τῶν ἀηδόνων ἔχουσι νεοσσιὰς ἐπὶ τῷ τάφῳ τοῦ Ὀρφέως, ταύτας ἥδιον καὶ μεῖζόν τι ᾄδειν.", "st": "9.30"}, {"sp": "N", "t": "Μακεδόνων δὲ οἱ χώραν τὴν ὑπὸ τὸ ὄρος τὴν Πιερίαν ἔχοντες καὶ πόλιν Δῖον, φασὶν ὑπὸ τῶν γυναικῶν γενέσθαι τὴν τελευτὴν ἐνταῦθα τῷ Ὀρφεῖ· ἰόντι δὲ ἐκ Δίου τὴν ἐπὶ τὸ ὄρος καὶ στάδια προεληλυθότι εἴκοσι κίων τέ ἐστιν ἐν δεξιᾷ καὶ ἐπίθημα ἐπὶ τῷ κίονι ὑδρία λίθου, ἔχει δὲ τὰ ὀστᾶ τοῦ Ὀρφέως ἡ ὑδρία, καθὰ οἱ ἐπιχώριοι λέγουσι.", "st": "9.30"}, {"sp": "N", "t": "ῥεῖ δὲ καὶ ποταμὸς Ἑλικών· ἄχρι σταδίων ἑβδομήκοντα πέντε προελθόντι τὸ ῥεῦμα ἀφανίζεται τὸ ἀπὸ τούτου κατὰ τῆς γῆς· διαλιπὸν δὲ μάλιστα δύο καὶ εἴκοσι στάδια ἄνεισι τὸ ὕδωρ αὖθις, καὶ ὄνομα Βαφύρας ἀντὶ Ἑλικῶνος λαβὼν κάτεισιν ἐς θάλασσαν ναυσίπορος. τοῦτον οἱ Διασταὶ τὸν ποταμὸν ἐπιρρεῖν διὰ παντὸς τῇ γῇ τὰ ἐξ ἀρχῆς φασι· τὰς γυναῖκας δὲ αἳ τὸν Ὀρφέα ἀπέκτειναν ἐναπονίψασθαί οἱ θελῆσαι τὸ αἷμα, καταδῦναί τε ἐπὶ τούτῳ τὸν ποταμὸν ἐς τὴν γῆν, ἵνα δὴ μὴ τοῦ φόνου καθάρσια τὸ ὕδωρ παράσχηται.", "st": "9.30"}, {"sp": "N", "t": "ἤκουσα δὲ καὶ ἄλλον ἐν Λαρίσῃ λόγον, ὡς ἐν τῷ Ὀλύμπῳ. πόλις οἰκοῖτο Λίβηθρα, ᾗ ἐπὶ Μακεδονίας τέτραπται τὸ ὄρος, καὶ εἶναι οὐ πόρρω τῆς πόλεως τὸ τοῦ Ὀρφέως μνῆμα· ἀφικέσθαι δὲ τοῖς Λιβηθρίοις παρὰ τοῦ Διονύσου μάντευμα ἐκ Θρᾴκης, ἐπειδὰν ἴδῃ τὰ ὀστᾶ τοῦ Ὀρφέως ἥλιος, τηνικαῦτα ὑπὸ συὸς ἀπολεῖσθαι Λιβηθρίοις τὴν πόλιν. οἱ μὲν δι’ οὐ πολλῆς φροντίδος ἐποιοῦντο τὸν χρησμόν, οὐδὲ ἄλλο τι θηρίον οὕτω μέγα καὶ ἄλκιμον ἔσεσθαι νομίζοντες ὡς ἑλεῖν σφισι τὴν πόλιν, συὶ δὲ θρασύτητος μετεῖναι μᾶλλον ἢ ἰσχύος.", "st": "9.30"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐδόκει τῷ θεῷ, συνέβαινέ σφισι τοιάδε. ποιμὴν περὶ μεσοῦσαν μάλιστα τὴν ἡμέραν ἐπικλίνων αὑτὸν πρὸς τοῦ Ὀρφέως τὸν τάφον, ὁ μὲν ἐκάθευδεν ὁ ποιμήν, ἐπῄει δέ οἱ καὶ καθεύδοντι ἔπη τε ᾄδειν τῶν Ὀρφέως καὶ μέγα καὶ ἡδὺ φωνεῖν. οἱ οὖν ἐγγύτατα νέμοντες ἢ καὶ ἀροῦντες ἕκαστοι τὰ ἔργα ἀπολείποντες ἠθροίζοντο ἐπὶ τοῦ ποιμένος τὴν ἐν τῷ ὕπνῳ ᾠδήν· καί ποτε ὠθοῦντες ἀλλήλους καὶ ἐρίζοντες ὅστις ἐγγύτατα ἔσται τῷ ποιμένι ἀνατρέπουσι τὸν κίονα, καὶ κατεάγη τε ἀπ’ αὐτοῦ πεσοῦσα ἡ θήκη καὶ εἶδεν ἥλιος ὅ τι ἦν τῶν ὀστῶν τοῦ Ὀρφέως λοιπόν.", "st": "9.30"}, {"sp": "N", "t": "αὐτίκα δὲ ἐν τῇ ἐπερχομένῃ νυκτὶ ὅ τε θεὸς κατέχει πολὺ ἐκ τοῦ οὐρανοῦ τὸ ὕδωρ καὶ ὁ ποταμὸς ὁ Σῦς—τῶν δὲ περὶ τὸν Ὄλυμπον χειμάρρων καὶ ὁ Σῦς ἐστι—, τότε οὖν οὗτος ὁ ποταμὸς κατέβαλε μὲν τὰ τείχη Λιβηθρίοις, θεῶν ⟨δὲ⟩ ἱερὰ καὶ οἴκους ἀνέτρεψεν ἀνθρώπων, ἀπέπνιξε δὲ τούς τε ἀνθρώπους καὶ τὰ ἐν τῇ πόλει ζῷα ὁμοίως τὰ πάντα. ἀπολλυμένων δὲ ἤδη Λιβηθρίων, οὕτως οἱ ἐν Δίῳ Μακεδόνες κατά γε τὸν λόγον τοῦ Λαρισαίου ξένου ἐς τὴν ἑαυτῶν τὰ ὀστᾶ κομίζουσι τοῦ Ὀρφέως.", "st": "9.30"}, {"sp": "N", "t": "ὅστις δὲ περὶ ποιήσεως ἐπολυπραγμόνησεν ἤδη, τοὺς Ὀρφέως ὕμνους οἶδεν ὄντας ἕκαστόν τε αὐτῶν ἐπὶ βραχύτατον καὶ τὸ σύμπαν οὐκ ἐς ἀριθμὸν πολὺν πεποιημένους· Λυκομίδαι δὲ ἴσασί τε καὶ ἐπᾴδουσι τοῖς δρωμένοις. κόσμῳ μὲν δὴ τῶν ἐπῶν δευτερεῖα φέροιντο ἂν μετά γε Ὁμήρου τοὺς ὕμνους, τιμῆς δὲ ἐκ τοῦ θείου καὶ ἐς πλέον ἐκείνων ἥκουσι.", "st": "9.30"}, {"sp": "N", "t": "καὶ Ἀρσινόης ἐστὶν ἐν Ἑλικῶνι εἰκών, ἣν Πτολεμαῖος ἔγημεν ἀδελφὸς ὤν. τὴν δὲ Ἀρσινόην στρουθὸς φέρει χαλκῆ τῶν ἀπτήνων· πτερὰ μέν γε καὶ αὗται κατὰ ταὐτὰ ταῖς ἄλλαις φύουσιν, ὑπὸ δὲ βάρους καὶ διὰ μέγεθος οὐχ οἷά τέ ἐστιν ἀνέχειν σφᾶς ἐς τὸν ἀέρα τὰ πτερά.", "st": "9.31"}, {"sp": "N", "t": "ἐνταῦθα καὶ Τηλέφῳ τῷ Ἡρακλέους γάλα ἐστὶν ἔλαφος παιδὶ μικρῷ διδοῦσα καὶ βοῦς τε παρ’ αὐτὸν καὶ ἄγαλμα Πριάπου θέας ἄξιον. τούτῳ τιμαὶ τῷ θεῷ δέδονται μὲν καὶ ἄλλως, ἔνθα εἰσὶν αἰγῶν νομαὶ καὶ προβάτων ἢ καὶ ἑσμοὶ μελισσῶν· Λαμψακηνοὶ δὲ ἐς πλέον ἢ θεοὺς τοὺς ἄλλους νομίζουσι, Διονύσου τε αὐτὸν παῖδα εἶναι καὶ Ἀφροδίτης λέγοντες.", "st": "9.31"}, {"sp": "N", "t": "ἐν δὲ τῷ Ἑλικῶνι καὶ ἄλλοι τρίποδες κεῖνται καὶ ἀρχαιότατος, ὃν ἐν Χαλκίδι λαβεῖν τῇ ἐπ’ Εὐρίπῳ λέγουσιν Ἡσίοδον νικήσαντα ᾠδῇ. περιοικοῦσι δὲ καὶ ἄνδρες τὸ ἄλσος, καὶ ἑορτήν τε ἐνταῦθα οἱ Θεσπιεῖς καὶ ἀγῶνα ἄγουσι Μουσεῖα· ἄγουσι δὲ καὶ τῷ Ἔρωτι, ἆθλα οὐ μουσικῆς μόνον ἀλλὰ καὶ ἀθληταῖς τιθέντες. ἐπαναβάντι δὲ στάδια ἀπὸ τοῦ ἄλσους τούτου ὡς εἴκοσιν ἔστιν ἡ τοῦ Ἵππου καλουμένη κρήνη· ταύτην τὸν Βελλεροφόντου ποιῆσαί φασιν ἵππον ἐπιψαύσαντα ὁπλῇ τῆς γῆς.", "st": "9.31"}, {"sp": "N", "t": "Βοιωτῶν δὲ οἱ περὶ τὸν Ἑλικῶνα οἰκοῦντες παρειλημμένα δόξῃ λέγουσιν ὡς ἄλλο Ἡσίοδος ποιήσειεν οὐδὲν ἢ τὰ Ἔργα· καὶ τούτων δὲ τὸ ἐς τὰς Μούσας ἀφαιροῦσι προοίμιον, ἀρχὴν τῆς ποιήσεως εἶναι τὸ ἐς τὰς Ἔριδας λέγοντες· καί μοι μόλυβδον ἐδείκνυσαν, ἔνθα ἡ πηγή, τὰ πολλὰ ὑπὸ τοῦ χρόνου λελυμασμένον·", "st": "9.31"}, {"sp": "N", "t": "ἐγγέγραπται δὲ αὐτῷ τὰ Ἔργα. ἔστι δὲ καὶ ἑτέρα κεχωρισμένη τῆς προτέρας, ὡς πολύν τινα ἐπῶν ὁ Ἡσίοδος ἀριθμὸν ποιήσειεν, ἐς γυναῖκάς τε ᾀδόμενα καὶ ἃς μεγάλας ἐπονομάζουσιν Ἠοίας, καὶ Θεογονίαν τε καὶ ἐς τὸν μάντιν Μελάμποδα, καὶ ὡς Θησεὺς ἐς τὸν Ἅιδην ὁμοῦ Πειρίθῳ καταβαίη παραινέσεις τε Χίρωνος ἐπὶ διδασκαλίᾳ δὴ τῇ Ἀχιλλέως, καὶ ὅσα ἐπὶ Ἔργοις τε καὶ Ἡμέραις. οἱ δὲ αὐτοὶ οὗτοι λέγουσι καὶ ὡς μαντικὴν Ἡσίοδος διδαχθείη παρὰ Ἀκαρνάνων· καὶ ἔστιν ἔπη Μαντικά, ὁπόσα τε ἐπελεξάμεθα καὶ ἡμεῖς, καὶ ἐξηγήσεις ἐπὶ τέρασιν.", "st": "9.31"}, {"sp": "N", "t": "ἐναντία δὲ καὶ ἐς τοῦ Ἡσιόδου τὴν τελευτήν ἐστιν εἰρημένα. ὅτι μὲν γὰρ οἱ παῖδες τοῦ Γανύκτορος Κτίμενος καὶ Ἄντιφος ἔφυγον ἐς Μολυκρίαν ἐκ Ναυπάκτου διὰ τοῦ Ἡσιόδου τὸν φόνον καὶ αὐτόθι ἀσεβήσασιν ἐς Ποσειδῶνα ἐγένετο [τῇ Μολυκρίδι] σφίσιν ἡ δίκη, τάδε μὲν καὶ οἱ πάντες κατὰ ταὐτὰ εἰρήκασι· τὴν δὲ ἀδελφὴν τῶν νεανίσκων οἱ μὲν ἄλλου τού φασιν αἰσχύναντος Ἡσίοδον λαβεῖν οὐκ ἀληθῆ τὴν τοῦ ἀδικήματος δόξαν, οἱ δὲ ἐκείνου γενέσθαι τὸ ἔργον. τὰ μὲν δὴ ἐς Ἡσίοδον καὶ αὐτὸν καὶ ἐς τὰ ἔπη διάφορα ἐπὶ τοσοῦτο εἴρηται·", "st": "9.31"}, {"sp": "N", "t": "ἐπὶ δὲ ἄκρᾳ τῇ κορυφῇ τοῦ Ἑλικῶνος ποταμὸς οὐ μέγας ἐστὶν ὁ Λάμος. Θεσπιέων δὲ ἐν τῇ γῇ [ἡ] Δονακών ἐστιν ὀνομαζόμενος· ἐνταῦθά ἐστι Ναρκίσσου πηγή, καὶ τὸν Νάρκισσον ἰδεῖν ἐς τοῦτο τὸ ὕδωρ φασίν, οὐ συνέντα δὲ ὅτι ἑώρα σκιὰν τὴν ἑαυτοῦ λαθεῖν τε αὐτὸν ἐρασθέντα αὑτοῦ καὶ ὑπὸ τοῦ ἔρωτος ἐπὶ τῇ πηγῇ οἱ συμβῆναι τὴν τελευτήν. τοῦτο μὲν δὴ παντάπασιν εὔηθες, ἡλικίας ἤδη τινὰ ἐς τοσοῦτο ἥκοντα ὡς ὑπὸ ἔρωτος ἁλίσκεσθαι μηδὲ ὁποῖόν τι ἄνθρωπος καὶ ὁποῖόν τι ἀνθρώπου σκιὰ διαγνῶναι·", "st": "9.31"}, {"sp": "N", "t": "ἔχει δὲ καὶ ἕτερος ἐς αὐτὸν λόγος, ἧσσον μὲν τοῦ προτέρου γνώριμος, λεγόμενος δὲ καὶ οὗτος, ἀδελφὴν γενέσθαι Ναρκίσσῳ δίδυμον, τά τε ἄλλα ἐς ἅπαν ὅμοιον τὸ εἶδος καὶ ἀμφοτέροις ὡσαύτως κόμην εἶναι καὶ ἐσθῆτα ἐοικυῖαν αὐτοὺς ἐνδύεσθαι καὶ δὴ καὶ ἐπὶ θήραν ἰέναι μετὰ ἀλλήλων· Νάρκισσον δὲ ἐρασθῆναι τῆς ἀδελφῆς, καὶ ὡς ἀπέθανεν ἡ παῖς, φοιτῶντα ἐπὶ τὴν πηγὴν συνιέναι μὲν ὅτι τὴν ἑαυτοῦ σκιὰν ἑώρα, εἶναι δέ οἱ καὶ συνιέντι ῥᾳστώνην τοῦ ἔρωτος ἅτε οὐχ ἑαυτοῦ σκιὰν δοξάζοντι ἀλλὰ εἰκόνα ὁρᾶν τῆς ἀδελφῆς.", "st": "9.31"}, {"sp": "N", "t": "νάρκισσον δὲ ἄνθος ἡ γῆ καὶ πρότερον ἔφυεν ἐμοὶ δοκεῖν, εἰ τοῖς Πάμφω τεκμαίρεσθαι χρή τι ἡμᾶς ἔπεσι· γεγονὼς γὰρ πολλοῖς πρότερον ἔτεσιν ἢ Νάρκισσος ὁ Θεσπιεὺς Κόρην τὴν Δήμητρός φησιν ἁρπασθῆναι παίζουσαν καὶ ἄνθη συλλέγουσαν, ἁρπασθῆναι δὲ οὐκ ἴοις ἀπατηθεῖσαν ἀλλὰ ναρκίσσοις.", "st": "9.31"}, {"sp": "N", "t": "τοῖς δὲ ἐν Κρεύσιδι, ἐπινείῳ τῷ Θεσπιέων, οἰκοῦσιν ἐν κοινῷ μέν ἐστιν οὐδέν, ἐν ἰδιώτου δὲ ἀνδρὸς ἄγαλμα ἦν Διονύσου γύψου πεποιημένον καὶ ἐπικεκοσμημένον γραφῇ. πλοῦς δὲ ἐς Κρεῦσίν ἐστιν ἐκ Πελοποννήσου σκολιός τε καὶ ἄλλως οὐκ εὔδιος· ἄκραι τε γὰρ ἀνέχουσιν ὡς μὴ κατ’ εὐθὺ τῆς θαλάσσης περαιοῦσθαι καὶ ἅμα ἐκ τῶν ὀρῶν καταπνέουσιν ἄνεμοι βίαιοι.", "st": "9.32"}, {"sp": "N", "t": "πλέοντι δὲ ἐκ Κρεύσιδος οὐκ ἄνω, παρὰ δὲ αὐτὴν Βοιωτίαν, πόλις ἐστὶν ἐν δεξιᾷ Θίσβη. πρῶτα μὲν ὄρος ἐστὶ πρὸς θαλάσσῃ, τοῦτο δὲ ὑπερβαλόντα πεδίον σε ἐκδέξεται καὶ μετὰ τοῦτο ἄλλο ὄρος· ἐν δὲ ταῖς ὑπωρείαις ἐστὶν ἡ πόλις. Ἡρακλέους δὲ ἱερὸν καὶ ἄγαλμα ὀρθὸν ἐνταῦθά ἐστι λίθου, καὶ Ἡράκλεια ἑορτὴν ἄγουσι.", "st": "9.32"}, {"sp": "N", "t": "τὸ δὲ πεδίον τὸ μεταξὺ τῶν ὀρῶν ἐκώλυεν οὐδὲν ⟨ἂν⟩ λίμνην ὑπὸ πλήθους εἶναι τοῦ ὕδατος, εἰ μὴ διὰ μέσου χῶμά σφισιν ἐπεποίητο ἰσχυρόν· καὶ οὕτω παρὰ ἔτος ἐς μὲν τὰ ἐπέκεινα τοῦ χώματος ἐκτρέπουσι τὸ ὕδωρ, τὸ δὲ ἐπὶ τὰ ἕτερα αὐτοῦ γεωργοῦσι. Θίσβην δὲ λέγουσιν ἐπιχώριον εἶναι νύμφην, ἀφ’ ἧς ἡ πόλις τὸ ὄνομα ἔσχηκεν.", "st": "9.32"}, {"sp": "N", "t": "παραπλέοντι δὲ αὐτόθεν πόλισμά ἐστιν οὐ μέγα ἐπὶ θαλάσσῃ Τίφα· Ἡρακλεῖόν τε Τιφαιεῦσίν ἐστι καὶ ἑορτὴν ἄγουσιν ἐπέτειον. οὗτοι Βοιωτῶν μάλιστα ἐκ παλαιοῦ τὰ θαλάσσια ἐθέλουσιν εἶναι σοφοί, Τῖφυν ἄνδρα μνημονεύοντες ἐπιχώριον ὡς προκριθείη γενέσθαι τῆς Ἀργοῦς κυβερνήτης· ἀποφαίνουσι δὲ καὶ πρὸ τῆς πόλεως ἔνθα ἐκ Κόλχων ὀπίσω κομιζομένην ὁρμίσασθαι τὴν Ἀργὼ λέγουσιν.", "st": "9.32"}, {"sp": "N", "t": "ἀπὸ δὲ Θεσπίας ἰόντι ἄνω πρὸς ἤπειρον ἔστιν Ἁλίαρτος. ὅστις δὲ Ἁλιάρτου γέγονε καὶ Κορωνείας οἰκιστής, οὔ με ἀπὸ τῶν ἐς Ὀρχομενίους ἐχόντων εἰκὸς ἦν χωρίζειν· κατὰ δὲ τὴν ἐπιστρατείαν τοῦ Μήδου φρονήσασιν Ἁλιαρτίοις τὰ Ἑλλήνων μοῖρα τῆς Ξέρξου στρατιᾶς γῆν τέ σφισιν ὁμοῦ καὶ τὴν πόλιν ἐπεξῆλθε καίουσα. ἐν Ἁλιάρτῳ δέ ἐστι Λυσάνδρου τοῦ Λακεδαιμονίου μνῆμα· προσβαλὼν γὰρ τῷ Ἁλιάρτῳ πρὸς τὸ τεῖχος στρατιᾶς ἔκ τε Θηβῶν ἐνούσης ἔνδον καὶ ἐξ Ἀθηνῶν καὶ ἐπεξελθόντων τῶν πολεμίων ἔπεσεν ἐν τῇ μάχῃ.", "st": "9.32"}, {"sp": "N", "t": "Λύσανδρον δὲ τὰ μὲν ἐς τὰ μάλιστα ἐπαινέσαι, τὰ δὲ καὶ πικρῶς ἔστι μέμψασθαι. σοφίαν μέν γε τοιαύτην ἐπεδείξατο· ἡγούμενος Πελοποννησίων ταῖς τριήρεσιν Ἀντίοχον κυβερνήτην ὄντα Ἀλκιβιάδου, φυλάξας Ἀλκιβιάδην ἀπόντα τοῦ ναυτικοῦ, τηνικαῦτα τὸν Ἀντίοχον ἐπηγάγετο ἐς ἐλπίδα ὡς ὄντα ἀξιόμαχον ναυμαχῆσαι Λακεδαιμονίοις, καὶ ἀναγαγόμενον ὑπὸ θράσους τε καὶ ἀλαζονίας ἐνίκησεν αὐτὸν οὐ πόρρω τοῦ Κολοφωνίων ἄστεως.", "st": "9.32"}, {"sp": "N", "t": "ὡς δὲ καὶ δεύτερα ὁ Λύσανδρος ἐπὶ τὰς τριήρεις ἀφίκετο ἐκ Σπάρτης, ἡμερώσατο μὲν οὕτω Κῦρον ὡς χρήματα, ὁπότε ἐς τὸ ναυτικὸν αἰτοίη, παρεῖναί οἱ κατὰ καιρόν τε καὶ ἄφθονα· ὁρμούντων δὲ ναυσὶν ἑκατὸν ἐν Αἰγὸς ποταμοῖς Ἀθηναίων, εἷλεν αὐτῶν τὰ πλοῖα, ἐσκεδασμένους ἐπί τε ὕδωρ τοὺς ναύτας καὶ ἐπὶ ἀγορὰν φυλάξας. παρέσχετο δὲ καὶ ἔργον τοιόνδε ἐς δικαιοσύνην.", "st": "9.32"}, {"sp": "N", "t": "Αὐτολύκῳ τῷ παγκρατιάσαντι, οὗ δὴ καὶ εἰκόνα ἰδὼν οἶδα ἐν πρυτανείῳ τῷ Ἀθηναίων, τούτῳ τῷ ἀνδρὶ ἐς ἀμφισβήτησιν ὅτου δὴ κτήματος Ἐτεόνικος ἦλθεν ὁ Σπαρτιάτης· ὡς δὲ ἄρα λέγων ἡλίσκετο οὐ δίκαια—ἦν γὰρ δὴ τηνικαῦτα Ἀθηναίοις τῶν τριάκοντα ἡ ἀρχὴ καὶ παρῆν ἔτι ὁ Λύσανδρος—τούτων ἕνεκα Ἐτεόνικος πληγῶν τε ἄρχειν ἐπήρθη καὶ ἀμυνάμενον τὸν Αὐτόλυκον ἦγεν ἐπὶ Λύσανδρον, παντάπασιν ἐκεῖνον ἐς χάριν τὴν ἑαυτοῦ δικάσειν ἐλπίζων· Λύσανδρος δὲ ἀδικεῖν Ἐτεόνικον κατέγνω καὶ ἀπέπεμψεν ἀτιμάσας τῷ λόγῳ.", "st": "9.32"}, {"sp": "N", "t": "τάδε μὲν Λυσάνδρῳ τὰ ἐς δόξαν ὑπάρχοντα ἦν, ἄλλα δὲ τοσάδε ὀνείδη. Φιλοκλέα γὰρ Ἀθηναῖον ἐν Αἰγὸς ποταμοῖς καὶ αὐτὸν στρατηγοῦντα καὶ Ἀθηναίων τῶν ἄλλων ὅσον τετρακισχιλίους αἰχμαλώτους ὄντας ἀπέκτεινεν ὁ Λύσανδρος καί σφισιν οὐδὲ ἀποθανοῦσιν ἐπήνεγκε γῆν, ὃ καὶ Μήδων τοῖς ἀποβᾶσιν ἐς Μαραθῶνα ὑπῆρξε παρὰ Ἀθηναίων καὶ αὐτῶν Λακεδαιμονίων τοῖς πεσοῦσιν ἐν Θερμοπύλαις ἐκ βασιλέως Ξέρξου. μείζονα δὲ ἔτι Λακεδαιμονίοις ὀνείδη γενέσθαι παρεσκεύασεν ὁ Λύσανδρος ἐπί τε δεκαδαρχίαις ἃς κατέστησε ταῖς πόλεσι καὶ ἐπὶ τοῖς Λάκωσιν ἁρμοσταῖς.", "st": "9.32"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ χρήματα οὐ νομιζόντων κτᾶσθαι κατὰ δή τι μάντευμα, ὡς ἡ φιλοχρηματία μόνη γένοιτο ἂν ἀπώλεια τῇ Σπάρτῃ, ὁ δὲ καὶ χρημάτων πόθον σφίσιν ἐνεποίησεν ἰσχυρόν. ἐγὼ μὲν δὴ Πέρσαις τε ἑπόμενος καὶ δικάζων νόμῳ γε τῷ ἐκείνων βλάβος κρίνω Λακεδαιμονίοις μᾶλλον ἢ ὠφέλειαν γενέσθαι Λύσανδρον·", "st": "9.32"}, {"sp": "N", "t": "ἐν Ἁλιάρτῳ δὲ τοῦ τε Λυσάνδρου μνῆμα καὶ Κέκροπος τοῦ Πανδίονός ἐστιν ἡρῷον. τὸ δὲ ὄρος τὸ Τιλφούσιον καὶ ἡ Τιλφοῦσα καλουμένη πηγὴ σταδίους μάλιστα Ἁλιάρτου πεντήκοντα ἀπέχουσι. λέγεται δὲ ὑπὸ Ἑλλήνων Ἀργείους μετὰ τῶν Πολυνείκους παίδων ἑλόντας Θήβας ἐς Δελφοὺς τῷ θεῷ καὶ ἄλλα τῶν λαφύρων καὶ Τειρεσίαν ἄγειν, καὶ—εἴχετο γὰρ δίψῃ—καθ’ ὁδόν φασιν αὐτὸν πιόντα ἀπὸ τῆς Τιλφούσης ἀφεῖναι τὴν ψυχήν· καὶ ἔστι τάφος αὐτῷ πρὸς τῇ πηγῇ.", "st": "9.33"}, {"sp": "N", "t": "τὴν δὲ θυγατέρα τοῦ Τειρεσίου δοθῆναι μέν φασι τῷ Ἀπόλλωνι ὑπὸ τῶν Ἀργείων, προστάξαντος δὲ τοῦ θεοῦ ναυσὶν ἐς τὴν νῦν Ἰωνίαν καὶ Ἰωνίας ἐς τὴν Κολοφωνίαν περαιωθῆναι. καὶ ἡ μὲν αὐτόθι συνῴκησεν ἡ Μαντὼ Ῥακίῳ Κρητί· τὰ δὲ ἄλλα ἐς Τειρεσίαν, ἐτῶν τε ἀριθμὸν ὧν γεγράφασιν αὐτὸν βιῶναι καὶ ὡς ἐκ γυναικὸς ἐς ἄνδρα ἠλλάγη καὶ ὅτι Ὅμηρος ἐποίησεν ἐν Ὀδυσσείᾳ συνετὸν εἶναι γνώμην Τειρεσίαν τῶν ἐν Ἅιδου μόνον, ταῦτα μὲν καὶ οἱ πάντες ἴσασιν ἀκοῇ.", "st": "9.33"}, {"sp": "N", "t": "Ἁλιαρτίοις δέ ἐστιν ἐν ὑπαίθρῳ θεῶν ἱερὸν ἃς Πραξιδίκας καλοῦσιν· ἐνταῦθα ὀμνύουσι μέν, ποιοῦνται δὲ οὐκ ἐπίδρομον τὸν ὅρκον. ταύταις μέν ἐστι πρὸς τῷ ὄρει τῷ Τιλφουσίῳ τὸ ἱερόν· ἐν Ἁλιάρτῳ δέ εἰσι ναοί, καί σφισιν οὐκ ἀγάλματα ἔνεστιν, οὐκ ὄροφος ἔπεστιν· οὐ μὴν οὐδὲ οἷς τισιν ἐποιήθησαν, οὐδὲ τοῦτο ἠδυνάμην πυθέσθαι.", "st": "9.33"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ Ἁλιαρτίᾳ ποταμὸς Λόφις. λέγεται δὲ τῆς χώρας αὐχμηρᾶς οὔσης τὸ ἐξ ἀρχῆς καὶ ὕδατος οὐκ ὄντος ἐν αὐτῇ ἄνδρα τῶν δυναστευόντων ἐλθόντα ἐς Δελφοὺς ἐπερέσθαι τρόπον ὅντινα ὕδωρ εὑρήσουσιν ἐν τῇ γῇ· τὴν δὲ Πυθίαν προστάσσειν, ὃς ἂν ἐπανήκοντι ἐς Ἁλίαρτον ἐντύχῃ οἱ πρὸ τῶν ἄλλων, τούτου δεῖν φονέα γενέσθαι αὐτόν. ἐντυχεῖν τε δὴ αὐτῷ παραγενομένῳ τὸν υἱὸν Λόφιν καὶ τὸν οὐ μελλήσαντα τῷ ξίφει τὸν νεανίσκον παῖσαι· καὶ τὸν μὲν ἔτι ἔμπνουν περιθεῖν, ὅπου δὲ ῥυῆναι τὸ αἷμα, ὕδωρ ἐντεῦθεν ἀνεῖναι τὴν γῆν. ἐπὶ τούτῳ μὲν ὁ ποταμὸς καλεῖται Λόφις·", "st": "9.33"}, {"sp": "N", "t": "Ἀλαλκομεναὶ δὲ κώμη μέν ἐστιν οὐ μεγάλη, κεῖται δὲ ὄρους οὐκ ἄγαν ὑψηλοῦ πρὸς τοῖς ποσὶν ἐσχάτοις. γενέσθαι δὲ αὐτῇ τὸ ὄνομα ⟨οἱ⟩ μὲν ἀπὸ Ἀλαλκομενέως ἀνδρὸς αὐτόχθονος, ὑπὸ τούτου δὲ Ἀθηνᾶν τραφῆναι λέγουσιν· οἱ δὲ εἶναι καὶ τὴν Ἀλαλκομενίαν τῶν Ὠγύγου θυγατέρων φασίν. ἀπωτέρω δὲ τῆς κώμης ἐπεποίητο ἐν τῷ χθαμαλῷ τῆς Ἀθηνᾶς ναὸς καὶ ἄγαλμα ἀρχαῖον ἐλέφαντος.", "st": "9.33"}, {"sp": "N", "t": "Σύλλα δὲ ἔστι μὲν καὶ τὰ ἐς Ἀθηναίους ἀνήμερα καὶ ἤθους ἀλλότρια τοῦ Ῥωμαίων, ἐοικότα δὲ τούτοις καὶ τὰ ἐς Θηβαίους τε καὶ Ὀρχομενίους· προσεξειργάσατο δὲ καὶ ἐν ταῖς Ἀλαλκομεναῖς, τῆς Ἀθηνᾶς τὸ ἄγαλμα αὐτὸ συλήσας. τοῦτον μὲν τοιαῦτα ἔς τε Ἑλληνίδας πόλεις καὶ θεοὺς τοὺς Ἑλλήνων ἐκμανέντα ἐπέλαβεν ἀχαριστοτάτη νόσος πασῶν· φθειρῶν γὰρ ἤνθησεν, ἥ τε πρότερον εὐτυχία δοκοῦσα ἐς τοιοῦτο περιῆλθεν αὐτῷ τέλος. τὸ δὲ ἱερὸν ⟨τὸ⟩ ἐν ταῖς Ἀλαλκομεναῖς ἠμελήθη τὸ ἀπὸ τοῦδε ἅτε ἠρημωμένον τῆς θεοῦ.", "st": "9.33"}, {"sp": "N", "t": "ἐγένετο δὲ καὶ ἄλλο ἐπ’ ἐμοῦ τοιόνδε ἐς κατάλυσιν τοῦ ναοῦ· κισσός οἱ προσπεφυκὼς μέγας καὶ ἰσχυρὸς διέλυσεν ἐκ τῶν ἁρμονιῶν καὶ διέσπα τοὺς λίθους ἀπ’ ἀλλήλων. ῥεῖ δὲ καὶ ποταμὸς ἐνταῦθα οὐ μέγας χείμαρρος· ὀνομάζουσι δὲ Τρίτωνα αὐτόν, ὅτι τὴν Ἀθηνᾶν τραφῆναι παρὰ ποταμῷ Τρίτωνι ἔχει λόγος, ὡς δὴ τοῦτον τὸν Τρίτωνα ὄντα καὶ οὐχὶ τὸν Λιβύων, ὃς ἐς τὴν πρὸς Λιβύῃ θάλασσαν ἐκδίδωσιν ἐκ τῆς Τριτωνίδος λίμνης.", "st": "9.33"}, {"sp": "N", "t": "πρὶν δὲ ἐς Κορώνειαν ἐξ Ἀλαλκομενῶν ἀφικέσθαι, τῆς Ἰτωνίας Ἀθηνᾶς ἐστι τὸ ἱερόν· καλεῖται δὲ ἀπὸ Ἰτωνίου τοῦ Ἀμφικτύονος, καὶ ἐς τὸν κοινὸν συνίασιν ἐνταῦθα οἱ Βοιωτοὶ σύλλογον. ἐν δὲ τῷ ναῷ χαλκοῦ πεποιημένα Ἀθηνᾶς Ἰτωνίας καὶ Διός ἐστιν ἀγάλματα· τέχνη δὲ Ἀγορακρίτου, μαθητοῦ τε καὶ ἐρωμένου Φειδίου. ἀνέθεσαν δὲ καὶ Χαρίτων ἀγάλματα ἐπ’ ἐμοῦ.", "st": "9.34"}, {"sp": "N", "t": "λέγεται δὲ καὶ τοιόνδε, Ἰοδάμαν ἱερωμένην τῇ θεῷ νύκτωρ ἐς τὸ τέμενος ἐσελθεῖν καὶ αὐτῇ τὴν Ἀθηνᾶν φανῆναι, τῷ χιτῶνι δὲ τῆς θεοῦ τὴν Μεδούσης ἐπεῖναι τῆς Γοργόνος κεφαλήν· Ἰοδάμαν δέ, ὡς εἶδε, γενέσθαι λίθον. καὶ διὰ τοῦτο ἐπιτιθεῖσα γυνὴ πῦρ ἀνὰ πᾶσαν ἡμέραν ἐπὶ τῆς Ἰοδάμας τὸν βωμὸν ἐς τρὶς ἐπιλέγει τῇ Βοιωτῶν φωνῇ Ἰοδάμαν ζῆν καὶ αἰτεῖν πῦρ.", "st": "9.34"}, {"sp": "N", "t": "Κορώνεια δὲ παρείχετο μὲν ἐς μνήμην ἐπὶ τῆς ἀγορᾶς Ἑρμοῦ βωμὸν Ἐπιμηλίου, τὸν δὲ ἀνέμων. κατωτέρω δὲ ὀλίγον Ἥρας ἐστὶν ἱερὸν καὶ ἄγαλμα ἀρχαῖον, Πυθοδώρου τέχνη Θηβαίου, φέρει δὲ ἐπὶ τῇ χειρὶ Σειρῆνας· τὰς γὰρ δὴ Ἀχελῴου θυγατέρας ἀναπεισθείσας φασὶν ὑπὸ Ἥρας καταστῆναι πρὸς τὰς Μούσας ἐς ᾠδῆς ἔργον· αἱ δὲ ὡς ἐνίκησαν, ἀποτίλασαι τῶν Σειρήνων τὰ πτερὰ ποιήσασθαι στεφάνους ἀπ’ αὐτῶν λέγονται.", "st": "9.34"}, {"sp": "N", "t": "Κορωνείας δὲ σταδίους ὡς τεσσαράκοντα ὄρος ἀπέχει τὸ Λιβήθριον, ἀγάλματα δὲ ἐν αὐτῷ Μουσῶν τε καὶ νυμφῶν ἐπίκλησίν ἐστι Λιβηθρίων· καὶ πηγαὶ—τὴν μὲν Λιβηθριάδα ὀνομάζουσιν, ἡ δὲ ἑτέρα †Πέτρα—γυναικὸς μαστοῖς εἰσιν εἰκασμέναι, καὶ ὅμοιον γάλακτι ὕδωρ ἀπ’ αὐτῶν ἄνεισιν.", "st": "9.34"}, {"sp": "N", "t": "ἐς δὲ τὸ ὄρος τὸ Λαφύστιον καὶ ἐς τοῦ Διὸς τοῦ Λαφυστίου τὸ τέμενός εἰσιν ἐκ Κορωνείας στάδιοι μάλιστα εἴκοσι. λίθου μὲν τὸ ἄγαλμά ἐστιν· Ἀθάμαντος δὲ θύειν Φρίξον καὶ Ἕλλην ἐνταῦθα μέλλοντος πεμφθῆναι κριὸν τοῖς παισί φασιν ὑπὸ Διὸς ἔχοντα τὸ ἔριον χρυσοῦν, καὶ ἀποδρᾶναι σφᾶς ἐπὶ τοῦ κριοῦ τούτου. ἀνωτέρω δέ ἐστιν Ἡρακλῆς Χάροψ ἐπίκλησιν· ἐνταῦθα δὲ οἱ Βοιωτοὶ λέγουσιν ἀναβῆναι τὸν Ἡρακλέα ἄγοντα τοῦ Ἅιδου τὸν κύνα. ἐκ δὲ Λαφυστίου κατιόντι ἐς τῆς Ἰτωνίας Ἀθηνᾶς τὸ ἱερὸν ποταμός ἐστι Φάλαρος ἐς τὴν Κηφισίδα ἐκδιδοὺς λίμνην.", "st": "9.34"}, {"sp": "N", "t": "τοῦ δὲ ὄρους τοῦ Λαφυστίου πέραν ἐστὶν Ὀρχομενός, εἴ τις Ἕλλησιν ἄλλη πόλις ἐπιφανὴς καὶ αὕτη ἐς δόξαν. εὐδαιμονίας δέ ποτε ἐπὶ μέγιστον προαχθεῖσαν ἔμελλεν ἄρα ὑποδέξεσθαι τέλος καὶ ταύτην οὐ πολύ τι ἀποδέον ἢ Μυκήνας τε καὶ Δῆλον. περὶ δὲ τῶν ἀρχαίων τοιαῦτ’ ἦν ὁπόσα καὶ μνημονεύουσιν. Ἀνδρέα πρῶτον ἐνταῦθα Πηνειοῦ παῖδα τοῦ ποταμοῦ λέγουσιν ἐποικῆσαι καὶ ἀπὸ τούτου τὴν γῆν Ἀνδρηίδα ὀνομασθῆναι·", "st": "9.34"}, {"sp": "N", "t": "παραγενομένου δὲ ὡς αὐτὸν Ἀθάμαντος, ἀπένειμε τῆς αὑτοῦ τῷ Ἀθάμαντι τήν τε περὶ τὸ Λαφύστιον χώραν καὶ τὴν νῦν Κορώνειαν καὶ Ἁλιαρτίαν. Ἀθάμας δὲ ἅτε οὐδένα οἱ παίδων τῶν ἀρσένων λελεῖφθαι νομίζων—τὰ μὲν γὰρ ἐς Λέαρχόν τε καὶ Μελικέρτην ἐτόλμησεν αὐτός, Λεύκωνι δὲ ὑπὸ νόσου τελευτῆσαι συνέβη, Φρίξον δὲ ἄρα οὐκ ἠπίστατο ἢ αὐτὸν περιόντα ἢ γένος ὑπολειπόμενον Φρίξου—τούτων ἕνεκα ἐποιήσατο Ἁλίαρτον καὶ Κόρωνον τοὺς Θερσάνδρου τοῦ Σισύφου· Σισύφου γὰρ ἀδελφὸς ἦν ὁ Ἀθάμας.", "st": "9.34"}, {"sp": "N", "t": "ὕστερον δὲ ἀναστρέψαντος ἐκ Κόλχων οἱ μὲν αὐτοῦ Φρίξου φασίν, οἱ δὲ Πρέσβωνος—γεγονέναι δὲ Φρίξῳ τὸν Πρέσβωνα ἐκ τῆς Αἰήτου θυγατρός— οὕτω συγχωροῦσιν οἱ Θερσάνδρου παῖδες οἶκον μὲν τὸν Ἀθάμαντος Ἀθάμαντι καὶ τοῖς ἀπὸ ἐκείνου προσήκειν· αὐτοὶ δὲ—μοῖραν γὰρ δίδωσί σφισιν Ἀθάμας τῆς γῆς—Ἁλιάρτου καὶ Κορωνείας ἐγένοντο οἰκισταί.", "st": "9.34"}, {"sp": "N", "t": "πρότερον δὲ ἔτι τούτων Ἀνδρεὺς Εὐίππην θυγατέρα Λεύκωνος λαμβάνει παρὰ Ἀθάμαντος γυναῖκα, καὶ υἱὸς Ἐτεοκλῆς αὐτῷ γίνεται, Κηφισοῦ δὲ τοῦ ποταμοῦ κατὰ τῶν πολιτῶν τὴν φήμην, ὥστε καὶ τῶν ποιησάντων τινὲς Κηφισιάδην τὸν Ἐτεοκλέα ἐκάλεσαν ἐν τοῖς ἔπεσιν.", "st": "9.34"}, {"sp": "N", "t": "οὗτος ὡς ἐβασίλευσεν ὁ Ἐτεοκλῆς, τὴν μὲν χώραν ἀπὸ Ἀνδρέως ἔχειν τὸ ὄνομα εἴασε, φυλὰς δὲ Κηφισιάδα, τὴν δὲ ἑτέραν ἐπώνυμον αὑτῷ κατεστήσατο. ἀφικομένῳ δὲ πρὸς αὐτὸν Ἄλμῳ τῷ Σισύφου δίδωσιν οἰκῆσαι τῆς χώρας οὐ πολλήν, καὶ κώμη τότε ἐκλήθη[σαν] Ἄλμωνες ἀπὸ τοῦ Ἄλμου τούτου· χρόνῳ δὲ ἐξενίκησεν ὕστερον ⟨ὄνομα⟩ εἶναι τῇ κώμῃ Ὄλμωνας.", "st": "9.34"}, {"sp": "N", "t": "τὸν δὲ Ἐτεοκλέα λέγουσιν οἱ Βοιωτοὶ Χάρισιν ἀνθρώπων θῦσαι πρῶτον. καὶ ὅτι μὲν τρεῖς εἶναι Χάριτας κατεστήσατο ἴσασιν, ὀνόματα δὲ οἷα ἔθετο αὐταῖς οὐ μνημονεύουσιν· ἐπεὶ Λακεδαιμόνιοί γε εἶναι Χάριτας δύο καὶ Λακεδαίμονα ἱδρύσασθαι τὸν Ταϋγέτης φασὶν αὐτὰς καὶ ὀνόματα θέσθαι Κλήταν καὶ Φαένναν.", "st": "9.35"}, {"sp": "N", "t": "ἐοικότα μὲν δὴ Χάρισιν ὀνόματα καὶ ταῦτα, ἐοικότα δὲ καὶ παρ’ Ἀθηναίοις· τιμῶσι γὰρ ἐκ παλαιοῦ καὶ Ἀθηναῖοι Χάριτας Αὐξὼ καὶ Ἡγεμόνην. τὸ γὰρ τῆς Καρποῦς ἐστὶν οὐ Χάριτος ἀλλὰ Ὥρας ὄνομα· τῇ δὲ ἑτέρᾳ τῶν Ὡρῶν νέμουσιν ὁμοῦ τῇ Πανδρόσῳ τιμὰς οἱ Ἀθηναῖοι, Θαλλὼ τὴν θεὸν ὀνομάζοντες.", "st": "9.35"}, {"sp": "N", "t": "παρὰ δὲ Ἐτεοκλέους τοῦ Ὀρχομενίου μαθόντες τρισὶν ἤδη νομίζομεν Χάρισιν εὔχεσθαι· καὶ Ἀγγελίων τε καὶ Τεκταῖος †ὅσοι γε Διονύσου †τὸν Ἀπόλλωνα ἐργασάμενοι Δηλίοις τρεῖς ἐποίησαν ἐπὶ τῇ χειρὶ αὐτοῦ Χάριτας· καὶ Ἀθήνῃσι πρὸ τῆς ἐς τὴν ἀκρόπολιν ἐσόδου Χάριτές εἰσι καὶ αὗται τρεῖς, παρὰ δὲ αὐταῖς τελετὴν ἄγουσιν ἐς τοὺς πολλοὺς ἀπόρρητον.", "st": "9.35"}, {"sp": "N", "t": "Πάμφως μὲν δὴ πρῶτος ὧν ἴσμεν ᾖσεν ἐς Χάριτας, πέρα δὲ οὔτε ἀριθμοῦ πέρι οὔτε ἐς τὰ ὀνόματά ἐστιν οὐδὲν αὐτῷ πεποιημένον· Ὅμηρος δὲ—ἐμνημόνευσε γὰρ Χαρίτων καὶ οὗτος—τὴν μὲν Ἡφαίστου γυναῖκα εἶναι λέγει καὶ ὄνομα αὐτῇ τίθεται Χάριν, Πασιθέας δὲ εἶναί φησιν ἐραστὴν ⟨Ὕπνον,⟩ ἐν δὲ Ὕπνου τοῖς λόγοις τὸ ἔπος ἐποίησεν<br>ἦ μέν μοι δώσειν Χαρίτων μίαν ὁπλοτεράων.<br>τούτου δὲ ἕνεκα ὑπόνοια δὴ παρέστη τισὶν ὡς Χάριτας ἄρα καὶ πρεσβυτέρας οἶδεν ἄλλας Ὅμηρος.", "st": "9.35"}, {"sp": "N", "t": "Ἡσίοδος δὲ ἐν Θεογονίᾳ—προσιέσθω δὲ ὅτῳ φίλον τὴν Θεογονίαν—, ἐν δ’ οὖν τῇ ποιήσει ταύτῃ τὰς Χάριτάς φησιν εἶναι Διός τε καὶ Εὐρυνόμης καί σφισιν ὀνόματα Εὐφροσύνην τε καὶ Ἀγλαΐαν εἶναι καὶ Θαλίαν. κατὰ ταὐτὰ δὲ ἐν ἔπεσίν ἐστι τοῖς Ὀνομακρίτου. Ἀντίμαχος δὲ οὔτε ἀριθμὸν Χαρίτων οὔτε ὀνόματα εἰπὼν Αἴγλης εἶναι θυγατέρας καὶ Ἡλίου φησὶν αὐτάς. Ἑρμησιάνακτι δὲ τῷ τὰ ἐλεγεῖα γράψαντι τοσόνδε οὐ κατὰ τὴν τῶν πρότερον δόξαν ἐστὶν αὐτῷ πεποιημένον, ὡς ἡ Πειθὼ Χαρίτων εἴη καὶ αὐτὴ μία.", "st": "9.35"}, {"sp": "N", "t": "ὅστις δὲ ἦν ἀνθρώπων ὁ γυμνὰς πρῶτος Χάριτας ἤτοι πλάσας ἢ γραφῇ μιμησάμενος, οὐχ οἷόν τε ἐγένετο πυθέσθαι με, ἐπεὶ τά γε ἀρχαιότερα ἐχούσας ἐσθῆτα οἵ τε πλάσται καὶ κατὰ ταὐτὰ ἐποίουν οἱ ζωγράφοι· καὶ Σμυρναίοις τοῦτο μὲν ἐν τῷ ἱερῷ τῶν Νεμέσεων ὑπὲρ τῶν ἀγαλμάτων χρυσοῦ Χάριτες ἀνάκεινται, τέχνη Βουπάλου, τοῦτο δέ σφισιν ἐν τῷ Ὠιδείῳ Χάριτός ἐστιν εἰκών, Ἀπελλοῦ γραφή, Περγαμηνοῖς δὲ ὡσαύτως ἐν τῷ Ἀττάλου θαλάμῳ, Βουπάλου καὶ αὗται·", "st": "9.35"}, {"sp": "N", "t": "καὶ πρὸς τῷ ὀνομαζομένῳ Πυθίῳ Χάριτες καὶ ἐνταῦθά εἰσι Πυθαγόρου γράψαντος Παρίου· Σωκράτης τε ὁ Σωφρονίσκου πρὸ τῆς ἐς τὴν ἀκρόπολιν ἐσόδου Χαρίτων εἰργάσατο ἀγάλματα Ἀθηναίοις. καὶ ταῦτα μέν ἐστιν ὁμοίως ἅπαντα ἐν ἐσθῆτι, οἱ δὲ ὕστερον— οὐκ οἶδα ἐφ’ ὅτῳ—μεταβεβλήκασι τὸ σχῆμα αὐταῖς· Χάριτας γοῦν οἱ κατ’ ἐμὲ ἔπλασσόν τε καὶ ἔγραφον γυμνάς.", "st": "9.35"}, {"sp": "N", "t": "γενομένης δὲ Ἐτεοκλεῖ τῆς τελευτῆς ἡ βασιλεία περιῆλθεν ἐς τὸ Ἄλμου γένος. Ἄλμῳ δὲ αὐτῷ μὲν θυγατέρες Χρυσογένεια ἐγένετο καὶ Χρύση· Χρύσης δὲ τῆς Ἄλμου καὶ Ἄρεως ἔχει φήμη γενέσθαι Φλεγύαν, καὶ τὴν ἀρχὴν [τὴν] Ἐτεοκλέους ἀποθανόντος ἄπαιδος ὁ Φλεγύας ἔσχεν οὗτος. τῇ μὲν δὴ χώρᾳ τῇ πάσῃ Φλεγυαντίδα ὄνομα εἶναι μετέθεντο ἀντὶ Ἀνδρηίδος,", "st": "9.36"}, {"sp": "N", "t": "πόλις δὲ ἐγένετο ἥ τε ἐξ ἀρχῆς οἰκισθεῖσα ἡ Ἀνδρηὶς καὶ προσέκτισεν ὁ Φλεγύας ὁμώνυμον αὑτῷ, τοὺς τὰ πολεμικὰ ἀρίστους Ἑλλήνων συλλέξας ἐς αὐτήν. καὶ ἀπέστησάν τε ἀνὰ χρόνον ἀπὸ τῶν ἄλλων Ὀρχομενίων ὑπὸ ἀνοίας καὶ τόλμης οἱ Φλεγύαι καὶ ἦγον καὶ ἔφερον τοὺς προσοίκους· τέλος δὲ καὶ ἐπὶ τὸ ἱερὸν συλήσοντες στρατεύουσι τὸ ἐν Δελφοῖς, ὅτε καὶ Φιλάμμων λογάσιν Ἀργείων ἐπ’ αὐτοὺς βοηθήσας αὐτός τε ἀπέθανεν ἐν τῇ μάχῃ καὶ οἱ τῶν Ἀργείων λογάδες.", "st": "9.36"}, {"sp": "N", "t": "τοὺς δὲ Φλεγύας πολέμῳ μάλιστα Ἑλλήνων χαίρειν μαρτυρεῖ μοι καὶ ἔπη τῶν ἐν Ἰλιάδι περὶ Ἄρεως καὶ Φόβου τοῦ Ἄρεως πεποιημένα,<br>τὼ μὲν ἄρ’ εἰς Ἐφύρους πόλεμον μέτα θωρήσσεσθον<br>ἠὲ μετὰ Φλεγύας μεγαλήτορας·<br>Ἐφύρους δὲ ἐνταῦθα ἐμοὶ δοκεῖν τοὺς ἐν τῇ Θεσπρωτίδι ἠπείρῳ λέγει. τὸ μὲν δὴ Φλεγυῶν γένος ἀνέτρεψεν ἐκ βάθρων ὁ θεὸς κεραυνοῖς συνεχέσι καὶ ἰσχυροῖς σεισμοῖς· τοὺς δὲ ὑπολειπομένους νόσος ἐπιπεσοῦσα ἔφθειρε λοιμώδης, ὀλίγοι δὲ καὶ ἐς τὴν Φωκίδα διαφεύγουσιν ἐξ αὐτῶν.", "st": "9.36"}, {"sp": "N", "t": "Φλεγύᾳ δὲ οὐ γενομένων παίδων ἐκδέχεται Χρύσης τὴν ἀρχήν, Χρυσογενείας τε ὢν τῆς Ἄλμου καὶ Ποσειδῶνος. τούτῳ δὲ υἱὸς γίνεται ⟨τῷ⟩ Χρύσῃ Μινύας, καὶ ἀπ’ αὐτοῦ Μινύαι καὶ νῦν ἔτι ὧν ἦρχεν ὀνομάζονται. πρόσοδοι δὲ ἐγίνοντο τῷ Μινύᾳ τηλικαῦται μέγεθος ὡς ὑπερβαλέσθαι τοὺς πρὸ αὐτοῦ πλούτῳ· θησαυρόν τε ἀνθρώπων ὧν ἴσμεν Μινύας πρῶτος ἐς ὑποδοχὴν χρημάτων ᾠκοδομήσατο.", "st": "9.36"}, {"sp": "N", "t": "Ἕλληνες δὲ ἄρα εἰσὶ δεινοὶ τὰ ὑπερόρια ἐν θαύματι τίθεσθαι μείζονι ἢ τὰ οἰκεῖα, ὁπότε γε ἀνδράσιν ἐπιφανέσιν ἐς συγγραφὴν πυραμίδας μὲν τὰς παρὰ Αἰγυπτίοις ἐπῆλθεν ἐξηγήσασθαι πρὸς ⟨τὸ⟩ ἀκριβέστατον, θησαυρὸν δὲ τὸν Μινύου καὶ τὰ τείχη τὰ ἐν Τίρυνθι οὐδὲ ἐπὶ βραχὺ ἤγαγον μνήμης, οὐδὲν ὄντα ἐλάττονος θαύματος.", "st": "9.36"}, {"sp": "N", "t": "Μινύου δὲ ἦν Ὀρχομενός, καὶ ἐπὶ τούτου βασιλεύοντος ἥ τε πόλις Ὀρχομενὸς καὶ οἱ ἄνδρες ἐκλήθησαν Ὀρχομένιοι· διέμεινε δὲ οὐδὲν ἧσσον καὶ Μινύας ἐπονομάζεσθαι σφᾶς ἐς διάκρισιν ἀπὸ Ὀρχομενίων τῶν ἐν Ἀρκαδίᾳ. παρὰ τοῦτον τὸν Ὀρχομενὸν βασιλεύοντα Ὕηττος ἀφίκετο ἐξ Ἄργους, φεύγων ἐπὶ τῷ Μολούρου φόνῳ τοῦ Ἀρίσβαντος, ὅντινα ἀπέκτεινεν ἐπὶ γυναικὶ ἑλὼν γαμετῇ· καὶ αὐτῷ τῆς χώρας ἀπένειμεν Ὀρχομενὸς ὅση νῦν περί τε Ὕηττόν ἐστι τὴν κώμην καὶ [ἡ] ταύτῃ προσεχής.", "st": "9.36"}, {"sp": "N", "t": "Ὑήττου δὲ ἐποιήσατο μνήμην καὶ ὁ τὰ ἔπη συνθεὶς ἃς μεγάλας Ἠοίας καλοῦσιν Ἕλληνες·<br>Ὕηττος δὲ Μόλουρον Ἀρίσβαντος φίλον υἱόν<br>κτείνας ἐν μεγάροις εὐνῆς ἕνεχ’ ἧς ἀλόχοιο,<br>οἶκον ἀποπρολιπὼν φεῦγ’ Ἄργεος ἱπποβότοιο,<br>ἷξεν δ’ Ὀρχομενὸν Μινυήιον· καί μιν ὅ γ’ ἥρως<br>δέξατο καὶ κτεάνων μοῖραν πόρεν ὡς ἐπιεικές.", "st": "9.36"}, {"sp": "N", "t": "πρῶτος δὲ οὗτος ὁ Ὕηττος δίκην μοιχείας λαβὼν δῆλός ἐστι· καὶ χρόνῳ ὕστερον Δράκοντος Ἀθηναίοις θεσμοθετήσαντος ἐκ τῶν ἐκείνου κατέστη νόμων, οὓς ἔγραφεν ἐπὶ τῆς ἀρχῆς, ἄλλων τε ὁπόσων ἄδειαν εἶναι χρὴ καὶ δὴ καὶ τιμωρίας μοιχοῦ. τὸ δὲ ἀξίωμα τῶν Μινυῶν ἐπὶ τοσοῦτο ἤδη προῆκτο, ὥστε καὶ Νηλεὺς Κρηθέως βασιλεύων Πύλου γυναῖκα ἔσχεν ἐξ Ὀρχομενοῦ Χλῶριν Ἀμφίονος τοῦ Ἰασίου.", "st": "9.36"}, {"sp": "N", "t": "ἔδει δὲ ἄρα παυσθῆναι καὶ τὸ Ἄλμου γένος· οὐχ ὑπολείπεται γὰρ παῖδα Ὀρχομενός, καὶ οὕτως ἐς Κλύμενον τὸν Πρέσβωνος τοῦ Φρίξου περιῆλθεν ἡ ἀρχή. Κλυμένου δὲ γίνονται παῖδες, πρεσβύτατος μὲν Ἐργῖνος, ἐπὶ δὲ αὐτῷ Στράτιος καὶ Ἄρρων καὶ Πύλεος, νεώτατος δὲ Ἀζεύς. Κλύμενον μὲν ἐν τῇ ἑορτῇ τοῦ Ὀγχηστίου Ποσειδῶνος Θηβαίων φονεύουσιν ἄνδρες ἐξ ἀφορμῆς μικρᾶς ἐς ἅπαν θυμοῦ προαχθέντες· Ἐργῖνος δὲ ὁ πρεσβύτατος τῶν Κλυμένου παίδων τὴν βασιλείαν παραλαμβάνει.", "st": "9.37"}, {"sp": "N", "t": "δύναμιν δὲ αὐτίκα αὐτός τε καὶ οἱ ἀδελφοὶ συλλέξαντες ἦλθον ἐπὶ τὰς Θήβας· καὶ μάχῃ μὲν ἐκράτησαν, τὸ δὲ ἀπὸ τούτου χωροῦσιν ἐς ὁμολογίαν Θηβαίους κατὰ ἔτος ἕκαστον τελεῖν δασμὸν τοῦ Κλυμένου φόνου. Ἡρακλέους δὲ ἐπιτραφέντος ἐν Θήβαις, οὕτω τοῦ δασμοῦ τε ἠλευθερώθησαν οἱ Θηβαῖοι καὶ οἱ Μινύαι μεγάλως τῷ πολέμῳ προσέπταισαν·", "st": "9.37"}, {"sp": "N", "t": "Ἐργῖνος δὲ ἅτε κεκακωμένων ἐς τὸ ἔσχατον τῶν πολιτῶν πρὸς μὲν τὸν Ἡρακλέα ἐποιήσατο εἰρήνην, πλοῦτον δὲ τὸν πρότερον καὶ εὐδαιμονίαν ἐκείνην ἀνασώσασθαι ζητῶν ἠμέλησεν ἁπάντων ὁμοίως τῶν ἄλλων, ὥστε καὶ ἔλαθεν ἄγαμος καὶ ἄπαις ἀφικόμενος ἐς γῆρας. ὡς δὲ αὐτῷ χρήματα συνείλεκτο, ἐνταῦθα ἐπεθύμησέν οἱ γενέσθαι παῖδας·", "st": "9.37"}, {"sp": "N", "t": "ἐλθόντι δὲ ἐς Δελφοὺς καὶ ἐρομένῳ περὶ παίδων χρᾷ τάδε ἡ Πυθία·<br>Ἐργῖνε Κλυμένοιο πάι Πρεσβωνιάδαο,<br>ὄψ’ ἦλθες γενεὴν διζήμενος, ἀλλ’ ἔτι καὶ νῦν<br>ἱστοβοῆι γέροντι νέην ποτίβαλλε κορώνην.<br>λαβόντι δὲ αὐτῷ νέαν γυναῖκα κατὰ τὸ μάντευμα Τροφώνιος γίνεται καὶ Ἀγαμήδης.", "st": "9.37"}, {"sp": "N", "t": "λέγεται δὲ ὁ Τροφώνιος Ἀπόλλωνος εἶναι καὶ οὐκ Ἐργίνου· καὶ ἐγώ τε πείθομαι καὶ ὅστις παρὰ Τροφώνιον ἦλθε δὴ μαντευσόμενος. τούτους φασίν, ὡς ηὐξήθησαν, γενέσθαι δεινοὺς θεοῖς τε ἱερὰ κατασκευάσασθαι καὶ βασίλεια ἀνθρώποις· καὶ γὰρ τῷ Ἀπόλλωνι τὸν ναὸν ᾠκοδόμησαν τὸν ἐν Δελφοῖς καὶ Ὑριεῖ τὸν θησαυρόν. ἐποίησαν δὲ ἐνταῦθα τῶν λίθων ἕνα εἶναί σφισιν ἀφαιρεῖν κατὰ τὸ ἐκτός· καὶ οἱ μὲν ἀεί τι ἀπὸ τῶν τιθεμένων ἐλάμβανον· Ὑριεὺς δὲ εἴχετο ἀφασίᾳ, κλεῖς μὲν καὶ σημεῖα τὰ ἄλλα ὁρῶν ἀκίνητα, τὸν δὲ ἀριθμὸν ἀεὶ τῶν χρημάτων ἐλάττονα.", "st": "9.37"}, {"sp": "N", "t": "ἵστησιν οὖν ὑπὲρ τῶν ἀγγείων, ἐν οἷς ὅ τε ἄργυρος ἐνῆν καὶ ὁ χρυσός οἱ, πάγας ἤ τι καὶ ἄλλο ὃ τὸν ἐσελθόντα καὶ ἁπτόμενον τῶν χρημάτων καθέξειν ἔμελλεν. ἐσελθόντος δὲ τοῦ Ἀγαμήδους τὸν μὲν ὁ δεσμὸς κατεῖχε, Τροφώνιος δὲ ἀπέτεμεν αὐτοῦ τὴν κεφαλήν, ὅπως μὴ ἡμέρας ἐπισχούσης ἐκεῖνος γένοιτο ἐν αἰκίαις καὶ αὐτὸς μηνυθείη μετέχων τοῦ τολμήματος.", "st": "9.37"}, {"sp": "N", "t": "καὶ Τροφώνιον μὲν ἐνταῦθα ἐδέξατο ἡ γῆ διαστᾶσα, ἔνθα ἐστὶν ἐν τῷ ἄλσει τῷ ἐν Λεβαδείᾳ βόθρος τε Ἀγαμήδους καλούμενος καὶ πρὸς αὐτῷ στήλη· τὴν δὲ ἀρχὴν τῶν Ὀρχομενίων ἔσχεν Ἀσκάλαφος καὶ Ἰάλμενος Ἄρεως εἶναι λεγόμενοι, μητρὸς δὲ Ἀστυόχης ἦσαν τῆς Ἄκτορος τοῦ Ἀζέως τοῦ Κλυμένου· καὶ ὑπὸ τούτοις ἡγεμόσι Μινύαι στρατεύουσιν ἐς Τροίαν.", "st": "9.37"}, {"sp": "N", "t": "μετέσχον Ὀρχομένιοι καὶ τοῖς Κόδρου παισὶν ἐς Ἰωνίαν τοῦ στόλου. γενομένους δὲ ἀναστάτους ὑπὸ Θηβαίων κατήγαγεν αὖθις ἐς Ὀρχομενὸν Φίλιππος ὁ Ἀμύντου· τὰ δὲ ἀπὸ τοῦ δαιμονίου σφίσιν ἐς τὸ ἀσθενέστερον ἔμελλεν ἀεὶ ῥέψειν.", "st": "9.37"}, {"sp": "N", "t": "Ὀρχομενίοις δὲ πεποίηται καὶ Διονύσου, τὸ δὲ ἀρχαιότατον Χαρίτων ἐστὶν ἱερόν. τὰς μὲν δὴ πέτρας σέβουσί τε μάλιστα καὶ τῷ Ἐτεοκλεῖ αὐτὰς πεσεῖν ἐκ τοῦ οὐρανοῦ φασιν· τὰ δὲ ἀγάλματα ⟨τὰ⟩ σὺν κόσμῳ πεποιημένα ἀνετέθη μὲν ἐπ’ ἐμοῦ, λίθου δέ ἐστι καὶ ταῦτα.", "st": "9.38"}, {"sp": "N", "t": "ἔστι δέ σφισι καὶ κρήνη θέας ἀξία· καταβαίνουσι δὲ ἐς αὐτὴν ὕδωρ οἴσοντες. θησαυρὸς δὲ ὁ Μινύου, θαῦμα ὂν τῶν ἐν Ἑλλάδι αὐτῇ καὶ τῶν ἑτέρωθι οὐδενὸς ὕστερον, πεποίηται τρόπον τοιόνδε· λίθου μὲν εἴργασται, σχῆμα δὲ περιφερές ἐστιν αὐτῷ, κορυφὴ δὲ οὐκ ἐς ἄγαν ὀξὺ ἀνηγμένη· τὸν δὲ ἀνωτάτω τῶν λίθων φασὶν ἁρμονίαν παντὶ εἶναι τῷ οἰκοδομήματι.", "st": "9.38"}, {"sp": "N", "t": "τάφοι δὲ Μινύου τε καὶ Ἡσιόδου· καταδέξασθαι δέ φασιν οὕτω τοῦ Ἡσιόδου τὰ ὀστᾶ. νόσου καταλαμβανούσης λοιμώδους καὶ ἀνθρώπους καὶ τὰ βοσκήματα ἀποστέλλουσι θεωροὺς παρὰ τὸν θεόν· τούτοις δὲ ἀποκρίνασθαι λέγουσι τὴν Πυθίαν, Ἡσιόδου τὰ ὀστᾶ ἐκ τῆς Ναυπακτίας ἀγαγοῦσιν ἐς τὴν Ὀρχομενίαν, ἄλλο δὲ εἶναί σφισιν οὐδὲν ἴαμα. τότε δὲ ἐπερέσθαι δεύτερα, ὅπου τῆς Ναυπακτίας αὐτὰ ἐξευρήσουσι· καὶ αὖθις τὴν Πυθίαν εἰπεῖν ὡς μηνύσοι κορώνη σφίσιν.", "st": "9.38"}, {"sp": "N", "t": "οὕτω τοῖς θεοπρόποις ἀποβᾶσιν ἐς τὴν γῆν πέτραν τε οὐ πόρρω τῆς ὁδοῦ καὶ τὴν ὄρνιθα ἐπὶ τῇ πέτρᾳ φασὶν ὀφθῆναι· καὶ τοῦ Ἡσιόδου δὲ τὰ ὀστᾶ εὗρον ἐν χηραμῷ τῆς πέτρας. καὶ ἐλεγεῖα ἐπὶ τῷ μνήματι ἐπεγέγραπτο·<br>Ἄσκρη μὲν πατρὶς πολυλήιος, ἀλλὰ θανόντος<br>ὀστέα πληξίππων γῆ Μινυῶν κατέχει<br>Ἡσιόδου, τοῦ πλεῖστον ἐν Ἑλλάδι κῦδος ὀρεῖται<br>ἀνδρῶν κρινομένων ἐν βασάνῳ σοφίης.", "st": "9.38"}, {"sp": "N", "t": "περὶ δὲ Ἀκταίωνος λεγόμενα ἦν Ὀρχομενίοις λυμαίνεσθαι τὴν γῆν πέτρας ἔχον εἴδωλον· ὡς δὲ ἐχρῶντο ἐν Δελφοῖς, κελεύει σφίσιν ὁ θεὸς ἀνευρόντας εἴ τι ἦν Ἀκταίωνος λοιπὸν κρύψαι γῇ, κελεύει δὲ καὶ τοῦ εἰδώλου χαλκῆν ποιησαμένους εἰκόνα πρὸς πέτρᾳ σιδήρῳ δῆσαι. τοῦτο καὶ αὐτὸς δεδεμένον τὸ ἄγαλμα εἶδον· καὶ τῷ Ἀκταίωνι ἐναγίζουσιν ἀνὰ πᾶν ἔτος.", "st": "9.38"}, {"sp": "N", "t": "σταδίους δὲ ἀφέστηκεν ἑπτὰ Ὀρχομενοῦ ναός τε Ἡρακλέους καὶ ἄγαλμα οὐ μέγα. ἐνταῦθα τοῦ ποταμοῦ τοῦ Μέλανός εἰσιν αἱ πηγαί, καὶ ὁ Μέλας ἐς λίμνην καὶ οὗτος τὴν Κηφισίδα ἐκδίδωσιν. ἐπέχει μὲν δὴ καὶ ἄλλως τῆς Ὀρχομενίας τὸ πολὺ ἡ λίμνη, χειμῶνος δὲ ὥρᾳ νότου τὰ πλείω πνεύσαντος ἔπεισιν ἐπὶ πλέον τῆς χώρας τὸ ὕδωρ.", "st": "9.38"}, {"sp": "N", "t": "Θηβαῖοι δὲ τὸν ποταμὸν τὸν Κηφισόν φασιν ὑπὸ Ἡρακλέους ἐς τὸ πεδίον ἀποστραφῆναι τὸ Ὀρχομένιον· τέως δὲ αὐτὸν ὑπὸ τὸ ὄρος ἐς θάλασσαν ἐξιέναι, πρὶν ἢ τὸν Ἡρακλέα τὸ χάσμα ἐμφράξαι τὸ διὰ τοῦ ὄρους. ἐπίσταται μὲν οὖν καὶ Ὅμηρος λίμνην ἄλλως τὴν Κηφισίδα οὖσαν καὶ οὐχ ὑπὸ Ἡρακλέους πεποιημένην, καὶ ἐπὶ τῷδε εἴρηκε<br>λίμνῃ κεκλιμένος Κηφισίδι·", "st": "9.38"}, {"sp": "N", "t": "ἔχει δὲ οὐδὲ εἰκότα λόγον τοὺς Ὀρχομενίους μὴ καὶ τὸ χάσμα ἐξευρεῖν καὶ τοῦ Ἡρακλέους ἀναρρήξαντας τὸ ἔργον ἀποδοῦναι τὴν διέξοδον τῷ Κηφισῷ τὴν ἀρχαίαν, ἐπεὶ μηδὲ ἄχρι τῶν Τρωικῶν χρήμασιν ἀδυνάτως εἶχον. μαρτυρεῖ δέ μοι καὶ Ὄμηρος ἐν Ἀχιλλέως ἀποκρίσει πρὸς τοὺς παρὰ Ἀγαμέμνονος πρέσβεις·<br>οὐδ’ ὅσ’ ἐς Ὀρχομενὸν ποτινίσσεται,<br>δῆλα δήπουθεν ὡς καὶ τότε προσιόντων τοῖς Ὀρχομενίοις χρημάτων πολλῶν.", "st": "9.38"}, {"sp": "N", "t": "Ἀσπληδόνα δὲ ἐκλιπεῖν τοὺς οἰκήτοράς φασιν ὕδατος σπανίζοντος· γενέσθαι δὲ τὸ ὄνομα ἀπὸ Ἀσπληδόνος τῇ πόλει, τοῦτον δὲ εἶναι νύμφης τε Μιδείας καὶ Ποσειδῶνος. ὁμολογεῖ δὲ καὶ ἔπη σφίσιν ἃ ἐποίησε Χερσίας, ἀνὴρ Ὀρχομένιος·<br>ἐκ δὲ Ποσειδάωνος ἀγακλειτῆς τε Μιδείης<br>Ἀσπληδὼν γένεθ’ υἱὸς ἀν’ εὐρύχορον πτολίεθρον.", "st": "9.38"}, {"sp": "N", "t": "τοῦδε τοῦ Χερσίου τῶν ἐπῶν οὐδεμία ἦν ἔτι κατ’ ἐμὲ μνήμη, ἀλλὰ καὶ τάδε ἐπηγάγετο ὁ Κάλλιππος ἐς τὸν αὐτὸν λόγον τὸν ἔχοντα ἐς Ὀρχομενίους· τούτου δὲ τοῦ Χερσίου καὶ ἐπίγραμμα οἱ Ὀρχομένιοι τὸ ἐπὶ τῷ Ἡσιόδου τάφῳ μνημονεύουσιν.", "st": "9.38"}, {"sp": "N", "t": "τὰ μὲν δὴ πρὸς τῶν ὀρῶν Φωκεῖς ὑπεροικοῦσιν Ὀρχομενίων, ἐν δὲ τῷ πεδίῳ Λεβάδειά ἐστιν αὐτοῖς ὅμορος. αὕτη τὸ μὲν ἐξ ἀρχῆς ᾠκεῖτο ἐπὶ μετεώρου καὶ ὠνομάζετο Μίδεια ἀπὸ τῆς Ἀσπληδόνος μητρός· Λεβάδου δὲ ἐξ Ἀθηνῶν ἐς αὐτὴν ἀφικομένου κατέβησάν τε ἐς τὸ χθαμαλὸν οἱ ἄνθρωποι καὶ ἐκλήθη Λεβάδεια ἡ πόλις ἀπ’ αὐτοῦ. πατέρα δὲ τοῦ Λεβάδου, καὶ καθ’ ἥντινα αἰτίαν ἦλθεν, οὐκ ἴσασιν ἄλλο ἢ γυναῖκα εἶναι Λεβάδου Λαονίκην.", "st": "9.39"}, {"sp": "N", "t": "κεκόσμηται μὲν δὴ τὰ ἄλλα σφίσιν ἡ πόλις ὁμοίως τοῖς Ἑλλήνων μάλιστα εὐδαίμοσι, διείργει δὲ ἀπ’ αὐτῆς τὸ ἄλσος τοῦ Τροφωνίου ⟨ποταμὸς Ἕρκυνα.⟩ φασὶ δ’ ἐνταῦθα Ἕρκυναν ὁμοῦ Κόρῃ τῇ Δήμητρος παίζουσαν καὶ ἔχουσαν χῆνα ἀφεῖναι τοῦτον ἄκουσαν· ἐς δὲ ἄντρον κοῖλον ἐσπτάντος καὶ ὑπὸ λίθον ἀποκρύψαντος αὑτὸν ἐσελθοῦσα ἡ Κόρη λαμβάνει τὸν ὄρνιθα ὑπὸ τῷ λίθῳ κατακείμενον· ῥυῆναί τε δὴ τὸ ὕδωρ ὅθεν ἀνείλετο ἡ Κόρη τὸν λίθον καὶ ὀνομασθῆναι τὸν ποταμὸν ἐπὶ τούτῳ λέγουσιν Ἕρκυναν.", "st": "9.39"}, {"sp": "N", "t": "καὶ ἔστι μὲν πρὸς τῇ ὄχθῃ τοῦ ποταμοῦ ναὸς Ἑρκύνης, ἐν δὲ αὐτῷ παρθένος χῆνα ἔχουσα ἐν ταῖς χερσίν· εἰσὶ δὲ ἐν τῷ σπηλαίῳ τοῦ ποταμοῦ τε αἱ πηγαὶ καὶ ἀγάλματα ὀρθά, περιειλιγμένοι δέ εἰσιν αὐτῶν τοῖς σκήπτροις δράκοντες. ταῦτα εἰκάσαι μὲν ἄν τις Ἀσκληπιοῦ τε εἶναι καὶ Ὑγείας, εἶεν δ’ ἂν Τροφώνιος καὶ Ἕρκυνα, ἐπεὶ μηδὲ τοὺς δράκοντας Ἀσκληπιοῦ μᾶλλον ἢ καὶ Τροφωνίου νομίζουσιν ἱεροὺς εἶναι. ἐπὶ δὲ τῷ ποταμῷ μνῆμά ἐστιν Ἀρκεσιλάου· Λήϊτον δὲ ἀνακομίσαι ⟨φασὶ⟩ τοῦ Ἀρκεσιλάου τὰ ὀστᾶ ἐκ Τροίας.", "st": "9.39"}, {"sp": "N", "t": "τὰ δὲ ἐπιφανέστατα ἐν τῷ ἄλσει Τροφωνίου ναὸς καὶ ἄγαλμά ἐστιν, Ἀσκληπιῷ καὶ τοῦτο εἰκασμένον· Πραξιτέλης δὲ ἐποίησε τὸ ἄγαλμα. ἔστι δὲ καὶ Δήμητρος ἱερὸν ἐπίκλησιν Εὐρώπης καὶ Ζεὺς Ὑέτιος ἐν ὑπαίθρῳ. ἀναβᾶσι δὲ ἐπὶ τὸ μαντεῖον καὶ αὐτόθεν ἰοῦσιν ἐς τὸ πρόσω τοῦ ὄρους, Κόρης ἐστὶ καλουμένη θήρα καὶ Διὸς Βασιλέως ναός. τοῦτον μὲν δὴ διὰ τὸ μέγεθος ἢ καὶ τῶν πολέμων τὸ ἀλλεπάλληλον ἀφείκασιν ἡμίεργον· ἐν δὲ ἑτέρῳ ναῷ Κρόνου καὶ Ἥρας καὶ Διός ἐστιν ἀγάλματα. ἔστι δὲ καὶ Ἀπόλλωνος ἱερόν.", "st": "9.39"}, {"sp": "N", "t": "κατὰ δὲ τὸ μαντεῖον τοιάδε γίνεται. ἐπειδὰν ἀνδρὶ ἐς τοῦ Τροφωνίου κατιέναι δόξῃ, πρῶτα μὲν τεταγμένων ἡμερῶν δίαιταν ἐν οἰκήματι ἔχει, τὸ δὲ οἴκημα Δαίμονός τε ἀγαθοῦ καὶ Τύχης ἱερόν ἐστιν ἀγαθῆς· διαιτώμενος δὲ ἐνταῦθα τά τε ἄλλα καθαρεύει καὶ λουτρῶν εἴργεται θερμῶν, τὸ δὲ λουτρὸν ὁ ποταμός ἐστιν ἡ Ἕρκυνα· καί οἱ καὶ κρέα ἄφθονά ἐστιν ἀπὸ τῶν θυσιῶν, θύει γὰρ δὴ ὁ κατιὼν αὐτῷ τε τῷ Τροφωνίῳ καὶ τοῦ Τροφωνίου τοῖς παισί, πρὸς δὲ Ἀπόλλωνί τε καὶ Κρόνῳ καὶ Διὶ ἐπίκλησιν Βασιλεῖ καὶ Ἥρᾳ τε Ἡνιόχῃ καὶ Δήμητρι ἣν ἐπονομάζοντες Εὐρώπην τοῦ Τροφωνίου φασὶν εἶναι τροφόν.", "st": "9.39"}, {"sp": "N", "t": "καθ’ ἑκάστην δὲ τῶν θυσιῶν ἀνὴρ μάντις παρὼν ἐς τοῦ ἱερείου τὰ σπλάγχνα ἐνορᾷ, ἐνιδὼν δὲ προθεσπίζει τῷ κατιόντι εἰ δὴ αὐτὸν εὐμενὴς ὁ Τροφώνιος καὶ ἵλεως δέξεται. τῶν μὲν δὴ ἄλλων ἱερείων τὰ σπλάγχνα οὐχ ὁμοίως δηλοῖ τοῦ Τροφωνίου τὴν γνώμην· ἐν δὲ νυκτὶ ᾗ κάτεισιν ἕκαστος, ἐν ταύτῃ κριὸν θύουσιν ἐς βόθρον, ἐπικαλούμενοι τὸν Ἀγαμήδην. θυμάτων δὲ τῶν πρότερον πεφηνότων αἰσίων λόγος ἐστὶν οὐδείς, εἰ μὴ καὶ τοῦδε τοῦ κριοῦ τὰ σπλάγχνα τὸ αὐτὸ θέλοι λέγειν· ὁμολογούντων δὲ καὶ τούτων, τότε ἕκαστος ἤδη κάτεισιν εὔελπις, κάτεισι δὲ οὕτω.", "st": "9.39"}, {"sp": "N", "t": "πρῶτα μὲν ἐν τῇ νυκτὶ αὐτὸν ἄγουσιν ἐπὶ τὸν ποταμὸν τὴν Ἕρκυναν, ἀγαγόντες δὲ ἐλαίῳ χρίουσι καὶ λούουσι δύο παῖδες τῶν ἀστῶν ἔτη τρία που καὶ δέκα γεγονότες, οὓς Ἑρμᾶς ἐπονομάζουσιν· οὗτοι τὸν καταβαίνοντά εἰσιν οἱ λούοντες καὶ ὁπόσα χρὴ διακονούμενοι ἅτε παῖδες. τὸ ἐντεῦθεν ὑπὸ τῶν ἱερέων οὐκ αὐτίκα ἐπὶ τὸ μαντεῖον, ἐπὶ δὲ ὕδατος πηγὰς ἄγεται· αἱ δὲ ἐγγύτατά εἰσιν ἀλλήλων.", "st": "9.39"}, {"sp": "N", "t": "ἐνταῦθα δὴ χρὴ πιεῖν αὐτὸν Λήθης τε ὕδωρ καλούμενον, ἵνα λήθη γένηταί οἱ πάντων ἃ τέως ἐφρόντιζε, καὶ ἐπὶ τῷδε ἄλλο αὖθις ὕδωρ πίνειν Μνημοσύνης· ἀπὸ τούτου τε μνημονεύει τὰ ὀφθέντα οἱ καταβάντι. θεασάμενος δὲ ἄγαλμα ὃ ποιῆσαι Δαίδαλόν φασιν—ὑπὸ δὲ τῶν ἱερέων οὐκ ἐπιδείκνυται πλὴν ὅσοι παρὰ τὸν Τροφώνιον μέλλουσιν ἔρχεσθαι— τοῦτο τὸ ἄγαλμα ἰδὼν καὶ θεραπεύσας τε καὶ εὐξάμενος ἔρχεται πρὸς τὸ μαντεῖον, χιτῶνα ἐνδεδυκὼς λινοῦν καὶ ταινίαις τὸν χιτῶνα ἐπιζωσθεὶς καὶ ὑποδησάμενος ἐπιχωρίας κρηπῖδας.", "st": "9.39"}, {"sp": "N", "t": "ἔστι δὲ τὸ μαντεῖον ὑπὲρ τὸ ἄλσος ἐπὶ τοῦ ὄρους. κρηπὶς μὲν ἐν κύκλῳ περιβέβληται λίθου λευκοῦ, περίοδος δὲ τῆς κρηπῖδος κατὰ ἅλων τὴν ἐλαχίστην ἐστίν, ὕψος δὲ ἀποδέουσα δύο εἶναι πήχεις· ἐφεστήκασι δὲ ἐπὶ τῇ κρηπῖδι ὀβελοὶ καὶ αὐτοὶ χαλκοῖ καὶ αἱ συνέχουσαι σφᾶς ζῶναι, διὰ δὲ αὐτῶν θύραι πεποίηνται. τοῦ περιβόλου δὲ ἐντὸς χάσμα γῆς ἐστιν οὐκ αὐτόματον ἀλλὰ σὺν τέχνῃ καὶ ἁρμονίᾳ πρὸς τὸ ἀκριβέστατον ᾠκοδομημένον.", "st": "9.39"}, {"sp": "N", "t": "τοῦ δὲ οἰκοδομήματος τούτου τὸ σχῆμα εἴκασται κριβάνῳ· τὸ δὲ εὖρος ἡ διάμετρος αὐτοῦ τέσσαρας παρέχοιτο ἂν ὡς εἰκάσαι πήχεις· βάθος δὲ τοῦ οἰκοδομήματος, οὐκ ἂν οὐδὲ τοῦτο εἰκάζοι τις ἐς πλέον ὀκτὼ καθήκειν πηχῶν. κατάβασις δὲ οὐκ ἔστι πεποιημένη σφίσιν ἐς τὸ ἔδαφος· ἐπειδὰν δὲ ἀνὴρ ἔρχηται παρὰ τὸν Τροφώνιον, κλίμακα αὐτῷ κομίζουσι στενὴν καὶ ἐλαφράν. καταβάντι δέ ἐστιν ὀπὴ μεταξὺ τοῦ τε ἐδάφους καὶ τοῦ οἰκοδομήματος· σπιθαμῶν τὸ εὖρος δύο, τὸ δὲ ὕψος ἐφαίνετο εἶναι σπιθαμῆς.", "st": "9.39"}, {"sp": "N", "t": "ὁ οὖν κατιὼν κατακλίνας ἑαυτὸν ἐς τὸ ἔδαφος ἔχων μάζας μεμαγμένας μέλιτι προεμβάλλει τε ἐς τὴν ὀπὴν τοὺς πόδας καὶ αὐτὸς ἐπιχωρεῖ, τὰ γόνατά οἱ τῆς ὀπῆς ἐντὸς γενέσθαι προθυμούμενος· τὸ δὲ λοιπὸν σῶμα αὐτίκα ἐφειλκύσθη τε καὶ τοῖς γόνασιν ἐπέδραμεν, ὥσπερ ποταμῶν ὁ μέγιστος καὶ ὠκύτατος συνδεθέντα ὑπὸ δίνης ἀποκρύψειεν ⟨ἂν⟩ ἄνθρωπον. τὸ δὲ ἐντεῦθεν τοῖς ἐντὸς τοῦ ἀδύτου γενομένοις οὐχ εἷς οὐδὲ ὁ αὐτὸς τρόπος ἐστὶν ὅτῳ διδάσκονται τὰ μέλλοντα, ἀλλά πού τις καὶ εἶδε καὶ ἄλλος ἤκουσεν. ἀναστρέψαι δὲ ὀπίσω τοῖς καταβᾶσι διὰ στομίου τε ἔστι τοῦ αὐτοῦ καὶ προεκθεόντων σφίσι τῶν ποδῶν.", "st": "9.39"}, {"sp": "N", "t": "ἀποθανεῖν δὲ οὐδένα τῶν καταβάντων λέγουσιν ὅτι μὴ μόνον τῶν Δημητρίου τινὰ δορυφόρων· τοῦτον δὲ οὔτε ποιῆσαι περὶ τὸ ἱερόν φασιν οὐδὲν τῶν νενομισμένων οὔτε χρησόμενον τῷ θεῷ καταβῆναι, χρυσὸν δὲ καὶ ἄργυρον ἐκκομιεῖν ἐλπίσαντα ἐκ τοῦ ἀδύτου. λέγεται δὲ καὶ τούτου τὸν νεκρὸν ἑτέρωθι ἀναφανῆναι καὶ οὐ κατὰ στόμα ἐκβληθῆναι τὸ ἱερόν. ἐς μὲν δὴ τὸν ἄνθρωπον λεγομένων καὶ ἄλλων εἴρηταί μοι τὰ ἀξιολογώτατα·", "st": "9.39"}, {"sp": "N", "t": "τὸν δὲ ἀναβάντα παρὰ τοῦ Τροφωνίου παραλαβόντες αὖθις οἱ ἱερεῖς καθίζουσιν ἐπὶ θρόνον Μνημοσύνης μὲν καλούμενον, κεῖται δὲ οὐ πόρρω τοῦ ἀδύτου, καθεσθέντα δὲ ἐνταῦθα ἀνερωτῶσιν ὁπόσα εἶδέ τε καὶ ἐπύθετο· μαθόντες δὲ ἐπιτρέπουσιν αὐτὸν ἤδη τοῖς προσήκουσιν. οἱ δὲ ἐς τὸ οἴκημα, ἔνθα καὶ πρότερον διῃτᾶτο παρά τε Τύχῃ καὶ Δαίμονι ἀγαθοῖς, ἐς τοῦτο ἀράμενοι κομίζουσι κάτοχόν τε ἔτι τῷ δείματι καὶ ἀγνῶτα ὁμοίως αὑτοῦ τε καὶ τῶν πέλας. ὕστερον μέντοι τά τε ἄλλα οὐδέν τι φρονήσει μεῖον ἢ πρότερον καὶ γέλως ἐπάνεισίν οἱ.", "st": "9.39"}, {"sp": "N", "t": "γράφω δὲ οὐκ ἀκοὴν ἀλλὰ ἑτέρους τε ἰδὼν καὶ αὐτὸς τῷ Τροφωνίῳ χρησάμενος. τοὺς δὲ ἐς τοῦ Τροφωνίου κατελθόντας, ἀνάγκη σφᾶς, ὁπόσα ἤκουσεν ἕκαστος ἢ εἶδεν, ἀναθεῖναι γεγραμμένα ἐν πίνακι. λείπεται δ’ ἔτι καὶ τοῦ Ἀριστομένους ἐνταῦθα ἡ ἀσπίς· τὰ δὲ ἐς αὐτὴν ὁποῖα ἐγένετο, ἐδήλωσα ἐν τοῖς προτέροις τοῦ λόγου.", "st": "9.39"}, {"sp": "N", "t": "τὸ δὲ μαντεῖον οἱ Βοιωτοὶ τοῦτο οὐ πεπυσμένοι πρότερον ἐπ’ αἰτίᾳ τοιᾷδε ἔγνωσαν. θεωροὺς ἀφ’ ἑκάστης πόλεως ἄνδρας ἀποστέλλουσιν ἐς Δελφούς· οὐ γὰρ δή σφισιν ἔτος δεύτερον ὗεν ὁ θεός. τούτοις αἰτοῦσιν ἐπανόρθωμα τοῦ αὐχμοῦ προσέταξεν ἡ Πυθία παρὰ Τροφώνιον ἐς Λεβάδειαν ἐλθοῦσιν εὕρασθαι παρὰ ἐκείνου τὸ ἴαμα.", "st": "9.40"}, {"sp": "N", "t": "ὡς δὲ ἐς τὴν Λεβάδειαν ἐλθόντες οὐκ ἐδύναντο εὑρεῖν τὸ μαντεῖον, ἐνταῦθα τῶν ἐξ Ἀκραιφνίου πόλεως Σάων—οὗτος δὲ ἦν καὶ ἡλικίᾳ τῶν θεωρῶν πρεσβύτατος—εἶδεν ἑσμὸν μελισσῶν, ⟨καὶ παρέστη οἱ,⟩ ὅποι ποτ’ ἂν ἀποτράπωνται, καὶ αὐτὸς ἕπεσθαι. αὐτίκα δὴ τὰς μελίσσας ἐς τοῦτο ἐσπετομένας ὁρᾷ τῆς γῆς, καὶ συνεσῆλθέ σφισιν ἐς τὸ μαντεῖον. τοῦτον τὸν Σάωνα καὶ τὴν ἱερουργίαν τὴν καθεστηκυῖαν, καὶ ὁπόσα περὶ τὸ χρηστήριον δρῶσιν ἄλλα, διδαχθῆναι παρὰ τοῦ Τροφωνίου φασίν.", "st": "9.40"}, {"sp": "N", "t": "Δαιδάλου δὲ τῶν ἔργων δύο μὲν ταῦτά ἐστιν ἐν Βοιωτοῖς, Ἡρακλῆς τε ἐν Θήβαις καὶ παρὰ Λεβαδεῦσιν ὁ Τροφώνιος, τοσαῦτα δὲ ἕτερα ξόανα ἐν Κρήτῃ, Βριτόμαρτις ἐν Ὀλοῦντι καὶ Ἀθηνᾶ παρὰ Κνωσσίοις· παρὰ τούτοις δὲ καὶ ὁ τῆς Ἀριάδνης χορός, οὗ καὶ Ὅμηρος ἐν Ἰλιάδι μνήμην ἐποιήσατο, ἐπειργασμένος ἐστὶν ἐπὶ λευκοῦ λίθου. καὶ Δηλίοις Ἀφροδίτης ἐστὶν οὐ μέγα ξόανον, λελυμασμένον τὴν δεξιὰν χεῖρα ὑπὸ τοῦ χρόνου· κάτεισι δὲ ἀντὶ ποδῶν ἐς τετράγωνον σχῆμα.", "st": "9.40"}, {"sp": "N", "t": "πείθομαι τοῦτο Ἀριάδνην λαβεῖν παρὰ Δαιδάλου, καὶ ἡνίκα ἠκολούθησε τῷ Θησεῖ, τὸ ἄγαλμα ἐπεκομίζετο οἴκοθεν· ἀφαιρεθέντα δὲ αὐτῆς τὸν Θησέα οὕτω φασὶν οἱ Δήλιοι τὸ ξόανον τῆς θεοῦ ἀναθεῖναι τῷ Ἀπόλλωνι τῷ Δηλίῳ, ἵνα μὴ οἴκαδε ἐπαγόμενος ἐς ἀνάμνησίν τε Ἀριάδνης ἐφέλκηται καὶ ἀεὶ νέας ἐπὶ τῷ ἔρωτι εὑρίσκηται τὰς συμφοράς. πέρα δὲ οὐκ οἶδα ὑπόλοιπα ὄντα τῶν Δαιδάλου· τοῖς γὰρ ἀνατεθεῖσιν ὑπὸ Ἀργείων ἐς τὸ Ἡραῖον καὶ ἐς Γέλαν τὴν ἐν Σικελίᾳ κομισθεῖσιν ἐξ Ὀμφάκης, ἀφανισθῆναί σφισιν ὁ χρόνος καθέστηκεν αἴτιος.", "st": "9.40"}, {"sp": "N", "t": "Λεβαδέων δὲ ἔχονται Χαιρωνεῖς. ἐκαλεῖτο δὲ ἡ πόλις καὶ τούτοις Ἄρνη τὸ ἀρχαῖον· θυγατέρα δὲ εἶναι λέγουσιν Αἰόλου τὴν Ἄρνην, ἀπὸ δὲ ταύτης κληθῆναι καὶ ἑτέραν ἐν Θεσσαλίᾳ πόλιν· τὸ δὲ νῦν τοῖς Χαιρωνεῦσιν ὄνομα γεγονέναι ἀπὸ Χαίρωνος, ὃν Ἀπόλλωνός φασιν εἶναι, μητέρα δὲ αὐτοῦ Θηρὼ τὴν Φύλαντος εἶναι. μαρτυρεῖ δὲ καὶ ὁ τὰ ἔπη τὰς μεγάλας Ἠοίας ποιήσας·", "st": "9.40"}, {"sp": "N", "t": "Φύλας δ’ ὤπυιεν κούρην κλειτοῦ Ἰολάου<br>† λειπεφιληνη⟨ν⟩ εἶδος Ὀλυμπιάδεσσιν ⟨ὅμοιον,⟩<br>Ἱππότην δέ οἱ υἱὸν ἐνὶ μεγάροισιν ἔτικτεν<br>Θηρώ τ’ εὐειδῆ, ἰκέλην φαέεσσι σελήνης.<br>Θηρὼ δ’ Ἀπόλλωνος ἐς ἀγκοίνῃσι πεσοῦσα<br>γείνατο Χαίρωνος κρατερὸν μένος ἱπποδάμοιο.<br>Ὅμηρος δὲ ἐπιστάμενος ἐμοὶ δοκεῖν Χαιρώνειάν τε ἤδη καὶ Λεβάδειαν καλουμένας, ὅμως τοῖς ἀρχαίοις ἐχρήσατο ὀνόμασιν ἐς αὐτάς, καθότι καὶ Αἴγυπτον τὸν ποταμὸν εἶπεν, οὐ Νεῖλον.", "st": "9.40"}, {"sp": "N", "t": "Χαιρωνεῦσι δὲ δύο ἐστὶν ἐν τῇ χώρᾳ τρόπαια, ἃ Ῥωμαῖοι καὶ Σύλλας ἔστησαν Ταξίλον καὶ στρατιὰν τὴν Μιθριδάτου κρατήσαντες. Φίλιππος δὲ οὐκ ἀνέθηκεν ὁ Ἀμύντου τρόπαιον οὔτε ἐνταῦθα οὔτε ὁπόσας μάχας ἄλλας βαρβάρους ἢ καὶ Ἕλληνας ἐνίκησεν· οὐ γάρ τι Μακεδόσιν ἱστάναι τρόπαια ἦν νενομισμένον.", "st": "9.40"}, {"sp": "N", "t": "λέγεται δὲ ὑπὸ Μακεδόνων Καρανὸν βασιλεύοντα ἐν Μακεδονίᾳ κρατῆσαι μάχῃ Κισσέως, ὃς ἐδυνάστευεν ἐν χώρᾳ τῇ ὁμόρῳ· καὶ ὁ μὲν τρόπαιον ὁ Καρανὸς κατὰ νόμους τοὺς Ἀργείων ἔστησεν ἐπὶ τῇ νίκῃ· ἐπελθόντα δέ φασιν ἐκ τοῦ Ὀλύμπου λέοντα ἀνατρέψαι τε τὸ τρόπαιον ⟨καὶ⟩ ἀφανισθῆναι, ⟨συνεῖναι τε⟩ γνώμῃ", "st": "9.40"}, {"sp": "N", "t": "Καρανὸν [δὲ] οὐκ εὖ βουλεύσασθαι βαρβάροις τοῖς περιοικοῦσιν ἐς ἔχθραν ἐλθόντα ἀδιάλλακτον, καταστῆναί ⟨τε⟩ χρῆναι [γὰρ] μήτε ὑπὸ αὐτοῦ Καρανοῦ μήτε ὑπὸ τῶν ὕστερον βασιλευσόντων Μακεδονίας τρόπαια ἵστασθαι, εἰ ἐς εὔνοιάν ποτε τοὺς προσχώρους ὑπάξονται. μαρτυρεῖ δὲ τῷ λόγῳ καὶ Ἀλέξανδρος, οὐκ ἀναστήσας οὔτε ἐπὶ Δαρείῳ τρόπαια οὔτε ἐπὶ ταῖς Ἰνδικαῖς νίκαις.", "st": "9.40"}, {"sp": "N", "t": "προσιόντων δὲ τῇ πόλει πολυάνδριον Θηβαίων ἐστὶν ἐν τῷ πρὸς Φίλιππον ἀγῶνι ἀποθανόντων. ἐπιγέγραπται μὲν δὴ ἐπίγραμμα οὐδέν, ἐπίθημα δ’ ἔπεστιν αὐτῷ λέων· φέροι δ’ ἂν ἐς τῶν ἀνδρῶν μάλιστα τὸν θυμόν· ἐπίγραμμα δὲ ἄπεστιν ἐμοὶ δοκεῖν ὅτι οὐδὲ ἐοικότα τῇ τόλμῃ σφίσι τὰ ἐκ τοῦ δαίμονος ἠκολούθησε.", "st": "9.40"}, {"sp": "N", "t": "θεῶν δὲ μάλιστα Χαιρωνεῖς τιμῶσι τὸ σκῆπτρον ὃ ποιῆσαι Διί φησιν Ὅμηρος Ἥφαιστον, παρὰ δὲ Διὸς λαβόντα Ἑρμῆν δοῦναι Πέλοπι, Πέλοπα δὲ Ἀτρεῖ καταλιπεῖν, τὸν δὲ Ἀτρέα Θυέστῃ, παρὰ Θυέστου δὲ ἔχειν Ἀγαμέμνονα· τοῦτο οὖν τὸ σκῆπτρον σέβουσι, Δόρυ ὀνομάζοντες. καὶ εἶναι μέν τι θειότερον οὐχ ἥκιστα δηλοῖ τὸ ἐς τοὺς ἀνθρώπους ἐπιφανὲς ἐξ αὐτοῦ·", "st": "9.40"}, {"sp": "N", "t": "φασὶ δ’ ἐπὶ τοῖς ὅροις αὐτῶν καὶ Πανοπέων τῶν ἐν τῇ Φωκίδι εὑρεθῆναι, σὺν δὲ αὐτῷ καὶ χρυσὸν εὕρασθαι τοὺς Φωκεῖς, σφίσι δὲ ἀσμένοις ἀντὶ χρυσοῦ γενέσθαι τὸ σκῆπτρον. κομισθῆναι δὲ αὐτὸ ἐς τὴν Φωκίδα ὑπὸ Ἠλέκτρας τῆς Ἀγαμέμνονος πείθομαι. ναὸς δὲ οὐκ ἔστιν αὐτῷ δημοσίᾳ πεποιημένος, ἀλλὰ κατὰ ἔτος ἕκαστον ὁ ἱερώμενος ἐν οἰκήματι ἔχει τὸ σκῆπτρον· καί οἱ θυσίαι ἀνὰ πᾶσαν ἡμέραν θύονται, καὶ τράπεζα παράκειται παντοδαπῶν κρεῶν καὶ πεμμάτων πλήρης.", "st": "9.40"}, {"sp": "N", "t": "ὁπόσα δὲ εἶναι τῶν Ἡφαίστου ποιηταί τε ᾄδουσι καὶ τῶν ἀνθρώπων ἠκολούθηκεν ἡ φήμη, τούτων, ὅτι μὴ τὸ Ἀγαμέμνονος σκῆπτρον, ἄλλο γε οὐδὲν ἀξιόχρεών ἐστιν ἐς πίστιν. Λύκιοι μέν γε ἐν Πατάροις ἐν τῷ ναῷ τοῦ Ἀπόλλωνος χαλκοῦν ἐπιδεικνύουσι κρατῆρα, ἀνάθημα εἶναι φάμενοι Τηλέφου καὶ ἔργον Ἡφαίστου· καὶ σφᾶς, ὥς γε εἰκός, λέληθε Θεόδωρον καὶ Ῥοῖκον Σαμίους εἶναι τοὺς διαχέαντας χαλκὸν πρώτους.", "st": "9.41"}, {"sp": "N", "t": "Πατρεῖς δὲ οἱ Ἀχαιοὶ λόγῳ μὲν λέγουσιν ὅτι Ἡφαίστου ποίημά ἐστιν ἡ λάρναξ ἣν Εὐρύπυλος ἤνεγκεν ἐξ Ἰλίου, ἔργῳ δὲ οὐ παρέχουσιν αὐτὴν θεάσασθαι. ἔστι δὲ Ἀμαθοῦς ἐν Κύπρῳ πόλις, Ἀδώνιδος ἐν αὐτῇ καὶ Ἀφροδίτης ἱερόν ἐστιν ἀρχαῖον· ἀνακεῖσθαι δὲ ἐνταῦθα λέγουσιν ὅρμον Ἁρμονίᾳ μὲν δοθέντα ἐξ ἀρχῆς, καλούμενον δὲ Ἐριφύλης, ὅτι αὐτὴ δῶρον ἔλαβεν ἐπὶ τῷ ἀνδρί· ὃν ἀνέθεσαν μὲν οἱ παῖδες ἐς Δελφοὺς οἱ Φηγέως—τρόπον δὲ ὅντινα ἐκτήσαντο αὐτόν, ἐδήλωσεν ἤδη μοι τὰ ἐς Ἀρκάδας ἔχοντα—, ἐσυλήθη δὲ ὑπὸ τυράννων τῶν ἐν Φωκεῦσιν.", "st": "9.41"}, {"sp": "N", "t": "οὐ μὴν παρὰ Ἀμαθουσίοις γε ἐν τῷ ἱερῷ τοῦ Ἀδώνιδος ἐμοὶ δοκεῖν ἐστίν· ἐν Ἀμαθοῦντι μὲν γάρ ἐστι λίθοι χλωροὶ συνδέοντος χρυσοῦ σφᾶς ὁ ὅρμος, τὸν δὲ τῇ Ἐριφύλῃ δοθέντα Ὅμηρός φησιν ἐν Ὀδυσσείᾳ πεποιῆσθαι χρυσοῦ, καὶ οὕτως ἔχει·<br>ἣ χρυσὸν φίλου ἀνδρὸς ἐδέξατο τιμήεντα.", "st": "9.41"}, {"sp": "N", "t": "οὐ μὲν οὐδὲ ἠγνόει τοὺς ὅρμους τοὺς ποικίλους· ἐν μέν γε τοῖς Εὐμαίου λόγοις πρὸς Ὀδυσσέα, πρὶν ἢ ἐκ Πύλου Τηλέμαχον ἀφικέσθαι σφίσιν ἐπὶ τὴν αὐλήν, ἐν τούτοις τοῖς λόγοις ἐστὶν<br>ἤλυθ’ ἀνὴρ πολύιδρις ἐμοῦ πρὸς δώματα πατρός<br>χρύσεον ὅρμον ἔχων, μετὰ δ’ ἠλέκτροισιν ἔερτο,", "st": "9.41"}, {"sp": "N", "t": "καὶ ἐν Πηνελόπης δώροις—ἄλλους τε γὰρ τῶν μνηστήρων δῶρα καὶ Εὐρύμαχον διδόντα Πηνελόπῃ πεποίηκεν—<br>ὅρμον δ’ Εὐρύμαχος πολυδαίδαλον αὐτίκ’ ἔνεικε<br>χρύσεον, ἠλέκτροισιν ἐερμένον, ἠέλιον ὥς·<br>Ἐριφύλην δὲ οὐ χρυσῷ καὶ λίθοις ποικίλον δέξασθαί φησιν ὅρμον. οὕτω τὸ εἰκὸς τῷ σκήπτρῳ πρόσεστιν εἶναι μόνον ποίημα Ἡφαίστου.", "st": "9.41"}, {"sp": "N", "t": "ἔστι δὲ ὑπὲρ τὴν πόλιν κρημνὸς Πετραχὸς καλούμενος· Κρόνον δὲ ἐθέλουσιν ἐνταῦθα ἀπατηθῆναι δεξάμενον ἀντὶ Διὸς πέτρον παρὰ τῆς Ῥέας, καὶ ἄγαλμα Διὸς οὐ μέγα ἐστὶν ἐπὶ κορυφῇ τοῦ ὄρους.", "st": "9.41"}, {"sp": "N", "t": "ἐνταῦθα ἐν τῇ Χαιρωνείᾳ μύρα ἀπὸ ἀνθῶν ἕψουσι κρίνου καὶ ῥόδου καὶ ναρκίσσου καὶ ἴρεως· ταῦτα ἀλγηδόνων ἰάματα ἀνθρώποις γίνεται. τὸ δὲ ἐκ τῶν ῥόδων ποιούμενον, εἰ καὶ ἀγάλματα εἰργασμένα ξύλου χρίοις, ῥύεται καὶ ταῦτα σηπεδόνος. ἡ δὲ ἶρις φύεται μὲν ἐν ἕλεσι, μέγεθος δ’ ἐστὶν ἴση κρίνῳ, χρόαν δὲ οὐ λευκή, καὶ ὀσμὴν ἀποδεῖ κρίνου.", "st": "9.41"}, {"sp": "HDR", "t": "Βιβλίον Ιʹ — Φωκικά, Λοκρῶν Ὀζόλων", "st": "10"}, {"sp": "N", "t": "γῆς δὲ τῆς Φωκίδος, ὅσον μὲν περὶ Τιθορέαν καὶ Δελφούς ἐστιν αὐτῆς, ἐκ παλαιοτάτου φανερὰ τὸ ὄνομα τοῦτο εἰληφυῖά ἐστιν ἀπὸ ἀνδρὸς Κορινθίου Φώκου τοῦ Ὀρνυτίωνος· ἔτεσι δ’ ὕστερον οὐ πολλοῖς ἐξενίκησε καὶ ἁπάσῃ γενέσθαι τῇ ἐφ’ ἡμῶν καλουμένῃ Φωκίδι, Αἰγινητῶν ναυσὶν ἐς τὴν χώραν διαβάντων ὁμοῦ Φώκῳ τῷ Αἰακοῦ.", "st": "10.1"}, {"sp": "N", "t": "τὰ μὲν δὴ ἀπαντικρὺ Πελοποννήσου καὶ τὰ ἐπὶ Βοιωτίας καθήκουσιν ἐπὶ θάλασσαν οἱ Φωκεῖς, τῇ μὲν ἐς Κίρραν τὸ ἐπίνειον Δελφῶν, τῇ δ’ ἐπὶ Ἀντίκυραν πόλιν· τὰ δὲ πρὸς τοῦ Λαμιακοῦ κόλπου Λοκροὶ σφᾶς παραθαλασσίους οἱ Ὑποκνημίδιοι κωλύουσιν εἶναι· οὗτοι γὰρ δή εἰσιν οἱ ταύτῃ τὴν Φωκίδα ὑπεροικοῦντες, Σκαρφεῖς μὲν τὰ ἐπέκεινα Ἐλατείας, ὑπὲρ δὲ Ὑάμπολιν καὶ Ἄβας οἱ πόλιν τε Ὀποῦντα καὶ Ὀπουντίων ἐπίνειον νεμόμενοι Κῦνον.", "st": "10.1"}, {"sp": "N", "t": "τὰ δὲ ἐπιφανέστατα Φωκεῦσίν ἐστιν ἐν κοινῷ· πολέμου γὰρ τοῦ πρὸς Ἰλίῳ μετεσχήκασι, καὶ Θεσσαλῶν ἐναντία ἐπολέμησαν πρότερον ἔτι ἢ ἐλάσαι τὸν Μῆδον ἐπὶ Ἕλληνας, ὅτε δὴ καὶ ἐπεδείξαντο οἱ Φωκεῖς ἔργα ἐς μνήμην. κατὰ γὰρ τὴν Ὑάμπολιν, ᾗ τοὺς Θεσσαλοὺς προσεδέχοντο ἐμβαλεῖν σφισιν ἐς τὴν χώραν, ὑδρίας κεράμου πεποιημένας κατορύξαντες καὶ ἐπ’ αὐτὰς γῆν ἐπιφορήσαντες ὑπέμενον τὴν ἵππον τῶν Θεσσαλῶν· οἱ δέ, ἅτε οὐ προπεπυσμένοι τῶν Φωκέων τὴν τέχνην, ἐπελάσαντες τοὺς ἵππους λανθάνουσιν ἐπὶ τὰς ὑδρίας. ἐνταῦθα ἀπεχωλοῦντο μὲν οἱ ἵπποι τῶν ποδῶν ἐσπιπτόντων σφίσιν ἐς τὰς ὑδρίας, ἐκτείνοντο δὲ καὶ ἀπέπιπτον οἱ ἄνδρες ἀπὸ τῶν ἵππων.", "st": "10.1"}, {"sp": "N", "t": "ὡς δὲ οἱ Θεσσαλοὶ μείζονι ἢ τὰ πρότερα ἐς τοὺς Φωκέας χρώμενοι τῇ ὀργῇ συνελέχθησαν ἀπὸ τῶν πόλεων πασῶν καὶ ἐς τὴν Φωκίδα ἐστρατεύοντο, ἐνταῦθα οἱ Φωκεῖς ἐν οὐ μικρῷ ποιούμενοι δείματι τήν τε ἄλλην τῶν Θεσσαλῶν ἐς τὸν πόλεμον παρασκευὴν καὶ οὐχ ἥκιστα τῆς ἵππου τὸ πλῆθος καὶ ὁμοῦ τῷ ἀριθμῷ τὴν ἐς τοὺς ἀγῶνας τῶν τε ἵππων καὶ αὐτῶν μελέτην τῶν ἱππέων, ἀποστέλλουσιν ἐς Δελφοὺς αἰτοῦντες τὸν θεὸν ἐκφυγεῖν τὸν ἐπιόντα κίνδυνον· καὶ αὐτοῖς ἀφίκετο μάντευμα·<br>συμβαλέω θνητόν τε καὶ ἀθάνατον μαχέσασθαι,<br>νίκην δ’ ἀμφοτέροις δώσω, θνητῷ δέ νυ μᾶλλον.", "st": "10.1"}, {"sp": "N", "t": "ταῦτα ὡς ἐπύθοντο οἱ Φωκεῖς, λογάδας τριακοσίους καὶ Γέλωνα ἐπ’ αὐτοῖς ἄρχοντα ἀποστέλλουσιν ἐς τοὺς πολεμίους ἄρτι ἀρχομένης νυκτός, προστάξαντές σφισι κατοπτεῦσαί τε τὰ τῶν Θεσσαλῶν ὅντινα ἀφανέστατον δύναιντο τρόπον καὶ αὖθις ἐς τὸ στράτευμα ἐπανήκειν κατὰ τῶν ὁδῶν τὴν μάλιστα ἄγνωστον, μηδὲ ἑκόντας μάχης ἄρχειν. οὗτοι ὑπὸ τῶν Θεσσαλῶν οἱ λογάδες ἀπώλοντο ἀθρόοι καὶ αὐτοὶ καὶ ὁ ἡγούμενός σφισι Γέλων, συμπατούμενοί τε ὑπὸ τῶν ἵππων καὶ ὑπὸ τῶν ἀνδρῶν φονευόμενοι.", "st": "10.1"}, {"sp": "N", "t": "καὶ ἡ συμφορὰ σφῶν κατάπληξιν τοῖς ἐπὶ ⟨τοῦ⟩ στρατοπέδου τῶν Φωκέων τηλικαύτην ἐνεποίησεν, ὥστε καὶ τὰς γυναῖκας καὶ παῖδας καὶ ὅσα τῶν κτημάτων ἄγειν ἦν σφίσιν ἢ φέρειν, ἔτι δὲ καὶ ἐσθῆτα καὶ χρυσόν τε καὶ ἄργυρον καὶ τὰ ἀγάλματα τῶν θεῶν ἐς ταὐτὸ συλλέξαντες πυρὰν ὡς μεγίστην ἐποίησαν, καὶ ἐπ’ αὐτοῖς ἀριθμὸν τριάκοντα ἄνδρας ἀπολείπουσι·", "st": "10.1"}, {"sp": "N", "t": "προσετέτακτο δὲ τοῖς ἀνδράσιν, εἰ ἡττᾶσθαι τοὺς Φωκέας συμβαίνοι τῇ μάχῃ, τότε δὴ προαποσφάξαι μὲν τὰς γυναῖκάς τε καὶ παῖδας καὶ ὡς ἱερεῖα ἀναθέντας ταῦτά τε καὶ τὰ χρήματα ἐπὶ τὴν πυρὰν καὶ ἐνέντας πῦρ οὕτως ἤδη διαφθαρῆναι καὶ αὐτοὺς ἤτοι ὑπ’ ἀλλήλων ἢ ἐς τὴν ἵππον τῶν Θεσσαλῶν ἐσπίπτοντας. ἀντὶ τούτου μὲν ἅπαντα τὰ ἀνάλγητα βουλεύματα ἀπόνοια ὑπὸ Ἑλλήνων ὀνομάζεται Φωκική, τότε δὲ οἱ Φωκεῖς ἐποιοῦντο αὐτίκα ἐπὶ τοὺς Θεσσαλοὺς ἔξοδον·", "st": "10.1"}, {"sp": "N", "t": "στρατηγοὶ δὲ ἦσάν σφισι Ῥοῖός τε Ἀμβροσσεὺς καὶ Ὑαμπολίτης Δαϊφάντης, οὗτος μὲν δὴ ἐπὶ τῇ ἵππῳ, δυνάμεως δὲ τῆς πεζῆς ὁ Ἀμβροσσεύς. ὁ δὲ χώραν ⟨ἐν⟩ τοῖς ἄρχουσιν ἔχων τὴν μεγίστην μάντις ἦν ⟨Τελλίας⟩ ὁ Ἠλεῖος, καὶ ἐς τὸν Τελλίαν τοῖς Φωκεῦσι τῆς σωτηρίας ἀπέκειντο αἱ ἐλπίδες.", "st": "10.1"}, {"sp": "N", "t": "ὡς δὲ ἐς χεῖρας συνῄεσαν, ἐνταῦθα τοῖς Φωκεῦσιν ἐγίνετο ἐν ὀφθαλμοῖς τὰ ἐς τὰς γυναῖκας καὶ ἐς τὰ τέκνα δόξαντα, τήν τε σωτηρίαν οὐκ ἐν βεβαίῳ σφίσιν ἑώρων σαλεύουσαν καὶ τούτων ἕνεκα ἐς παντοῖα ἀφικνοῦντο τολμήματα· προσγενομένου δὲ καὶ τοῦ ἐκ θεῶν εὐμενοῦς νίκην τῶν τότε ἀνείλοντο ἐπιφανεστάτην.", "st": "10.1"}, {"sp": "N", "t": "τό τε λόγιον τὸ γεγενημένον τοῖς Φωκεῦσι παρὰ τοῦ Ἀπόλλωνος καὶ τοῖς πᾶσιν Ἕλλησιν ἐγνώσθη· τὸ γὰρ σύνθημα κατὰ τὰ αὐτὰ ὑπὸ τῶν στρατηγούντων ἐδίδοτο ἐν ταῖς μάχαις Θεσσαλοῖς μὲν Ἀθηνᾶς Ἰτωνίας, τοῖς δὲ ὁ ἐπώνυμος Φῶκος. ἀπὸ τούτου δὲ τοῦ ἔργου καὶ ἀναθήματα οἱ Φωκεῖς ἀπέστειλαν ἐς Δελφοὺς Ἀπόλλωνα καὶ Τελλίαν τότε τὸν μάντιν καὶ ὅσοι μαχομένοις ἄλλοι σφίσιν ἐστρατήγησαν, σὺν δὲ αὐτοῖς καὶ ἥρωας τῶν ἐπιχωρίων· ἔργα δὲ αἱ εἰκόνες Ἀριστομέδοντός εἰσιν Ἀργείου.", "st": "10.1"}, {"sp": "N", "t": "εὑρέθη δὲ καὶ ὕστερον τοῖς Φωκεῦσιν οὐκ ἀποδέον σοφίᾳ τῶν προτέρων. ὡς γὰρ δὴ τὰ στρατόπεδα ἀντεκάθητο περὶ τὴν ἐς τὴν Φωκίδα ἐσβολήν, λογάδες Φωκέων πεντακόσιοι φυλάσσοντες πλήρη τὸν κύκλον τῆς σελήνης ἐπιχειροῦσιν ἐν τῇ νυκτὶ τοῖς Θεσσαλοῖς, αὐτοί τε ἀληλιμμένοι γύψῳ καὶ ἐνδεδυκότες ὅπλα λευκὰ ἐπὶ τῇ γύψῳ. ἐνταῦθα ἐξεργασθῆναι φόνον τῶν Θεσσαλῶν λέγεται πλεῖστον, θειότερόν τι ἡγουμένων ἢ κατὰ ἔφοδον πολεμίων τὸ ἐν τῇ νυκτὶ συμβαῖνον. ὁ δὲ Ἠλεῖος ἦν Τελλίας ὃς καὶ ταῦτα τοῖς Φωκεῦσιν ἐμηχανήσατο ἐς τοὺς Θεσσαλούς.", "st": "10.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐς τὴν Εὐρώπην ὁ Περσῶν στρατὸς διέβη, λέγεται τοὺς Φωκέας φρονῆσαι μὲν ὑπὸ ἀνάγκης τὰ βασιλέως, αὐτομολῆσαι δὲ ἐκ τῶν Μήδων καὶ ἐς τὸ Ἑλληνικὸν παρὰ τὸ ἔργον τὸ Πλαταιᾶσι παρατάξασθαι. χρόνῳ δὲ ὕστερον κατέλαβεν αὐτοὺς ζημιωθῆναι χρήμασιν ὑπὸ Ἀμφικτυόνων· οὐδὲ ἔχω τοῦ λόγου τὸ ἀληθὲς ἐξευρεῖν εἴτε ἀδικήσασιν ἐπεβλήθη σφίσιν εἴτε Θεσσαλοὶ κατὰ τὸ ἐκ παλαιοῦ μῖσος γενέσθαι τὴν ζημίαν τοῖς Φωκεῦσιν ἦσαν οἱ πράξαντες.", "st": "10.2"}, {"sp": "N", "t": "ἐχόντων δὲ ἀθύμως αὐτῶν πρὸς τῆς ζημίας τὸ μέγεθος, Φιλόμηλος σφᾶς ὑπολαβὼν ὁ Θεοτίμου, Φωκέων οὐδενὸς ἀξιώματι ὕστερος—πατρὶς δὲ αὐτῷ Λέδων τῶν ἐν Φωκεῦσιν ἦν πόλεων—οὗτος οὖν ὁ Φιλόμηλος τήν τε ἔκτισιν αὐτοῖς ἀδύνατον ἀπέφηνε τῶν χρημάτων καὶ ἀνέπειθε τὸ ἱερὸν καταλαβεῖν τὸ ἐν Δελφοῖς, λέγων καὶ ἄλλα ἐπαγωγὰ καὶ ὡς τὰ Ἀθηναίων καὶ ἐκ Λακεδαίμονος ἐπιτήδεια ἐξ ἀρχῆς ἐστιν αὐτοῖς, Θηβαίων δὲ καὶ εἴ τις ἄλλος κατασταίη σφίσιν ἐς πόλεμον, περιέσεσθαι καὶ ἀρετῇ σφᾶς καὶ δαπάνῃ χρημάτων.", "st": "10.2"}, {"sp": "N", "t": "ταῦτα τοῦ Φιλομήλου λέγοντος οὐκ ἐγίνετο ἀκούσια τῷ πλήθει τῶν Φωκέων, εἴτε τὴν γνώμην σφίσι τοῦ θεοῦ βλάπτοντος εἴτε καὶ αὐτοῖς πεφυκόσιν ἐπίπροσθεν εὐσεβείας τὰ κέρδη ποιεῖσθαι. τὴν δὲ τῶν Δελφῶν κατάληψιν ἐποιήσαντο οἱ Φωκεῖς Ἡρακλείδου μὲν πρυτανεύοντος ἐν Δελφοῖς καὶ Ἀγαθοκλέους Ἀθήνῃσιν ἄρχοντος, τετάρτῳ δὲ ἔτει πέμπτης Ὀλυμπιάδος ἐπὶ ταῖς ἑκατόν, ἣν Πρῶρος ἐνίκα Κυρηναῖος στάδιον.", "st": "10.2"}, {"sp": "N", "t": "καταλαβοῦσι δὲ αὐτοῖς τὸ ἱερὸν ξενικά τε αὐτίκα τὰ ἰσχυρότατα τῶν ἐν Ἕλλησιν ἠθροίσθη καὶ οἱ Θηβαῖοί σφισιν ἐς πόλεμον ἐκ τοῦ φανεροῦ καθεστήκεσαν, διάφοροι καὶ τὰ πρότερα ὄντες. χρόνος μὲν δὴ ἐγένετο ὃν ἐπολέμησαν δέκα ἔτη συνεχῶς, καὶ ἐν τοσούτῳ πολέμου μήκει πολλάκις μὲν οἱ Φωκεῖς καὶ τὰ παρ’ αὐτοῖς ξενικὰ ἐνίκησε, πολλάκις δὲ ἦν τὰ τῶν Θηβαίων ἐπικρατέστερα· γενομένης δὲ κατὰ Νεῶνα πόλιν συμβολῆς ἐτράποντο οἱ Φωκεῖς, καὶ ὁ Φιλόμηλος ῥίπτει τε αὑτὸν ἐν τῇ φυγῇ κατὰ ὑψηλοῦ καὶ ἀποτόμου κρημνοῦ καὶ ἀφίησιν οὕτω τὴν ψυχήν· ἐτέτακτο δὲ καὶ ἄλλως τοῖς Ἀμφικτύοσιν ἐς τοὺς συλῶντας αὕτη ⟨ἡ⟩ δίκη.", "st": "10.2"}, {"sp": "N", "t": "μετὰ δὲ Φιλόμηλον τελευτήσαντα Ὀνομάρχῳ μὲν τὴν ἡγεμονίαν διδόασιν οἱ Φωκεῖς, ἐς δὲ τῶν Θηβαίων τὴν συμμαχίαν προσεχώρησε Φίλιππος ὁ Ἀμύντου· καὶ —ἐκράτησε γὰρ Φίλιππος τῆς συμβολῆς—φεύγων ὁ Ὀνόμαρχος καὶ ἐπὶ θάλασσαν ἀφικόμενος ἐνταῦθα ὑπὸ τῶν στρατιωτῶν κατηκοντίσθη τῶν οἰκείων, ὡς τὴν ἧσσάν σφισιν ὑπὸ ἀτολμίας συμβᾶσαν τῆς ἐκείνου καὶ ἐς τὸ στρατηγεῖν ἀπειρίας.", "st": "10.2"}, {"sp": "N", "t": "Ὀνομάρχῳ μὲν τέλος τοῦ βίου τοιοῦτον ἐπήγαγεν ὁ δαίμων, στρατηγὸν δὲ αὐτοκράτορα εἵλοντο ἀδελφὸν τοῦ Ὀνομάρχου Φάυλον. ⟨λέγουσι δὲ τοῦτον τὸν Φάυλον⟩ παρεληλυθέναι τε δὴ ἄρτι ἐπὶ τῶν Φωκέων τὴν ἀρχὴν καὶ ὄψιν ὀνείρατος ἰδεῖν τοιάνδε. ἐν τοῖς ἀναθήμασι τοῦ Ἀπόλλωνος μίμημα ἦν χαλκοῦν ⟨ἀνδρὸς⟩ χρονιωτέρου, κατερρυηκότος τε ἤδη τὰς σάρκας καὶ τὰ ὀστᾶ ὑπολειπομένου μόνα· ἀνάθημα δὲ ὑπὸ Δελφῶν Ἱπποκράτους ἐλέγετο εἶναι τοῦ ἰατροῦ. τούτῳ δὴ ἑαυτὸν ἐοικέναι τῷ ἀναθήματι ἔδοξεν ὁ Φάυλος· αὐτίκα δὲ ὑπολαβοῦσα αὐτὸν φθοώδης νόσος ἐπετέλει τοῦ ἐνυπνίου τὴν μαντείαν.", "st": "10.2"}, {"sp": "N", "t": "Φαύλου δὲ ἀποθανόντος ἐς Φάλαικον τὸν παῖδα αὐτοῦ περιεχώρησεν ἡ ⟨ἐν⟩ Φωκεῦσι δυναστεία· καὶ ἐπεὶ ἔσχεν ὁ Φάλαικος ⟨αἰτίαν⟩ ἰδίᾳ περιποιεῖσθαι τῶν ἱερῶν χρημάτων, ἐπαύθη τῆς ἀρχῆς. διαβὰς δὲ ναυσὶν ἐς Κρήτην ὁμοῦ Φωκέων τοῖς ᾑρημένοις τὰ ἐκείνου καὶ μοίρᾳ τοῦ ξενικοῦ, Κυδωνίᾳ προσκαθήμενος— οὐ γάρ οἱ διδόναι χρήματα ἐβούλοντο αἰτοῦντι— τῆς στρατιᾶς τὸ πολὺ ἀπόλλυσι καὶ αὐτὸς ἀπώλετο.", "st": "10.2"}, {"sp": "N", "t": "δεκάτῳ δὲ ὕστερον ἔτει μετὰ τὴν τοῦ ἱεροῦ κατάληψιν ἐπέθηκεν ὁ Φίλιππος πέρας τῷ πολέμῳ, Φωκικῷ τε καὶ ἱερῷ κληθέντι τῷ αὐτῷ, Θεοφίλου μὲν Ἀθήνῃσιν ἄρχοντος, ὀγδόης δὲ Ὀλυμπιάδος καὶ ἑκατοστῆς ἔτει πρώτῳ, ἣν Πολυκλῆς ἐνίκα στάδιον Κυρηναῖος. καὶ ἐς ἔδαφος ἁλοῦσαι κατεβλήθησαν τῶν Φωκέων αἱ πόλεις· ἀριθμὸς δὲ ἦν αὐτῶν Λίλαια καὶ Ὑάμπολις καὶ Ἀντίκυρα καὶ Παραποτάμιοι καὶ Πανοπεύς τε καὶ Δαυλίς. τούτων μὲν δὴ ὄνομα ἦν ἐκ παλαιοῦ, καὶ οὐχ ἥκιστα ἐπῶν ἕνεκα τῶν Ὁμήρου·", "st": "10.3"}, {"sp": "N", "t": "τὰς δὲ αὐτῶν ἡ στρατιὰ καταπρήσασα ἡ μετὰ Ξέρξου γνωριμωτέρας ἐς τὸ Ἑλληνικὸν ἐποίησεν, Ἐρωχὸν καὶ Χαράδραν καὶ Ἀμφίκλειαν καὶ Νεῶνας καὶ Τεθρώνιον καὶ Δρυμαίαν. αἱ δὲ ἄλλαι πλήν γε δὴ Ἐλατείας τὰ πρότερα οὐκ ἐπιφανεῖς ἦσαν, Τραχίς τε ἡ Φωκικὴ καὶ Μεδεὼν ὁ Φωκικὸς καὶ Ἐχεδάμεια καὶ Ἄμβροσσος καὶ Λέδων καὶ Φλυγόνιον ἔτι καὶ Στῖρις. τότε δὲ κατεσκάφησάν τε αἱ κατειλεγμέναι καὶ ἐς κώμας πλὴν Ἄβας ᾠκίσθησαν αἱ ἄλλαι· Ἀβαίοις δὲ ἐκτὸς ἀσεβείας ὑπῆρχε καθεστηκέναι, καὶ οὔτε τοῦ ἱεροῦ τῆς καταλήψεως οὔτε τοῦ πολέμου μετεσχήκεσαν.", "st": "10.3"}, {"sp": "N", "t": "ἀφῃρέθησαν δὲ οἱ Φωκεῖς καὶ μετεῖναί σφισιν ἱεροῦ τοῦ ἐν Δελφοῖς καὶ συνόδου τῆς ἐς τὸ Ἑλληνικόν, καὶ τὰς ψήφους αὐτῶν Μακεδόσιν ἔδοσαν οἱ Ἀμφικτύονες. ἀνὰ χρόνον μέντοι τοῖς Φωκεῦσιν αἱ πόλεις ἀνῳκίσθησαν καὶ ἐς τὰς πατρίδας κατήχθησαν ἐκ τῶν κωμῶν, πλὴν εἰ μὴ ἀνοικισθῆναί τινας ἐκώλυσεν ἀσθένειά τε ἡ ἐξ ἀρχῆς καὶ ἡ τῶν χρημάτων ἐν τῷ τότε ἔνδεια· Ἀθηναῖοι δὲ καὶ Θηβαῖοι σφᾶς ἦσαν οἱ κατάγοντες, πρὶν ἢ τὸ ἐν Χαιρωνείᾳ συμβῆναι πταῖσμα Ἕλλησι.", "st": "10.3"}, {"sp": "N", "t": "καὶ ἀγῶνος τοῦ ἐν Χαιρωνείᾳ μετέσχον οἱ Φωκεῖς, καὶ ὕστερον περὶ Λάμιαν καὶ ἐν Κραννῶνι ἐναντία Ἀντιπάτρου καὶ Μακεδόνων ἐμαχέσαντο· Γαλάτας δὲ καὶ τὴν Κελτικὴν στρατιὰν προθυμότατα ἠμύνοντο Ἑλλήνων, θεῷ τε τιμωροῦντες τῷ ἐν Δελφοῖς καὶ ἐς ἀπολογίαν ἅμα ἐμοὶ δοκεῖν τῶν ἀρχαίων ἐγκλημάτων.", "st": "10.3"}, {"sp": "N", "t": "τούτοις μὲν δὴ τοιαῦτα ὑπῆρχεν ἐς μνήμην· στάδια δὲ ἐκ Χαιρωνείας εἴκοσιν ἐς Πανοπέας ἐστὶ πόλιν Φωκέων, εἴγε ὀνομάσαι τις πόλιν καὶ τούτους οἷς γε οὐκ ἀρχεῖα οὐ γυμνάσιόν ἐστιν, οὐ θέατρον οὐκ ἀγορὰν ἔχουσιν, οὐχ ὕδωρ κατερχόμενον ἐς κρήνην, ἀλλὰ ἐν στέγαις κοίλαις κατὰ τὰς καλύβας μάλιστα τὰς ἐν τοῖς ὄρεσιν, ἐνταῦθα οἰκοῦσιν ἐπὶ χαράδρᾳ. ὅμως δὲ ὅροι γε τῆς χώρας εἰσὶν αὐτοῖς ἐς τοὺς ὁμόρους, καὶ ἐς τὸν σύλλογον συνέδρους καὶ οὗτοι πέμπουσι τὸν Φωκικόν. καὶ γενέσθαι μὲν τῇ πόλει τὸ ὄνομα λέγουσιν ἀπὸ τοῦ Ἐπειοῦ πατρός, αὐτοὶ δὲ οὐ Φωκεῖς, Φλεγύαι δὲ εἶναι τὸ ἐξ ἀρχῆς καὶ ἐς τὴν γῆν διαφυγεῖν φασι τὴν Φωκίδα ἐκ τῆς Ὀρχομενίας.", "st": "10.4"}, {"sp": "N", "t": "Πανοπέων δὲ τὸν ἀρχαῖον θεώμενοι περίβολον ἑπτὰ εἶναι σταδίων μάλιστα εἰκάζομεν· ὑπῄει τε ἐπῶν ἡμᾶς τῶν Ὁμήρου μνήμη ὧν ἐποίησεν ἐς Τιτυόν, καλλίχορον τῶν Πανοπέων ὀνομάσας τὴν πόλιν, καὶ ὡς ἐν τῇ μάχῃ τῇ [τε] ἐπὶ τῷ Πατρόκλου νεκρῷ καὶ Σχεδίον τὸν Ἰφίτου βασιλεύοντα Φωκέων καὶ ἀποθανόντα ὑφ’ Ἕκτορος κατοικεῖν εἶπεν ἐν τῷ Πανοπεῖ. τοῦτο μὲν δὴ ἐφαίνετο ἡμῖν ἔχειν αἰτίαν, φόβῳ τῶν Βοιωτῶν —κατὰ γὰρ τοῦτό ἐστιν ἐκ τῆς Βοιωτίας ἡ ἐς τὴν Φωκίδα ἐσβολὴ ῥᾴστη—ἐνταῦθα οἰκεῖν τὸν βασιλέα ἅτε φρουρίῳ τῷ Πανοπεῖ χρώμενον·", "st": "10.4"}, {"sp": "N", "t": "τὸ ἕτερον δὲ οὐκ ἐδυνήθην συμβαλέσθαι πρότερον, ἐφ’ ὅτῳ καλλίχορον τὸν Πανοπέα εἴρηκε, πρὶν ἢ ἐδιδάχθην ὑπὸ τῶν παρ’ Ἀθηναίοις καλουμένων Θυιάδων. αἱ δὲ Θυιάδες γυναῖκες μέν εἰσιν Ἀττικαί, φοιτῶσαι δὲ ἐς τὸν Παρνασσὸν παρὰ ἔτος αὐταί τε καὶ αἱ γυναῖκες Δελφῶν ἄγουσιν ὄργια Διονύσῳ. ταύταις ταῖς Θυιάσι κατὰ τὴν ἐξ Ἀθηνῶν ὁδὸν καὶ ἀλλαχοῦ χοροὺς ἱστάναι καὶ παρὰ τοῖς Πανοπεῦσι καθέστηκε· καὶ ἡ ἐπίκλησις ἡ ἐς τὸν Πανοπέα Ὁμήρου ὑποσημαίνειν τῶν Θυιάδων δοκεῖ τὸν χορόν.", "st": "10.4"}, {"sp": "N", "t": "Πανοπεῦσι δέ ἐστιν ἐπὶ τῇ ὁδῷ πλίνθου τε ὠμῆς οἴκημα οὐ μέγα καὶ ἐν αὐτῷ λίθου τοῦ Πεντελῆσιν ἄγαλμα, ὃν Ἀσκληπιόν, οἱ δὲ Προμηθέα εἶναί φασι· καὶ παρέχονταί γε τοῦ λόγου μαρτύρια. λίθοι κεῖνταί σφισιν ἐπὶ τῇ χαράδρᾳ, μέγεθος μὲν ἑκάτερος ὡς φόρτον ἀποχρῶντα ἁμάξης εἶναι, χρῶμα δέ ἐστι πηλοῦ σφισιν, οὐ γεώδους ἀλλ’ οἷος ἂν χαράδρας γένοιτο ἢ χειμάρρου ψαμμώδους, παρέχονται δὲ καὶ ὀσμὴν ἐγγύτατα χρωτὶ ἀνθρώπου· ταῦτα ἔτι λείπεσθαι τοῦ πηλοῦ λέγουσιν ἐξ οὗ καὶ ἅπαν ὑπὸ τοῦ Προμηθέως τὸ γένος πλασθῆναι τῶν ἀνθρώπων.", "st": "10.4"}, {"sp": "N", "t": "ἐνταῦθα ἐπὶ τῇ χαράδρᾳ καὶ Τιτυοῦ μνῆμά ἐστι· περίοδος μὲν τοῦ χώματος τρίτον μάλιστά που σταδίου, τὸ δὲ ἔπος τὸ ἐν Ὀδυσσείᾳ<br>κείμενον ἐν δαπέδῳ· ὁ δ’ ἐπ’ ἐννέα κεῖτο πέλεθρα<br>οὐκ ἐπὶ μεγέθει πεποιῆσθαι τοῦ Τιτυοῦ φασιν, ἀλλ’ ἔνθα ὁ Τιτυὸς ἐτέθη, Πλέθρα ἐννέα ⟨ὄνομα⟩ εἶναι τῷ χωρίῳ.", "st": "10.4"}, {"sp": "N", "t": "Κλέων δὲ ἀνὴρ Μάγνης, οἳ τῷ Ἕρμῳ προσοικοῦσιν, ἔφασκεν ἐς τὰ παράδοξα ἀπίστους εἶναι τῶν ἀνθρώπων οἷς ἂν μὴ παρὰ τὸν αὐτῶν γένηται βίον θεάμασιν ἐπιτυχεῖν λόγου μείζοσιν· αὐτὸς δὲ καὶ Τιτυὸν καὶ ἄλλους ἔφη πείθεσθαι γεγονέναι κατὰ τὴν φήμην· τυχεῖν γὰρ δὴ ὢν ⟨ἐν⟩ Γαδείροις, καὶ ἐκπλεῦσαι μὲν αὐτός τε καὶ τὸν ἄλλον πάντα ὄχλον ἐκ τῆς νήσου κατὰ τὸ Ἡρακλέους πρόσταγμα, ὡς δὲ αὖθις ἐπανήκειν ἐς τὰ Γάδειρα, ἄνδρα εὑρεῖν θαλάσσιον ἐκπεπτωκότα ἐς τὴν γῆν· τοῦτον πλέθρα μὲν πέντε μάλιστα ἐπέχειν, κεραυνωθέντα δὲ ὑπὸ τοῦ θεοῦ καίεσθαι.", "st": "10.4"}, {"sp": "N", "t": "οὗτος μὲν δὴ ταῦτα ἔλεγεν, Πανοπέως δὲ ὅσον στάδια ⟨εἴκοσι καὶ⟩ ἑπτὰ ἀπέχει Δαυλίς. οἱ δὲ ἐνταῦθα ἄνθρωποι πλῆθος μέν εἰσιν οὐ πολλοί, μεγέθει δὲ καὶ ἀλκῇ καὶ ἐς ἐμὲ ἔτι δοκιμώτατοι Φωκέων. τὸ δὲ ὄνομα τῇ πόλει τεθῆναι λέγουσιν ἀπὸ Δαυλίδος νύμφης, θυγατέρα δὲ εἶναι τοῦ Κηφισοῦ τὴν Δαυλίδα. τοῖς δέ ἐστιν εἰρημένον ὡς τὸ χωρίον, ἔνθα ἡ πόλις ᾠκίσθη, παρείχετο συνεχῆ δένδρα, καλεῖσθαι δὲ τὰ δασέα ὑπὸ τῶν πάλαι δαῦλα· ἐπὶ τούτῳ δὲ καὶ Αἰσχύλον τὰ Γλαύκου τοῦ Ἀνθηδονίου γένεια ὑπήνην ὠνομακέναι δαῦλον.", "st": "10.4"}, {"sp": "N", "t": "ἐνταῦθα ἐν τῇ Δαυλίδι παραθεῖναι τῷ Τηρεῖ τὸν παῖδα αἱ γυναῖκες λέγονται, καὶ ἀνθρώποις τῶν ἐπὶ τραπέζῃ μιασμάτων τοῦτο ἦρξεν. ὁ δὲ ἔποψ ἐς ὃν ἔχει λόγος τὸν Τηρέα ἀλλαγῆναι, οὗτος ὁ ὄρνις μέγεθος μὲν ὀλίγον ἐστὶν ὑπὲρ ὄρτυγα, ἐπὶ τῇ κεφαλῇ δέ οἱ τὰ πτερὰ ἐς λόφου σχῆμα ἐξῆρται.", "st": "10.4"}, {"sp": "N", "t": "θαυμάσαι δὲ ἄξιον ὅτι ἐν τῇ γῇ ταύτῃ χελιδόνες οὔτε τίκτουσιν οὔτε ἐκλέπουσί γε τὰ ᾠά, οὐδ’ ἂν ἀρχὴν πρὸς οἰκήματος ὀρόφῳ νεοσσιὰν χελιδὼν ποιήσαιτο· λέγουσι δὲ οἱ Φωκεῖς ὡς τῇ Φιλομήλᾳ καὶ ὄρνιθι οὔσῃ Τηρέως δεῖμα ⟨ἐφάνη⟩ καὶ ⟨οὕτω⟩ τῆς πατρίδος ἀπέστη τῆς Τηρέως. Δαυλιεῦσι δὲ Ἀθηνᾶς ἱερὸν καὶ ἄγαλμά ἐστιν ἀρχαῖον· τὸ δὲ ξόανον τὸ ἔτι παλαιότερον λέγουσιν ἐπαγαγέσθαι Πρόκνην ἐξ Ἀθηνῶν.", "st": "10.4"}, {"sp": "N", "t": "ἔστι δὲ τῆς Δαυλίας χώρα καλουμένη Τρωνίς· ἐνταῦθα ἡρῷον ἥρω Ἀρχηγέτου πεποίηται· τὸν δὲ ἥρω τοῦτον Ξάνθιππον οὐκ ἀφανῆ τὰ ἐς πόλεμον, οἱ δὲ Φῶκον εἶναι τὸν Ὀρνυτίωνος τοῦ Σισύφου φασίν. ἔχει δ’ οὖν ἐπὶ ἡμέρᾳ τε πάσῃ τιμὰς καὶ ἄγοντες ἱερεῖα οἱ Φωκεῖς τὸ μὲν αἷμα δι’ ὀπῆς ἐσχέουσιν ἐς τὸν τάφον, τὰ δὲ κρέα ταύτῃ σφίσιν ἀναλοῦν καθέστηκεν.", "st": "10.4"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄνοδος διὰ τῆς Δαυλίδος ἐς τὰ ἄκρα τοῦ Παρνασσοῦ μακροτέρα τῆς ἐκ Δελφῶν, οὐ μέντοι καὶ κατὰ ταὐτὰ χαλεπή. ἐς δὲ τὴν ἐπὶ Δελφῶν εὐθεῖαν ἀναστρέψαντι ἐκ Δαυλίδος καὶ ἰόντι ἐπὶ τὸ πρόσω, ἔστιν οἰκοδόμημα ἐν ἀριστερᾷ τῆς ὁδοῦ καλούμενον Φωκικόν, ἐς ὃ ἀπὸ ἑκάστης πόλεως συνίασιν οἱ Φωκεῖς.", "st": "10.5"}, {"sp": "N", "t": "μεγέθει μὲν μέγα τὸ οἴκημα, ἐντὸς δὲ αὐτοῦ κίονες κατὰ μῆκός εἰσιν ἑστηκότες· ἀναβασμοὶ δὲ ἀπὸ τῶν κιόνων ἀνήκουσιν ἐς ἑκάτερον τοῖχον, καὶ ἐπὶ τῶν ἀναβασμῶν τούτων οἱ συνιόντες τῶν Φωκέων καθέζονται. πρὸς δὲ τῷ πέρατι κίονες μὲν οὐκ εἰσὶν οὐδὲ ἀναβασμοί, Διὸς δὲ ἄγαλμα καὶ Ἀθηνᾶς καὶ Ἥρας, τὸ μὲν ἐν θρόνῳ τοῦ Διός, ἑκατέρωθεν δὲ ἡ μὲν κατὰ δεξιά, ἡ δὲ ⟨κατὰ⟩ ἀριστερὰ παρεστῶσα ⟨ἡ⟩ Ἀθηνᾶ πεποίηται.", "st": "10.5"}, {"sp": "N", "t": "προϊὼν δὲ αὐτόθεν ἐπὶ ὁδὸν ἀφίξῃ καλουμένην Σχιστήν· ἐπ’ αὐτῇ τῇ ὁδῷ τὰ ἐς τὸν φόνον τοῦ πατρὸς Οἰδίποδι εἰργάσθη. ἔδει δὲ ἄρα παθημάτων τῶν Οἰδίποδος ἀνὰ πᾶσαν τὴν Ἑλλάδα ὑπολειφθῆναι μνημόσυνα. τεχθέντος μέν γε διαπείραντες διὰ τῶν σφυρῶν κέντρα ἐκτιθέασιν αὐτὸν ἐς τὴν Πλαταιίδα, ὄρος τὸν Κιθαιρῶνα· Κόρινθος δὲ καὶ ἡ ἐπὶ τῷ ἰσθμῷ χώρα τροφὸς τῷ Οἰδίποδι ἐγένετο· γῆ δὲ ἡ Φωκὶς καὶ ὁδὸς ἡ Σχιστὴ τοῦ πατρῴου φόνου τὸ μίασμα ὑπεδέξατο· Θηβαίοις δὲ καὶ ἐς πλέον γάμων τέ σφισι τῶν Οἰδίποδος καὶ ἀδικίας τῆς Ἐτεοκλέους ἐστὶν ἡ φήμη.", "st": "10.5"}, {"sp": "N", "t": "Οἰδίποδι μὲν ὁδὸς ἡ Σχιστὴ καὶ τόλμημα τὸ ἐπ’ αὐτῇ κακῶν ἦρχε, καὶ τὰ τοῦ Λαΐου μνήματα καὶ οἰκέτου τοῦ ἑπομένου ταὐτὰ ἔτι ἐν μεσαιτάτῳ τῆς τριόδου ⟨ἐστὶ⟩ καὶ ἐπ’ αὐτῷ λίθοι λογάδες σεσωρευμένοι· Δαμασίστρατον δὲ ἄνδρα ἐν Πλαταιαῖς βασιλεύοντα ἐπιτυχεῖν τε κειμένοις τοῖς νεκροῖς καὶ θάψαι φασὶν αὐτούς.", "st": "10.5"}, {"sp": "N", "t": "ἡ δὲ λεωφόρος αὐτόθεν ἡ ἐς Δελφοὺς καὶ προσάντης γίνεται μᾶλλον καὶ ἀνδρὶ εὐζώνῳ χαλεπωτέρα. λέγεται δὲ πολλὰ μὲν καὶ διάφορα ἐς αὐτοὺς τοὺς Δελφούς, πλείω δὲ ἔτι ἐς τοῦ Ἀπόλλωνος τὸ μαντεῖον. φασὶ γὰρ δὴ τὰ ἀρχαιότατα Γῆς εἶναι τὸ χρηστήριον, καὶ Δαφνίδα ἐπ’ αὐτῷ τετάχθαι πρόμαντιν ὑπὸ τῆς Γῆς·", "st": "10.5"}, {"sp": "N", "t": "εἶναι δὲ αὐτὴν τῶν περὶ τὸ ὄρος νυμφῶν. ἔστι δὲ ἐν Ἕλλησι ποίησις, ὄνομα μὲν τοῖς ἔπεσίν ἐστιν Εὐμολπία, Μουσαίῳ δὲ τῷ Ἀντιοφήμου προσποιοῦσι τὰ ἔπη· πεποιημένον οὖν ἐστιν ἐν τούτοις Ποσειδῶνος ἐν κοινῷ καὶ Γῆς εἶναι τὸ μαντεῖον, καὶ τὴν μὲν χρᾶν αὐτήν, Ποσειδῶνι δὲ ὑπηρέτην ἐς τὰ μαντεύματα εἶναι Πύρκωνα. καὶ οὕτως ἔχει τὰ ἔπη·<br>αὐτίκα δὲ Χθονίης φωνὴ πινυτὸν φάτο μῦθον,<br>σὺν δὲ τε Πύρκων ἀμφίπολος κλυτοῦ Ἐννοσιγαίου.<br>χρόνῳ δὲ ὕστερον, ὅσον τῇ Γῇ μετῆν, δοθῆναι Θέμιδι ὑπ’ αὐτῆς λέγουσιν, Ἀπόλλωνα δὲ παρὰ Θέμιδος λαβεῖν δωρεάν· Ποσειδῶνι δὲ ἀντὶ τοῦ μαντείου Καλαύρειαν ἀντιδοῦναί φασιν αὐτὸν τὴν πρὸ Τροιζῆνος.", "st": "10.5"}, {"sp": "N", "t": "ἤκουσα δὲ καὶ ὡς ἄνδρες ποιμαίνοντες ἐπιτύχοιεν τῷ μαντείῳ, καὶ ἔνθεοί τε ἐγένοντο ὑπὸ τοῦ ἀτμοῦ καὶ ἐμαντεύσαντο ἐξ Ἀπόλλωνος. μεγίστη δὲ καὶ παρὰ πλείστων ἐς Φημονόην δόξα ἐστίν, ὡς πρόμαντις γένοιτο ἡ Φημονόη τοῦ θεοῦ πρώτη καὶ πρώτη τὸ ἑξάμετρον ᾖσεν. Βοιὼ δὲ ἐπιχωρία γυνὴ ποιήσασα ὕμνον Δελφοῖς ἔφη κατασκευάσασθαι τὸ μαντεῖον τῷ θεῷ τοὺς ἀφικομένους ἐξ Ὑπερβορέων τούς τε ἄλλους καὶ Ὠλῆνα· τοῦτον δὲ καὶ μαντεύσασθαι πρῶτον καὶ ᾄσαι πρῶτον τὸ ἑξάμετρον.", "st": "10.5"}, {"sp": "N", "t": "πεποίηκε δὲ ἡ Βοιὼ τοιάδε·<br>ἔνθα τοι εὔμνηστον χρηστήριον ἐκτελέσαντο<br>παῖδες Ὑπερβορέων Παγασὸς καὶ δῖος Ἀγυιεύς.<br>ἐπαριθμοῦσα δὲ καὶ ἄλλους τῶν Ὑπερβορέων, ἐπὶ τελευτῇ τοῦ ὕμνου τὸν Ὠλῆνα ὠνόμασεν·<br>Ὠλήν θ’, ὃς γένετο πρῶτος Φοίβοιο προφάτας,<br>πρῶτος δ’ ἀρχαίων ἐπέων τεκτάνατ’ ἀοιδάν.<br>οὐ μέντοι τά γε ἥκοντα ἐς μνήμην ἐς ἄλλον τινά, ἐς δὲ γυναικῶν μαντείαν ἀνήκει μόνων.", "st": "10.5"}, {"sp": "N", "t": "ποιηθῆναι δὲ τὸν ναὸν τῷ Ἀπόλλωνι τὸ ἀρχαιότατον δάφνης φασί, κομισθῆναι δὲ τοὺς κλάδους ἀπὸ τῆς δάφνης τῆς ἐν τοῖς Τέμπεσι· καλύβης δ’ ἂν σχῆμα οὗτός γε ἂν εἴη παρεσχηματισμένος ὁ ναός. δεύτερα δὲ λέγουσιν οἱ Δελφοὶ γενέσθαι ὑπὸ μελισσῶν τὸν ναὸν ἀπό τε τοῦ κηροῦ τῶν μελισσῶν καὶ ἐκ πτερῶν· πεμφθῆναι δὲ ἐς Ὑπερβορέους φασὶν αὐτὸν ὑπὸ τοῦ Ἀπόλλωνος.", "st": "10.5"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἕτερος λόγος, ὡς τὸν ναὸν κατεσκευάσατο ἀνὴρ Δελφός, ὄνομα δὲ αὐτῷ Πτερᾶν εἶναι· κατὰ τοῦτο οὖν γενέσθαι καὶ τῷ ναῷ τοὔνομα ἀπὸ τοῦ οἰκοδομήσαντος· ἀπὸ τούτου δὲ τοῦ Πτερᾶ καὶ πόλιν Κρητικὴν προσθήκῃ γράμματος Ἀπτερεούς φασιν ὀνομάζεσθαι. τὸν γὰρ δὴ λόγον τὸν ἔχοντα ἐς τὴν ἐν τοῖς ὄρεσιν αὐξομένην πτέριν, ὡς ἐκ τῆς πόας ταύτης χλωρᾶς ἔτι διεπλέξαντο ναόν, οὐδὲ ἀρχὴν προσίεμαι τὸν λόγον τοῦτον.", "st": "10.5"}, {"sp": "N", "t": "τὰ δὲ ἐς τὸν τρίτον τῶν ναῶν, ὅτι ἐγένετο ἐκ χαλκοῦ, θαῦμα οὐδέν, εἴ γε Ἀκρίσιος μὲν θάλαμον χαλκοῦν τῇ θυγατρὶ ἐποιήσατο, Λακεδαιμονίοις δὲ Ἀθηνᾶς ἱερὸν Χαλκιοίκου καὶ ἐς ἡμᾶς ἔτι λείπεται, Ῥωμαίοις δὲ ἡ ἀγορὰ μεγέθους ἕνεκα καὶ κατασκευῆς τῆς ἄλλης θαῦμα οὖσα παρέχεται τὸν ὄροφον χαλκοῦν· οὕτω καὶ ναὸν τῷ Ἀπόλλωνι οὐκ ἂν ἄπο γε τοῦ εἰκότος εἴη γενέσθαι χαλκοῦν.", "st": "10.5"}, {"sp": "N", "t": "τὰ μέντοι ἄλλα με οὐκ ἔπειθεν ὁ λόγος ἢ Ἡφαίστου τὸν ναὸν τέχνην εἶναι ἢ τὰ ἐς τὰς ᾠδοὺς τὰς χρυσᾶς, ἃ δὴ Πίνδαρος ᾖσεν ἐπ’ ἐκείνῳ τῷ ναῷ·<br>χρύσειαι δ’ ἐξύπερθ’ αἰετοῦ<br>ἄειδον Κηληδόνες.<br>οὗτος μὲν δὴ ταῦτα ἐς μίμησιν ἐμοὶ δοκεῖν τῶν παρ’ Ὁμήρῳ Σειρήνων ἐποίησεν· οὐ μὴν οὐδὲ τρόπον ὅντινα ἀφανισθῆναι συνέπεσε τῷ ναῷ, κατὰ ταὐτὰ εἰρημένα εὕρισκον· καὶ γὰρ ἐς χάσμα γῆς ἐμπεσεῖν αὐτὸν καὶ ὑπὸ πυρὸς τακῆναι λέγουσιν.", "st": "10.5"}, {"sp": "N", "t": "τέταρτος δὲ ὑπὸ Τροφωνίου μὲν εἰργάσθη καὶ Ἀγαμήδους, λίθου δὲ αὐτὸν ποιηθῆναι μνημονεύουσι· κατεκαύθη δὲ Ἐρξικλείδου μὲν Ἀθήνῃσιν ἄρχοντος, πρώτῳ δὲ τῆς ὀγδόης Ὀλυμπιάδος ἔτει καὶ πεντηκοστῆς, ἣν Κροτωνιάτης ἐνίκα Διόγνητος. τὸν δ’ ἐφ’ ἡμῶν τῷ θεῷ ναὸν ᾠκοδόμησαν μὲν ἀπὸ τῶν ἱερῶν οἱ Ἀμφικτύονες χρημάτων, ἀρχιτέκτων δέ τις Σπίνθαρος ἐγένετο αὐτοῦ Κορίνθιος.", "st": "10.5"}, {"sp": "N", "t": "πόλιν δὲ ἀρχαιοτάτην οἰκισθῆναί φασιν ἐνταῦθα ὑπὸ Παρνασσοῦ, Κλεοδώρας δὲ εἶναι νύμφης παῖδα αὐτόν· καί οἱ πατέρας, καθάπερ γε καὶ ἄλλοις τῶν καλουμένων ἡρώων, Ποσειδῶνά τε θεὸν καὶ Κλεόπομπον ἄνδρα ἐπονομάζουσιν. ἀπὸ τούτου δὲ τοῦ Παρνασσοῦ τῷ τε ὄρει τὸ ὄνομα τεθῆναι λέγουσι καὶ [ἀπὸ τούτου] Παρνασσίαν ὀνομασθῆναι νάπην· τῶν πετομένων τε ὀρνίθων … τὴν ἀπ’ αὐτῶν μαντείαν γενέσθαι Παρνασσοῦ τὸ εὕρημα.", "st": "10.6"}, {"sp": "N", "t": "ταύτην μὲν οὖν κατακλυσθῆναι τὴν πόλιν ὑπὸ τῶν ὄμβρων τῶν κατὰ Δευκαλίωνα συμβάντων· τῶν δὲ ἀνθρώπων ὅσοι διαφυγεῖν τὸν χειμῶνα ἠδυνήθησαν, λύκων ὠρυγαῖς ἀπεσώθησαν ἐς τοῦ Παρνασσοῦ τὰ ἄκρα ὑπὸ ἡγεμόσι τῆς πορείας τοῖς θηρίοις, πόλιν δὲ ἣν ἔκτισαν ἐκάλεσαν ἐπὶ τούτῳ Λυκώρειαν.", "st": "10.6"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἄλλος διάφορος λόγος τῷ προτέρῳ, Ἀπόλλωνι ἐκ νύμφης Κωρυκίας γενέσθαι Λύκωρον, καὶ ἀπὸ μὲν Λυκώρου πόλιν Λυκώρειαν, τὸ ἄντρον δὲ ὀνομασθῆναι τὸ Κωρύκιον ἀπὸ τῆς νύμφης. λέγεται δὲ καὶ τάδε, Κελαινὼ θυγατέρα Ὑάμῳ τῷ Λυκώρου γενέσθαι, Δελφὸν δέ, ἀφ’ οὗ τῇ πόλει τὸ ὄνομα τὸ ἐφ’ ἡμῶν ἐστι, Κελαινοῦς τε αὐτὸν τῆς Ὑάμου καὶ Ἀπόλλωνος εἶναι.", "st": "10.6"}, {"sp": "N", "t": "οἱ δὲ Καστάλιόν τε ἄνδρα αὐτόχθονα καὶ θυγατέρα ἐθέλουσιν αὐτῷ γενέσθαι Θυίαν, καὶ ἱερᾶσθαί τε τὴν Θυίαν Διονύσῳ πρῶτον καὶ ὄργια ἀγαγεῖν τῷ θεῷ· ἀπὸ ταύτης δὲ καὶ ὕστερον ὅσαι τῷ Διονύσῳ μαίνονται Θυιάδας καλεῖσθαι σφᾶς ὑπὸ ἀνθρώπων· Ἀπόλλωνος δ’ οὖν παῖδα καὶ Θυίας νομίζουσιν εἶναι Δελφόν. οἱ δὲ μητρὸς [μὲν] Μελαίνης φασὶν αὐτόν, θυγατρὸς Κηφισοῦ.", "st": "10.6"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον καὶ Πυθὼ τὴν πόλιν, οὐ Δελφοὺς μόνον ἐκάλεσαν οἱ περιοικοῦντες, καθὰ καὶ Ὁμήρῳ πεποιημένα ἐν καταλόγῳ Φωκέων ἐστίν. οἱ μὲν δὴ γενεαλογεῖν τὰ πάντα ἐθέλοντες παῖδα εἶναι Δελφοῦ Πύθην καὶ ἀπὸ τούτου βασιλεύσαντος γενέσθαι τῇ πόλει τὸ ὄνομα ἥγηνται· λόγος δὲ ὃς ἥκει τῶν ἀνθρώπων ἐς τοὺς πολλούς, τὸν ὑπὸ τοῦ Ἀπόλλωνος τοξευθέντα σήπεσθαί φησιν ἐνταῦθα, καὶ διὰ τοῦτο ὄνομα τῇ πόλει γενέσθαι Πυθώ· πύθεσθαι γὰρ δὴ τὰ σηπόμενα οἱ τότε ἔλεγον, καὶ τοῦδε ἕνεκα Ὅμηρος πεποίηκεν ὡς ἡ τῶν Σειρήνων νῆσος ἀνάπλεως ὀστῶν εἴη, ὅτι οἱ τῆς ᾠδῆς αὐτῶν ἀκούοντες ἐπύθοντο ἄνθρωποι.", "st": "10.6"}, {"sp": "N", "t": "τὸν δὲ ἀποθανόντα ὑπὸ τοῦ Ἀπόλλωνος ποιηταὶ μὲν δράκοντα εἶναι καὶ ἐπὶ τῷ μαντείῳ φύλακα ὑπὸ Γῆς τετάχθαι φασί· λέγεται δὲ καὶ ὡς Κριοῦ δυναστεύοντος ἀνδρὸς περὶ Εὔβοιαν παῖς γένοιτο ὑβριστής, καὶ ἐσύλησε μὲν τοῦ θεοῦ τὸ ἱερόν, ἐσύλησε δὲ καὶ οἴκους ἀνδρῶν εὐδαιμόνων. ὡς δὲ ἐπεστράτευε καὶ δεύτερον, ἐνταῦθα οἱ Δελφοὶ τὸν Ἀπόλλωνα ἱκέτευον ἀμῦναί σφισι τὸν ἐπιόντα κίνδυνον·", "st": "10.6"}, {"sp": "N", "t": "καὶ ἡ Φημονόη πρόμαντις τηνικαῦτα οὖσα ἐν ἑξαμέτρῳ σφίσιν ἔχρησεν·<br>ἀγχοῦ δὴ βαρὺν ἰὸν ἐπ’ ἀνέρι Φοῖβος ἐφήσει<br>σίντῃ Παρνησσοῖο· φόνου δέ ἑ Κρήσιοι ἄνδρες<br>χεῖρας ἁγιστεύ⟨σ⟩ουσι· τὸ δὲ κλέος οὔ ποτ’ ὀλεῖται.", "st": "10.6"}, {"sp": "N", "t": "ἔοικε δὲ ἐξ ἀρχῆς τὸ ἱερὸν τὸ ἐν Δελφοῖς ὑπὸ ἀνθρώπων ἐπιβεβουλεῦσθαι πλείστων ἤδη. οὗτός τε ὁ Εὐβοεὺς λῃστὴς καὶ ἔτεσιν ὕστερον τὸ ἔθνος τὸ Φλεγυῶν, ἔτι δὲ Πύρρος ὁ Ἀχιλλέως ἐπεχείρησεν αὐτῷ, καὶ δυνάμεως μοῖρα τῆς Ξέρξου, καὶ οἱ χρόνον τε ἐπὶ πλεῖστον καὶ μάλιστα τοῦ θεοῦ τοῖς χρήμασιν ἐπελθόντες οἱ ἐν Φωκεῦσι δυνάσται, καὶ ἡ Γαλατῶν στρατιά. ἔμελλε δὲ ἄρα οὐδὲ τῆς Νέρωνος ἐς πάντα ὀλιγωρίας ἀπειράτως ἕξειν, ὃς τὸν Ἀπόλλωνα πεντακοσίας θεῶν τε ἀναμὶξ ἀφείλετο καὶ ἀνθρώπων εἰκόνας χαλκᾶς.", "st": "10.7"}, {"sp": "N", "t": "ἀρχαιότατον δὲ ἀγώνισμα γενέσθαι μνημονεύουσι καὶ ἐφ’ ᾧ πρῶτον ἆθλα ἔθεσαν, ᾆσαι ὕμνον ἐς τὸν θεόν· καὶ ᾖσε καὶ ἐνίκησεν ᾄδων Χρυσόθεμις ἐκ Κρήτης, οὗ δὴ ὁ πατὴρ λέγεται Καρμάνωρ καθῆραι Ἀπόλλωνα. Χρυσοθέμιδος δὲ ὕστερον Φιλάμμωνά τε ᾠδῇ μνημονεύουσι νικῆσαι καὶ ἐπ’ ἐκείνῳ Θάμυριν τὸν Φιλάμμωνος. Ὀρφέα δὲ σεμνολογίᾳ τῇ ἐπὶ τελεταῖς καὶ ὑπὸ φρονήματος τοῦ ἄλλου καὶ Μουσαῖον τῇ ἐς πάντα μιμήσει τοῦ Ὀρφέως οὐκ ἐθελῆσαί φασιν αὐτοὺς ἐπὶ ἀγῶνι μουσικῆς ἐξετάζεσθαι.", "st": "10.7"}, {"sp": "N", "t": "φασὶ δὲ καὶ Ἐλευθῆρα ἀνελέσθαι Πυθικὴν νίκην μέγα καὶ ἡδὺ φωνοῦντα, ἐπεὶ ᾄδειν γε αὐτὸν οὐχ αὑτοῦ τὴν ᾠδήν. λέγεται δὲ καὶ Ἡσίοδον ἀπελαθῆναι τοῦ ἀγωνίσματος ἅτε οὐ κιθαρίζειν ὁμοῦ τῇ ᾠδῇ δεδιδαγμένον. Ὅμηρος δὲ ἀφίκετο μὲν ἐς Δελφοὺς ἐρησόμενος ὁπόσα καὶ ἐδεῖτο, ἔμελλε δὲ αὐτῷ καὶ κιθαρίζειν διδαχθέντι ἀχρεῖον τὸ μάθημα ὑπὸ τῶν ὀφθαλμῶν τῆς συμφορᾶς γενήσεσθαι.", "st": "10.7"}, {"sp": "N", "t": "τῆς δὲ τεσσαρακοστῆς Ὀλυμπιάδος καὶ ὀγδόης, ἣν Γλαυκίας ὁ Κροτωνιάτης ἐνίκησε, ταύτης ἔτει τρίτῳ ἆθλα ἔθεσαν οἱ Ἀμφικτύονες κιθαρῳδίας μὲν καθὰ καὶ ἐξ ἀρχῆς, προσέθεσαν δὲ καὶ αὐλῳδίας ἀγώνισμα καὶ αὐλῶν· ἀνηγορεύθησαν δὲ νικῶντες Κεφαλήν τε Μελάμπους κιθαρῳδίᾳ καὶ αὐλῳδὸς Ἀρκὰς Ἐχέμβροτος, Σακάδας δὲ Ἀργεῖος ἐπὶ τοῖς αὐλοῖς· ἀνείλετο δὲ ὁ Σακάδας οὗτος καὶ ἄλλας δύο τὰς ἐφεξῆς ταύτης πυθιάδας.", "st": "10.7"}, {"sp": "N", "t": "ἔθεσαν δὲ καὶ ἆθλα τότε ἀθληταῖς πρῶτον, τά τε ἐν Ὀλυμπίᾳ πλὴν τεθρίππου καὶ αὐτοὶ νομοθετήσαντες δολίχου καὶ διαύλου παισὶν εἶναι δρόμον. δευτέρᾳ δὲ πυθιάδι οὐκ ἐπὶ ἄθλοις ἐκάλεσαν ἔτι ἀγωνίζεσθαι, στεφανίτην δὲ τὸν ἀγῶνα ἀπὸ τούτου κατεστήσαντο· καὶ αὐλῳδίαν ⟨τό⟩τε κατέλυσαν, καταγνόντες οὐκ εἶναι τὸ ἄκουσμα εὔφημον· ἡ γὰρ αὐλῳδία μέλη τε ἦν αὐλῶν τὰ σκυθρωπότατα καὶ ἐλεγεῖα [θρῆνοι] προσᾳδόμενα τοῖς αὐλοῖς.", "st": "10.7"}, {"sp": "N", "t": "μαρτυρεῖ δέ μοι καὶ τοῦ Ἐχεμβρότου τὸ ἀνάθημα, τρίπους χαλκοῦς ἀνατεθεὶς τῷ Ἡρακλεῖ τῷ ἐν Θήβαις· ἐπίγραμμα δὲ ὁ τρίπους εἶχεν·<br>Ἐχέμβροτος Ἀρκὰς θῆκε τῷ Ἡρακλεῖ<br>νικήσας τόδ’ ἄγαλμ’ Ἀμφικτυόνων ἐν ἀέθλοις,<br>Ἕλλησι δ’ ἀείδων μέλεα καὶ ἐλέγους.<br>κατὰ τοῦτο μὲν τῆς αὐλῳδίας ἐπαύσθη τὸ ἀγώνισμα· προσέθεσαν δὲ καὶ ἵππων δρόμον, ἀνηγορεύθη δὲ ἐπὶ τῷ ἅρματι Κλεισθένης ὁ Σικυῶνος τυραννήσας.", "st": "10.7"}, {"sp": "N", "t": "ὀγδόῃ δὲ πυθιάδι προσενομοθέτησαν κιθαριστὰς τοὺς ἐπὶ τῶν κρουμάτων τῶν ἀφώνων· καὶ Τεγεάτης ἐστεφανοῦτο Ἀγέλαος. τρίτῃ δὲ πυθιάδι ἐπὶ ταῖς εἴκοσι προστιθέασιν ὁπλίτην δρόμον· καὶ ἐπ’ αὐτῷ Τιμαίνετος ἐκ Φλιοῦντος ἀνείλετο τὴν δάφνην, Ὀλυμπιάσιν ὕστερον πέντε ἢ Δαμάρετος Ἡραιεὺς ἐνίκησεν. ὀγδόῃ δὲ ἐπὶ τεσσαράκοντα πυθιάδι καὶ συνωρίδος εἶναι κατεστήσαντο δρόμον· καὶ Ἐξηκεστίδου Φωκέως ἐνίκησεν ἡ συνωρίς. πέμπτῃ δὲ πυθιάδι ἀπὸ ταύτης πώλους ἔζευξαν ὑπὸ ἅρματι· καὶ παρέδραμεν Ὀρφώνδα Θηβαίου τέθριππον.", "st": "10.7"}, {"sp": "N", "t": "παγκράτιον δ’ ἐν παισὶ καὶ συνωρίδα τε πώλων καὶ ⟨πῶλον⟩ κέλητα πολλοῖς ἔτεσιν ὕστερον κατεδέξαντο Ἠλείων, τὸ μὲν πρώτῃ πυθιάδι ἐπὶ ταῖς ἑξήκοντα, καὶ Ἰολαΐδας ἐνίκα Θηβαῖος· διαλιπόντες δὲ ἀπὸ ταύτης μίαν κέλητι ἔθεσαν δρόμον πώλῳ, ἐνάτῃ δὲ ἐπὶ ταῖς ἑξήκοντα συνωρίδι πωλικῇ, καὶ ἐπὶ μὲν τῷ πώλῳ τῷ κέλητι Λυκόρμας ἀνηγορεύθη Λαρισαῖος, Πτολεμαῖος δὲ ἐπὶ τῇ συνωρίδι Μακεδών· ἔχαιρον γὰρ δὴ Μακεδόνες οἱ ἐν Αἰγύπτῳ καλούμενοι βασιλεῖς, καθάπερ γε ἦσαν. δάφνης δὲ στέφανος ἐπὶ τῶν Πυθίων τῇ νίκῃ κατ’ ἄλλο μὲν ἐμοὶ δοκεῖν ἐστιν οὐδέν, ὅτι δὲ τῆς Λάδωνος θυγατρὸς Ἀπόλλωνα ἐρασθῆναι κατέσχηκεν ἡ φήμη.", "st": "10.7"}, {"sp": "N", "t": "καταστήσασθαι δὲ συνέδριον ἐνταῦθα Ἑλλήνων οἱ μὲν Ἀμφικτύονα τὸν Δευκαλίωνος νομίζουσι καὶ ἀπὸ τούτου τοῖς συνελθοῦσιν ἐπίκλησιν Ἀμφικτύονας γενέσθαι, Ἀνδροτίων δὲ ἐν τῇ Ἀτθίδι ἔφη συγγραφῇ ὡς τὸ ἐξ ἀρχῆς ἀφίκοντο ἐς Δελφοὺς παρὰ τῶν προσοικούντων συνεδρεύοντες, καὶ ὀνομασθῆναι μὲν Ἀμφικτίονας τοὺς συνελθόντας, ἐκνικῆσαι δὲ ἀνὰ χρόνον τὸ νῦν σφισιν ὄνομα.", "st": "10.8"}, {"sp": "N", "t": "ὑπὸ μὲν δὴ Ἀμφικτύονος αὐτοῦ φασιν ἐς συνέδριον κοινὸν τοσάδε γένη τοῦ Ἑλληνικοῦ συναχθῆναι, Ἴωνας Δόλοπας Θεσσαλοὺς Αἰνιᾶνας Μάγνητας Μαλιέας Φθιώτας Δωριεῖς Φωκέας Λοκροὺς τῇ Φωκίδι ὁμόρους ὑπὸ τῷ ὄρει τῇ Κνήμιδι· καταλαβόντων δὲ Φωκέων τὸ ἱερὸν καὶ ὕστερον δεκάτῳ ἔτει λαβόντος πέρας τοῦ πολέμου, μεταβολὴν καὶ τὰ Ἀμφικτυόνων ἔσχε. Μακεδόνες μὲν γὰρ τελεῖν ἐς Ἀμφικτύονας εὕραντο, Φωκέων δὲ τὸ ἔθνος καὶ ἐκ τοῦ Δωρικοῦ Λακεδαιμόνιοι μετασχόντες ἐπαύσαντο Ἀμφικτυονίας, οἱ μὲν τοῦ τολμήματος ἕνεκα οἱ Φωκεῖς, οἱ δὲ συμμαχίας εὕραντο οἱ Λακεδαιμόνιοι τῆς Φωκέων ζημίαν.", "st": "10.8"}, {"sp": "N", "t": "Βρέννου δὲ τὸν Γαλατῶν στρατὸν ἀγαγόντος ἐς Δελφοὺς προθυμίαν ἐς τὸν πόλεμον οἱ Φωκεῖς πλείστην τοῦ Ἑλληνικοῦ παρέσχοντο, καὶ ἀπὸ τοῦ ἔργου τούτου μετασχεῖν Ἀμφικτυονίας αὖθις καὶ ἐς τὰ ἄλλα ἐγένετο ἀξίωμα αὐτοῖς ἀνασώσασθαι τὸ ἀρχαῖον. βασιλεὺς δὲ Αὔγουστος μετεῖναι καὶ Νικοπολίταις τοῖς πρὸς τῷ Ἀκτίῳ συνεδρίου τοῦ Ἀμφικτυόνων ἠθέλησε· Μάγνητας μὲν οὖν καὶ Μαλιεῖς καὶ Αἰνιᾶνας καὶ Φθιώτας Θεσσαλοῖς ⟨συντελεῖν⟩, τὰς ψήφους δὲ ὅσαι τούτων τε καὶ Δολόπων—οὐ γὰρ ἔτι ἦν Δολόπων γένος—Νικοπολίτας φέρειν.", "st": "10.8"}, {"sp": "N", "t": "οἱ δὲ Ἀμφικτύονες οἱ ἐπ’ ἐμοῦ τριάκοντα ἀριθμῷ ἦσαν· ἐκ Νικοπόλεως μὲν καὶ Μακεδονίας τε καὶ Θεσσαλῶν, ἀπὸ ἑκάστων ἀριθμῷ ἦσαν ⟨ἕξ,⟩ ἐκ δὲ Βοιωτῶν—Θεσσαλίαν γὰρ καὶ οὗτοι τὰ ἀρχαιότερα ᾤκησαν καὶ Αἰολεῖς τηνικαῦτα ἐκαλοῦντο—καὶ ἐκ Φωκέων τε καὶ Δελφῶν, παρὰ τούτων δύο ἑκάστων· εἷς δ’ ἐκ Δωρίδος τῆς ἀρχαίας.", "st": "10.8"}, {"sp": "N", "t": "πέμπουσι δὲ καὶ Λοκροὶ οἵ τε καλούμενοι Ὀζόλαι καὶ οἱ πέραν Εὐβοίας ἕνα ἑκάτεροι, καὶ Εὐβοεύς ἐστιν εἷς· Πελοποννησίων δὲ ἐξ Ἄργους καὶ Σικυῶνος καὶ Κορίνθου σὺν Μεγαρεῦσίν ἐστιν εἷς καὶ εἷς Ἀθηναῖος. αἱ μὲν δὴ πόλεις Ἀθῆναι καὶ Δελφοὶ καὶ ἡ Νικόπολις, αὗται μὲν ἀποστέλλουσι συνεδρεύσοντας ἐς Ἀμφικτυονίαν πᾶσαν· ἀπὸ δὲ ἐθνῶν τῶν κατειλεγμένων ἑκάστῃ πόλει ἀνὰ μέρος ἐς Ἀμφικτύονας καὶ ἐν χρόνου περιόδῳ συντελεῖν ἔστιν.", "st": "10.8"}, {"sp": "N", "t": "ἐσελθόντι δὲ ἐς τὴν πόλιν εἰσὶν ἐφεξῆς ναοί· καὶ ὁ μὲν πρῶτος αὐτῶν ἐρείπια ἦν, ὁ ἐπὶ τούτῳ δὲ κενὸς καὶ ἀγαλμάτων καὶ ἀνδριάντων· ὁ δὲ αὐτῶν τρίτος καὶ ὁ τέταρτος, ὁ μὲν τῶν ἐν Ῥώμῃ βασιλευσάντων εἶχεν οὐ πολλῶν τινῶν εἰκόνας, ὁ τέταρτος δὲ Ἀθηνᾶς καλεῖται Προνοίας. τῶν δὲ ἀγαλμάτων τὸ ἐν τῷ προνάῳ Μασσαλιωτῶν ἀνάθημά ἐστι, μεγέθει τοῦ ἔνδον ἀγάλματος μεῖζον. οἱ δὲ Μεσσαλιῶται Φωκαέων εἰσὶν ἄποικοι τῶν ἐν Ἰωνίᾳ, μοῖρα καὶ αὕτη τῶν ποτε Ἅρπαγον τὸν Μῆδον φυγόντων ἐκ Φωκαίας· γενόμενοι δὲ ναυσὶν ἐπικρατέστεροι Καρχηδονίων τήν τε γῆν ἣν ἔχουσιν ἐκτήσαντο καὶ ἐπὶ μέγα ἀφίκοντο εὐδαιμονίας.", "st": "10.8"}, {"sp": "N", "t": "τῶν μὲν δὴ Μασσαλιωτῶν χαλκοῦν τὸ ἀνάθημά ἐστι· χρυσοῦ δὲ ἀσπίδα ὑπὸ Κροίσου τοῦ Λυδοῦ τῇ Ἀθηνᾷ τῇ Προνοίᾳ δοθεῖσαν, ἐλέγετο ὑπὸ τῶν Δελφῶν ὡς Φιλόμηλος αὐτὴν ἐσύλησε. πρὸς δὲ τῷ ἱερῷ τῆς Προνοίας Φυλάκου τέμενός ἐστιν ἥρωος· καὶ ὁ Φύλακος οὗτος ὑπὸ Δελφῶν ἔχει φήμην κατὰ τὴν ἐπιστρατείαν σφίσιν ἀμῦναι τὴν Περσῶν.", "st": "10.8"}, {"sp": "N", "t": "ἐν δὲ τοῦ γυμνασίου τῷ ὑπαίθρῳ πεφυκέναι ποτὲ ἀγρίαν φασὶν ὕλην, καὶ Ὀδυσσέα, ἡνίκα ὡς τὸν Αὐτόλυκον ἀφικόμενος μετὰ τοῦ Αὐτολύκου τῶν παίδων ἐθήρευε, τότε αὐτὸν τὸ τραῦμα τὸ ὑπὲρ τοῦ γόνατος ἐνταῦθα σχεῖν ὑπὸ τοῦ συός. τραπομένῳ δὲ ἐς ἀριστερὰν ἀπὸ τοῦ γυμνασίου καὶ ὑποκαταβάντι οὐ πλέον ἐμοὶ δοκεῖν ἢ τρία στάδια, ποταμός ἐστιν ὀνομαζόμενος Πλεῖστος· οὗτος ὁ Πλεῖστος ἐπὶ Κίρραν τὸ ἐπίνειον Δελφῶν καὶ τὴν ταύτῃ κάτεισι θάλασσαν.", "st": "10.8"}, {"sp": "N", "t": "ἐκ δὲ τοῦ γυμνασίου τὴν ἐς τὸ ἱερὸν ἀνιόντι ἔστιν ἐν δεξιᾷ τῆς ὁδοῦ τὸ ὕδωρ τῆς Κασταλίας, καὶ πιεῖν ἡδὺ ⟨καὶ λοῦσθαι καλόν.⟩ δοῦναι δὲ τὸ ὄνομα τῇ πηγῇ γυναῖκα λέγουσιν ἐπιχωρίαν, οἱ δὲ ἄνδρα Καστάλιον· Πανύασσις δὲ ὁ Πολυάρχου πεποιηκὼς ἐς Ἡρακλέα ἔπη θυγατέρα Ἀχελῴου τὴν Κασταλίαν φησὶν εἶναι. λέγει γὰρ δὴ περὶ τοῦ Ἡρακλέους·<br>Παρνησσὸν νιφόεντα θοοῖς διὰ ποσσὶ περήσας<br>ἵκετο Κασταλίης Ἀχελωΐδος ἄμβροτον ὕδωρ.", "st": "10.8"}, {"sp": "N", "t": "ἤκουσα δὲ καὶ ἄλλο τοιόνδε, τὸ ὕδωρ τῇ Κασταλίᾳ ποταμοῦ δῶρον εἶναι τοῦ Κηφισοῦ. τοῦτο ἐποίησε καὶ Ἀλκαῖος ἐν προοιμίῳ τῷ ἐς Ἀπόλλωνα· βεβαιοῦνται δὲ οὐχ ἥκιστα οἱ Λιλαιεῖς, οἳ ἐς τοῦ Κηφισοῦ τὴν πηγὴν πέμματα ἐπιχώρια καὶ ἄλλα ὁπόσα νομίζουσιν ἀφιᾶσιν ἔν τισιν εἰρημέναις ἡμέραις, καὶ αὖθις ἐν τῇ Κασταλίᾳ φασὶν αὐτὰ ἀναφαίνεσθαι.", "st": "10.8"}, {"sp": "N", "t": "Δελφοῖς δὲ ἡ πόλις ἄναντες διὰ πάσης παρέχεται σχῆμα, κατὰ τὰ αὐτὰ δὲ τῇ πόλει τῇ ἄλλῃ καὶ ὁ ἱερὸς περίβολος τοῦ Ἀπόλλωνος. οὗτος δὲ μεγέθει μέγας καὶ ἀνωτάτω τοῦ ἄστεώς ἐστι· τέτμηνται δὲ καὶ ἔξοδοι δι’ αὐτοῦ συνεχεῖς. ὁπόσα δὲ τῶν ἀναθημάτων εἶναί μοι λόγου μάλιστα ⟨ἄξια⟩ ἐφαίνετο, ποιησόμεθα αὐτῶν μνήμην.", "st": "10.9"}, {"sp": "N", "t": "ἀθλητὰς μὲν οὖν καὶ ὅσαι ἀγωνισταὶ μουσικῆς τῶν ἀνθρώπων τοῖς πλείοσιν ἐγίνοντο μετὰ οὐδενὸς λογισμοῦ, [μετὰ τῆς] ⟨οὐ πάνυ τι ἡγοῦμαι⟩ σπουδῆς ⟨ἀξίους⟩· ἀθλητὰς δὲ ὁπόσοι τι καὶ ὑπελείποντο ἐς δόξαν, ἐν λόγῳ σφᾶς ἐδήλωσα τῷ ἐς Ἠλείους. Φαΰλῳ δὲ Κροτωνιάτῃ—Ὀλυμπίασι μὲν οὐκ ἔστιν αὐτῷ νίκη, τὰς δὲ Πυθοῖ πεντάθλου δύο ἀνείλετο καὶ σταδίου τὴν τρίτην· ἐναυμάχησε δὲ καὶ ἐναντία τοῦ Μήδου ναῦν τε παρασκευασάμενος οἰκείαν καὶ Κροτωνιατῶν ὁπόσοι ἐπεδήμουν τῇ Ἑλλάδι ἀνεβίβασεν— τούτου ἐστὶν ἀνδριὰς ἐν Δελφοῖς. τὰ μὲν δὴ ἐς τὸν Κροτωνιάτην οὕτως εἶχεν, ἐσελθόντι δὲ ἐς τὸ τέμενος", "st": "10.9"}, {"sp": "N", "t": "χαλκοῦς ταῦρος τέχνη μὲν Θεοπρόπου ἐστὶν Αἰγινήτου, Κορκυραίων δὲ ἀνάθημα. λέγεται δὲ ὡς ταῦρος ἐν τῇ Κορκύρᾳ καταλιπὼν τὰς ἄλλας βοῦς καὶ ἀπὸ τῆς νομῆς κατερχόμενος ἐμυκᾶτο ἐπὶ θαλάσσῃ· γινομένου δὲ ἐπὶ ἡμέρᾳ πάσῃ τοῦ αὐτοῦ κάτεισιν ἐπὶ θάλασσαν ὁ βουκόλος, καὶ εἶδεν ἰχθύων τῶν θύννων ἀτέκμαρτόν τι ἀριθμῷ πλῆθος.", "st": "10.9"}, {"sp": "N", "t": "καὶ ὁ μὲν δῆλα τοῖς ἐν τῇ πόλει Κορκυραίοις ἐποίησεν· οἱ δὲ—ἑλεῖν γὰρ τοὺς θύννους προαιρούμενοι τὴν ἄλλως ταλαιπωρίαν εἶχον—θεωροὺς ἀποστέλλουσιν ἐς Δελφούς· καὶ οὕτω Ποσειδῶνί τε ἐκεῖνον θύουσι τὸν ταῦρον καὶ αὐτίκα μετὰ τὴν θυσίαν αἱροῦσι τοὺς ἰχθῦς, καί σφισι τὸ ἀνάθημα ἐν Ὀλυμπίᾳ τε καὶ ἐν Δελφοῖς ἐστιν ἡ δεκάτη τῆς ἄγρας.", "st": "10.9"}, {"sp": "N", "t": "ἐφεξῆς δὲ Τεγεατῶν ἀναθήματα ἀπὸ Λακεδαιμονίων Ἀπόλλων ἐστὶ καὶ Νίκη καὶ οἱ ἐπιχώριοι τῶν ἡρώων, Καλλιστώ τε ἡ Λυκάονος καὶ Ἀρκὰς ὁ ἐπώνυμος τῆς γῆς καὶ οἱ τοῦ Ἀρκάδος παῖδες Ἔλατος καὶ Ἀφείδας καὶ Ἀζάν, ἐπὶ δὲ αὐτοῖς Τρίφυλος· τούτῳ δὲ ἦν οὐκ Ἐρατὼ τῷ Τριφύλῳ μήτηρ, ἀλλὰ Λαοδάμεια ἡ Ἀμύκλα τοῦ ἐν Λακεδαίμονι βασιλεύσαντος· ἀνάκειται δὲ καὶ Ἔρασος Τριφύλου παῖς.", "st": "10.9"}, {"sp": "N", "t": "οἱ δὲ εἰργασμένοι τὰ ἀγάλματα Παυσανίας ἐστὶν Ἀπολλωνιάτης, οὗτος μὲν τόν τε Ἀπόλλωνα καὶ Καλλιστώ, τὴν δὲ Νίκην καὶ τοῦ Ἀρκάδος ⟨τὴν⟩ εἰκόνα ὁ Σικυώνιος Δαίδαλος· Ἀντιφάνης δὲ Ἀργεῖος καὶ Σαμόλας Ἀρκάς, οὗτος μὲν τὸν Τρίφυλον καὶ Ἀζᾶνα, Ἔλατον δὲ καὶ Ἀφείδαντά τε καὶ Ἔρασον ⟨ὁ⟩ Ἀργεῖος. ταῦτα μὲν δὴ οἱ Τεγεᾶται ἔπεμψαν ἐς Δελφούς, Λακεδαιμονίους ὅτε ἐπὶ σφᾶς ἐστρατεύσαντο αἰχμαλώτους ἑλόντες·", "st": "10.9"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἀπαντικρὺ τούτων ἀναθήματά ἐστιν ἀπ’ Ἀθηναίων Διόσκουροι καὶ Ζεὺς καὶ Ἀπόλλων τε καὶ Ἄρτεμις, ἐπὶ δὲ αὐτοῖς Ποσειδῶν τε καὶ Λύσανδρος ὁ Ἀριστοκρίτου στεφανούμενος ὑπὸ τοῦ Ποσειδῶνος, Ἀγίας τε ὃς τῷ Λυσάνδρῳ τότε ἐμαντεύετο καὶ Ἕρμων ὁ τὴν ναῦν τοῦ Λυσάνδρου τὴν στρατηγίδα κυβερνῶν.", "st": "10.9"}, {"sp": "N", "t": "τοῦτον μὲν δὴ τὸν Ἕρμωνα Θεόκοσμος ποιήσειν ἔμελλεν ὁ Μεγαρεὺς ἅτε ὑπὸ τῶν Μεγαρέων ἐγγραφέντα ἐς τὴν πολιτείαν· οἱ δὲ Διόσκουροι Ἀντιφάνους εἰσὶν Ἀργείου καὶ ὁ μάντις τέχνη Πίσωνος ἐκ Καλαυρείας τῆς Τροιζηνίων· Ἀθηνόδωρος δὲ καὶ Δαμέας, ὁ μὲν τὴν Ἄρτεμίν τε καὶ Ποσειδῶνα εἰργάσατο, ἔτι δὲ τὸν Λύσανδρον, Ἀθηνόδωρος δὲ τὸν Ἀπόλλωνα ἐποίησε καὶ τὸν Δία·", "st": "10.9"}, {"sp": "N", "t": "οὗτοι δὲ Ἀρκάδες εἰσὶν ἐκ Κλείτορος. ἀνάκεινται δὲ καὶ ὄπισθεν τῶν κατειλεγμένων ὅσοι συγκατειργάσαντο τῷ Λυσάνδρῳ τὰ ἐν Αἰγὸς ποταμοῖς ἢ αὐτῶν Σπαρτιατῶν ἢ [ἀπὸ] τῶν συμμαχησάντων, εἰσὶ δὲ οἵδε· Ἄρακος μὲν καὶ Ἐριάνθης, ὁ μὲν αὐτῶν ἐκ Λακεδαίμονος, ὁ δὲ Ἐριάνθης Βοιώτιος … ὑπὲρ τοῦ Μίμαντος, ἐντεῦθεν μὲν Ἀστυκράτης, Χῖοι δὲ Κηφισοκλῆς καὶ Ἑρμόφαντός τε καὶ Ἱκέσιος, Τίμαρχος δὲ καὶ Διαγόρας Ῥόδιοι, Κνίδιος δὲ Θεόδαμος, ἐκ δὲ Ἐφέσου Κιμμέριος, καὶ Μιλήσιος Αἰαντίδης.", "st": "10.9"}, {"sp": "N", "t": "τούτους μὲν δὴ ἐποίησε Τίσανδρος, τοὺς δὲ ἐφεξῆς Ἄλυπος Σικυώνιος, Θεόπομπον Μύνδιον καὶ Κλεομήδην Σάμιον καὶ ἐξ Εὐβοίας Ἀριστοκλέα τε Καρύστιον καὶ Αὐτόνομον Ἐρετριέα καὶ Ἀριστόφαντον Κορίνθιον καὶ Ἀπολλόδωρον Τροιζήνιον καὶ ἐξ Ἐπιδαύρου Δίωνα τῆς ἐν τῇ Ἀργολίδι. ἐχόμενοι δὲ τούτων Ἀξιόνικός ἐστιν Ἀχαιὸς ἐκ Πελλήνης, ἐκ δὲ Ἑρμιόνος Θεάρης, καὶ Φωκεύς τε Πυρρίας καὶ Κώμων Μεγαρεὺς καὶ Ἀγασιμένης Σικυώνιος, ἐκ δὲ Ἀμβρακίας καὶ Κορίνθου τε καὶ Λευκάδος Τηλυκράτης καὶ Πυθόδοτος Κορίνθιος καὶ Ἀμβρακιώτης Εὐαντίδας· τελευτᾷ δὲ Ἐπικυδίδας καὶ Ἐτεόνικος οἱ Λακεδαιμόνιοι· Πατροκλέους δὲ καὶ Κανάχου φασὶν ἔργα.", "st": "10.9"}, {"sp": "N", "t": "τὴν δὲ πληγὴν Ἀθηναῖοι τὴν ἐν Αἰγὸς ποταμοῖς οὐ μετὰ τοῦ δικαίου συμβῆναί σφισιν ὁμολογοῦσι· προδοθῆναι γὰρ ἐπὶ χρήμασιν ὑπὸ τῶν στρατηγησάντων, Τυδέα δὲ εἶναι καὶ Ἀδείμαντον οἳ τὰ δῶρα ἐδέξαντο παρὰ Λυσάνδρου. καὶ ἐς ἀπόδειξιν τοῦ λόγου Σιβύλλης παρέχονται τὸν χρησμόν·<br>καὶ τότ’ Ἀθηναίοισι βαρύστονα κήδεα θήσει<br>Ζεὺς ὑψιβρεμέτης, οὗπερ κράτος ἐστὶ μέγιστον,<br>νηυσὶ φερεπτολέμοισι μάχην καὶ δηιοτῆτα<br>ὀλλυμέναις δολεροῖσι τρόποις, κακότητι νομήων.<br>τὰ δὲ ἕτερα ἐκ Μουσαίου χρησμῶν μνημονεύουσι·<br>καὶ γὰρ Ἀθηναίοισιν ἐπέρχεται ἄγριος ὄμβρος<br>ἡγεμόνων κακότητι, παραιφασίη δέ τις ἔσται<br>ἥττης· οὐ λήσουσι πόλιν, τίσουσι δὲ ποινήν.", "st": "10.9"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἐπὶ τοσοῦτον εἰρήσθω· τὸν δὲ ὑπὲρ τῆς καλουμένης Θυρέας Λακεδαιμονίων ἀγῶνα καὶ Ἀργείων, Σίβυλλα μὲν καὶ τοῦτον προεθέσπισεν ὡς συμβήσοιτο ἐξ ἴσου ταῖς πόλεσιν, Ἀργεῖοι δὲ ἀξιοῦντες ἐσχηκέναι πλέον ἐν τῷ ἔργῳ χαλκοῦν ἵππον—τὸν δούρειον δῆθεν—ἀπέστειλαν ἐς Δελφούς· τὸ δὲ ἔργον Ἀντιφάνους ἐστὶν Ἀργείου.", "st": "10.9"}, {"sp": "N", "t": "τῷ βάθρῳ δὲ τῷ ὑπὸ τὸν ἵππον τὸν δούρειον [δὴ] ἐπίγραμμα μέν ἐστιν ἀπὸ δεκάτης τοῦ Μαραθωνίου ἔργου τεθῆναι τὰς εἰκόνας· εἰσὶ δὲ Ἀθηνᾶ τε καὶ Ἀπόλλων καὶ ἀνὴρ τῶν στρατηγησάντων Μιλτιάδης· ἐκ δὲ τῶν ἡρώων καλουμένων Ἐρεχθεύς τε καὶ Κέκροψ καὶ Πανδίων, [οὗτοι μὲν δὴ] καὶ Λεώς τε καὶ Ἀντίοχος ὁ ἐκ Μήδας Ἡρακλεῖ γενόμενος τῆς Φύλαντος, ἔτι δὲ Αἰγεύς τε καὶ παίδων τῶν Θησέως Ἀκάμας, οὗτοι μὲν καὶ φυλαῖς Ἀθήνῃσιν ὀνόματα κατὰ μάντευμα ἔδοσαν τὸ ἐκ Δελφῶν· ὁ δὲ Μελάνθου Κόδρος καὶ Θησεὺς καὶ Νηλεύς [ἐστιν], οὗτοι δὲ οὐκέτι τῶν ἐπωνύμων εἰσί.", "st": "10.10"}, {"sp": "N", "t": "τοὺς μὲν δὴ κατειλεγμένους Φειδίας ἐποίησε, καὶ ἀληθεῖ λόγῳ δεκάτη καὶ οὗτοι τῆς μάχης εἰσίν· Ἀντίγονον δὲ καὶ τὸν παῖδα Δημήτριον καὶ Πτολεμαῖον τὸν Αἰγύπτιον χρόνῳ ὕστερον ἀπέστειλαν ἐς Δελφούς, τὸν μὲν Αἰγύπτιον καὶ εὐνοίᾳ τινὶ ἐς αὐτόν, τοὺς δὲ Μακεδόνας τῷ ἐς αὐτοὺς δέει.", "st": "10.10"}, {"sp": "N", "t": "πλησίον δὲ τοῦ ἵππου καὶ ἄλλα ἀναθήματά ἐστιν Ἀργείων, οἱ ἡγεμόνες τῶν ἐς Θήβας ὁμοῦ Πολυνείκει στρατευσάντων, Ἄδραστός τε ὁ Ταλαοῦ καὶ Τυδεὺς Οἰνέως καὶ οἱ ἀπόγονοι Προίτου [καὶ] Καπανεὺς Ἱππόνου καὶ Ἐτέοκλος ὁ Ἴφιος, Πολυνείκης τε καὶ ὁ Ἱππομέδων ἀδελφῆς Ἀδράστου παῖς· Ἀμφιαράου δὲ καὶ ἅρμα ἐγγὺς πεποίηται καὶ ἐφεστηκὼς Βάτων ἐπὶ τῷ ἅρματι ἡνίοχός τε τῶν ἵππων καὶ τῷ Ἀμφιαράῳ καὶ ἄλλως προσήκων κατὰ οἰκειότητα· τελευταῖος δὲ Ἀλιθέρσης ἐστὶν αὐτῶν.", "st": "10.10"}, {"sp": "N", "t": "οὗτοι μὲν δὴ Ὑπατοδώρου καὶ Ἀριστογείτονός εἰσιν ἔργα, καὶ ἐποίησαν σφᾶς, ὡς αὐτοὶ Ἀργεῖοι λέγουσιν, ἀπὸ τῆς νίκης ἥντινα ἐν Οἰνόῃ τῇ Ἀργείᾳ αὐτοί τε καὶ Ἀθηναίων ἐπίκουροι Λακεδαιμονίους ἐνίκησαν. ἀπὸ δὲ τοῦ αὐτοῦ ἐμοὶ δοκεῖν ἔργου καὶ τοὺς Ἐπιγόνους ὑπὸ Ἑλλήνων καλουμένους ἀνέθεσαν οἱ Ἀργεῖοι· κεῖνται γὰρ δὴ εἰκόνες καὶ τούτων, Σθένελος καὶ Ἀλκμαίων, κατὰ ἡλικίαν ἐμοὶ δοκεῖν πρὸ Ἀμφιλόχου τετιμημένος, ἐπὶ δὲ αὐτοῖς Πρόμαχος καὶ Θέρσανδρος καὶ Αἰγιαλεύς τε καὶ Διομήδης· ἐν μέσῳ δὲ Διομήδους καὶ τοῦ Αἰγιαλέως ἐστὶν Εὐρύαλος.", "st": "10.10"}, {"sp": "N", "t": "ἀπαντικρὺ δὲ αὐτῶν ἀνδριάντες [τε] εἰσὶν ἄλλοι· τούτους δὲ ἀνέθεσαν οἱ Ἀργεῖοι τοῦ οἰκισμοῦ τοῦ Μεσσηνίων Θηβαίοις καὶ Ἐπαμινώνδᾳ μετασχόντες. ἡρώων δέ εἰσιν αἱ εἰκόνες, Δαναὸς μὲν βασιλέων ἰσχύσας τῶν ἐν Ἄργει μέγιστον, Ὑπερμήστρα δὲ ἅτε καθαρὰ χεῖρας μόνη τῶν ἀδελφῶν· παρὰ δὲ αὐτὴν καὶ ὁ Λυγκεὺς καὶ ἅπαν τὸ ἐφεξῆς αὐτῶν γένος τὸ ἐς Ἡρακλέα τε καὶ ἔτι πρότερον καθῆκον ἐς Περσέα.", "st": "10.10"}, {"sp": "N", "t": "Ταραντίνων δὲ οἱ ἵπποι οἱ χαλκοῖ καὶ αἰχμάλωτοι γυναῖκες ἀπὸ Μεσσαπίων εἰσίν, ὁμόρων τῇ Ταραντίνων βαρβάρων, Ἀγελάδα δὲ ἔργα τοῦ Ἀργείου. Τάραντα δὲ ἀπῴκισαν μὲν Λακεδαιμόνιοι, οἰκιστὴς δὲ ἐγένετο Σπαρτιάτης Φάλανθος. στελλομένῳ δὲ ἐς ἀποικίαν τῷ Φαλάνθῳ λόγιον ἦλθεν ἐκ Δελφῶν· ὑετοῦ αὐτὸν αἰσθόμενον ὑπὸ αἴθρᾳ, τηνικαῦτα καὶ χώραν κτήσεσθαι καὶ πόλιν.", "st": "10.10"}, {"sp": "N", "t": "τὸ μὲν δὴ παραυτίκα οὔτε ἰδίᾳ τὸ μάντευμα ἐπισκεψάμενος οὔτε πρὸς τῶν ἐξηγητῶν τινα ἀνακοινώσας κατέσχε ταῖς ναυσὶν ἐς Ἰταλίαν· ὡς δέ οἱ νικῶντι τοὺς βαρβάρους οὐκ ἐγίνετο οὔτε τινὰ ἑλεῖν τῶν πόλεων οὔτε ἐπικρατῆσαι χώρας, ἐς ἀνάμνησιν ἀφικνεῖτο τοῦ χρησμοῦ, καὶ ἀδύνατα ἐνόμιζέν οἱ τὸν θεὸν χρῆσαι· μὴ γὰρ ἄν ποτε ἐν καθαρῷ καὶ αἰθρίῳ τῷ ἀέρι ὑσθῆναι. καὶ αὐτὸν ἡ γυνὴ ἀθύμως ἔχοντα —ἠκολουθήκει γὰρ οἴκοθεν—τά τε ἄλλα ἐφιλοφρονεῖτο καὶ ἐς τὰ γόνατα ἐσθεμένη τὰ αὑτῆς τοῦ ἀνδρὸς τὴν κεφαλὴν ἐξέλεγε τοὺς φθεῖρας· καί πως ὑπὸ εὐνοίας δακρῦσαι παρίσταται τῇ γυναικὶ ὁρώσῃ τοῦ ἀνδρὸς ἐς οὐδὲν προχωροῦντα τὰ πράγματα.", "st": "10.10"}, {"sp": "N", "t": "προέχει δὲ ἀφειδέστερον τῶν δακρύων καὶ—ἔβρεχε γὰρ τοῦ Φαλάνθου τὴν κεφαλήν—συνίησί τε τῆς μαντείας—ὄνομα γὰρ δὴ ἦν Αἴθρα τῇ γυναικί—καὶ οὕτω τῇ ἐπιούσῃ νυκτὶ Τάραντα τῶν βαρβάρων εἷλε μεγίστην καὶ εὐδαιμονεστάτην τῶν ἐπὶ θαλάσσῃ πόλεων. Τάραντα δὲ τὸν ἥρω Ποσειδῶνός φασι καὶ ἐπιχωρίας νύμφης παῖδα εἶναι, ἀπὸ δὲ τοῦ ἥρωος τεθῆναι τὰ ὀνόματα τῇ πόλει τε καὶ τῷ ποταμῷ· καλεῖται γὰρ δὴ Τάρας κατὰ τὰ αὐτὰ τῇ πόλει καὶ ὁ ποταμός.", "st": "10.10"}, {"sp": "N", "t": "πλησίον δὲ τοῦ ἀναθήματος τοῦ Ταραντίνων Σικυωνίων ἐστὶ θησαυρός· χρήματα δὲ οὔτε ἐνταῦθα ἴδοις ἂν οὔτε ἐν ἄλλῳ τῶν θησαυρῶν. Κνίδιοι δὲ ἐκόμισαν ἀγάλματα ἐς Δελφοὺς Τριόπαν οἰκιστὴν τῆς Κνίδου παρεστῶτα ἵππῳ καὶ Λητὼ καὶ Ἀπόλλωνά τε καὶ Ἄρτεμιν ἀφιέντας τῶν βελῶν ἐπὶ Τιτυόν· ὁ δὲ καὶ τετρωμένος ἐστὶν ἤδη τὸ σῶμα.", "st": "10.11"}, {"sp": "N", "t": "ταῦτα ἕστηκε παρὰ τὸν Σικυωνίων θησαυρόν· ἐποιήθη δὲ καὶ ὑπὸ Σιφνίων ἐπὶ αἰτίᾳ τοιᾷδε θησαυρός. Σιφνίοις ἡ νῆσος χρυσοῦ μέταλλα ἤνεγκε, καὶ αὐτοὺς τῶν προσιόντων ἐκέλευσεν ὁ θεὸς ἀποφέρειν δεκάτην ἐς Δελφούς· οἱ δὲ τὸν θησαυρὸν ᾠκοδομήσαντο καὶ ἀπέφερον τὴν δεκάτην. ὡς δὲ ὑπὸ ἀπληστίας ἐξέλιπον τὴν φοράν, ἐπικλύσασα ἡ θάλασσα ἀφανῆ τὰ μέταλλά σφισιν ἐποίησεν.", "st": "10.11"}, {"sp": "N", "t": "ἀνέθεσαν δὲ καὶ ἀνδριάντας Λιπαραῖοι ναυμαχίᾳ κρατήσαντες Τυρρηνῶν. οἱ δὲ Λιπαραῖοι οὗτοι Κνιδίων μὲν ἦσαν ἄποικοι, τῆς δὲ ἀποικίας ἡγεμόνα γενέσθαι φασὶν ἄνδρα Κνίδιον· ὄνομα δὲ εἶναί οἱ Πένταθλον Ἀντίοχος ὁ Ξενοφάνους Συρακούσιος ἐν τῇ Σικελιώτιδι συγγραφῇ φησι. λέγει δὲ καὶ ὡς ἐπὶ Παχύνῳ τῇ ἄκρᾳ τῇ ἐν Σικελίᾳ κτίσαντες πόλιν αὐτοὶ μὲν ἐκπίπτουσιν ὑπὸ Ἐλύμων καὶ Φοινίκων πολέμῳ πιεσθέντες, τὰς νήσους δὲ ἔσχον ἐρήμους ἔτι ἢ ἀναστήσαντες τοὺς ἐνοικοῦντας, ἃς [καὶ] κατὰ τὰ τὰ ἔπη τὰ Ὁμήρεια Αἰόλου καὶ ἐς ἡμᾶς ἔτι ὀνομάζουσι.", "st": "10.11"}, {"sp": "N", "t": "τούτων Λιπάραν μὲν κτίσαντες πόλιν ἐνταῦθα οἰκοῦσιν, Ἱέραν δὲ καὶ Στρογγύλην καὶ Διδύμας γεωργοῦσι διαβαίνοντες ναυσὶν ἐς αὐτάς. ἐν δὲ τῇ Στρογγύλῃ καὶ πῦρ δῆλόν ἐστιν ἀνιὸν ἐκ τῆς γῆς· καὶ ἐν Ἱέρᾳ δὲ πῦρ τε αὐτόματον ἐπὶ ἄκρας ἀνακαίεται τῆς νήσου καὶ ἐπὶ θαλάσσῃ λουτρά ἐστιν ἐπιτήδεια, ⟨εἰ⟩ δέξεταί σε ἠπίως τὸ ὕδωρ, ἐπεὶ ἄλλως γε χαλεπὸν ὑπὸ ζεστότητός ἐστιν ἐμβαίνεσθαι.", "st": "10.11"}, {"sp": "N", "t": "οἱ δὲ θησαυροὶ Θηβαίων ἀπὸ ἔργου τῶν ἐς πόλεμον, καὶ Ἀθηναίων ἐστὶν ὡσαύτως· Κνιδίους δὲ οὐκ οἶδα εἰ ἐπὶ νίκῃ τινὶ ἢ ἐς ἐπίδειξιν εὐδαιμονίας ᾠκοδομήσαντο, ἐπεὶ Θηβαίοις γε ἀπὸ ἔργου τοῦ ἐν Λεύκτροις καὶ Ἀθηναίοις ἀπὸ τῶν ἐς Μαραθῶνα ἀποβάντων ὁμοῦ Δάτιδί εἰσιν οἱ θησαυροί. Κλεωναῖοι δὲ ἐπιέσθησαν μὲν κατὰ τὸ αὐτὸ Ἀθηναίοις ὑπὸ νόσου τῆς λοιμώδους, κατὰ δὲ μάντευμα ἐκ Δελφῶν ἔθυσαν τράγον ἀνίσχοντι ἔτι τῷ ἡλίῳ, καὶ—εὕραντο γὰρ λύσιν τοῦ κακοῦ—τράγον χαλκοῦν ἀποπέμπουσι τᾷ Ἀπόλλωνι. Ποτιδαιατῶν δὲ τῶν ἐν Θρᾴκῃ καὶ Συρακουσίων, τῶν μέν ἐστιν ὁ θησαυρὸς ἀπὸ τοῦ Ἀττικοῦ τοῦ μεγάλου πταίσματος, Ποτιδαιᾶται δὲ εὐσεβείας τῆς ἐς τὸν θεὸν ἐποίησαν.", "st": "10.11"}, {"sp": "N", "t": "ᾠκοδόμησαν δὲ καὶ Ἀθηναῖοι στοὰν ἀπὸ χρημάτων ἃ ἐν τῷ πολέμῳ σφίσιν ἐγένετο ἀπό τε Πελοποννησίων καὶ ὅσαι Πελοποννησίοις ἦσαν τοῦ Ἑλληνικοῦ σύμμαχοι. ἀνάκειται δὲ καὶ πλοίων τὰ ἄκρα κοσμήματα καὶ ἀσπίδες χαλκαῖ· τὸ δὲ ἐπίγραμμα τὸ ἐπ’ αὐτοῖς ἀριθμεῖ τὰς πόλεις ἀφ’ ὧν οἱ Ἀθηναῖοι τὰ ἀκροθίνια ἀπέστειλαν, τήν τε Ἠλείων καὶ Λακεδαιμονίων Σικυῶνά τε καὶ Μέγαρα καὶ Πελληνέας Ἀχαιῶν Ἀμβρακίαν τε καὶ Λευκάδα καὶ αὐτὴν Κόρινθον· γενέσθαι δὲ ἀπὸ τῶν ναυμαχιῶν τούτων καὶ θυσίαν Θησεῖ καὶ τῷ Ποσειδῶνι ἐπὶ τῷ ὀνομαζομένῳ Ῥίῳ. καί μοι φαίνεται τὸ ἐπίγραμμα ἐς Φορμίωνα τὸν Ἀσωπίχου ἔχειν καὶ ἐς τοῦ Φορμίωνος τὰ ἔργα.", "st": "10.11"}, {"sp": "N", "t": "πέτρα δέ ἐστιν ἀνίσχουσα ὑπὲρ τῆς γῆς· ἐπὶ ταύτῃ Δελφοὶ στᾶσάν φασιν ᾆσαι τοὺς χρησμοὺς ⟨γυναῖκα⟩ ὄνομα Ἡροφίλην, Σίβυλλαν δὲ ἐπίκλησιν. τὴν ⟨δὲ⟩ πρότερον γενομένην, ταύτην ταῖς μάλιστα ὁμοίως οὖσαν ἀρχαίαν εὕρισκον, ἣν θυγατέρα Ἕλληνες Διὸς καὶ Λαμίας τῆς Ποσειδῶνός φασιν εἶναι, καὶ χρησμούς τε αὐτὴν γυναικῶν πρώτην ᾆσαι καὶ ὑπὸ τῶν Λιβύων Σίβυλλαν λέγουσιν ὀνομασθῆναι.", "st": "10.12"}, {"sp": "N", "t": "ἡ δὲ Ἡροφίλη νεωτέρα μὲν ἐκείνης, φαίνεται δὲ ὅμως πρὸ τοῦ πολέμου γεγονυῖα καὶ αὕτη τοῦ Τρωικοῦ, καὶ Ἑλένην τε προεδήλωσεν ἐν τοῖς χρησμοῖς, ὡς ἐπ’ ὀλέθρῳ τῆς Ἀσίας καὶ Εὐρώπης τραφήσοιτο ἐν Σπάρτῃ, καὶ ὡς Ἴλιον ἁλώσεται δι’ αὐτὴν ὑπὸ Ἑλλήνων. Δήλιοι δὲ καὶ ὕμνον μέμνηνται τῆς γυναικὸς ἐς Ἀπόλλωνα. καλεῖ δὲ οὐχ Ἡροφίλην μόνον ἀλλὰ καὶ Ἄρτεμιν ἐν τοῖς ἔπεσιν αὑτήν, καὶ Ἀπόλλωνος γυνὴ γαμετή, τοτὲ δὲ ἀδελφὴ καὶ αὖθις θυγάτηρ φησὶν εἶναι.", "st": "10.12"}, {"sp": "N", "t": "ταῦτα μὲν δὴ μαινομένη τε καὶ ἐκ τοῦ θεοῦ κάτοχος πεποίηκεν· ἑτέρωθι δὲ εἶπε τῶν χρησμῶν ὡς μητρὸς μὲν ἀθανάτης εἴη μιᾶς τῶν ἐν Ἴδῃ νυμφῶν, πατρὸς δὲ ἀνθρώπου, καὶ οὕτω λέγει τὰ ἔπη·<br>εἰμὶ δ’ ἐγὼ γεγαυῖα μέσον θνητοῦ τε θεᾶς τε,<br>νύμφης [δ’] ἀθανάτης, πατρὸς δ’ αὖ κητοφάγοιο,<br>μητρόθεν Ἰδογενής, πατρὶς δέ μοί ἐστιν ἐρυθρή<br>Μάρπησσος, μητρὸς ἱερή, ποταμός ⟨τ’⟩ Ἀιδωνεύς.", "st": "10.12"}, {"sp": "N", "t": "ἦν δὲ ἔτι καὶ νῦν ἐν τῇ Ἴδῃ τῇ Τρωικῇ πόλεως Μαρπήσσου τὰ ἐρείπια καὶ ἐν αὐτοῖς οἰκήτορες ὅσον ἑξήκοντα ἄνθρωποι· ὑπέρυθρος δὲ πᾶσα ἡ περὶ τὴν Μάρπησσον γῆ καὶ δεινῶς ἐστιν αὐχμώδης, ὥστε καὶ τῷ Ἀϊδωνεῖ ποταμῷ καταδύεσθαί τε ἐς τὴν χώραν καὶ ἀνασχόντι τὸ αὐτὸ αὖθις πάσχειν, τέλος δὲ καὶ ἀφανίζεσθαι κατὰ τῆς γῆς, αἴτιον ἐμοὶ δοκεῖν ἐστιν ὅτι λεπτή τε κατὰ τοῦτο καὶ σηραγγώδης ἐστὶν ἡ Ἴδη. ἀπέχει δὲ Ἀλεξανδρείας τῆς ἐν τῇ Τρῳάδι τεσσαράκοντα ἡ Μάρπησσος καὶ διακόσια στάδια.", "st": "10.12"}, {"sp": "N", "t": "τὴν δὲ Ἡροφίλην οἱ ἐν τῇ Ἀλεξανδρείᾳ ταύτῃ νεωκόρον τε τοῦ Ἀπόλλωνος γενέσθαι τοῦ Σμινθέως καὶ ἐπὶ τῷ ὀνείρατι τῷ Ἑκάβης χρῆσαί φασιν αὐτὴν ἃ δὴ καὶ ἐπιτελεσθέντα ἴσμεν. αὕτη ἡ Σίβυλλα ᾤκησε μὲν τὸ πολὺ τοῦ βίου ἐν Σάμῳ, ἀφίκετο δὲ καὶ ἐς Κλάρον τὴν Κολοφωνίων καὶ ἐς Δῆλόν τε καὶ ἐς Δελφούς· ὁπότε δὲ ἀφίκοιτο, ἐπὶ ταύτης ἱσταμένη τῆς πέτρας ᾖδε.", "st": "10.12"}, {"sp": "N", "t": "τὸ μέντοι χρεὼν αὐτὴν ἐπέλαβεν ἐν τῇ Τρῳάδι, καί οἱ τὸ μνῆμα ἐν τῷ ἄλσει τοῦ Σμινθέως ἐστὶ καὶ ἐλεγεῖον ἐπὶ τῆς στήλης·<br>ἅδ’ ἐγὼ ἁ Φοίβοιο σαφηγορίς εἰμι Σίβυλλα<br>τῷδ’ ὑπὸ λαϊνέῳ σάματι κευθομένα,<br>παρθένος αὐδάεσσα τὸ πρίν, νῦν δ’ αἰὲν ἄναυδος,<br>μοίρᾳ ὑπὸ στιβαρᾷ τάνδε λαχοῦσα πέδαν.<br>ἀλλὰ πέλας Νύμφαισι καὶ Ἑρμῇ τῷδ’ ὑπόκειμαι,<br>μοῖραν ἔχοισα κάτω τᾶς τότ’ ἀνακτορίας.<br>ὁ μὲν δὴ παρὰ τὸ μνῆμα ἕστηκεν Ἑρμῆς λίθου τετράγωνον σχῆμα· ἐξ ἀριστερᾶς δὲ ὕδωρ τε κατερχόμενον ἐς κρήνην καὶ τῶν Νυμφῶν ἐστι τὰ ἀγάλματα.", "st": "10.12"}, {"sp": "N", "t": "Ἐρυθραῖοι δὲ—ἀμφισβητοῦσι γὰρ τῆς Ἡροφίλης προθυμότατα Ἑλλήνων—Κώρυκόν τε καλούμενον ὄρος καὶ ἐν τῷ ὄρει σπήλαιον ἀποφαίνουσι, τεχθῆναι τὴν Ἡροφίλην ἐν αὐτῷ λέγοντες, Θεοδώρου δὲ ἐπιχωρίου ποιμένος καὶ νύμφης παῖδα εἶναι· Ἰδαίαν δὲ ἐπίκλησιν γενέσθαι τῇ νύμφῃ κατ’ ἄλλο μὲν οὐδέν, τῶν δὲ χωρίων τὰ δασέα ὑπὸ τῶν ἀνθρώπων ἴδας τότε ὀνομάζεσθαι. τὸ δὲ ἔπος τὸ ἐς τὴν Μάρπησσον καὶ τὸν ποταμὸν τὸν Ἀϊδωνέα, τοῦτο οἱ Ἐρυθραῖοι τὸ ἔπος ἀφαιροῦσιν ἀπὸ τῶν χρησμῶν.", "st": "10.12"}, {"sp": "N", "t": "τὴν δὲ ἐπὶ ταύτῃ χρησμοὺς κατὰ ταὐτὰ εἰποῦσαν ἐκ Κύμης τῆς ἐν Ὀπικοῖς εἶναι, καλεῖσθαι δὲ [αὐτὴν] Δημὼ συνέγραψεν Ὑπέροχος ἀνὴρ Κυμαῖος. χρησμὸν δὲ οἱ Κυμαῖοι τῆς γυναικὸς ταύτης [ἐς] οὐδένα εἶχον ἐπιδείξασθαι, λίθου δὲ ὑδρίαν ἐν Ἀπόλλωνος ἱερῷ δεικνύουσιν οὐ μεγάλην, τῆς Σιβύλλης ἐνταῦθα κεῖσθαι φάμενοι τὰ ὀστᾶ.", "st": "10.12"}, {"sp": "N", "t": "ἐπετράφη δὲ καὶ ὕστερον τῆς Δημοῦς παρ’ Ἑβραίοις τοῖς ὑπὲρ τῆς Παλαιστίνης γυνὴ χρησμολόγος, ὄνομα δὲ αὐτῇ Σάββη· Βηρόσου δὲ εἶναι πατρὸς καὶ Ἐρυμάνθης μητρός φασι Σάββην· οἱ δὲ αὐτὴν Βαβυλωνίαν, ἕτεροι δὲ Σίβυλλαν καλοῦσιν Αἰγυπτίαν.", "st": "10.12"}, {"sp": "N", "t": "Φαεννὶς δὲ θυγάτηρ βασιλεύσαντος ἀνδρὸς ἐν Χάοσι καὶ αἱ Πέλειαι παρὰ Δωδωναίοις ἐμαντεύσαντο μὲν ἐκ θεοῦ καὶ αὗται, Σίβυλλαι δὲ ὑπὸ ἀνθρώπων οὐκ ἐκλήθησαν. τῆς μὲν δὴ πυθέσθαι τὴν ἡλικίαν καὶ ἐπιλέξασθαι τοὺς χρησμούς … Ἀντιόχου γὰρ μετὰ τὸ ἁλῶναι Δημήτριον αὐτίκα ἐς τὴν ἀρχὴν καθισταμένου γέγονε Φαεννίς. τὰς Πελειάδας δὲ Φημονόης τε ἔτι προτέρας γενέσθαι λέγουσι καὶ ᾆσαι γυναικῶν πρώτας τάδε τὰ ἔπη·<br>Ζεὺς ἦν, Ζεὺς ἐστίν, Ζεὺς ἔσσεται· ὦ μεγάλε Ζεῦ.<br>Γᾶ καρποὺς ἀνίει, διὸ κλῄζετε Ματέρα γαῖαν.", "st": "10.12"}, {"sp": "N", "t": "χρησμολόγους δὲ ἄνδρας Κύπριόν τε Εὔκλουν καὶ Ἀθηναίους Μουσαῖον τὸν Ἀντιοφήμου καὶ Λύκον τὸν Πανδίονος, τούτους τε γενέσθαι καὶ ἐκ Βοιωτίας Βάκιν φασὶ κατάσχετον ἄνδρα ἐκ νυμφῶν· τούτων πλὴν Λύκου τῶν ἄλλων ἐπελεξάμην τοὺς χρησμούς. τοσαῦται μὲν ἄχρι ἐμοῦ λέγονται γυναῖκες καὶ ἄνδρες ἐκ θεοῦ μαντεύσασθαι· ἐν δὲ τῷ χρόνῳ τῷ πολλῷ καὶ αὖθις γένοιτο ἂν ἕτερα τοιαῦτα.", "st": "10.12"}, {"sp": "N", "t": "βίσωνος δὲ ταύρου τῶν Παιονικῶν χαλκοῦ πεποιημένην κεφαλὴν Δρωπίων Λέοντος ἔπεμψεν ἐς Δελφοὺς βασιλεὺς Παιόνων. οὗτοι οἱ βίσωνες χαλεπώτατοι θηρίων εἰσὶν ἁλίσκεσθαι ζῶντες, καὶ δίκτυα οὐκ ἂν οὕτω γένοιτο ἰσχυρὰ ⟨ὡς ἀντισχεῖν⟩ τῇ ἐμβολῇ. θηρεύονται δὲ οὗτοι τρόπον τοιόνδε. ἐπειδὰν χωρίον οἱ ἀγρεύοντες πρανὲς εὕρωσι καθῆκον ἐς κοιλότητα, πρῶτα μὲν φράγματι ἰσχυρῷ πέριξ ὠχυρώσαντο, δεύτερον δὲ τὸ κάταντες καὶ τὸ περὶ τῷ πέρατι ὁμαλὸν αὐτοῦ νεοδάρτοις βύρσαις κατεστόρεσαν· ἢν δὲ τύχωσιν ἀποροῦντες βυρσῶν, τότε καὶ τὰ αὖα τῶν δερμάτων ὑπὸ ἐλαίου σφίσιν ὀλισθηρὰ ποιεῖται.", "st": "10.13"}, {"sp": "N", "t": "τὸ δὲ ἐντεῦθεν οἱ μάλιστα ἱππεύειν ἀγαθοὶ συνελαύνουσιν ἐς τὸ εἰρημένον χωρίον τοὺς βίσωνας· οἱ δὲ εὐθὺς ἐν ταῖς πρώταις τῶν βυρσῶν ὀλισθόντες κατὰ τοῦ πρανοῦς κυλίνδονται, ἕως κατενεχθῶσιν ἐς τὸ ὁμαλόν. ἐρριμμένοι δὲ ἐνταῦθα ἠμέληνται κατ’ ἀρχάς· τετάρτῃ δὲ ἢ πέμπτῃ μάλιστα ἡμέρᾳ τῶν μὲν ἤδη τοῦ θυμοῦ τὸ πολὺ ὁ λιμὸς ἀφαιρεῖ καὶ ἡ ταλαιπωρία, οἱ δέ σφισιν, οἷς", "st": "10.13"}, {"sp": "N", "t": "τέχνη τιθασεύειν, προσφέρουσιν ἔτι κειμένοις πίτυος τῆς ἡμέρου καρπὸν προεκλέξαντες ἐκ τῶν ἐλαχίστων ἐλύτρων· ἑτέρας δὲ οὐκ ἂν τροφῆς τό γε παραυτίκα ἅψαιτο τὰ θηρία· τέλος δὲ διαλαβόντες δεσμοῖς ἄγουσι.", "st": "10.13"}, {"sp": "N", "t": "καὶ τοὺς μὲν τρόπον αἱροῦσι τὸν εἰρημένον, τοῦ βίσωνος δὲ τῆς κεφαλῆς καταντικρὺ τῆς χαλκῆς ἀνδριάς ἐστι θώρακά τε ἐνδεδυκὼς καὶ χλαμύδα ἐπὶ τῷ θώρακι· Ἀνδρίων δὲ ἀνάθημα οἱ Δελφοὶ λέγουσιν Ἀνδρέα εἶναι τὸν οἰκιστήν. τό τε ἄγαλμα τοῦ Ἀπόλλωνος καὶ Ἀθηνᾶς τε καὶ Ἀρτέμιδος Φωκέων ἀναθήματά ἐστιν ἀπὸ Θεσσαλῶν ὁμόρων τε—πλὴν ὅσον οἱ Λοκροὶ σφᾶς οἱ Ἐπικνημίδιοι διείργουσι—καὶ ἀεὶ πολεμίων ὄντων.", "st": "10.13"}, {"sp": "N", "t": "ἀνέθεσαν δὲ καὶ οἱ ἐν Φαρσάλῳ Θεσσαλοὶ καὶ Μακεδόνων οἱ ὑπὸ τῇ Πιερίᾳ πόλιν Δῖον οἰκοῦντες Κυρηναῖοί τε τοῦ Ἑλληνικοῦ τοῦ ἐν Λιβύῃ, οὗτοι μὲν τὸ ἅρμα καὶ ἐπὶ τῷ ἅρματι ἄγαλμα Ἄμμωνος, Μακεδόνες δὲ οἱ ἐν Δίῳ τὸν Ἀπόλλωνα ὃς εἰλημμένος ἐστὶ τῆς ἐλάφου, Φαρσάλιοι δὲ Ἀχιλλέα τε ἐπὶ ἵππῳ καὶ ὁ Πάτροκλος συμπαραθεῖ[ν] οἱ [καὶ] τῷ ἵππῳ. Κορίνθιοι δὲ οἱ Δωριεῖς ᾠκοδόμησαν θησαυρὸν καὶ οὗτοι·", "st": "10.13"}, {"sp": "N", "t": "καὶ ὁ χρυσὸς ὁ ἐκ Λυδῶν ἀνέκειτο ἐνταῦθα. τὸ δὲ ἄγαλμα τοῦ Ἡρακλέους ἀνάθημά ἐστι Θηβαίων, ὅτε Φωκεῦσιν ἐπολέμησαν τὸν ἱερὸν καλούμενον πόλεμον. εἰσὶ καὶ εἰκόνες χαλκαῖ Φωκέων ἀναθέντων, ἡνίκα δευτέρᾳ συμβολῇ τὸ ἱππικὸν ἐτρέψαντο τὸ ἐκ Θεσσαλίας. Φλιάσιοι δὲ ἐκόμισαν ἐς Δελφοὺς Δία τε χαλκοῦν καὶ ὁμοῦ τῷ Διὶ ἄγαλμα Αἰγίνης. ἐκ δὲ Μαντινείας τῆς Ἀρκάδων Ἀπόλλων χαλκοῦς ἐστιν ἀνάθημα· οὗτος οὐ πόρρω τοῦ Κορινθίων ἐστὶ θησαυροῦ.", "st": "10.13"}, {"sp": "N", "t": "Ἡρακλῆς δὲ καὶ Ἀπόλλων ἔχονται τοῦ τρίποδος καὶ ἐς μάχην περὶ αὐτοῦ καθίστανται· Λητὼ μὲν δὴ καὶ Ἄρτεμις Ἀπόλλωνα, Ἀθηνᾶ δὲ Ἡρακλέα ἐπέχουσι τοῦ θυμοῦ. Φωκέων καὶ τοῦτό ἐστιν ἀνάθημα, ὅτε σφίσιν ἐπὶ τοὺς Θεσσαλοὺς Τελλίας ἡγήσατο Ἠλεῖος. τὰ μὲν δὴ ἄλλα ἀγάλματα Δίυλλός τε ἐν κοινῷ καὶ Ἀμυκλαῖος, τὴν δὲ Ἀθηνᾶν καὶ Ἄρτεμιν Χίονίς ἐστιν εἰργασμένος· Κορινθίους δὲ εἶναί φασιν αὐτούς.", "st": "10.13"}, {"sp": "N", "t": "λέγεται δὲ ὑπὸ Δελφῶν Ἡρακλεῖ τῷ Ἀμφιτρύωνος ἐλθόντι ἐπὶ τὸ χρηστήριον τὴν πρόμαντιν Ξενόκλειαν οὐκ ἐθελῆσαί οἱ χρᾶν διὰ τοῦ Ἰφίτου τὸν φόνον· τὸν δὲ ἀράμενον τὸν τρίποδα ἐκ τοῦ ναοῦ φέρειν ἔξω, εἰπεῖν τε δὴ τὴν πρόμαντιν·<br>ἄλλος ἄρ’ Ἡρακλέης Τιρύνθιος, οὐχὶ Κανωβεύς·<br>πρότερον γὰρ ἔτι ὁ Αἰγύπτιος Ἡρακλῆς ἀφίκετο ἐς Δελφούς. τότε δὲ ὁ Ἀμφιτρύωνος τόν τε τρίποδα ἀποδίδωσι τῷ Ἀπόλλωνι καὶ παρὰ τῆς Ξενοκλείας ὁπόσα ἐδεῖτο ἐδιδάχθη. παραδεξάμενοι δὲ οἱ ποιηταὶ τὸν λόγον μάχην Ἡρακλέους πρὸς Ἀπόλλωνα ὑπὲρ τρίποδος ᾄδουσιν.", "st": "10.13"}, {"sp": "N", "t": "ἐν κοινῷ δὲ ἀνέθεσαν ἀπὸ ἔργου τοῦ Πλαταιᾶσιν οἱ Ἕλληνες χρυσοῦν τρίποδα δράκοντι ἐπικείμενον χαλκῷ. ὅσον μὲν δὴ χαλκὸς ἦν τοῦ ἀναθήματος, σῶον καὶ ἐς ἐμὲ ἔτι ἦν· οὐ μέντοι κατὰ τὰ αὐτὰ καὶ τὸν χρυσὸν οἱ Φωκέων ὑπελίποντο ἡγεμόνες.", "st": "10.13"}, {"sp": "N", "t": "Ταραντῖνοι δὲ καὶ ἄλλην δεκάτην ἐς Δελφοὺς ἀπὸ βαρβάρων Πευκετίων ἀπέστειλαν· τέχνη μὲν τὰ ἀναθήματα Ὀνάτα τοῦ Αἰγινήτου καὶ Ἀγελάδα ἐστὶ τοῦ Ἀργείου, εἰκόνες δὲ καὶ πεζῶν καὶ ἱππέων, βασιλεὺς Ἰαπύγων Ὦπις ἥκων τοῖς Πευκετίοις σύμμαχος. οὗτος μὲν δὴ εἴκασται τεθνεῶτι ἐν τῇ μάχῃ, οἱ δὲ αὐτῷ κειμένῳ ἐφεστηκότες ὁ ἥρως Τάρας ἐστὶ καὶ Φάλανθος ὁ ἐκ Λακεδαίμονος, καὶ οὐ πόρρω τοῦ Φαλάνθου δελφίς· πρὶν γὰρ δὴ ἐς Ἰταλίαν ἀφικέσθαι, [καὶ] ναυαγίᾳ τε ἐν τῷ πελάγει τῷ Κρισαίῳ τὸν Φάλανθον χρήσασθαι καὶ ὑπὸ δελφῖνος ἐκκομισθῆναί φασιν ἐς τὴν γῆν.", "st": "10.13"}, {"sp": "N", "t": "οἱ δὲ πελέκεις Περικλύτου τοῦ Εὐθυμάχου Τενεδίου ἀνδρὸς ἐπὶ λόγῳ ἀνάθημά εἰσιν ἀρχαίῳ. Κύκνον παῖδα εἶναι Ποσειδῶνος καὶ βασιλεύειν φασὶν ἐν Κολώναις· αἱ δὲ ᾠκοῦντο ἐν [τῇ] γῇ τῇ Τρῳάδι αἱ Κολῶναι κατὰ νῆσον κείμεναι Λεύκοφρυν.", "st": "10.14"}, {"sp": "N", "t": "ἔχοντος δὲ θυγατέρα ὄνομα Ἡμιθέαν τοῦ Κύκνου καὶ υἱὸν καλούμενον Τέννην ἐκ Προκλείας—ἣ Κλυτίου μὲν ἦν θυγάτηρ, ἀδελφὴ δὲ Καλήτορος, ὃν Ὅμηρος ἐν Ἰλιάδι ἀποθανεῖν φησιν ὑπὸ Αἴαντος, ὅτε ὑπὸ τὴν Πρωτεσιλάου ναῦν ἔφερεν ὁ Καλήτωρ τὸ πῦρ—ταύτης οὖν προαποθανούσης ἡ ἐπεισελθοῦσα Φιλονόμη ἡ Κραγάσου —διήμαρτε γὰρ ἐρασθεῖσα τοῦ Τέννου—ψεύδεται πρὸς τὸν ἄνδρα ὡς αὐτὴ μὲν οὐκ ἐθέλουσα, τὸν δὲ αὑτῇ Τέννην συγγενέσθαι θελήσαντα· καὶ ὁ Κύκνος πείθεται τῇ ἀπάτῃ, καὶ ἐς λάρνακα ἐνθέμενος ὁμοῦ τῇ ἀδελφῇ Τέννην ἐς θάλασσαν σφᾶς ἀφίησι.", "st": "10.14"}, {"sp": "N", "t": "σώζονταί τε δὴ πρὸς τὴν νῆσον οἱ παῖδες τὴν Λεύκοφρυν καὶ ὄνομα ἡ νῆσος τὸ νῦν ἔσχεν ἀπὸ τοῦ Τέννου. Κύκνος δὲ—οὐ γὰρ τὸν πάντα ἔμελλε χρόνον ἀγνοήσειν ἀπατώμενος—ἔπλει παρὰ τὸν υἱὸν ἄγνοιάν τε ὁμολογήσων τὴν αὑτοῦ καὶ παραιτησόμενος τὸ ἁμάρτημα· προσορμισαμένου δὲ τῇ νήσῳ καὶ ἐξάψαντος ἀπὸ τῆς νεὼς πρός τινα ἢ πέτραν ἢ δένδρον τοὺς κάλους, Τέννης πελέκει σφᾶς ἀπέκοψεν ὑπὸ τοῦ θυμοῦ.", "st": "10.14"}, {"sp": "N", "t": "ἐπὶ τούτῳ [μὲν] ἐς τοὺς ἀρνουμένους στερεῶς λέγεσθαι καθέστηκεν ὡς ὁ δεῖνα ὅστις δὴ Τενεδίῳ πελέκει τόδε τι ἀποκόψειεν. Τέννην μὲν ὑπὸ Ἀχιλλέως ἀποθανεῖν ἀμύνοντα τῇ οἰκείᾳ φασὶν Ἕλληνες· Τενέδιοι δὲ ἀνὰ χρόνον ὑπὸ ἀσθενείας προσεχώρησαν τοῖς Ἀλεξάνδρειαν ἐν τῇ ἠπείρῳ τῇ Τρῳάδι ἔχουσιν.", "st": "10.14"}, {"sp": "N", "t": "Ἕλληνες δὲ οἱ ἐναντία βασιλέως πολεμήσαντες ἀνέθεσαν μὲν Δία ἐς Ὀλυμπίαν χαλκοῦν, ἀνέθεσαν δὲ καὶ ἐς Δελφοὺς Ἀπόλλωνα ἀπὸ ἔργων τῶν ἐν ταῖς ναυσὶν ἐπί τε Ἀρτεμισίῳ καὶ ἐν Σαλαμῖνι. λέγεται δὲ καὶ ὡς Θεμιστοκλῆς ἀφίκοιτο ἐς Δελφοὺς λαφύρων τῶν Μηδικῶν κομίζων τῷ Ἀπόλλωνι· ἐρωτήσαντα δὲ ὑπὲρ τῶν ἀναθημάτων εἰ ἐντὸς ἀναθήσει τοῦ ναοῦ, ἐκέλευεν αὐτὸν ἡ Πυθία τὰ παράπαν ἀποφέρειν ἐκ τοῦ ἱεροῦ. καὶ ἔχει οὕτω τὰ ἐς τοῦ τοῦ χρησμοῦ·<br>μή μοι Περσῆος σκύλων περικαλλέα κόσμον<br>νηῷ ἐγκαταθῇς· οἶκόνδ’ ἀπόπεμπε τάχιστα.", "st": "10.14"}, {"sp": "N", "t": "θαῦμα οὖν ἐποιούμεθα εἰ ἀπηξίωσεν ἐκείνου μόνου μὴ προσέσθαι τὰ ἀπὸ τῶν Μήδων. καὶ οἱ μὲν ἀπώσασθαι ἂν τὸν θεὸν καὶ ἅπαντα ὁμοίως ἡγοῦντο ὅσα ἀπὸ τοῦ Πέρσου, εἰ ὥσπερ ὁ Θεμιστοκλῆς καὶ οἱ ἄλλοι πρότερον ἢ ἀναθεῖναι σφᾶς ἐπήροντο τὸν Ἀπόλλωνα· οἱ δὲ εἰδότα τὸν θεὸν ὅτι ἱκέτης τοῦ Πέρσου γενήσοιτο ὁ Θεμιστοκλῆς, ἐπὶ τούτῳ τὰ δῶρα ἔφασαν οὐκ ἐθελῆσαι λαβεῖν, ἵνα μὴ ἀναθέντι τὸ ἔχθος ἄπαυστον ποιήσῃ ⟨τὸ⟩ ἀπὸ τοῦ Μήδου. στρατείαν δὲ τὴν ἐπὶ τὴν Ἑλλάδα [ἀπὸ] τοῦ βαρβάρου ἔστιν εὑρεῖν προρρηθεῖσαν μὲν ἐν τοῖς Βάκιδος χρησμοῖς, πρότερον δ’ ἔτι Εὔκλῳ τὰ ἐς αὐτὴν πεποιημένα ἐστίν.", "st": "10.14"}, {"sp": "N", "t": "Δελφῶν δὲ ἀνάθημά ἐστιν αὐτῶν πλησίον τοῦ βωμοῦ τοῦ μεγάλου λύκος χαλκοῦς. λέγουσι δὲ τῶν τοῦ θεοῦ χρημάτων συλήσαντα ἄνθρωπον, τὸν μὲν ὁμοῦ τῷ χρυσίῳ κατακρύψαντα ἔχειν αὑτὸν ἔνθα τοῦ Παρνασσοῦ μάλιστα ἦν συνεχὲς ὑπὸ ἀγρίων δένδρων, λύκον δὲ ἐπιθέσθαι οἱ καθεύδοντι, καὶ ἀποθανεῖν τε ὑπὸ τοῦ λύκου τὸν ἄνθρωπον καὶ ὡς ἐς τὴν πόλιν ὁσημέραι φοιτῶν ὠρύετο ὁ λύκος· ἐπεὶ δὲ οὐκ ἄνευ θεοῦ παραγίνεσθαί σφισιν ὑπελάμβανον, οὕτως ἐπακολουθοῦσι τῷ θηρίῳ, καὶ ἀνευρίσκουσί τε τὸ ἱερὸν χρυσίον καὶ ἀνέθεσαν λύκον τῷ θεῷ χαλκοῦν.", "st": "10.14"}, {"sp": "N", "t": "Φρύνης δὲ εἰκόνα ἐπίχρυσον Πραξιτέλης μὲν εἰργάσατο ἐραστὴς καὶ οὗτος, ἀνάθημα δὲ αὐτῆς Φρύνης ἐστὶν ἡ εἰκών. τὰ δὲ ἐφεξῆς ταύτῃ, τὰ μὲν ἀγάλματα τοῦ Ἀπόλλωνος Ἐπιδαύριοι τὸ ἕτερον οἱ ἐν τῇ Ἀργολίδι ἀπὸ Μήδων, τὸ δὲ αὐτῶν Μεγαρεῖς ἀνέθεσαν Ἀθηναίους μάχῃ πρὸς Νισαίᾳ κρατήσαντες· Πλαταιέων δὲ βοῦς ἐστιν, ἡνίκα ἐν τῇ σφετέρᾳ καὶ οὗτοι Μαρδόνιον τὸν Γωβρύου μετὰ Ἑλλήνων ἠμύναντο ἄλλων. καὶ αὖθις δύο Ἀπόλλωνος, τὸ μὲν Ἡρακλεωτῶν ⟨τῶν⟩ πρὸς τῷ Εὐξείνῳ, τὸ δὲ Ἀμφικτυόνων ἐστίν, ὅτε Φωκεῦσιν ἐπεργαζομένοις τοῦ θεοῦ τὴν χώραν ἐπέβαλον χρημάτων ζημίαν·", "st": "10.15"}, {"sp": "N", "t": "ὁ δὲ Ἀπόλλων οὗτος καλεῖται μὲν ὑπὸ Δελφῶν Σιτάλκας, μέγεθος δὲ πέντε πηχῶν καὶ τριάκοντά ἐστι. στρατηγοὶ δὲ οἱ πολλοὶ καὶ Ἀρτέμιδος, τὸ δὲ Ἀθηνᾶς, δύο τε Ἀπόλλωνος ἀγάλματα ἔστιν Αἰτωλῶν, ἡνίκα σφίσιν ἐξειργάσθη τὰ ἐς Γαλάτας. στρατιὰν δὲ τὴν Κελτῶν, ὡς ἐκ τῆς Εὐρώπης διαβήσοιτο ἐς τὴν Ἀσίαν ἐπ’ ὀλέθρῳ τῶν πόλεων, Φαεννὶς προεδήλωσεν ἐν τοῖς χρησμοῖς γενεᾷ πρότερον ἢ ἐπράχθη τὸ ἔργον·", "st": "10.15"}, {"sp": "N", "t": "ἦ τότ’ ἀμειψάμενος στεινὸν πόρον Ἑλλησπόντου<br>† αὐδήσει Γαλατῶν ὀλοὸς στρατός, οἵ ῥ’ ἀθεμίστως<br>Ἀσίδα πορθήσουσι· θεὸς δ’ ἔτι κύντερα θήσει<br>⟨πάγχυ⟩ μάλ’, οἳ ναίουσι παρ’ ἠϊόνεσσι θαλάσσης—<br>εἰς ὀλίγον· τάχα γάρ σφιν ἀοσσητῆρα Κρονίων<br>ὁρμήσει, ταύροιο διοτρεφέος φίλον υἱόν,<br>ὃς πᾶσιν Γαλάτῃσιν ὀλέθριον ἦμαρ ἐφήσει.<br>παῖδα δὲ εἶπε ταύρου τὸν ἐν Περγάμῳ βασιλεύσαντα Ἄτταλον· τὸν δὲ αὐτὸν τοῦτον καὶ ταυρόκερων προσείρηκε χρηστήριον.", "st": "10.15"}, {"sp": "N", "t": "ἱππικοῦ δὲ ἡγεμόνας ἀναβεβηκότας ἐπὶ ἵππους Φεραῖοι παρὰ τῷ Ἀπόλλωνι ἔστησαν τρεψάμενοι τὴν Ἀττικὴν ἵππον. τὸν δὲ φοίνικα ἀνέθεσαν Ἀθηναῖοι τὸν χαλκοῦν, καὶ αὐτὸν καὶ Ἀθηνᾶς ἄγαλμα ἐπίχρυσον ἐπὶ τῷ φοίνικι, ἀπὸ ἔργων ὧν ἐπ’ Εὐρυμέδοντι ἐν ἡμέρᾳ τῇ αὐτῇ τὸ μὲν πεζῇ, τὸ δὲ ναυσὶν ἐν τῷ ποταμῷ κατώρθωσαν. τούτου τοῦ ἀγάλματος ἐνιαχοῦ τὸν ἐπ’ αὐτῷ χρυσὸν ἐθεώμην λελυμασμένον.", "st": "10.15"}, {"sp": "N", "t": "ἐγὼ μὲν δὴ τὸ ἔγκλημα ἐς κακούργους τε ἦγον καὶ φῶρας ἀνθρώπους· Κλειτόδημος δέ, ὁπόσοι τὰ Ἀθηναίων ἐπιχώρια ἔγραψαν ὁ ἀρχαιότατος, οὗτος ἐν τῷ λόγῳ φησὶ τῷ Ἀττικῷ, ὅτε Ἀθηναῖοι παρεσκευάζοντο ἐπὶ Σικελίᾳ τὸν στόλον, ὡς ἔθνος τι ἄπειρον κοράκων κατῆρε τότε ἐς Δελφούς, καὶ περιέκοπτόν τε τοῦ ἀγάλματος τούτου καὶ ἀπέρρησσον τοῖς ῥάμφεσιν ἀπ’ αὐτοῦ τὸν χρυσόν· λέγει δὲ καὶ ὡς τὸ δόρυ καὶ τὰς γλαῦκας καὶ ὅσος καρπὸς ἐπὶ τῷ φοίνικι ἐπεποίητο ἐς μίμησιν τῆς ὀπώρας, κατακλάσαιεν καὶ ταῦτα οἱ κόρακες.", "st": "10.15"}, {"sp": "N", "t": "Ἀθηναίοις μὲν δὴ καὶ ἄλλα σημεῖα μὴ ἐκπλεῦσαι σφᾶς ἀπαγορεύοντα ἐς Σικελίαν διηγήσατο ὁ Κλειτόδημος, Κυρηναῖοι δὲ ἀνέθεσαν ἐν Δελφοῖς Βάττον ἐπὶ ἅρματι, ὃς ἐς Λιβύην ἤγαγε σφᾶς ναυσὶν ἐκ Θήρας. ἡνίοχος μὲν τοῦ ἅρματός ἐστι Κυρήνη, ἐπὶ δὲ τῷ ἅρματι Βάττος τε καὶ Λιβύη στεφανοῦσά ἐστιν αὐτόν· ἐποίησε δὲ Ἀμφίων Ἀκέστορος Κνώσσιος.", "st": "10.15"}, {"sp": "N", "t": "ἐπεὶ δὲ ᾤκισε Βάττος τὴν Κυρήνην, λέγεται καὶ τῆς φωνῆς γενέσθαι οἱ τοιόνδε ἴαμα· ἐπιὼν τῶν Κυρηναίων τὴν χώραν ἐν τοῖς ἐσχάτοις αὐτῆς ἐρήμοις ἔτι οὖσι θεᾶται λέοντα, καὶ αὐτὸν τὸ δεῖμα τὸ ἐκ τῆς θέας βοῆσαι σαφὲς καὶ μέγα ἠνάγκασεν. οὐ πόρρω δὲ τοῦ Βάττου καὶ ἄλλον ἔστησαν οἱ Ἀμφικτύονες Ἀπόλλωνα ἀπὸ τοῦ ἀδικήματος τοῦ ἐς τὸν θεὸν τῶν Φωκέων.", "st": "10.15"}, {"sp": "N", "t": "τῶν δὲ ἀναθημάτων ἃ οἱ βασιλεῖς ἀπέστειλαν οἱ Λυδῶν, οὐδὲν ἔτι ἦν αὐτῶν εἰ μὴ σιδηροῦν μόνον τὸ ὑπόθημα τοῦ Ἀλυάττου κρατῆρος. τοῦτο Γλαύκου μέν ἐστιν ἔργον τοῦ Χίου, σιδήρου κόλλησιν ἀνδρὸς εὑρόντος· ἔλασμα δὲ ἕκαστον τοῦ ὑποθήματος ἐλάσματι ἄλλῳ προσεχὲς οὐ περόναις ἐστὶν ἢ κέντροις, μόνη δὲ ἡ κόλλα συνέχει τε καὶ ἔστιν αὕτη τῷ σιδήρῳ δεσμός.", "st": "10.16"}, {"sp": "N", "t": "σχῆμα δὲ τοῦ ὑποθήματος κατὰ πύργον μάλιστα ἐς μύουρον ἀνιόντα ἀπὸ εὐρυτέρου τοῦ κάτω· ἑκάστη δὲ πλευρὰ τοῦ ὑποθήματος οὐ διὰ πάσης πέφρακται, ἀλλά εἰσιν αἱ πλάγιαι τοῦ σιδήρου ζῶναι ὥσπερ ἐν κλίμακι οἱ ἀναβασμοί· τὰ δὲ ἐλάσματα τοῦ σιδήρου τὰ ὀρθὰ ἀνέστραπται κατὰ τὰ ἄκρα ἐς τὸ ἐκτός, καὶ ἕδρα τοῦτο ἦν τῷ κρατῆρι.", "st": "10.16"}, {"sp": "N", "t": "τὸν δὲ ὑπὸ Δελφῶν καλούμενον Ὀμφαλὸν λίθου πεποιημένον λευκοῦ, τοῦτο εἶναι τὸ ἐν μέσῳ γῆς πάσης αὐτοί τε λέγουσιν οἱ Δελφοὶ καὶ ἐν ᾠδῇ τινι Πίνδαρος ὁμολογοῦντά σφισιν ἐποίησεν.", "st": "10.16"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἀνάθημά ἐστιν ἐνταῦθα, Καλάμιδος δὲ ἔργον, Ἑρμιόνη ἡ Μενελάου θυγάτηρ, ἡ συνοικήσασα Ὀρέστῃ τῷ Ἀγαμέμνονος καὶ ἔτι πρότερον Νεοπτολέμῳ τῷ Ἀχιλλέως. Εὐρύδαμον δὲ στρατηγόν τε Αἰτωλῶν καὶ στρατοῦ τοῦ Γαλατῶν ἐναντία ἡγησάμενον ἀνέθεσαν οἱ Αἰτωλοί.", "st": "10.16"}, {"sp": "N", "t": "ἔστι δὲ ἐν τοῖς Κρητικοῖς ὄρεσι καὶ κατ’ ἐμὲ ἔτι Ἔλυρος πόλις· οὗτοι οὖν αἶγα χαλκῆν ἀπέστειλαν ἐς Δελφούς, δίδωσι δὲ νηπίοις ἡ αἲξ Φυλακίδῃ καὶ Φιλάνδρῳ γάλα· παῖδας δὲ αὐτοὺς οἱ Ἐλύριοί φασιν Ἀπόλλωνός τε εἶναι καὶ Ἀκακαλλίδος νύμφης, συγγενέσθαι δὲ τῇ Ἀκακαλλίδι Ἀπόλλωνα ἐν πόλει Τάρρᾳ καὶ οἴκῳ Καρμάνορος.", "st": "10.16"}, {"sp": "N", "t": "Καρύστιοι δὲ οἱ Εὐβοεῖς βοῦν καὶ οὗτοι χαλκοῦν παρὰ τῷ Ἀπόλλωνι ἔστησαν ἀπὸ ἔργου τοῦ Μηδικοῦ· βοῦς δὲ οἱ Καρύστιοι καὶ οἱ Πλαταιεῖς τὰ ἀναθήματα ἐποιήσαντο, ὅτι ἐμοὶ δοκεῖν ἀπωσάμενοι τὸν βάρβαρον τήν τε ἄλλην βεβαίως ἐκτήσαντο εὐδαιμονίαν καὶ ἀροῦν ἐλευθέραν τὴν γῆν. στρατηγῶν δὲ εἰκόνας καὶ Ἀπόλλωνά τε καὶ Ἄρτεμιν τὸ ἔθνος τὸ Αἰτωλικὸν ἀπέστειλαν καταστρεψάμενοι τοὺς ὁμόρους σφίσιν Ἀκαρνᾶνας.", "st": "10.16"}, {"sp": "N", "t": "παραλογώτατον δὲ ἐπυνθανόμην ὑπάρξαν Λιπαραίοις ἐς Τυρσηνούς. τοὺς γὰρ δὴ Λιπαραίους ἐναντία ναυμαχῆσαι τῶν Τυρσηνῶν ναυσὶν ὡς ἐλαχίσταις ἐκέλευσεν ἡ Πυθία. πέντε οὖν ἀνάγονται τριήρεσιν ἐπὶ τοὺς Τυρσηνούς· οἱ δὲ—ἀπηξίουν γὰρ μὴ ἀποδεῖν Λιπαραίων τὰ ναυτικά—ἀντανάγονταί σφισιν ἴσαις ναυσί. ταύτας τε οὖν αἱροῦσιν οἱ Λιπαραῖοι καὶ ἄλλας πέντε ὑστέρας σφίσιν ἀνταναχθείσας, καὶ τρίτην νεῶν πεντάδα καὶ ὡσαύτως τετάρτην ἐχειρώσαντο. ἀνέθεσαν οὖν ἐς Δελφοὺς ταῖς ἁλούσαις ναυσὶν ἀριθμὸν ἴσα Ἀπόλλωνος ἀγάλματα.", "st": "10.16"}, {"sp": "N", "t": "Ἐχεκρατίδης δὲ ἀνὴρ Λαρισαῖος τὸν Ἀπόλλωνα ἀνέθηκε τὸν μικρόν· καὶ ἁπάντων πρῶτον τεθῆναι τῶν ἀναθημάτων τοῦτό φασιν οἱ Δελφοί.", "st": "10.16"}, {"sp": "N", "t": "βαρβάρων δὲ τῶν πρὸς τῇ ἑσπέρᾳ οἱ ἔχοντες Σαρδώ, εἰκόνα οὗτοι χαλκῆν τοῦ ἐπωνύμου σφίσιν ἀπέστειλαν. ἡ δὲ Σαρδὼ μέγεθος μὲν καὶ εὐδαιμονίαν ἐστὶν ὁμοία ταῖς μάλιστα ἐπαινουμέναις· ὄνομα δὲ αὐτῇ τὸ ἀρχαῖον ὅ τι μὲν ὑπὸ τῶν ἐπιχωρίων ἐγένετο οὐκ οἶδα, Ἑλλήνων δὲ οἱ κατ’ ἐμπορίαν ἐσπλέοντες Ἰχνοῦσσαν ἐκάλεσαν, ὅτι τὸ σχῆμα τῇ νήσῳ κατ’ ἴχνος μάλιστά ἐστιν ἀνθρώπου. μῆκος δὲ [ἀπ’] αὐτῆς εἴκοσι στάδιοι καὶ ἑκατόν εἰσι καὶ χίλιοι, εὖρος δὲ ἐς εἴκοσί τε καὶ τετρακοσίους προήκει.", "st": "10.17"}, {"sp": "N", "t": "πρῶτοι δὲ διαβῆναι λέγονται ναυσὶν ἐς τὴν νῆσον Λίβυες· ἡγεμὼν δὲ τοῖς Λίβυσιν ἦν Σάρδος ὁ Μακήριδος, Ἡρακλέους δὲ ἐπονομασθέντος ὑπὸ Αἰγυπτίων τε καὶ Λιβύων. Μακήριδι μὲν δὴ αὐτῷ τὰ ἐπιφανέστατα ὁδὸς ἐγένετο ἡ ἐς Δελφούς· Σάρδῳ δὲ ἡγεμονία τε ὑπῆρξε τῶν Λιβύων ἡ ἐς τὴν Ἰχνοῦσσαν καὶ τὸ ὄνομα ἀπὸ τοῦ Σάρδου τούτου μετέβαλεν ἡ νῆσος. οὐ μέντοι τούς γε αὐτόχθονας ἐξέβαλεν ὁ τῶν Λιβύων στόλος, σύνοικοι δὲ ὑπ’ αὐτῶν οἱ ἐπελθόντες ἀνάγκῃ μᾶλλον ἢ ὑπὸ εὐνοίας ἐδέχθησαν. καὶ πόλεις μὲν οὔτε οἱ Λίβυες οὔτε τὸ γένος τὸ ἐγχώριον ἠπίσταντο ποιήσασθαι· σποράδες δὲ ἐν καλύβαις τε καὶ σπηλαίοις, ὡς ἕκαστοι τύχοιεν, ᾤκησαν.", "st": "10.17"}, {"sp": "N", "t": "ἔτεσι δὲ ὕστερον μετὰ τοὺς Λίβυας ἀφίκοντο ἐκ τῆς Ἑλλάδος ἐς τὴν νῆσον οἱ μετ’ Ἀρισταίου. παῖδα δὲ λέγουσιν Ἀρισταῖον Ἀπόλλωνός τε εἶναι καὶ Κυρήνης· ἐπὶ δὲ τοῦ Ἀκταίωνος περισσῶς ἀλγήσαντα τῇ συμφορᾷ καὶ Βοιωτίᾳ τε καὶ πάσῃ τῇ Ἑλλάδι κατὰ ταὐτὰ ἀχθόμενον, οὕτως ἐς τὴν Σαρδὼ μετοικῆσαί φασιν αὐτόν.", "st": "10.17"}, {"sp": "N", "t": "οἱ δὲ καὶ Δαίδαλον ἀποδρᾶναι τηνικαῦτα †καὶ οἴκου διὰ τὴν ἐπιστρατείαν τὴν Κρητῶν καὶ ἀποικίας ἐς τὴν Σαρδὼ μετασχεῖν τῷ Ἀρισταίῳ νομίζουσιν· ἔχοι δ’ ἂν λόγον οὐδένα Αὐτονόῃ τῇ Κάδμου συνοικήσαντι τῷ Ἀρισταίῳ Δαίδαλον ἢ ἀποικίας ἢ ἄλλου τινὸς μετεσχηκέναι, ὃς ἡλικίαν κατὰ Οἰδίποδα ἦν βασιλεύοντα ἐν Θήβαις. πόλιν δ’ οὖν οἰκίζουσιν οὐδεμίαν οὐδ’ οὗτοι, ὅτι ἀριθμῷ τε καὶ ἰσχύι ἐλάσσονες ἐμοὶ δοκεῖν ἢ κατὰ πόλεως ἦσαν οἰκισμόν.", "st": "10.17"}, {"sp": "N", "t": "μετὰ δὲ Ἀρισταῖον Ἴβηρες ἐς τὴν Σαρδὼ διαβαίνουσιν ὑπὸ ἡγεμόνι τοῦ στόλου Νώρακι, καὶ ᾠκίσθη Νώρα πόλις ὑπὸ αὐτῶν· ταύτην πρώτην γενέσθαι πόλιν μνημονεύουσιν ἐν τῇ νήσῳ, παῖδα δὲ Ἐρυθείας τε τῆς Γηρυόνου καὶ Ἑρμοῦ λέγουσιν εἶναι τὸν Νώρακα. τετάρτη δὲ μοῖρα Ἰολάου Θεσπιέων τε καὶ ἐκ τῆς Ἀττικῆς στρατιὰ κατῆρεν ἐς Σαρδώ, καὶ Ὀλβίαν μὲν πόλιν οἰκίζουσιν, ἰδίᾳ δὲ Ὀγρύλην οἱ Ἀθηναῖοι διασώζοντες τῶν δήμων τῶν οἴκοι τινὸς τὸ ὄνομα· ἢ καὶ αὐτὸς τοῦ στόλου μετεῖχεν Ὀγρύλος. ἔστι δ’ οὖν καὶ κατ’ ἐμὲ ἔτι χωρία τε Ἰολάια ἐν τῇ Σαρδοῖ καὶ Ἰόλαος παρὰ τῶν οἰκητόρων ἔχει τιμάς.", "st": "10.17"}, {"sp": "N", "t": "Ἰλίου δὲ ἁλισκομένης ἄλλοι τε ἐκφεύγουσι τῶν Τρώων καὶ οἱ ἀποσωθέντες μετὰ Αἰνείου· τούτων μοῖρα ἀπενεχθεῖσα ὑπὸ ἀνέμων ἐς Σαρδὼ ἀνεμίχθησαν τοῖς προενοικοῦσιν Ἕλλησι. καταστῆναι δὲ ἐς μάχην τῷ Ἑλληνικῷ καὶ τοῖς Τρωσὶν ἐκώλυσε τοὺς βαρβάρους· παρασκευῇ τε γὰρ ἴσοι τῇ ἁπάσῃ τὰ ἐς πόλεμον ἦσαν καὶ ὁ Θόρσος ποταμὸς διὰ μέσου σφίσι ῥέων τῆς χώρας ἐπ’ ἴσης καὶ ἀμφοτέροις διαβαίνειν παρεῖχε δέος.", "st": "10.17"}, {"sp": "N", "t": "ὕστερον μέντοι πολλοῖς ἔτεσιν οἱ Λίβυες ἐπεραιώθησάν τε αὖθις ἐς τὴν νῆσον στόλῳ μείζονι καὶ ἦρξαν ἐς τὸ Ἑλληνικὸν πολέμου. τὸ μὲν δὴ Ἑλληνικὸν ἐς ἅπαν ἐπέλαβε φθαρῆναι, ἢ ὀλίγον ἐγένετο ἐξ αὐτοῦ τὸ ὑπολειφθέν· οἱ δὲ Τρῶες ἐς τῆς νήσου τὰ ὑψηλὰ ἀναφεύγουσι, καταλαβόντες δὲ ὄρη δύσβατα ὑπὸ σκολόπων τε καὶ κρημνῶν Ἰλιεῖς μὲν ὄνομα καὶ ἐς ἐμὲ ἔτι ἔχουσι, Λίβυσι μέντοι τὰς μορφὰς καὶ τῶν ὅπλων τὴν σκευὴν καὶ ἐς τὴν πᾶσαν δίαιταν ἐοίκασιν.", "st": "10.17"}, {"sp": "N", "t": "ἔστι δὲ νῆσος οὐ πολὺ ἀπέχουσα τῆς Σαρδοῦς, Κύρνος ὑπὸ Ἑλλήνων, ὑπὸ δὲ Λιβύων τῶν ἐνοικούντων καλουμένη Κορσική. ἐκ ταύτης μοῖρα οὐκ ἐλαχίστη στάσει πιεσθεῖσα ἀφίκετο ἐς τὴν Σαρδώ, καὶ ᾤκησαν τῆς χώρας ἀποτεμόμενοι τῆς ἐν τοῖς ὄρεσιν· ὑπὸ μέντοι τῶν ἐν τῇ Σαρδοῖ τῷ ὀνόματι ὀνομάζονται τῷ οἴκοθεν Κορσοί.", "st": "10.17"}, {"sp": "N", "t": "Καρχηδόνιοι δὲ ὅτε ναυτικῷ μάλιστα ἴσχυσαν, κατεστρέψαντο μὲν καὶ ἅπαντας τοὺς ἐν τῇ Σαρδοῖ πλὴν Ἰλιέων τε καὶ Κορσῶν—τούτοις δὲ μὴ ἐς δουλείαν ὑπαχθῆναι τὸ ἐχυρὸν ἤρκεσε τῶν ὀρῶν—, ᾤκισαν δὲ ἐν τῇ νήσῳ καὶ αὐτοὶ πόλιν οἱ Καρχηδόνιοι Κάραλίν τε καὶ Σύλκους. τοῦ δὲ ἐπικουρικοῦ τῶν Καρχηδονίων Λίβυες ἢ Ἴβηρες ἐς ἀμφισβήτησιν λαφύρων ἀφικόμενοι καὶ ὡς εἶχον ὀργῆς ἀποστάντες ἐσῳκίσαντο ἐς τὰ ὑψηλὰ καὶ οὗτοι τῆς νήσου. Βαλαροὶ τὸ ὄνομά ἐστιν αὐτοῖς κατὰ γλῶσσαν τὴν Κυρνίων· Βαλαροὺς γὰρ τοὺς φυγάδας καλοῦσιν οἱ Κύρνιοι.", "st": "10.17"}, {"sp": "N", "t": "γένη μὲν τοσαῦτα τὴν Σαρδὼ καὶ ἐσῳκισμένα οὕτω νέμεται, τῆς δὲ νήσου τὰ πρὸς τῆς ἄρκτου καὶ ἠπείρου τῆς κατὰ Ἰταλίαν ἐστὶν ὄρη δύσβατα τὰ πέρατα συνάπτοντα ἀλλήλοις· καὶ ἢν παραπλέῃς, ναυσὶν ⟨οὔ⟩τε ὅρμους παρέχεται κατὰ τοῦτο ἡ νῆσος πνεύματά τε ἄτακτα καὶ ἰσχυρὰ αἱ ἄκραι τῶν ὀρῶν καταπέμπουσιν ἐς τὴν θάλασσαν.", "st": "10.17"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλα διὰ μέσης αὐτῆς ὄρη χθαμαλώτερα. ὁ δὲ ἀὴρ ὁ ἐνταῦθα θολερός τε ὡς ἐπίπαν ἐστὶ καὶ νοσώδης· αἴτιοι δὲ οἵ τε ἅλες οἱ πηγνύμενοι καὶ ὁ νότος βαρὺς καὶ βίαιος ἐγκείμενος, οἱ ἄνεμοί τε οἱ ἀπὸ τῆς ἄρκτου διὰ τὸ ὑψηλὸν τῶν ὀρῶν τῶν πρὸς τῆς Ἰταλίας κωλύονται πνέοντες θέρους ὥρᾳ τόν τε ἀέρα τὸν ταύτῃ καὶ τὴν γῆν ἀναψύχειν. οἱ δὲ τὴν Κύρνον σταδίους φασὶν οὐ πλέονας ἀπὸ τῆς Σαρδοῦς ἢ ὀκτὼ τῇ θαλάσσῃ διείργεσθαι, ὀρεινήν τε οὖσαν καὶ ἐς ὕψος διὰ πάσης ἀνήκουσαν· τὸν Ζέφυρον οὖν καὶ Βορέαν ὑπὸ τῆς Κύρνου κωλύεσθαι νομίζουσι μὴ καὶ ἄχρι τῆς Σαρδοῦς ἐξικνεῖσθαι.", "st": "10.17"}, {"sp": "N", "t": "ὄφεις δὲ οὔτε ἐπὶ συμφορᾷ τῇ ἀνθρώπων οὔτε ὅσον ἀνώλεθρον αὐτῶν, οὐδὲ οἱ λύκοι τρέφεσθαι πεφύκασιν. οἱ δὲ τράγοι [ἄγριοι] μέγεθος μὲν τοὺς ἑτέρωθι οὐχ ὑπερβάλλουσιν, εἶδος δέ ἐστιν αὐτοῖς ὁποῖον ἐν πλαστικῇ τις ἂν τῇ Αἰγιναίᾳ ποιήσειεν ἀγρίου κριοῦ· τὰ μέντοι ἀμφὶ τὸ στῆθος δασύτερά ἐστιν αὐτοῖς ἢ ὡς πρὸς Αἰγιναίαν τέχνην εἰκάσαι· κέρατα δὲ οὐ διεστηκότα ἀπὸ τῆς κεφαλῆς, ἀλλὰ ἐς εὐθὺ παρὰ τὰ ὦτα ἔχουσιν ἐληλιγμένα· ὠκύτητι δὲ ἅπαντα τὰ θηρία ὑπερήρκασι.", "st": "10.17"}, {"sp": "N", "t": "πλὴν δὲ ἢ βοτάνης μιᾶς καθαρεύει καὶ ἀπὸ φαρμάκων ἡ νῆσος ὅσα ἐργάζεται θάνατον· ἡ πόα δὲ ἡ ὀλέθριος σελίνῳ μέν ἐστιν ἐμφερής, τοῖς φαγοῦσι δὲ γελῶσιν ἐπιγίνεσθαι τὴν τελευτὴν λέγουσιν. ἐπὶ τούτῳ δὲ Ὅμηρός τε καὶ οἱ ἔπειτα ἄνθρωποι τὸν ἐπὶ οὐδενὶ ὑγιεῖ Σαρδάνιον γέλωτα ὀνομάζουσι. φύεται δὲ μάλιστα ἡ πόα περὶ τὰς πηγάς, οὐ μέντοι μεταδίδωσί γε καὶ τῷ ὕδατι τοῦ ἰοῦ. τὸν μὲν δὴ περὶ τῆς Σαρδοῦς λόγον ἐπεισηγαγόμεθα ἐς τὴν Φωκίδα συγγραφήν, ὅτι οὐχ ἥκιστα καὶ ἐς ταύτην οἱ Ἕλληνες τὴν νῆσον ἀνηκόως εἶχον·", "st": "10.17"}, {"sp": "N", "t": "τὸν δὲ ἵππον, ὃς ἐφεξῆς τῇ εἰκόνι ἐστὶ τοῦ Σάρδου, Ἀθηναῖος Καλλίας Λυσιμαχίδου πατρὸς ἀναθεῖναί φησιν ἰδίᾳ περιποιησάμενος ἀπὸ τοῦ πρὸς Πέρσας πολέμου χρήματα. Ἀχαιοὶ δὲ ἀνέθεσαν Ἀθηνᾶς ἄγαλμα πόλιν τῶν ἐν Αἰτωλίᾳ παραστησάμενοι πολιορκίᾳ· τῇ πόλει δὲ ἣν εἷλον Φάνα τοὔνομα ἦν. γενέσθαι δὲ χρόνον φασὶν οὐκ ὀλίγον τῇ πολιορκίᾳ· καὶ ὡς ἀδυνάτως εἶχον ἑλεῖν τὴν πόλιν, θεωροὺς ἀποστέλλουσιν ἐς Δελφούς, καὶ αὐτοῖς ἀφίκετο μάντευμα·", "st": "10.18"}, {"sp": "N", "t": "γῆς Πέλοπος ναέται καὶ Ἀχαιίδος, οἳ ποτὶ Πυθώ<br>ἤλθετε πευσόμενοι ὥς κε πτολίεθρον ἕλητε,<br>ἀλλ’ ἄγε δὴ φράζεσθε λάχος πόσον ἦμαρ ἕκαστον<br>λαῶν πινόντων ῥύεται πόλιν, ἡ δὲ πέπωκεν·<br>οὕτω γάρ κεν ἕλοιτε Φάναν πυργήρεα κώμην.", "st": "10.18"}, {"sp": "N", "t": "οὐ συνιέντες οὖν ὁποῖόν τι ἤθελεν ὁ χρησμὸς λέγειν, οἱ μὲν οἴκαδε ἀποπλεῖν ἐβουλεύοντο διαλύσαντες τὴν πολιορκίαν, οἱ δὲ ἐντὸς τοῦ τείχους οἵ τε ἄλλοι οὐδενὶ λόγῳ σφᾶς ἐνεποιοῦντο καὶ γυνὴ πρόεισιν ἐκ τοῦ τείχους ὕδωρ ἐκ τῆς ὑπὸ τῷ τείχει λαβεῖν πίδακος. ἐπιδραμόντες δὲ ἐκ τοῦ στρατεύματος αἰχμάλωτόν τε τὴν γυναῖκα αἱροῦσι καὶ διδάσκονται παρ’ αὐτῆς οἱ Ἀχαιοὶ ὅτι τὸ ὀλίγον τὸ ἐκ τῆς πίδακος ὕδωρ, ὁπότε ἐφ’ ἑκάστης λάβοιεν τῆς νυκτός, διεμετροῦντο αὐτό, καὶ ἄλλο ἦν τοῖς ἔνδον ἀλέξημα οὐδὲν ἐς δίψαν. οὕτω δὴ συγχέαντες οἱ Ἀχαιοὶ τὴν πηγὴν τὸ πόλισμα αἱροῦσιν.", "st": "10.18"}, {"sp": "N", "t": "Ῥόδιοι δὲ οἱ ἐν Λίνδῳ παρὰ ταύτην τὴν Ἀθηνᾶν τὸ ἄγαλμα ἔστησαν τοῦ Ἀπόλλωνος. ἀνέθεσαν δὲ καὶ Ἀβρακιῶται χαλκοῦν ὄνον, νυκτομαχίᾳ Μολοσσοὺς νικήσαντες. λόχον μέν σφισιν ἐν νυκτὶ οἱ Μολοσσοὶ παρεσκεύασαν· ὄνου δέ, ὃς ἐλαυνόμενος ἐκ τοῦ ἀγροῦ τότε ἔτυχεν, ὄνον θήλειαν διώκοντος σὺν ὕβρει τε τῇ ἄλλῃ καὶ τραχύτητι τοῦ φθέγματος, ὡσαύτως δὲ καὶ τοῦ ἀνδρὸς ὃς τὸν ὄνον ἤλαυνε βοῶντος ἀσαφῆ τε καὶ ἄκοσμα, οὕτως οἵ τε ἐκ τῆς ἐνέδρας τῶν Μολοσσῶν ἐξανίστανται ταραχθέντες καὶ οἱ Ἀμβρακιῶται φωράσαντες τὰ ἐπὶ σφίσι βεβουλευμένα ἐπιχειροῦσιν ἐν τῇ νυκτί, καὶ ἐκράτησαν μάχῃ τῶν Μολοσσῶν.", "st": "10.18"}, {"sp": "N", "t": "Ὀρνεᾶται δὲ οἱ ἐν τῇ Ἀργολίδι πολέμῳ σφᾶς Σικυωνίων πιεζόντων τῷ Ἀπόλλωνι εὔξαντο, εἰ ἀπώσαιντο ἐκ τῆς πατρίδος τῶν Σικυωνίων τὸν στρατόν, πομπήν τε ἐν Δελφοῖς αὐτῷ στελεῖν ὁσημέραι καὶ ἱερεῖα θύσειν οἷα δὴ καὶ ὅσα ἀριθμόν. νικῶσί τε δὴ μάχῃ τοὺς Σικυωνίους, καὶ ὥς σφισιν ἐφ’ ἡμέρας πάσης ἀποδιδοῦσι τὰ κατὰ τὴν εὐχὴν δαπάνη τε ἦν μεγάλη καὶ μείζων ἔτι τοῦ ἀναλώματος ἡ ταλαιπωρία, οὕτω δὴ σόφισμα εὑρίσκουσιν ἀναθεῖναι τῷ θεῷ θυσίαν τε καὶ πομπὴν χαλκᾶ ποιήματα.", "st": "10.18"}, {"sp": "N", "t": "ἔστιν ἐνταῦθα καὶ ἄθλων τῶν Ἡρακλέους τὸ ἐς τὴν ὕδραν, ἀνάθημά τε ὁμοῦ Τισαγόρου καὶ τέχνη, σιδήρου καὶ ἡ ὕδρα καὶ ὁ Ἡρακλῆς. σιδήρου δὲ ἐργασίαν τὴν ἐπὶ ἀγάλμασι χαλεπωτάτην καὶ πόνου συμβέβηκεν εἶναι πλείστου· θαύματος μὲν δὴ καὶ τοῦ Τισαγόρου τὸ ἔργον, ὅστις δὴ ὁ Τισαγόρας, θαύματος δὲ οὐκ ἐλαχίστου καὶ ἐν Περγάμῳ λέοντός τε καὶ ὑὸς ἀγρίου κεφαλαί, σιδήρου καὶ αὗται· Διονύσῳ δὲ ἀναθήματα σφᾶς ἐποιήσαντο.", "st": "10.18"}, {"sp": "N", "t": "Φωκέων δὲ οἱ ἔχοντες Ἐλάτειαν—ἀντέσχον γὰρ τῇ Κασσάνδρου πολιορκίᾳ Ὀλυμπιοδώρου σφίσιν ἐξ Ἀθηνῶν ἀμύνοντος—λέοντα τῷ Ἀπόλλωνι χαλκοῦν ἀποπέμπουσιν ἐς Δελφούς. ὁ δὲ Ἀπόλλων ὁ ἐγγυτάτω τοῦ λέοντος Μασσαλιωτῶν ἐστιν ἀπὸ τῆς πρὸς Καρχηδονίους ἀπαρχὴ ναυμαχίας. πεποίηται δὲ ὑπὸ Αἰτωλῶν τρόπαιόν τε καὶ γυναικὸς ἄγαλμα ὡπλισμένης, ἡ Αἰτωλία δῆθεν· ταῦτα ἀνέθεσαν ἐπιθέντες οἱ Αἰτωλοὶ Γαλάταις δίκην ὠμότητος ⟨τῆς⟩ ἐς Καλλιέας. ἐπίχρυσος δὲ εἰκών, ἀνάθημα Γοργίου τοῦ ἐκ Λεοντίνων, αὐτὸς Γοργίας ἐστίν [εἰκών].", "st": "10.18"}, {"sp": "N", "t": "παρὰ δὲ τὸν Γοργίαν ἀνάθημά ἐστιν Ἀμφικτυόνων Σκιωναῖος Σκύλλις, ὃς καταδῦναι καὶ ἐς τὰ βαθύτατα θαλάσσης πάσης ἔχει φήμην· ἐδιδάξατο δὲ καὶ Ὕδναν τὴν θυγατέρα δύεσθαι.", "st": "10.19"}, {"sp": "N", "t": "οὗτοι περὶ τὸ ὄρος τὸ Πήλιον ἐπιπεσόντος ναυτικῷ τῷ Ξέρξου βιαίου χειμῶνος προσεξειργάσαντό σφισιν ἀπώλειαν, τάς τε ἀγκύρας καὶ εἰ δή τι ἄλλο ἔρυμα ταῖς τριήρεσιν ἦν ὑφέλκοντες. ἀντὶ τούτου μὲν οἱ Ἀμφικτύονες καὶ αὐτὸν Σκύλλιν καὶ τὴν παῖδα ἀνέθεσαν· ἐν δὲ τοῖς ἀνδριᾶσιν ὁπόσους Νέρων ἔλαβεν ἐκ Δελφῶν, ἐν τούτοις τὸν ἀριθμὸν καὶ τῆς Ὕδνης ἀπεπλήρωσεν ἡ εἰκών. [καταδύονται δὲ ἐς θάλασσαν γένους τοῦ θήλεος αἱ καθαρῶς ἔτι παρθένοι.]", "st": "10.19"}, {"sp": "N", "t": "τὸ ἀπὸ τούτου δὲ ἔρχομαι διηγησόμενος λόγον Λέσβιον. ἁλιεῦσιν ἐν Μηθύμνῃ τὰ δίκτυα ἀνείλκυσεν ἐκ θαλάσσης πρόσωπον ἐλαίας ξύλου πεποιημένον· τοῦτο ἰδέαν παρείχετο φέρουσαν μὲν [τοι] ἐς τὸ θεῖον, ξένην δὲ καὶ ἐπὶ θεοῖς Ἑλληνικοῖς οὐ καθεστῶσαν. εἴροντο οὖν οἱ Μηθυμναῖοι τὴν Πυθίαν ὅτου θεῶν ἢ καὶ ἡρώων ἐστὶν ἡ εἰκών· ἡ δὲ αὐτοὺς σέβεσθαι Διόνυσον Φαλλῆνα ἐκέλευσεν. ἐπὶ τούτῳ οἱ Μηθυμναῖοι ξόανον μὲν τὸ ἐκ τῆς θαλάσσης παρὰ σφίσιν ἔχοντες καὶ θυσίαις καὶ εὐχαῖς τιμῶσι, χαλκοῦν δὲ ἀποπέμπουσιν ἐς Δελφούς.", "st": "10.19"}, {"sp": "N", "t": "τὰ δὲ ἐν τοῖς ἀετοῖς, ἔστιν Ἄρτεμις καὶ Λητὼ καὶ Ἀπόλλων καὶ Μοῦσαι δύσις τε Ἡλίου καὶ Διόνυσός τε καὶ αἱ γυναῖκες αἱ Θυιάδες. τὰ μὲν δὴ πρῶτα αὐτῶν Ἀθηναῖος Πραξίας μαθητὴς Καλάμιδός ἐστιν ⟨ὁ⟩ ἐργασάμενος· χρόνου δὲ ὡς ὁ ναὸς ἐποιεῖτο ἐγγινομένου Πραξίαν μὲν ἔμελλεν ἀπάξειν τὸ χρεών, τὰ δὲ ὑπολειπόμενα τοῦ ἐν τοῖς ἀετοῖς κόσμου ἐποίησεν Ἀνδροσθένης, γένος μὲν καὶ οὗτος Ἀθηναῖος, μαθητὴς δὲ Εὐκάδμου. ὅπλα δὲ ἐπὶ τῶν ἐπιστυλίων χρυσᾶ, Ἀθηναῖοι μὲν τὰς ἀσπίδας ἀπὸ τοῦ ἔργου τοῦ Μαραθῶνι ἀνέθεσαν, Αἰτωλοὶ δὲ τά τε ὄπισθεν καὶ τὰ ἐν ἀριστερᾷ Γαλατῶν δὴ ὅπλα· σχῆμα δὲ αὐτῶν ἐστιν ἐγγυτάτω τῶν Περσικῶν γέρρων.", "st": "10.19"}, {"sp": "N", "t": "Γαλατῶν δὲ τῆς ἐς τὴν Ἑλλάδα ἐπιστρατείας ἔχει μέν τινα μνήμην καὶ ἡ ἐς τὸ βουλευτήριον ἡμῖν τὸ Ἀττικὸν συγγραφή· προάγειν δὲ ἐς τὸ σαφέστερον τὰ ἐς αὐτοὺς ἠθέλησα ἐν τῷ λόγῳ τῷ ἐς Δελφούς, ὅτι ἔργων τῶν ἐπὶ τοὺς βαρβάρους τὰ μέγιστα Ἕλλησιν ἐνταῦθα ἦν. ὑπερόριον μὲν οἱ Κελτοὶ στρατείαν πρώτην ὑπὸ ἡγεμόνι ἐποιήσαντο Καμβαύλῃ· προελθόντες δὲ ἄχρι τῆς Θρᾴκης τὸ πρόσω τῆς πορείας οὐκ ἀπεθάρσησαν, καταγνόντες αὑτῶν ὅτι ὀλίγοι τε ἦσαν καὶ οὐκ ἀξιόμαχοι κατ’ ἀριθμὸν Ἕλλησιν.", "st": "10.19"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ δεύτερον ἐπιφέρειν ἐδόκει ὅπλα ἐπὶ τὴν ἄλλων— ἐνῆγον δὲ μάλιστα οἱ ὁμοῦ Καμβαύλῃ ἐκστρατεύσαντες ἅτε λῃστειῶν τε ἤδη γεγευμένοι καὶ ἁρπαγῆς καὶ κερδῶν ἐς ἔρωτα ἥκοντες—, πολὺς μὲν δὴ πεζός, οὐκ ἐλάχιστοι δὲ ἠθροίσθησαν καὶ ἐς τὸ ἱππικόν· ἐς μοίρας οὖν τρεῖς ἔνεμον οἱ ἡγεμόνες τὸν στρατόν, καὶ ἄλλος ἐξ αὐτῶν ἐπὶ ἄλλην ἐτέτακτο ἰέναι χώραν.", "st": "10.19"}, {"sp": "N", "t": "ἐπὶ μὲν οὖν Θρᾷκας καὶ τὸ ἔθνος τὸ Τριβαλλῶν ἔμελλε Κερέθριος ἡγήσεσθαι· τοῖς δὲ ἐς Παιονίαν ἰοῦσι Βρέννος ἦσαν καὶ Ἀκιχώριος ἄρχοντες· Βόλγιος δὲ ἐπὶ Μακεδόνας τε καὶ Ἰλλυριοὺς ἤλασε, καὶ ἐς ἀγῶνα πρὸς Πτολεμαῖον κατέστη τότε ἔχοντα τὴν Μακεδόνων βασιλείαν. Πτολεμαῖος δὲ ἦν οὗτος ὃς Σέλευκόν τε ἐδολοφόνησε τὸν Ἀντιόχου, καταπεφευγὼς ὅμως ἱκέτης ὡς αὐτόν, καὶ εἶχεν ἐπίκλησιν Κεραυνὸς διὰ τὸ ἄγαν τολμηρόν. καὶ ὁ μὲν αὐτός τε ὁ Πτολεμαῖος ἀπέθανεν ἐν τῇ μάχῃ καὶ τῶν Μακεδόνων ἐγένετο οὐκ ἐλαχίστη φθορά· προελθεῖν δὲ ὡς ἐπὶ τὴν Ἑλλάδα οὐδὲ τότε ἐθάρσησαν οἱ Κελτοί, καὶ ὁ δεύτερος οὕτω στόλος ἐπανῆλθεν ἐς τὴν οἰκείαν.", "st": "10.19"}, {"sp": "N", "t": "ἔνθα δὴ ὁ Βρέννος πολὺς μὲν ἐν συλλόγοις τοῖς κοινοῖς, πολὺς δὲ καθ’ ἕκαστον ἦν τῶν ἐν τέλει Γαλατῶν ἐπὶ τὴν Ἑλλάδα ἐπαίρων στρατεύεσθαι, ἀσθένειάν τε Ἑλλήνων τὴν ἐν τῷ παρόντι διηγούμενος καὶ ὡς χρήματα πολλὰ μὲν ἐν τῷ κοινῷ, πλείονα δὲ ἐν ἱεροῖς τά τε ἀναθήματα καὶ ἄργυρος καὶ χρυσός ἐστιν ἐπίσημος· ἀνέπεισέ τε δὴ τοὺς Γαλάτας ἐλαύνειν ἐπὶ τὴν Ἑλλάδα, καὶ αὑτῷ συνάρχοντας ἄλλους τε προσείλετο τῶν ἐν τέλει καὶ τὸν Ἀκιχώριον.", "st": "10.19"}, {"sp": "N", "t": "ὁ δὲ ἀθροισθεὶς στρατὸς πεζοὶ μὲν μυριάδες ἐγένοντο πεντεκαίδεκα προσόντων σφίσι δισχιλίων, οἱ δὲ ἱππεύοντες τετρακόσιοι καὶ δισμύριοι. τοσοῦτοι μὲν ἦσαν τῶν ἱππέων τὸ ἀεὶ ἐνεργόν, ἀριθμὸς δὲ αὐτῶν ὁ ἀληθὴς διακόσιοί τε καὶ χίλιοι καὶ ἓξ μυριάδες· δύο γὰρ οἰκέται περὶ ἕκαστον τῶν ἱππευόντων ἦσαν, ἀγαθοὶ καὶ αὐτοὶ τὰ ἱππικὰ καὶ ἵππους ὁμοίως ἔχοντες.", "st": "10.19"}, {"sp": "N", "t": "Γαλατῶν δὲ τοῖς ἱππεύουσιν ἀγῶνος συνεστηκότος ὑπομένοντες τῆς τάξεως ὄπισθεν οἱ οἰκέται τοσάδε σφίσιν ἐγίνοντο χρήσιμοι· τῷ γὰρ ἱππεῖ συμβὰν ἢ τῷ ἵππῳ πεσεῖν, τὸν μὲν ἵππον παρεῖχεν ἀναβῆναι τῷ ἀνδρί, τελευτήσαντος δὲ τοῦ ἀνδρὸς ὁ δοῦλος ἀντὶ τοῦ δεσπότου τὸν ἵππον ἀνέβαινεν· εἰ δὲ ἀμφοτέρους ἐπιλάβοι τὸ χρεών, ἐνταῦθα ἕτοιμος ἦν ἱππεύς. λαμβανόντων δὲ τραύματα αὐτῶν, ὁ μὲν ὑπεξῆγε τῶν δούλων ἐς τὸ στρατόπεδον τὸν τραυματίαν, ὁ δὲ καθίστατο ἐς τὴν τάξιν ἀντὶ τοῦ ἀπελθόντος.", "st": "10.19"}, {"sp": "N", "t": "ταῦτα ἐμοὶ δοκεῖν ἐνομίσθη τοῖς Γαλάταις ⟨ἐς⟩ μίμησιν τοῦ ἐν Πέρσαις ἀριθμοῦ τῶν μυρίων, οἳ ἐκαλοῦντο Ἀθάνατοι. διάφορα δὲ ἦν, ὅτι κατελέγοντο ἀντὶ τῶν ἀποθνησκόντων ὑπὸ μὲν Περσῶν τῆς μάχης ὕστερον, Γαλάταις δὲ ὑπ’ αὐτὴν τοῦ ἔργου τὴν ἀκμὴν ὁ ἀριθμὸς ἀπεπληροῦτο τῶν ἱππέων. τοῦτο ὠνόμαζον τὸ σύνταγμα τριμαρκισίαν τῇ ἐπιχωρίῳ φωνῇ· καὶ ἵππῳ τὸ ὄνομα ἴστω τις μάρκαν ὂν τὰ ὑπὸ τῶν Κελτῶν.", "st": "10.19"}, {"sp": "N", "t": "παρασκευῇ μὲν τοσαύτῃ καὶ μετὰ διανοίας τοιαύτης ἐπὶ τὴν Ἑλλάδα ὁ Βρέννος ἤλαυνε· τοῖς δέ γε Ἕλλησι κατεπεπτώκει μὲν ἐς ἅπαν τὰ φρονήματα, τὸ δὲ ἰσχυρὸν τοῦ δείματος προῆγεν ἐς ἀνάγκην τῇ Ἑλλάδι ἀμύνειν. ἑώρων δὲ τὸν ἐν τῷ παρόντι ἀγῶνα οὐχ ὑπὲρ ἐλευθερίας γενησόμενον, καθὰ ἐπὶ τοῦ Μήδου ποτέ, οὐδὲ δοῦσιν ὕδωρ καὶ γῆν τὰ ἀπὸ τούτου σφίσιν ἄδειαν φέροντα· ἀλλὰ τά τε ἐς Μακεδόνας καὶ Θρᾷκας καὶ Παίονας τὰ ἐπὶ τῆς προτέρας καταδρομῆς τῶν Γαλατῶν ἔτι σφίσιν ἔκειτο ἐν μνήμῃ, καὶ τὰ ἐν τῷ παρόντι τὰ ἐς Θεσσαλοὺς παρανομήματα ἀπηγγέλλετο. ὡς οὖν ἀπολωλέναι ⟨δέον⟩ ἢ [δ’ οὖν] ἐπικρατεστέρους εἶναι, κατ’ ἄνδρα τε ἰδίᾳ καὶ αἱ πόλεις διέκειντο ἐν κοινῷ.", "st": "10.19"}, {"sp": "N", "t": "πάρεστι δέ, ὅστις ἐθέλοι καὶ ἀνταριθμῆσαι τούς τε ἐπὶ βασιλέα Ξέρξην ἐς Πύλας καὶ τοὺς τότε ἐναντία Γαλατῶν ἀθροισθέντας. ἐπὶ μέν γε τὸν Μῆδον ἀφίκοντο τοσοίδε Ἑλλήνων· Λακεδαιμόνιοι οἱ μετὰ Λεωνίδου τριακοσίων οὐ πλείονες, Τεγεᾶται πεντακόσιοι καὶ ἐκ Μαντινείας ἴσοι, παρὰ δὲ Ὀρχομενίων Ἀρκάδων εἴκοσί τε καὶ ἑκατόν, ἀπὸ δὲ τῶν ἄλλων χίλιοι τῶν ἐν Ἀρκαδίᾳ πόλεων, ὀγδοήκοντα δὲ ἐκ Μυκηνῶν καὶ ἐκ Φλιοῦντος διακόσιοι, διπλάσιοι δὲ τούτων Κορίνθιοι· παρεγένοντο δὲ καὶ Βοιωτῶν ἑπτακόσιοι ἐκ [δὲ] Θεσπείας καὶ ⟨ἐκ⟩ Θηβῶν τετρακόσιοι. χίλιοι δὲ Φωκέων ἐφύλασσον μὲν τὴν ἀτραπὸν ἐν τῇ Οἴτῃ, προσέστω δὲ τῷ παντὶ Ἑλληνικῷ καὶ ὁ ἀριθμὸς ὁ τούτων.", "st": "10.20"}, {"sp": "N", "t": "Λοκροὺς δὲ τοὺς ὑπὸ τῷ ὄρει τῇ Κνήμιδι Ἡρόδοτος μὲν οὐχ ὑπήγαγεν ἐς ἀριθμόν, ἀλλ’ ἀφικέσθαι σφᾶς ἀπὸ πασῶν ἔφη τῶν πόλεων· τεκμήρασθαι δὲ ἀριθμὸν καὶ τούτων ἔστιν ἐγγύτατα τοῦ ἀληθοῦς· ἐς Μαραθῶνα γὰρ Ἀθηναῖοι σὺν ἡλικίᾳ τε τῇ ἀχρείῳ καὶ δούλοις ἐνακισχιλίων ἀφίκοντο οὐ πλείους, τὸ οὖν μάχιμον Λοκρῶν τὸ ἐς Θερμοπύλας ἐλθὸν οὐκ ἂν ὑπέρ γε ἑξακισχιλίους ἀριθμοίη τις. οὕτω γένοιτο ἂν ὁ σύμπας στρατὸς διακόσιοι καὶ χίλιοι καὶ μύριοι. φαίνονται δὲ οὐδὲ οὗτοι τὸν χρόνον πάντα ἐπὶ τῇ φρουρᾷ τῶν Πυλῶν καταμείναντες· πλὴν γὰρ Λακεδαιμονίων τε αὐτῶν καὶ Θεσπιέων καὶ Μυκηναίων προαπέλιπον τὸ πέρας τῆς μάχης οἱ λοιποί.", "st": "10.20"}, {"sp": "N", "t": "ἐπὶ δὲ τοὺς ἀπὸ τοῦ Ὠκεανοῦ βαρβάρους τοσοίδε ἐς Θερμοπύλας ἀφίκοντο Ἕλληνες· ὁπλῖται μύριοι καὶ ἵππος πεντακοσία παρὰ Βοιωτῶν· ἐβοιωτάρχουν δὲ Κηφισόδοτος καὶ Θεαρίδας καὶ Διογένης καὶ Λύσανδρος. ἐκ δὲ Φωκέων ἱππεῖς πεντακόσιοι καὶ ἐς τρισχιλίους ὁ ἀριθμὸς τῶν πεζῶν· στρατηγοὶ δὲ Φωκέων Κριτόβουλός τε ἦν καὶ Ἀντίοχος.", "st": "10.20"}, {"sp": "N", "t": "Λοκροὺς δὲ τοὺς ἐπὶ Ἀταλάντῃ τῇ νήσῳ Μειδίας ἦγεν· ἀριθμὸς δὲ αὐτῶν ἑπτακόσιοι, καὶ ἱππικόν σφισιν οὐ προσῆν. παρὰ δὲ Μεγαρέων ἀφίκοντο ὁπλῖται τετρακόσιοι· τούτων ἦγε τὸ †ἱππικὸν Μεγαρεύς. Αἰτωλῶν δὲ πλείστη τε ἐγένετο στρατιὰ καὶ ἐς πᾶσαν μάχης ἰδέαν, ἡ μὲν ἵππος οὐ λέγουσιν ὁπόση, ψιλοὶ δὲ ἐνενήκοντα καὶ ⟨ἑπτακόσιοι, πλέονες δὲ⟩ ἑπτακισχιλίων ἀριθμὸν ἦσαν οἱ ὁπλιτεύοντες· Αἰτωλοὺς δὲ ἦγον Πολύαρχος καὶ Πολύφρων τε καὶ Λακράτης.", "st": "10.20"}, {"sp": "N", "t": "Ἀθηναίων δὲ στρατηγὸς μὲν Κάλλιππος ἦν ὁ Μοιροκλέους, καθὰ ἐδήλωσα καὶ ἐν τοῖς προτέροις τοῦ λόγου, δύναμις δὲ τριήρεις τε ⟨αἱ⟩ πλώιμοι πᾶσαι, πεντακόσιοι δὲ ἐς τὸ ἱππικόν, χίλιοι δὲ ἐτάσσοντο ἐν τοῖς πεζοῖς· καὶ ἡγεμονίαν οὗτοι κατ’ ἀξίωμα εἶχον τὸ ἀρχαῖον. βασιλέων δὲ ξενικὰ πεντακόσιοί τε ἐκ Μακεδονίας καὶ ἐκ τῆς Ἀσίας ἴσοι σφίσιν ἀφίκοντο ἀριθμόν· ἄρχοντες δὲ τῶν μὲν παρ’ Ἀντιγόνου πεμφθέντων Ἀριστόδημος ἦν Μακεδών, τῶν δὲ παρὰ Ἀντιόχου τε καὶ ἐκ τῆς Ἀσίας Τελέσαρχος τῶν ἐπὶ Ὀρόντῃ Σύρων.", "st": "10.20"}, {"sp": "N", "t": "τοῖς δὲ ἐς Θερμοπύλας ἀθροισθεῖσιν Ἑλλήνων, ὡς ἐπύθοντο περί τε Μαγνησίαν καὶ γῆν τὴν Φθιῶτιν ὄντα ἤδη τῶν Γαλατῶν τὸν στρατόν, ἔδοξεν ἤδη ψιλούς τε ἐς χιλίους καὶ [ἐς] τὴν ἵππον ἀπολέξαντας ἀποστεῖλαι σφᾶς ἐπὶ τὸν Σπερχειόν, ἵνα μηδὲ τὸν ποταμὸν διαβῆναι τοῖς βαρβάροις ἄνευ ἀγῶνός τε καὶ κινδύνων ἐγγένηται. οἱ δὲ ἐλθόντες τὰς γεφύρας τε καταλύουσι καὶ αὐτοὶ παρὰ τὴν ὄχθην ἐστρατοπεδεύσαντο. ἦν δὲ οὐδὲ ὁ Βρέννος οὔτε πάντα ἀσύνετος οὔτε ἀπείρως εἶχεν ὡς ἄν τις βάρβαρος σοφίσματα ἐς πολεμίους ἐξευρεῖν.", "st": "10.20"}, {"sp": "N", "t": "εὐθὺς οὖν τῇ ἐπιούσῃ νυκτί, οὐ καθότι ἦν τὰ ἀρχαῖα τῷ ποταμῷ ζεύγματα ἀλλὰ ἐς τὸ κάτω, ὡς μή τις τοῖς Ἕλλησι διαβαινόντων γένοιτο αἴσθησις, καὶ ᾗ μάλιστα ὁ Σπερχειὸς διεχεῖτο ἐς πλέον τοῦ πεδίου καὶ ἕλος τε ἐποίει καὶ λίμνην ἀντὶ βιαίου καὶ στενοῦ ῥεύματος, κατὰ τοῦτο ὁ Βρέννος ὅσον μυρίους τῶν Γαλατῶν ἀπέστειλεν, ὁπόσοι τε νεῖν ἠπίσταντο ἐξ αὐτῶν καὶ ὅστις τῷ μήκει τοῦ σώματος ἐτύγχανεν ὢν ὑπὲρ τοὺς πολλούς· εἰσὶ δὲ καὶ ἄλλως οἱ Κελτοὶ μακρῷ πάντας ὑπερηρκότες μήκει τοὺς ἀνθρώπους.", "st": "10.20"}, {"sp": "N", "t": "οὗτοι οὖν διαβαίνουσιν ἐν τῇ νυκτὶ διανηχόμενοι ὧδε τὸ λιμνῶδες τοῦ ποταμοῦ· [καὶ] τὰ ὅπλα, τοὺς ἐπιχωρίους θυρεούς, ἐποιεῖτο ἕκαστος ἀντὶ σχεδίας, οἱ δὲ αὐτῶν μήκιστοι διελθεῖν ἐμβαδὸν τὸ ὕδωρ ἐδυνήθησαν. οἱ δὲ Ἕλληνες οἱ ἐπὶ τῷ Σπερχειῷ —πυνθάνονται γὰρ ὅτι κατὰ τὸ ἕλος διέβη μοῖρα τῶν βαρβάρων—αὐτίκα ἐς τὸ στράτευμα ἀναχωροῦσι, Βρέννος δὲ τοῖς περὶ τὸν Μαλιακὸν κόλπον οἰκοῦσι ζευγνύναι τὸν Σπερχειὸν ἐπέτασσεν· οἱ δὲ ἤνυον τὸ ἔργον σπουδῇ, τῷ τε ἐκείνου δέει καὶ ἀπελθεῖν ἐκ τῆς χώρας σφίσιν ἐπιθυμοῦντες τοὺς βαρβάρους μηδὲ ἐπὶ πλέον κακουργεῖν μένοντας.", "st": "10.20"}, {"sp": "N", "t": "ὁ δὲ ὡς κατὰ τὰς γεφύρας διεβίβασε τὴν στρατιάν, ἐχώρει πρὸς τὴν Ἡράκλειαν· καὶ διήρπασαν μὲν τὰ ἐκ τῆς χώρας οἱ Γαλάται καὶ ἀνθρώπους τοὺς ἐπὶ τῶν ἀγρῶν ἐγκαταληφθέντας ἐφόνευσαν, τὴν πόλιν δὲ οὐχ εἷλον. ἔτει γὰρ πρότερον τούτων οἱ Αἰτωλοὶ συντελεῖν τοὺς Ἡρακλεώτας ἠνάγκασαν ἐς τὸ Αἰτωλικόν· τότε οὖν ἠμύνοντο ὡς περὶ πόλεως οὐδέν τι Ἡρακλεώταις μᾶλλον ἢ καὶ αὑτοῖς προσηκούσης. ἦν δὲ καὶ τῷ Βρέννῳ τὰ μὲν Ἡρακλεωτῶν ἐλάσσονος φροντίδος, ἀγώνισμα δὲ ἐποιεῖτο ἐξελάσαι τε ἐκ τῶν στενῶν τοὺς ἀντικαθημένους καὶ παρελθεῖν ἐς τὴν ἐντὸς Θερμοπυλῶν Ἑλλάδα.", "st": "10.20"}, {"sp": "N", "t": "προελθὼν οὖν ἀπὸ τῆς Ἡρακλείας—ἐπυνθάνετο γὰρ παρὰ αὐτομόλων τοὺς συνειλεγμένους ἐς Πύλας ἀπὸ ἑκάστης πόλεως— ὑπερεφρόνει τε τοῦ Ἑλληνικοῦ καὶ ἦρχεν ἐς τὴν ἐπιοῦσαν μάχης ἅμα ἀνίσχοντι τῷ ἡλίῳ, οὔτε Ἕλληνα ἔχων μάντιν οὔτε ἱεροῖς ἐπιχωρίοις χρώμενος, εἰ δὴ ἔστι γε μαντεία Κελτική. ἐνταῦθα οἱ Ἕλληνες ἐν σιγῇ τε ἐπῄεσαν καὶ ἐν κόσμῳ· καὶ ὡς ἀφίκοντο ἐς χεῖρας, οὔτε σφίσιν οἱ πεζοὶ τοσοῦτο ἀπὸ τῆς τάξεως ἐξέθεον ὥστε τὴν φάλαγγα ἐπιταράσσειν τὴν οἰκείαν καὶ οἱ ψιλοὶ μένοντες κατὰ χώραν τά τε ἀκόντια ἔπεμπον καὶ ὅσα ἀπὸ τῶν τόξων ἢ σφενδονῶν.", "st": "10.21"}, {"sp": "N", "t": "τὰ δὲ ἱππικὰ ἀμφοτέροις ἀχρεῖα ἐγένετο ἅτε οὐ στενοῦ μόνον χωρίου τοῦ μετὰ τὰς Πύλας ὄντος ἀλλὰ καὶ ὑπὸ αὐτοφυοῦς πέτρας λείου καὶ διὰ τῶν ῥευμάτων τὸ συνεχὲς τὰ πλείονα καὶ ὀλισθηροῦ. τοῖς δὲ Γαλάταις τὰ μὲν τῆς σκευῆς ἀσθενέστερα ἦν—θυρεοὺς γὰρ τοὺς ἐπιχωρίους εἶχον, καὶ ἄλλο σφίσιν οὐκ ἦν ὅπλον σκέπη σώματος—, πλέον δὲ ἔτι ἐμπειρίᾳ τῇ ἐς τὰ πολεμικὰ ἀπέδεον.", "st": "10.21"}, {"sp": "N", "t": "οἱ δὲ ἐν ὀργῇ τε ἐπὶ τοὺς ἐναντίους καὶ θυμῷ μετὰ οὐδενὸς λογισμοῦ καθάπερ τὰ θηρία ἐχώρουν· καὶ οὔτε πελέκεσι διαιρουμένους ἢ ὑπὸ μαχαιρῶν ⟨ἡ⟩ ἀπόνοια τοὺς ἔτι ἐμπνέοντας [ἔτι] ἀπέλειπεν, οὔτε ὅσοι βέλεσι καὶ ἀκοντίοις διεπείροντο, ὑφῄρουν τοῦ θυμοῦ, μέχρι οὗ παρέμενεν ἡ ψυχή· οἱ δὲ καὶ ἐκ τῶν τραυμάτων τὰ δόρατα οἷς ἐβέβληντο ἀνασπῶντες ἠφίεσάν τε ἐς τοὺς Ἕλληνας καὶ ἐχρῶντο ἐκ χειρός.", "st": "10.21"}, {"sp": "N", "t": "ἐν τούτῳ δὲ οἱ ἐπὶ τῶν τριήρων Ἀθηναῖοι μόγις μὲν καὶ οὐκ ἄνευ κινδύνου, παραπλεύσαντες δὲ ὅμως διὰ τῆς ἰλύος, ⟨ἣ⟩ ἐπὶ πλεῖστον ἐπέχει τῆς θαλάσσης, καὶ τὰς ναῦς ὅτι ἐγγύτατα τῶν βαρβάρων σχόντες, βέλεσί τε παντοίοις ἐς τὰ πλάγια καὶ τοξεύμασιν ἐς αὐτοὺς ἐχρῶντο. καμνόντων δὲ λόγου μειζόνως τῶν Κελτῶν καὶ ἅτε ἐν στενοχωρίᾳ μικρὰ μὲν δρώντων, διπλάσια δὲ καὶ τετραπλάσια πασχόντων, ἀναχωρεῖν ἐς τὸ στρατόπεδον ἐσήμαινόν σφισιν ⟨οἱ⟩ ἡγεμόνες. οἱ δὲ ἀτάκτως καὶ σὺν οὐδενὶ ἀναστρέφοντες κόσμῳ πολλοὶ μὲν συνεπατήθησαν ὑπὸ ἀλλήλων, πολλοὶ δὲ ἐς τὸ τέλμα ἐμπεσόντες ἠφανίσθησαν κατὰ τοῦ πηλοῦ, καὶ ἀπώλεια οὐκ ἐλάσσων ἀναχωροῦσιν αὐτοῖς ἢ ἐν τοῦ ἀγῶνος συνέβη τῇ ἀκμῇ.", "st": "10.21"}, {"sp": "N", "t": "τοὺς μὲν δὴ Ἕλληνας τὸ Ἀττικὸν ὑπερεβάλετο ἀρετῇ τὴν ἡμέραν ταύτην· αὐτῶν δὲ Ἀθηναίων Κυδίας μάλιστα ἐγένετο ἀγαθός, νέος τε ἡλικίαν καὶ τότε ἐς ἀγῶνα ἐλθὼν πολέμου πρῶτον. ἀποθανόντος δὲ ὑπὸ τῶν Γαλατῶν τὴν ἀσπίδα οἱ προσήκοντες ἀνέθεσαν τῷ Ἐλευθερίῳ Διί, καὶ ἦν τὸ ἐπίγραμμα·<br>†ημαρλα δὴ ποθέουσα νέαν ἔτι Κυδίου ἥβην<br>ἀσπὶς ἀριζήλου φωτός, ἄγαλμα Διί,<br>ἇς διὰ δὴ πρώτας λαιὸν τότε πῆχυν ἔτεινεν,<br>εὖτ’ ἐπὶ τὸν Γαλάταν ἤκμασε θοῦρος Ἄρης.", "st": "10.21"}, {"sp": "N", "t": "τοῦτο μὲν δὴ ἐπεγέγραπτο πρὶν ἢ τοὺς ὁμοῦ Σύλλᾳ καὶ ἄλλα τῶν Ἀθήνῃσι καὶ τὰς ἐν τῇ στοᾷ τοῦ Ἐλευθερίου Διὸς καθελεῖν ἀσπίδας· τότε δὲ ἐν ταῖς Θερμοπύλαις οἱ μὲν Ἕλληνες μετὰ τὴν μάχην τούς τε αὑτῶν ἔθαπτον καὶ ἐσκύλευον τοὺς βαρβάρους, οἱ Γαλάται δὲ οὔτε ὑπὲρ ἀναιρέσεως τῶν νεκρῶν ἐπεκηρυκεύοντο ἐποιοῦντό τε ἐπ’ ἴσης γῆς σφᾶς τυχεῖν ἢ θηρία τε αὐτῶν ἐμφορηθῆναι καὶ ὅσον τεθνεῶσι πολέμιόν ἐστιν ὀρνίθων.", "st": "10.21"}, {"sp": "N", "t": "ὀλιγώρως δὲ αὐτοὺς ἐς τῶν ἀπογινομένων ἔχειν τὰς ταφὰς δύο ἐμοὶ δοκεῖν τὰ ἀναπείθοντα ἦν, πολεμίους τε ἄνδρας ἐκπλῆξαι καὶ ὅτι ἔστι τεθνεώτων οὐ δι’ ἔθους οἶκτος αὐτοῖς. ἀπέθανον δὲ παρὰ τὴν μάχην τεσσαράκοντα μὲν τοῦ Ἑλληνικοῦ, τοὺς δὲ τῶν βαρβάρων οὐχ οἷόν τε ἦν ἀκριβῶς ἐξευρεῖν· πολὺ γὰρ καὶ τὸ ἀφανισθὲν κατὰ τῆς ἰλύος ἐγένετο ἐξ αὐτῶν.", "st": "10.21"}, {"sp": "N", "t": "ἑβδόμῃ δὲ ὕστερον μετὰ τὴν μάχην λόχος τῶν Γαλατῶν ἀνελθεῖν ἐς τὴν Οἴτην ἐπεχείρησε κατὰ Ἡράκλειαν· ἀτραπὸς δὲ στενὴ καὶ ταύτῃ μετὰ [ταῦτα] τὰ ἐρείπια ἀνήκει τὰ Τραχῖνος· ἦν δὲ καὶ ἱερὸν Ἀθηνᾶς τότε ὑπὲρ τῆς ⟨πόλεως⟩ Τραχινίδος καὶ ἀναθήματα ἐν αὐτῷ. ἔς τε οὖν τὴν Οἴτην ἀναβήσεσθαι κατὰ τὴν ἀτραπὸν ἤλπιζον καὶ ἅμα προσέσεσθαί σφισιν ἐν παρέργῳ τὰ ἐκ τοῦ ἱεροῦ … τὴν φρουρὰν οἰομένου Τελεσάρχῳ. καὶ νικῶσι μὲν τοὺς βαρβάρους τῇ μάχῃ, αὐτὸς δὲ ἔπεσεν ὁ Τελέσαρχος, ἀνήρ εἴπερ τις καὶ ἄλλος πρόθυμος ἐς τὰ Ἑλλήνων.", "st": "10.22"}, {"sp": "N", "t": "οἱ μὲν δὴ ἡγεμόνες τῶν βαρβάρων οἱ ἄλλοι κατεπεπλήγεσαν τὸ Ἑλληνικόν, καὶ ἠπόρουν ἅμα ὑπὲρ τῶν μελλόντων, ἐς οὐδέν σφισι πλέον προχωροῦντα ὁρῶντες τὰ ἐν χερσί· τῷ δὲ Βρέννῳ λογισμὸς παρίστατο ὡς εἰ ἀναγκάσει τοὺς Αἰτωλοὺς οἴκαδε ἐς τὴν Αἰτωλίαν ἀναχωρῆσαι, ῥᾴων ἤδη γενήσοιτο ὁ πόλεμος αὐτῷ πρὸς τὸ Ἑλληνικόν. ἀπολέξας οὖν τῆς στρατιᾶς μυριάδας τοὺς πεζοὺς τέσσαρας καὶ ὅσον ὀκτακοσίους ἱππέας, Ὀρεστόριόν τε αὐτοῖς καὶ Κόμβουτιν ἐφίστησιν ἄρχοντας, οἳ ὀπίσω κατὰ τοῦ Σπερχειοῦ τὰς γεφύρας καὶ", "st": "10.22"}, {"sp": "N", "t": "αὖθις διὰ Θεσσαλίας ὁδεύσαντες ἐμβάλλουσιν ἐς τὴν Αἰτωλίαν· καὶ τὰ ἐς Καλλιέας Κόμβουτις οἱ ἐργασάμενοι καὶ Ὀρεστόριος ἦσαν, ἀνοσιώτατά τε ὧν ἀκοῇ ἐπιστάμεθα καὶ οὐδὲν τοῖς ἀνθρώπων τολμήμασιν ὅμοια. γένος μέν γε πᾶν ἐξέκοψαν τὸ ἄρσεν, καὶ ὁμοίως γέροντές τε καὶ τὰ νήπια ἐπὶ τῶν μητέρων τοῖς μαστοῖς ἐφονεύετο· τούτων δὲ καὶ τὰ ὑπὸ τοῦ γάλακτος πιότερα ἀποκτείνοντες ἔπινόν τε οἱ Γαλάται τοῦ αἵματος καὶ ἥπτοντο τῶν σαρκῶν.", "st": "10.22"}, {"sp": "N", "t": "γυναῖκες δὲ καὶ ὅσοι ἐν ὥρᾳ τῶν παρθένων, ὅσαι μὲν φρονήματός τι αὐτῶν εἶχον, ἑαυτὰς ἔφθησαν ὡς ἡλίσκετο ἡ πόλις διειργασμέναι· τὰς δὲ ἔτι περιούσας ἐς ἰδέαν ὕβρεως πᾶσαν μετὰ ἀνάγκης ἦγον ἰσχυρᾶς, ἅτε ἴσον μὲν ἐλέου, ἴσον δὲ τὰς φύσεις καὶ ἔρωτος ἀπέχοντες. καὶ ὅσαι μὲν τῶν γυναικῶν ταῖς μαχαίραις τῶν Γαλατῶν ἐπετύγχανον, αὐτοχειρίᾳ τὰς ψυχὰς ἠφίεσαν· ταῖς δὲ οὐ μετὰ πολὺ ὑπάρξειν τὸ χρεὼν ἔμελλεν ἥ τε ἀσιτία καὶ ἡ ἀυπνία, ἀστέγων βαρβάρων ἐκ διαδοχῆς ἀλλήλοις ὑβριζόντων· οἱ δὲ καὶ ἀφιείσαις τὰς ψυχάς, οἱ δὲ καὶ ἤδη νεκραῖς συνεγίνοντο ὅμως.", "st": "10.22"}, {"sp": "N", "t": "Αἰτωλοὶ δὲ πεπυσμένοι τε παρὰ ἀγγέλων ἦσαν ὁποῖαι σφᾶς κατειλήφεσαν συμφοραὶ καὶ αὐτίκα ὡς τάχους εἶχον ἀναστήσαντες ἀπὸ τῶν Θερμοπυλῶν τὴν δύναμιν ἠπείγοντο ἐς τὴν Αἰτωλίαν, τά τε παθήματα τῶν Καλλιέων ἐν ὀργῇ ποιούμενοι καὶ πλέον ἔτι τὰς οὐχ ἑαλωκυίας πω διασώσασθαι πόλεις προθυμούμενοι. ἐξεστρατεύοντο δὲ καὶ οἴκοθεν ἀπὸ τῶν πόλεων πασῶν οἱ ἐν ἡλικίᾳ, ἀναμεμιγμένοι δ’ ἦσαν ὑπὸ ἀνάγκης τε καὶ φρονήματος καὶ οἱ γεγηρακότες· συνεστρατεύοντο δέ σφισι καὶ αἱ γυναῖκες ἑκουσίως, πλέον ἐς τοὺς Γαλάτας καὶ τῶν ἀνδρῶν τῷ θυμῷ χρώμεναι.", "st": "10.22"}, {"sp": "N", "t": "ὡς δὲ οἱ βάρβαροι συλήσαντες τούς τε οἴκους καὶ τὰ ἱερὰ καὶ ἐνέντες πῦρ ἐς τὸ Κάλλιον ἐκομίζοντο τὴν αὐτήν, ἐνταῦθα Πατρεῖς μὲν ἐπικουροῦντες Αἰτωλοῖς Ἀχαιῶν μόνοι προσέκειντο ἐξ ἐναντίας τοῖς βαρβάροις ἅτε ὁπλιτεύειν δεδιδαγμένοι, καὶ ὑπὸ πλήθους τε τῶν Γαλατῶν καὶ τῆς ἐς τὰ ἔργα ἀπονοίας μάλιστα ἐταλαιπώρησαν· οἱ δὲ Αἰτωλοὶ καὶ αἱ γυναῖκες αἱ Αἰτωλαὶ παρὰ πᾶσαν τεταγμένοι τὴν ὁδὸν ἐσηκόντιζόν τε ἐς τοὺς βαρβάρους, καὶ οὐδὲν ἄλλο ὅτι μὴ τοὺς ἐπιχωρίους ἐχόντων θυρεοὺς ὀλίγα αὐτῶν ἡμάρτανον, διώκοντάς τε ἀπέφευγον οὐ χαλεπῶς καὶ ἀναστρέφουσιν ἀπὸ τῆς διώξεως ἐπέκειντο αὖθις σπουδῇ.", "st": "10.22"}, {"sp": "N", "t": "Καλλιεῦσι δὲ καίπερ δεινὰ οὕτω παθοῦσιν ὡς μηδὲ τὰ ὑπὸ Ὁμήρου πεποιημένα ἔς τε Λαιστρυγόνας καὶ ἐς Κύκλωπα ἐκτὸς εἶναι δοκεῖν ἀληθείας, ὅμως κατὰ τὴν ἀξίαν ἐγίνετο ἡ ὑπὲρ αὐτῶν δίκη· ἀπὸ γὰρ τεσσάρων μυριάδων προσόντων σφίσιν ὀκτακοσίων ἐλάσσονες ἡμίσεων ἐς τὸ στρατόπεδον οἱ βάρβαροι τὸ πρὸς Θερμοπύλαις ἀπεσώθησαν.", "st": "10.22"}, {"sp": "N", "t": "περὶ δὲ τοὺς Ἕλληνας ἐν τῷ αὐτῷ χρόνῳ τοὺς ἐν Θερμοπύλαις συνέβαινεν ἄλλα τοιαῦτα. ἀτραπός ἐστι διὰ τοῦ ὄρους τῆς Οἴτης, μία μὲν ἡ ὑπὲρ Τραχῖνος ἀπότομός τε τὰ πλείω καὶ ὄρθιος δεινῶς, ἑτέρα δὲ ἡ διὰ τῆς Αἰνιάνων ὁδεῦσαι στρατῷ ῥᾴων, δι’ ἧς καὶ Ὑδάρνης ποτὲ Μῆδος κατὰ νώτου τοῖς περὶ Λεωνίδην ἐπέθετο Ἕλλησι.", "st": "10.22"}, {"sp": "N", "t": "κατὰ ταύτην τὴν ὁδὸν ἐπηγγέλλοντο ἄξειν Βρέννον οἱ Ἡρακλεῶται καὶ οἱ Αἰνιᾶνες, οὐ κακονοίᾳ τῇ ἐς τὸ Ἑλληνικόν, τοὺς δὲ Κελτοὺς ἐκ τῆς χώρας σφίσιν ἀπελθεῖν μηδὲ ἐγκαθημένους φθείρειν περὶ πολλοῦ ποιούμενοι. καί μοι φαίνεται Πίνδαρος ἀληθῆ καὶ ἐν τῷδε εἰπεῖν, ὃς πάντα τινὰ ὑπὸ κακῶν οἰκείων ἔφη πιέζεσθαι, ἐπὶ δὲ ἀλλοτρίοις κήδεσιν ἀπήμαντον εἶναι.", "st": "10.22"}, {"sp": "N", "t": "τότε δὲ ἡ τῶν Αἰνιάνων καὶ [ἡ] τῶν Ἡρακλεωτῶν ὑπόσχεσις ἐπήγειρε τὸν Βρέννον· καὶ Ἀκιχώριον μὲν κατέλιπεν ἐπὶ τῇ στρατιᾷ, προειπών, ἐπειδὰν περιλάβωσιν αὐτοὶ τὸ Ἑλληνικόν, τηνικαῦτα καὶ ἐκείνοις ἐφόδου καιρὸν εἶναι· ἀπολέξας δὲ αὐτὸς μυριάδας τοῦ στρατοῦ τέσσαρας ἐποιεῖτο τὴν ὁδὸν διὰ τῆς ἀτραποῦ.", "st": "10.22"}, {"sp": "N", "t": "καί πως ἐπ’ ἐκείνης συνέβαινε τῆς ἡμέρας τήν τε ὁμίχλην κατὰ τοῦ ὄρους καταχεῖσθαι πολλὴν καὶ ἀμαυρὸν ὑπ’ αὐτῆς εἶναι τὸν ἥλιον, ὥστε τῶν Φωκέων τοῖς ἔχουσιν ἐπὶ τῇ ἀτραπῷ τὴν φρουρὰν οὐ πρότερον ἐπιόντες οἱ βάρβαροι παρέσχοντο αἴσθησιν πρὶν ἢ πλησίον ἐγεγόνεσαν. ἐνταῦθα δὲ οἱ μὲν μάχης ἦρχον, οἱ δὲ ἠμύνοντο ἐρρωμένως, τέλος δὲ ἐβιάσθησαν καὶ ἀναχωροῦσιν ἀπὸ τῆς ἀτραποῦ· καταδραμόντες μέντοι παρὰ τοὺς συμμάχους καὶ ἀπαγγείλαντες τὰ παρόντα ἔφθησαν πρὶν ἢ ἀκριβῆ καὶ πανταχόθεν τελέαν γενέσθαι τοῦ Ἑλληνικοῦ τὴν κύκλωσιν.", "st": "10.22"}, {"sp": "N", "t": "ἔνθα δὴ οἱ ἐπὶ τῶν τριήρων Ἀθηναῖοι φθάνουσιν ὑπεξαγαγόντες ἐκ τῶν Θερμοπυλῶν τὸ Ἑλληνικόν· καὶ οἱ μὲν κατὰ τὰς πατρίδας ἕκαστοι τὰς αὑτῶν ἐσκεδάσθησαν, ὁ δὲ Βρέννος οὐδένα ἔτι ἐπισχὼν χρόνον, πρὶν ἢ τοὺς ἀπὸ τοῦ στρατοπέδου τοῦ σὺν τῷ Ἀκιχωρίῳ παραγενέσθαι, τὴν ὁδὸν ἐποιεῖτο ἐπὶ τοὺς Δελφούς. οἱ δὲ καταφεύγουσιν ὑπὸ δείματος ἐπὶ τὸ χρηστήριον· καὶ ὁ θεὸς σφᾶς οὐκ εἴα φοβεῖσθαι, φυλάξειν δὲ αὐτὸς ἐπηγγέλλετο τὰ ἑαυτοῦ.", "st": "10.22"}, {"sp": "N", "t": "οἱ δὲ ἀφικόμενοι τιμωρεῖν τῷ θεῷ τοσοίδε ἐγένοντο Ἑλλήνων· Φωκεῖς μὲν ἀπὸ τῶν πόλεων πασῶν, ἐκ δὲ Ἀμφίσσης ὁπλῖται τετρακόσιοι, παρὰ δὲ Αἰτωλῶν ὀλίγοι μέν τινες αὐτίκα, ὅτε ἐπύθοντο ἐς τὸ πρόσω χωροῦντας τοὺς βαρβάρους, διακοσίους δὲ καὶ χιλίους Φιλόμηλος ἤγαγεν ὕστερον. τὸ δὲ μάλιστα ἐν ἀκμῇ τῶν Αἰτωλῶν ἐτράπετο ἐπὶ τὴν μετὰ τοῦ Ἀκιχωρίου στρατιάν, καὶ μάχης μὲν οὐκ ἦρχον, ὁδευόντων δὲ ἐπέκειντο ἀεὶ τοῖς ἐσχάτοις ἁρπάζοντές τε τὰ τῶν σκευαγωγούντων καὶ αὐτοὺς τοὺς ἄνδρας φονεύοντες· καὶ ἡ πορεία κατὰ ταύτην μάλιστα ἐγίνετό σφισι βραδεῖα τὴν αἰτίαν. κατέλιπε δὲ καὶ περὶ τὴν Ἡράκλειαν ὁ Ἀκιχώριος μοῖραν, οἳ ἔμελλον φρουρήσειν τὰ ἐπὶ τοῦ στρατοπέδου χρήματα.", "st": "10.22"}, {"sp": "N", "t": "Βρέννῳ δὲ καὶ τῇ στρατιᾷ τῶν τε Ἑλλήνων οἱ ἐς Δελφοὺς ἀθροισθέντες ἀντετάξαντο, καὶ τοῖς βαρβάροις ἀντεσήμαινε τὰ ἐκ τοῦ θεοῦ ταχύ τε καὶ ὧν ἴσμεν φανερώτατα. ἥ τε γὰρ γῆ πᾶσα, ὅσην ἐπεῖχεν ἡ τῶν Γαλατῶν στρατιά, βιαίως καὶ ἐπὶ πλεῖστον ἐσείετο τῆς ἡμέρας, βρονταί τε καὶ κεραυνοὶ συνεχεῖς ἐγίνοντο·", "st": "10.23"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐξέπληττόν τε τοὺς Κελτοὺς καὶ δέχεσθαι τοῖς ὠσὶ τὰ παραγγελλόμενα ἐκώλυον, τὰ δὲ ἐκ τοῦ οὐρανοῦ οὐκ ἐς ὅντινα κατασκήψαι μόνον ἀλλὰ καὶ τοὺς πλησίον καὶ αὐτοὺς ὁμοίως καὶ τὰ ὅπλα ἐξῆπτε. τά τε τῶν ἡρώων τηνικαῦτά σφισιν ἐφάνη φάσματα, ὁ Ὑπέροχος καὶ ὁ Λαόδοκός τε καὶ Πύρρος· οἱ δὲ καὶ τέταρτον Φύλακον ἐπιχώριον Δελφοῖς ἀπαριθμοῦσιν ἥρωα.", "st": "10.23"}, {"sp": "N", "t": "ἀπέθανον δὲ καὶ αὐτῶν παρὰ τὸ ἔργον τῶν Φωκέων ἄλλοι τε ἀριθμὸν πολλοὶ καὶ Ἀλεξίμαχος, ὃς ἐν τῇ μάχῃ ταύτῃ μάλιστα Ἑλλήνων ἡλικίας τε τῷ ἀκμάζοντι καὶ ἰσχύι σώματος καὶ τῷ ἐρρωμένῳ τοῦ θυμοῦ κατεχρήσατο ἐς τῶν βαρβάρων τὸν φόνον· Φωκεῖς δὲ εἰκόνα τοῦ Ἀλεξιμάχου ποιησάμενοι ἀπέστειλαν τῷ Ἀπόλλωνι ἐς Δελφούς.", "st": "10.23"}, {"sp": "N", "t": "τοιούτοις μὲν οἱ βάρβαροι παρὰ πᾶσαν τὴν ἡμέραν παθήμασί τε καὶ ἐκπλήξει συνείχοντο· τὰ δὲ ⟨ἐν⟩ τῇ νυκτὶ πολλῷ σφᾶς ἔμελλεν ἀλγεινότερα ἐπιλήψεσθαι. ῥῖγός τε γὰρ ἰσχυρὸν καὶ νιφετὸς ἦν ὁμοῦ τῷ ῥίγει, πέτραι τε ἀπολισθάνουσαι τοῦ Παρνασσοῦ μεγάλαι [τε] καὶ κρημνοὶ καταρρηγνύμενοι σκοπὸν τοὺς βαρβάρους εἶχον, καὶ αὐτοῖς οὐ κατὰ ἕνα ἢ δύο ἀλλὰ κατὰ τριάκοντα καὶ ἔτι πλείοσιν, ὡς ἕκαστοι ἐν τῷ αὐτῷ φρουροῦντες ἢ καὶ ἀναπαυόμενοι τύχοιεν, ἀθρόοις ἡ ἀπώλεια ἐγένετο ὑπὸ τῆς ἐμβολῆς τῶν κρημνῶν.", "st": "10.23"}, {"sp": "N", "t": "ἅμα δὲ τῷ ἡλίῳ ἀνίσχοντι οἱ Ἕλληνες ἐπῄεσάν σφισιν ἐκ τῶν Δελφῶν, οἱ μὲν ἄλλοι τὴν ἐπὶ τὸ στράτευμα εὐθεῖαν, οἱ Φωκεῖς δὲ ἅτε καὶ μᾶλλον ἔχοντες τῶν χωρίων ἐμπείρως κατέβησάν τε διὰ τῆς χιόνος κατὰ τὰ ἀπότομα τοῦ Παρνασσοῦ καὶ ἔλαθον κατὰ νώτου γενόμενοι τοῖς Κελτοῖς, ἠκόντιζόν τε ἐς αὐτοὺς καὶ ἐτόξευον σὺν οὐδενὶ ἀπὸ τῶν βαρβάρων δείματι.", "st": "10.23"}, {"sp": "N", "t": "οἱ δὲ ἀρχομένης μὲν τῆς μάχης, καὶ μάλιστα οἱ περὶ τὸν Βρέννον —οὗτοι δὲ μήκιστοί τε ἦσαν καὶ ἀλκιμώτατοι τῶν Γαλατῶν—τότε μὲν ὑπὸ προθυμίας ἔτι ἀντεῖχον βαλλόμενοί τε πανταχόθεν καὶ οὐχ ἧσσον ὑπὸ τοῦ ῥίγους, μάλιστα οἱ τραυματίαι, ταλαιπωροῦντες· ὡς δὲ καὶ ὁ Βρέννος ἔλαβε τραύματα, ἐκεῖνον μὲν λιποψυχήσαντα ἐκκομίζουσιν ἐκ τῆς μάχης, οἱ δὲ βάρβαροι πανταχόθεν σφίσιν ἐγκειμένων τῶν Ἑλλήνων ὑπέφευγόν τε ἄκοντες καὶ ἑαυτῶν τοὺς ἀδυνάτους διὰ τραύματα ἕπεσθαι καὶ ἀρρωστίαν φονεύουσιν.", "st": "10.23"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐστρατοπεδεύσαντο ἔνθα νὺξ κατελάμβανεν ἀναχωροῦντας, ἐν δὲ τῇ νυκτὶ φόβος σφίσιν ἐμπίπτει Πανικός· τὰ γὰρ ἀπὸ αἰτίας οὐδεμιᾶς δείματα ἐκ τούτου φασὶ γίνεσθαι. ἐνέπεσε μὲν ἐς τὸ στράτευμα ἡ ταραχὴ περὶ βαθεῖαν τὴν ἑσπέραν, καὶ ὀλίγοι τὸ κατ’ ἀρχὰς ἐγένοντο οἱ παραχθέντες ἐκ τοῦ νοῦ, ἐδόξαζόν τε οὗτοι κτύπου τε ἐπελαυνομένων ἵππων καὶ ἐφόδου πολεμίων ⟨αἰσθάνεσθαι⟩· μετὰ δὲ οὐ πολὺ καὶ ἐς ἅπαντας διέδρα ἡ ἄγνοια.", "st": "10.23"}, {"sp": "N", "t": "ἀναλαβόντες οὖν τὰ ὅπλα καὶ διαστάντες ἔκτεινόν τε ἀλλήλους καὶ ἀνὰ μέρος ἐκτείνοντο, οὔτε γλώσσης τῆς ἐπιχωρίου συνιέντες οὔτε τὰς ἀλλήλων μορφὰς οὔτε τῶν θυρεῶν καθορῶντες τὰ σχήματα· ἀλλὰ ἀμφοτέραις ταῖς τάξεσιν ὁμοίως ὑπὸ τῆς ἐν τῷ παρόντι ἀγνοίας οἵ τε ἄνδρες οἱ ἀνθεστηκότες εἶναί σφισιν Ἕλληνες καὶ αὐτοὶ καὶ τὰ ὅπλα ἐφαίνοντο καὶ Ἑλλάδα ἀφιέναι τὴν φωνήν, ἥ τε ἐκ τοῦ θεοῦ μανία πλεῖστον ἐξειργάσατο ὑπ’ ἀλλήλων τοῖς Γαλάταις τὸν φόνον.", "st": "10.23"}, {"sp": "N", "t": "τῶν δὲ Φωκέων ὅσοι κατελίποντο κατὰ τοὺς ἀγροὺς φυλακῆς βοσκημάτων ἕνεκα, πρῶτοί τε ᾔσθοντο καὶ ἀπαγγέλλουσι τοῖς Ἕλλησι τὰ ἐν τῇ νυκτὶ κατασχόντα τοὺς βαρβάρους. ἀναθαρσήσαντες δὲ οἱ Φωκεῖς προθυμότερον ἔτι ἐνέκειντο τοῖς Κελτοῖς· διὰ φυλακῆς τε πλείονος τὰς ἐπαύλεις ἐποιοῦντο καὶ τὰ ἐς βίου χρείαν οὐ περιεώρων σφᾶς ἐκ τῆς χώρας ἀμαχεὶ λαμβάνοντας, ἐγεγόνει τε αὐτίκα τοῖς Γαλάταις διὰ παντὸς τοῦ στρατοῦ καὶ σίτου καὶ ὅσα ἐς τροφὴν ἄλλα ἔνδεια ἰσχυρά.", "st": "10.23"}, {"sp": "N", "t": "πλῆθος δὲ τὸ ἐν τῇ Φωκίδι αὐτῶν ἀναλωθέν, ὀλίγῳ μὲν ἑξακισχιλίων ἐλάσσονες οἱ ἐν ταῖς μάχαις, οἱ δ’ ἐν τῇ χειμερίῳ διαφθαρέντες νυκτὶ καὶ ὕστερον οἱ ἐν τῷ Πανικῷ δείματι ἐγένοντο ὑπὲρ τοὺς μυρίους, τοσοῦτοι δὲ ἄλλοι καὶ ὑπὸ τοῦ λιμοῦ.", "st": "10.23"}, {"sp": "N", "t": "Ἀθηναίων δὲ ἄνδρες ἐπισκεψόμενοι μὲν ἀφίκοντο ἐν Δελφοῖς· τότε δὲ ἐπανήκοντες τά τε ἄλλα ἤγγελλον ὁποῖα συμβεβήκει τοῖς βαρβάροις καὶ τὰ ἐκ τοῦ θεοῦ κατειληφότα. οἱ δὲ αὐτοί τε ἐξεστρατεύοντο καὶ ὡς τὴν Βοιωτίαν διώδευον οἱ Βοιωτοί σφισιν ἀνεμίχθησαν· οὕτω δὴ ἀμφότεροι τοῖς βαρβάροις ἐπακολουθοῦντες ἐλόχων τε καὶ ἔκτεινον τοὺς ἀεὶ ἐσχάτους.", "st": "10.23"}, {"sp": "N", "t": "τοῖς δὲ φεύγουσιν ὁμοῦ τῷ Βρέννῳ καὶ οἱ περὶ τὸν Ἀκιχώριον ἐν τῇ προτέρᾳ νυκτὶ ἀνεμίχθησαν· βραδεῖαν γὰρ τὴν πορείαν ἐποίησάν σφισιν οἱ Αἰτωλοὶ τοῖς τε ἀκοντίοις ἐς αὐτοὺς ἀφειδέστερον καὶ ὅτῳ τύχοιεν καὶ ἄλλῳ χρώμενοι, ὥστε ἐς τὸ στρατόπεδον τὸ πρὸς τῇ Ἡρακλείᾳ μοῖρα οὐ πολλὴ διέφυγεν ἐξ αὐτῶν. τῷ δὲ Βρέννῳ κατὰ μὲν τὰ τραύματα ἐλείπετο ἔτι σωτηρίας ἐλπίς· τῶν δὲ πολιτῶν φόβῳ φασὶν αὐτὸν καὶ τῇ αἰδοῖ πλέον, ἅτε τῶν ἐν τῇ Ἑλλάδι κακῶν αἴτιον, ἑκουσίως ἀφεῖναι τὴν ψυχὴν ἀκράτου πίνοντα τοῦ οἴνου.", "st": "10.23"}, {"sp": "N", "t": "καὶ τὸ ἀπὸ τούτου δὲ οἱ βάρβαροι μέχρι μὲν τοῦ Σπερχειοῦ χαλεπῶς ἐκομίσθησαν, τῶν Αἰτωλῶν βιαίως σφίσιν ἐγκειμένων· ὡς δὲ ἀφίκοντο ἐπὶ τὸν Σπερχειόν, οἱ ἐντεῦθεν ὑποκαθήμενοι Θεσσαλοὶ καὶ οἱ Μαλιεῖς ἐνεφορήθησαν οὕτω σφῶν ὡς μηδένα οἴκαδε ἀποσωθῆναι.", "st": "10.23"}, {"sp": "N", "t": "ἐγένετο δὲ τῶν Κελτῶν στρατεία τε ἐπὶ τὴν Ἑλλάδα καὶ ἡ ἀπώλεια Ἀναξικράτους Ἀθήνῃσιν ἄρχοντος, δευτέρῳ δὲ ἔτει τῆς πέμπτης Ὀλυμπιάδος ἐπὶ εἴκοσι καὶ ἑκατόν, ἣν Λάδας Αἰγιεὺς ἐνίκα στάδιον· τῷ δὲ ἔτει τῷ ἐφεξῆς Δημοκλέους Ἀθήνῃσιν ἄρχοντος, οἱ δὲ αὖθις ἐς τὴν Ἀσίαν διαβαίνουσιν οἱ Κελτοί.", "st": "10.23"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω γενόμενα ἴστω τις· ἐν δὲ τῷ προνάῳ τῷ ἐν Δελφοῖς γεγραμμένα ἐστὶν ὠφελήματα ἀνθρώποις ἐς βίον, ἐγράφη δὲ ὑπὸ ἀνδρῶν οὓς γενέσθαι σοφοὺς λέγουσιν Ἕλληνες. οὗτοι δὲ ἦσαν ἐκ μὲν Ἰωνίας Θαλῆς τε Μιλήσιος καὶ Πριηνεὺς Βίας, Αἰολέων δὲ τῶν ἐν Λέσβῳ Πιττακὸς Μιτυληναῖος, ἐκ δὲ Δωριέων τῶν ἐν τῇ Ἀσίᾳ Κλεόβουλος Λίνδιος, καὶ Ἀθηναῖός τε Σόλων καὶ Σπαρτιάτης Χίλων· τὸν δὲ ἕβδομον Πλάτων ὁ Ἀρίστωνος ἀντὶ Περιάνδρου τοῦ Κυψέλου Μύσωνα κατείλοχε τὸν Χηνέα· κώμη δὲ ἐν τῇ Οἴτῃ τῷ ὄρει ᾠκοῦντο αἱ Χῆναι. οὗτοι οὖν οἱ ἄνδρες ἀφικόμενοι ἐς Δελφοὺς ἀνέθεσαν τῷ Ἀπόλλωνι τὰ ᾀδόμενα Γνῶθι σαυτὸν καὶ Μηδὲν ἄγαν.", "st": "10.24"}, {"sp": "N", "t": "οὗτοι μὲν δὴ ἐνταῦθα ἔγραψαν τὰ εἰρημένα, θεάσαιο δ’ ἂν καὶ εἰκόνα Ὁμήρου χαλκῆν ἐπὶ στήλῃ καὶ ἐπιλέξει τὸ μάντευμα ὃ γενέσθαι τῷ Ὁμήρῳ λέγουσιν·<br>ὄλβιε καὶ δύσδαιμον—ἔφυς γὰρ ἐπ’ ἀμφοτέροισι—,<br>πατρίδα δίζηαι. μητρὶς δέ τοι, οὐ πατρίς ἐστιν.<br>⟨ἔστιν⟩ Ἴος νῆσος μητρὸς πατρίς, ἥ σε θανόντα<br>δέξεται. ἀλλὰ νέων παίδων αἴνιγμα φύλαξαι.<br>δεικνύουσι δὲ οἱ Ἰῆται καὶ Ὁμήρου μνῆμα ἐν τῇ νήσῳ καὶ ἑτέρωθι Κλυμένης, τὴν Κλυμένην μητέρα εἶναι τοῦ Ὁμήρου λέγοντες.", "st": "10.24"}, {"sp": "N", "t": "Κύπριοι δὲ—οἰκειοῦνται γὰρ δὴ καὶ οὗτοι Ὅμηρον—Θεμιστώ τε αὐτῷ μητέρα εἶναι τῶν τινα ἐπιχωρίων γυναικῶν λέγουσι καὶ ὑπὸ Εὔκλου προθεσπισθῆναι τὰ ἐς τὴν γένεσιν τὴν Ὁμήρου φασὶν ἐν τοῖσδε·<br>καὶ τότ’ ἐν εἰναλίῃ Κύπρῳ μέγας ἔσσετ’ ἀοιδός,<br>ὅν τε Θεμιστὼ τέξει ἐπ’ ἀγροῦ δῖα γυναικῶν<br>νόσφι πολυκτεάνοιο πολύκλειτον Σαλαμῖνος.<br>Κύπρον δὲ προλιπὼν διερός θ’ ὑπὸ κύμασιν ἀρθείς,<br>Ἑλλάδος εὐρυχόρου μοῦνος κακὰ πρῶτος ἀείσας<br>ἔσσεται ἀθάνατος καὶ ἀγήραος ἤματα πάντα.<br>ταῦτα ἡμεῖς ἀκούσαντές τε καὶ ἐπιλεξάμενοι τοὺς χρησμοὺς ἰδίᾳ [δὲ] οὐδένα αὐτῶν λόγον οὔτε ἐς πατρίδα οὔτε περὶ ἡλικίας Ὁμήρου γράφομεν.", "st": "10.24"}, {"sp": "N", "t": "ἐν δὲ τῷ ναῷ πεποίηται μὲν Ποσειδῶνος βωμός, ὅτι τὸ μαντεῖον τὸ ἀρχαιότατον κτῆμα ἦν καὶ Ποσειδῶνος, ἕστηκε δὲ καὶ ἀγάλματα Μοιρῶν δύο· ἀντὶ δὲ αὐτῶν τῆς τρίτης Ζεύς τε Μοιραγέτης καὶ Ἀπόλλων σφίσι παρέστηκε Μοιραγέτης. θεάσαιο δ’ ἂν ἐνταῦθα καὶ ἑστίαν, ἐφ’ ᾗ Νεοπτόλεμον τὸν Ἀχιλλέως ὁ ἱερεὺς ἀπέκτεινε τοῦ Ἀπόλλωνος· τὰ δὲ ἐς τοῦ Νεοπτολέμου τὴν τελευτήν ἐστιν ἡμῖν ἑτέρωθι εἰρημένα.", "st": "10.24"}, {"sp": "N", "t": "ἀνάκειται δὲ οὐ πόρρω τῆς ἑστίας θρόνος Πινδάρου· σιδήρου μέν ἐστιν ὁ θρόνος, ἐπὶ δὲ αὐτῷ φασιν, ὁπότε ἀφίκοιτο ἐς Δελφοὺς, καθέζεσθαί τε τὸν Πίνδαρον καὶ ᾄδειν ὁπόσα τῶν ᾀσμάτων ἐς Ἀπόλλωνά ἐστιν. ἐς δὲ τοῦ ναοῦ τὸ ἐσωτάτω, παρίασί τε ἐς αὐτὸ ὀλίγοι καὶ χρυσοῦν Ἀπόλλωνος ἕτερον ἄγαλμα ἀνάκειται.", "st": "10.24"}, {"sp": "N", "t": "ἐξελθόντι δὲ τοῦ ναοῦ καὶ τραπέντι ἐς ἀριστερὰ περίβολός ἐστι καὶ Νεοπτολέμου τοῦ Ἀχιλλέως ἐν αὐτῷ τάφος· καί οἱ κατὰ ἔτος ἐναγίζουσιν οἱ Δελφοί. ἐπαναβάντι δὲ ἀπὸ τοῦ μνήματος λίθος ἐστὶν οὐ μέγας· τούτου καὶ ἔλαιον ὁσημέραι καταχέουσι καὶ κατὰ ἑορτὴν ἑκάστην ἔρια ἐπιτιθέασι τὰ ἀργά· ἔστι δὲ καὶ δόξα ἐς αὐτὸν δοθῆναι Κρόνῳ τὸν λίθον ἀντὶ τοῦ παιδός, καὶ ὡς αὖθις ἤμεσεν αὐτὸν ὁ Κρόνος.", "st": "10.24"}, {"sp": "N", "t": "ἰοῦσι δὲ ὡς ἐπὶ τὸν ναὸν αὖθις μετὰ τοῦ λίθου τὴν θέαν ἐστὶν ἡ Κασσοτὶς καλουμένη πηγή· τεῖχος δὲ οὐ μέγα ἐπ’ αὐτῇ καὶ ἡ ἄνοδος διὰ τοῦ τείχους ἐστὶν ἐπὶ τὴν πηγήν. ταύτης τῆς Κασσοτίδος δύεσθαί τε κατὰ τῆς γῆς λέγουσι τὸ ὕδωρ καὶ ἐν τῷ ἀδύτῳ τοῦ θεοῦ τὰς γυναῖκας μαντικὰς ποιεῖν· τὴν δὲ τῇ κρήνῃ δεδωκυῖαν τὸ ὄνομα τῶν περὶ τὸν Παρνασσὸν νυμφῶν φασιν εἶναι.", "st": "10.24"}, {"sp": "N", "t": "ὑπὲρ δὲ τὴν Κασσοτίδα ἐστὶν οἴκημα γραφὰς ἔχον τῶν Πολυγνώτου, ἀνάθημα μὲν Κνιδίων, καλεῖται δὲ ὑπὸ Δελφῶν Λέσχη, ὅτι ἐνταῦθα συνιόντες τὸ ἀρχαῖον τά τε σπουδαιότερα διελέγοντο καὶ ὁπόσα μυθώδη· τοιαῦτ’ εἶναι πολλὰ ἀνὰ πᾶσαν τὴν Ἑλλάδα Ὅμηρος ἐν Μελανθοῦς λοιδορίᾳ πρὸς Ὀδυσσέα ἐδήλωσεν·<br>οὐδ’ ἐθέλεις εὕδειν χαλκήιον ἐς δόμον ἐλθὼν<br>ἠέ που ἐς λέσχην, ἀλλ’ ἐνθάδε πόλλ’ ἀγορεύεις.", "st": "10.25"}, {"sp": "N", "t": "ἐς τοῦτο οὖν ἐσελθόντι τὸ οἴκημα τὸ μὲν σύμπαν τὸ ἐν δεξιᾷ τῆς γραφῆς Ἴλιός τέ ἐστιν ἑαλωκυῖα καὶ ἀπόπλους ὁ Ἑλλήνων. Μενελάῳ δὲ τὰ ἐς τὴν ἀναγωγὴν εὐτρεπίζουσι, καὶ ναῦς ἐστι γεγραμμένη καὶ ἄνδρες ἐν τοῖς ναύταις καὶ ἀναμὶξ παῖδες, ἐν μέσῃ δέ ἐστι τῇ νηὶ ὁ κυβερνήτης Φρόντις κοντοὺς δύο ἔχων. Ὅμηρος δὲ Νέστορα ἐποίησεν ἄλλα τε διαλεγόμενον πρὸς Τηλέμαχον καὶ περὶ τοῦ Φρόντιδος· πατρὸς μὲν Ὀνήτορος, Μενελάου δὲ ἦν κυβερνήτης, δοκιμώτατος δὲ ἐς τὴν τέχνην, καὶ ὡς Σούνιον ἤδη τὸ ἐν τῇ Ἀττικῇ παραπλέοντα ἐπέλαβεν αὐτὸν τὸ χρεών· καὶ τέως ὁμοῦ Νέστορι ὁ Μενέλαος πλέων τότε κατὰ αἰτίαν ἀπελείφθη ταύτην, ἵνα μνήματος καὶ ὅσα ἐπὶ νεκροῖς ἄλλα ἀξιώσειε τὸν Φρόντιν.", "st": "10.25"}, {"sp": "N", "t": "οὗτός τε οὖν ἐν τοῦ Πολυγνώτου τῇ γραφῇ καὶ ὑπ’ αὐτὸν Ἰθαιμένης τέ τις κομίζων ἐσθῆτα καὶ Ἐχοίαξ διὰ τῆς ἀποβάθρας κατιών ἐστιν, ὑδρίαν ἔχων χαλκῆν. καταλύουσι δὲ καὶ τοῦ Μενελάου τὴν σκηνὴν οὐ πόρρω τῆς νεὼς οὖσαν Πολίτης καὶ Στρόφιός τε καὶ Ἄλφιος. καὶ ἄλλην διαλύων σκηνήν ἐστιν Ἀμφίαλος, ὑπὸ δὲ τοῦ Ἀμφιάλου τοῖς ποσὶ κάθηται παῖς· ἐπίγραμμα δὲ οὐκ ἔστι τῷ παιδί, γένεια δὲ μόνῳ τῷ Φρόντιδι. καὶ μόνου τούτου τὸ ὄνομα ἐκ τῆς ἐς Ὀδυσσέα ποιήσεως ἔμαθε, τῶν δὲ ἄλλων ἐμοὶ δοκεῖν τὰ ὀνόματα συνέθηκεν αὐτὸς ὁ Πολύγνωτος.", "st": "10.25"}, {"sp": "N", "t": "Βρισηὶς δὲ ἑστῶσα καὶ Διομήδη τε ὑπὲρ αὐτῆς καὶ Ἶφις πρὸ ἀμφοτέρων ἐοίκασιν ἀνασκοπούμενοι τὸ Ἑλένης εἶδος. κάθηται δὲ αὐτή τε ἡ Ἑλένη καὶ Εὐρυβάτης πλησίον· τὸν δὲ Ὀδυσσέως εἶναι κήρυκα εἰκάζομεν, οὐ μὴν εἶχεν ἤδη γένεια. θεράπαινα δὲ Ἠλέκτρα καὶ Πανθαλίς, ἡ μὲν τῇ Ἑλένῃ παρέστηκεν, ἡ δὲ ὑποδεῖ τὴν δέσποιναν ἡ Ἠλέκτρα· διάφορα δὲ καὶ ταῦτα τὰ ὀνόματα ⟨ἢ⟩ Ὅμηρος ἔθετο ἐν Ἰλιάδι, ἔνθα καὶ Ἑλένην καὶ ἰούσας ὁμοῦ τῇ Ἑλένῃ τὰς δούλας ἐπὶ τὸ τεῖχος πεποίηκεν.", "st": "10.25"}, {"sp": "N", "t": "κάθηται δὲ ὑπὲρ τὴν Ἑλένην πορφυροῦν ἀνὴρ ἀμπεχόμενος ἱμάτιον καὶ ἐς τὰ μάλιστα κατηφής· Ἕλενον εἶναι τεκμήραιο ἂν τὸν Πριάμου καὶ πρὶν ἢ [καὶ] τὸ ἐπίγραμμα ἐπιλέξασθαι. πλησίον δὲ τοῦ Ἑλένου Μέγης ἐστί· τέτρωται δὲ τὸν βραχίονα ὁ Μέγης, καθὰ δὴ καὶ Λέσχεως ὁ Αἰσχυλίνου Πυρραῖος ἐν Ἰλίου πέρσιδι ἐποίησε· τρωθῆναι δὲ ὑπὸ τὴν μάχην τοῦτον, ἣν ἐν τῇ νυκτὶ ἐμαχέσαντο οἱ Τρῶες, ὑπὸ Ἀδμήτου φησὶ τοῦ Αὐγείου.", "st": "10.25"}, {"sp": "N", "t": "γέγραπται δὲ καὶ Λυκομήδης παρὰ τὸν Μέγητα ὁ Κρέοντος, ἔχων τραῦμα ἐπὶ τῷ καρπῷ· Λέσχεως δ’ οὕτω φησὶν αὐτὸν ὑπὸ Ἀγήνορος τρωθῆναι. δῆλα οὖν ὡς ἄλλως γε οὐκ ἂν ὁ Πολύγνωτος ἔγραψεν οὕτω τὰ ἕλκη σφίσιν, εἰ μὴ ἐπελέξατο τὴν ποίησιν τοῦ Λέσχεω· προσεπέθηκε μέντοι καὶ σφυροῦ τῷ Λυκομήδει καὶ τρίτον τραῦμα ἐν τῇ κεφαλῇ. τέτρωται δὲ καὶ Εὐρύαλος ὁ Μηκιστέως κεφαλήν τε καὶ ἐπὶ τῇ χειρὶ τὸν καρπόν.", "st": "10.25"}, {"sp": "N", "t": "οὗτοι μὲν δὴ ἀνωτέρω τῆς Ἑλένης εἰσὶν ἐν τῇ γραφῇ· ἐφεξῆς δὲ τῇ Ἑλένῃ μήτηρ τε ἡ Θησέως ἐν χρῷ κεκαρμένη καὶ παίδων τῶν Θησέως Δημοφῶν ἐστι φροντίζων, ὅσα γε ἀπὸ τοῦ σχήματος, εἰ ἀνασώσασθαί οἱ τὴν Αἴθραν ἐνέσται. Ἀργεῖοι δὲ καὶ ἐκ τῆς Σίνιδος θυγατρὸς γενέσθαι Θησεῖ Μελάνιππον λέγουσι, καὶ ὡς ἀνέλοιτο ὁ Μελάνιππος δρόμου νίκην, ὅτε οἱ Ἐπίγονοι καλούμενοι Νέμεια δεύτεροι οὗτοι ἔθεσαν μετὰ Ἄδραστον.", "st": "10.25"}, {"sp": "N", "t": "Λέσχεως δὲ ἐς τὴν Αἴθραν ἐποίησεν, ἡνίκα ἡλίσκετο Ἴλιον, ὑπεξελθοῦσαν ἐς τὸ στρατόπεδον αὐτὴν ἀφικέσθαι τὸ Ἑλλήνων καὶ ὑπὸ τῶν παίδων γνωρισθῆναι τῶν Θησέως, καὶ ὡς παρ’ Ἀγαμέμνονος αἰτήσαι Δημοφῶν αὐτήν· ὁ δὲ ἐκείνῳ μὲν ἐθέλειν χαρίζεσθαι, ποιήσειν δὲ οὐ πρότερον ἔφη πρὶν Ἑλένην πεῖσαι· ἀποστείλαντι δὲ αὐτῷ κήρυκα ἔδωκεν Ἑλένη τὴν χάριν. ἔοικεν οὖν ὁ Εὐρυβάτης ὁ ἐν τῇ γραφῇ ἀφῖχθαί τε ὡς τὴν Ἑλένην τῆς Αἴθρας ἕνεκα καὶ τὰ ἐντεταλμένα ὑπὸ τοῦ Ἀγαμέμνονος ἀπαγγέλλειν.", "st": "10.25"}, {"sp": "N", "t": "γυναῖκες δὲ αἱ Τρῳάδες αἰχμαλώτοις τε ἤδη καὶ ὀδυρομέναις ἐοίκασι. γέγραπται μὲν Ἀνδρομάχη, καὶ ὁ παῖς οἱ προσέστηκεν ἑλόμενος τοῦ μαστοῦ—τούτῳ Λέσχεως ῥιφθέντι ἀπὸ τοῦ πύργου συμβῆναι λέγει τὴν τελευτήν· οὐ μὴν ὑπὸ δόγματός γε Ἑλλήνων, ἀλλ’ ἰδίᾳ Νεοπτόλεμον αὐτόχειρα ἐθελῆσαι γενέσθαι—, γέγραπται δὲ Μηδεσικάστη, θυγατέρων μὲν Πριάμου καὶ αὕτη τῶν νόθων, ἐξῳκίσθαι δὲ ἐς Πήδαιον πόλιν φησὶν αὐτὴν Ὅμηρος Ἰμβρίῳ Μέντορος παιδὶ ἀνδρὶ [ἐς Πήδαιον] συνοικοῦσαν.", "st": "10.25"}, {"sp": "N", "t": "ἡ μὲν δὴ Ἀνδρομάχη καὶ ἡ Μηδεσικάστη καλύμματά εἰσιν ἐπικείμεναι, Πολυξένη δὲ κατὰ τὰ εἰθισμένα παρθένοις ἀναπέπλεκται τὰς ἐν τῇ κεφαλῇ τρίχας· ἀποθανεῖν δὲ αὐτὴν ἐπὶ τῷ Ἀχιλλέως μνήματι ποιηταί τε ᾄδουσι καὶ γραφὰς ἔν τε Ἀθήναις καὶ Περγάμῳ τῇ ὑπὲρ Καΐκου θεασάμενος οἶδα ἐχούσας ἐς τῆς Πολυξένης τὰ παθήματα.", "st": "10.25"}, {"sp": "N", "t": "γέγραφε δὲ καὶ Νέστορα τῇ κεφαλῇ τε ἐπικείμενον πῖλον καὶ ἐν τῇ χειρὶ δόρυ ἔχοντα· καὶ ἵππος κονίεσθαι μέλλοντος παρέχεται σχῆμα· ἄχρι μὲν δὴ τοῦ ἵππου αἰγιαλός τε καὶ ἐν αὐτῷ ψηφῖδες ὑποφαίνονται, τὸ δὲ ἐντεῦθεν οὐκέτι ἔοικεν εἶναι θάλασσα.", "st": "10.25"}, {"sp": "N", "t": "τῶν δὲ γυναικῶν τῶν μεταξὺ τῆς τε Αἴθρας καὶ Νέστορος, εἰσὶν ἄνωθεν τούτων αἰχμάλωτοι καὶ αὗται Κλυμένη τε καὶ Κρέουσα καὶ Ἀριστομάχη καὶ Ξενοδίκη. Κλυμένην μὲν οὖν Στησίχορος ἐν Ἰλίου πέρσιδι κατηρίθμηκεν ἐν ταῖς αἰχμαλώτοις· ὡσαύτως δὲ καὶ Ἀριστομάχην ἐποίησεν ἐν Νόστοις θυγατέρα μὲν Πριάμου, Κριτολάου δὲ γυναῖκα εἶναι τοῦ Ἱκετάονος· Ξενοδίκης δὲ μνημονεύσαντα οὐκ οἶδα οὔτε ποιητὴν οὔτε ὅσοι λόγων συνθέται. ἐπὶ δὲ τῇ Κρεούσῃ λέγουσιν ὡς ἡ θεῶν μήτηρ καὶ Ἀφροδίτη δουλείας ἀπὸ Ἑλλήνων αὐτὴν ἐρρύσαντο, εἶναι γὰρ δὴ καὶ Αἰνείου τὴν Κρέουσαν γυναῖκα· Λέσχεως δὲ καὶ ἔπη τὰ Κύπρια διδόασιν Εὐρυδίκην γυναῖκα Αἰνείᾳ.", "st": "10.26"}, {"sp": "N", "t": "γεγραμμέναι δὲ ἐπὶ κλίνης ὑπὲρ ταύτας Δηινόμη τε καὶ Μητιόχη καὶ Πεῖσίς ἐστι καὶ Κλεοδίκη· τούτων ἐν Ἰλιάδι καλουμένῃ μικρᾷ μόνης ἐστὶ τὸ ὄνομα τῆς Δηινόμης, τῶν δ’ ἄλλων ἐμοὶ δοκεῖν συνέθηκε τὰ ὀνόματα ὁ Πολύγνωτος. γέγραπται δὲ καὶ Ἐπειὸς γυμνὸς καταβάλλων ἐς ἔδαφος τῶν Τρώων τὸ τεῖχος· ἀνέχει δὲ ὑπὲρ αὐτὸ κεφαλὴ τοῦ ἵππου μόνη τοῦ δουρείου. Πολυποίτης δὲ ὁ Πειρίθου δεδεμένος τὴν κεφαλὴν ταινίᾳ καὶ παρ’ αὐτὸν Ἀκάμας ἐστὶν ὁ Θησέως ἐπικείμενος τῇ κεφαλῇ κράνος·", "st": "10.26"}, {"sp": "N", "t": "λόφος δὲ ἐπὶ τῷ κράνει πεποίηται. καὶ Ὀδυσσεύς τέ ἐστι … καὶ ἐνδέδυκε θώρακα Ὀδυσσεύς. Αἴας δὲ ὁ Οἰλέως ἔχων ἀσπίδα βωμῷ προσέστηκεν, ὀμνύμενος ὑπὲρ τοῦ ἐς Κασσάνδραν τολμήματος· ἡ δὲ κάθηταί τε ἡ Κασσάνδρα χαμαὶ καὶ τὸ ἄγαλμα ἔχει τῆς Ἀθηνᾶς, εἴγε δὴ ἀνέτρεψεν ἐκ βάθρων τὸ ξόανον, ὅτε ἀπὸ τῆς ἱκεσίας αὐτὴν ὁ Αἴας ἀφεῖλκε. γεγραμμένοι δὲ καὶ οἱ παῖδές εἰσιν οἱ Ἀτρέως, ἐπικείμενοι καὶ οὗτοι κράνη, Μενελάῳ δὲ ἀσπίδα ἔχοντι δράκων ἐπὶ τῇ ἀσπίδι ἐστὶν εἰργασμένος τοῦ ἐν Αὐλίδι φανέντος ἐπὶ τοῖς ἱερείοις τέρατος ἕνεκα. ὑπὸ τούτοις ⟨τοῖς⟩ τὸν Αἴαντα ἐξορκοῦσιν, κατ’ εὐθὺ δὲ τοῦ ἵππου ⟨τοῦ⟩", "st": "10.26"}, {"sp": "N", "t": "παρὰ τῷ Νέστορι Νεοπτόλεμος ἀπεκτονώς ἐστιν Ἔλασον, ὅστις δὴ ὁ Ἔλασος. οὗτος μὲν δὴ ὀλίγον ἐμπνέοντι ἔτι εἴκασται· Ἀστύνοον δέ, οὗ δὴ ἐποιήσατο καὶ Λέσχεως μνήμην, πεπτωκότα ἐς γόνυ ὁ Νεοπτόλεμος ξίφει παίει. Νεοπτόλεμον δὲ μόνον τοῦ Ἑλληνικοῦ φονεύοντα ἔτι τοὺς Τρῶας ἐποίησεν ὁ Πολύγνωτος, ὅτι ὑπὲρ τοῦ Νεοπτολέμου τὸν τάφον ἡ γραφὴ πᾶσα ἔμελλεν αὐτῷ γενήσεσθαι. τοῦ δὲ Ἀχιλλέως τῷ παιδὶ Ὅμηρος μὲν Νεοπτόλεμον ὄνομα ἐν ἁπάσῃ οἱ τίθεται τῇ ποιήσει· τὰ δὲ Κύπρια ἔπη φησὶν ὑπὸ Λυκομήδους μὲν Πύρρον, Νεοπτόλεμον δὲ ὄνομα ὑπὸ Φοίνικος αὐτῷ τεθῆναι, ὅτι Ἀχιλλεὺς ἡλικίᾳ ἔτι νέος πολεμεῖν ἤρξατο.", "st": "10.26"}, {"sp": "N", "t": "γέγραπται δὲ βωμός τε καὶ ὑπὸ δείματος παῖς μικρὸς ἐχόμενος τοῦ βωμοῦ· κεῖται δὲ καὶ θώραξ ἐπὶ τῷ βωμῷ χαλκοῦς. κατὰ δὴ ἐμὲ σπάνιον τῶν θωράκων τὸ σχῆμα ἦν τούτων, τὸ δὲ ἀρχαῖον ἔφερον αὐτούς. δύο ἦν χαλκᾶ ποιήματα, τὸ μὲν στέρνῳ καὶ τοῖς ἀμφὶ τὴν γαστέρα ἁρμόζον, τὸ δὲ ὡς νώτου σκέπην εἶναι —γύαλα ἐκαλοῦντο—· τὸ μὲν ἔμπροσθεν τὸ δὲ ὄπισθεν προσῆγον, ἔπειτα περόναι συνῆπτον πρὸς ἄλληλα.", "st": "10.26"}, {"sp": "N", "t": "ἀσφάλειαν δὲ ἀποχρῶσαν ἐδόκει παρέχεσθαι καὶ ἀσπίδος χωρίς· ἐπὶ τούτῳ καὶ Ὅμηρος Φόρκυνα τὸν Φρύγα οὐκ ἔχοντα ἀσπίδα ἐποίησεν, ὅτι αὐτῷ γυαλοθώραξ ἦν. ἐγὼ δὲ γραφῇ μεμιμημένον τοῦτον ἐθεασάμην ὑπὸ τοῦ Πολυγνώτου, καὶ ἐν Ἀρτέμιδος τῆς Ἐφεσίας Καλλιφῶν ὁ Σάμιος Πατρόκλῳ τοῦ θώρακος τὰ γύαλα ἁρμοζούσας ἔγραψε γυναῖκας.", "st": "10.26"}, {"sp": "N", "t": "τοῦ βωμοῦ δὲ ἐπέκεινα Λαοδίκην ἔγραψεν ἑστῶσαν. ταύτην οὔτε ὑπὸ ποιητοῦ κατειλεγμένην ἐν ταῖς αἰχμαλώτοις ταῖς Τρῳάσιν εὕρισκον οὔτε ἄλλως ἐφαίνετο ἔχειν μοι τὸ εἰκὸς ἢ ἀφεθῆναι τὴν Λαοδίκην ὑπὸ Ἑλλήνων. Ὅμηρος μέν γε ἐδήλωσεν ἐν Ἰλιάδι Μενελάου καὶ Ὀδυσσέως ξενίαν παρὰ Ἀντήνορι καὶ ὡς Ἑλικάονι ἡ Λαοδίκη συνοικοίη τῷ Ἀντήνορος·", "st": "10.26"}, {"sp": "N", "t": "Λέσχεως δὲ τετρωμένον τὸν Ἑλικάονα ἐν τῇ νυκτομαχίᾳ γνωρισθῆναί τε ὑπὸ Ὀδυσσέως καὶ ἐξαχθῆναι ζῶντα ἐκ τῆς μάχης φησίν. ἕποιτο ἂν οὖν τῇ Μενελάου καὶ Ὀδυσσέως κηδεμονίᾳ περὶ οἶκον τὸν Ἀντήνορος μηδὲ ἐς τοῦ Ἑλικάονος τὴν γυναῖκα ἔργον δυσμενὲς ὑπὸ Ἀγαμέμνονος καὶ Μενελάου γενέσθαι· Εὐφορίων δὲ ἀνὴρ Χαλκιδεὺς σὺν οὐδενὶ εἰκότι τὰ ἐς τὴν Λαοδίκην ἐποίησεν.", "st": "10.26"}, {"sp": "N", "t": "ἐφεξῆς δὲ τῇ Λαοδίκῃ ὑποστάτης τε λίθου καὶ λουτήριόν ἐστιν ἐπὶ τῷ ὑποστάτῃ χαλκοῦν, Μέδουσα δὲ κατέχουσα ταῖς χερσὶν ἀμφοτέραις τὸ ὑπόστατον ἐπὶ τοῦ ἐδάφους κάθηται· ἐν δὲ ταῖς Πριάμου θυγατράσιν ἀριθμήσαι τις ἂν καὶ ταύτην κατὰ τοῦ Ἱμεραίου τὴν ᾠδήν. παρὰ δὲ τὴν Μέδουσαν ἐν χρῷ κεκαρμένη πρεσβῦτις ἢ ἄνθρωπός ἐστιν εὐνοῦχος, παιδίον δὲ ἐν τοῖς γόνασιν ἔχει γυμνόν· τὸ δὲ τὴν χεῖρα ὑπὸ δείματος ἐπίπροσθε τῶν ὀφθαλμῶν πεποίηται.", "st": "10.26"}, {"sp": "N", "t": "νεκροὶ δὲ ὁ μὲν γυμνὸς Πῆλις ὄνομα ἐπὶ τὸν νῶτόν ἐστιν ἐρριμμένος, ὑπὸ δὲ τὸν Πῆλιν Ἠιονεύς τε κεῖται καὶ Ἄδμητος ἐνδεδυκότες ἔτι τοὺς θώρακας· καὶ αὐτῶν Λέσχεως Ἠιονέα ὑπὸ Νεοπτολέμου, τὸν δὲ ὑπὸ Φιλοκτήτου φησὶν ἀποθανεῖν τὸν Ἄδμητον. ἄλλοι δὲ ἀνωτέρω τούτων ὑπὸ μὲν τὸ λουτήριον Λεώκριτός ἐστιν ὁ Πουλυδάμαντος τεθνεὼς ὑπὸ Ὀδυσσέως, ὑπὲρ δὲ Ἠιονέα τε καὶ Ἄδμητον Κόροιβος ὁ Μύγδονος· τούτου μνῆμά τε ἐπιφανὲς ἐν ὅροις πεποίηται Φρυγῶν Στεκτορηνῶν καὶ ἀπ’ αὐτοῦ ποιηταῖς Μύγδονας ὄνομα ἐπὶ τοῖς Φρυξὶ τίθεσθαι καθέστηκεν. ἀφίκετο μὲν δὴ ἐπὶ τὸν Κασσάνδρας ὁ Κόροιβος γάμον, ἀπέθανε δέ, ὡς μὲν ὁ πλείων λόγος, ὑπὸ Νεοπτολέμου, Λέσχεως δὲ ὑπὸ Διομήδους ἐποίησεν.", "st": "10.27"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ ἐπάνω τοῦ Κοροίβου Πρίαμος καὶ Ἀξίων τε καὶ Ἀγήνωρ. Πρίαμον δὲ οὐκ ἀποθανεῖν ἔφη Λέσχεως ἐπὶ τῇ ἐσχάρᾳ τοῦ Ἑρκείου, ἀλλὰ ἀποσπασθέντα ἀπὸ τοῦ βωμοῦ πάρεργον τῷ Νεοπτολέμῳ πρὸς ταῖς τῆς οἰκίας γενέσθαι θύραις. ἐς δὲ Ἑκάβην Στησίχορος ἐν Ἰλίου πέρσιδι ἐποίησεν ἐς Λυκίαν ὑπὸ Ἀπόλλωνος αὐτὴν κομισθῆναι. Ἀξίονα δὲ παῖδα εἶναι Πριάμου Λέσχεως καὶ ἀποθανεῖν αὐτὸν ὑπὸ Εὐρυπύλου τοῦ Εὐαίμονός φησι· τοῦ Ἀγήνορος δὲ κατὰ τὸν αὐτὸν ποιητὴν Νεοπτόλεμος αὐτόχειρ ἐστί· καὶ οὕτω φαίνοιτο ἂν Ἔχεκλος μὲν φονευθεὶς ὁ Ἀγήνορος ὑπὸ Ἀχιλλέως, Ἀγήνωρ δὲ αὐτὸς ὑπὸ τοῦ Νεοπτολέμου.", "st": "10.27"}, {"sp": "N", "t": "Λαομέδοντος δὲ τὸν νεκρὸν Σίνων τε ἑταῖρος Ὀδυσσέως καὶ Ἀγχίαλός εἰσιν ἐκκομίζοντες. γέγραπται δὲ καὶ ἄλλος τεθνεώς· ὄνομά οἱ Ἔρεσος· τὰ δὲ ἐς Ἔρεσόν τε καὶ Λαομέδοντα, ὅσα γε ἡμεῖς ἐπιστάμεθα, ᾖσεν οὐδείς. ἔστι δὲ οἰκία τε ἡ Ἀντήνορος καὶ παρδάλεως κρεμάμενον δέρμα ὑπὲρ τῆς ἐσόδου, σύνθημα εἶναι τοῖς Ἕλλησιν ἀπέχεσθαι σφᾶς οἴκου τοῦ Ἀντήνορος. γέγραπται δὲ Θεανώ τε καὶ οἱ παῖδες, Γλαῦκος μὲν καθήμενος ἐπὶ θώρακι γυάλοις συνηρμοσμένῳ, Εὐρύμαχος δὲ ἐπὶ πέτρᾳ.", "st": "10.27"}, {"sp": "N", "t": "παρὰ δὲ αὐτὸν ἕστηκεν Ἀντήνωρ καὶ ἐφεξῆς θυγάτηρ Ἀντήνορος Κρινώ· παιδίον δὲ ἡ Κρινὼ φέρει νήπιον. τῶν προσώπων δὲ ἅπασιν οἷον ἐπὶ συμφορᾷ σχῆμά ἐστι. κιβωτὸν δὲ ἐπὶ ὄνον καὶ ἄλλα τῶν σκευῶν εἰσιν ἀνατιθέντες οἰκέται· κάθηται δὲ καὶ ἐπὶ ⟨τοῦ⟩ ὄνου παιδίον μικρόν. κατὰ τοῦτο τῆς γραφῆς καὶ ἐλεγεῖόν ἐστι Σιμωνίδου·<br>γράψε Πολύγνωτος, Θάσιος γένος, Ἀγλαοφῶντος<br>υἱός, περθομένην Ἰλίου ἀκρόπολιν.", "st": "10.27"}, {"sp": "N", "t": "τὸ δὲ ἕτερον μέρος τῆς γραφῆς τὸ ἐξ ἀριστερᾶς χειρός, ἔστιν Ὀδυσσεὺς καταβεβηκὼς ἐς τὸν Ἅιδην ὀνομαζόμενον, ὅπως Τειρεσίου τὴν ψυχὴν περὶ τῆς ἐς τὴν οἰκείαν ἐπέρηται σωτηρίας· ἔχει δὲ οὕτω τὰ ἐς τὴν γραφήν. ὕδωρ εἶναι ποταμὸς ἔοικε, δῆλα ὡς ὁ Ἀχέρων, καὶ κάλαμοί τε ἐν αὐτῷ πεφυκότες καὶ ⟨ἰχθύες· ἔστι δ’⟩ ἀμυδρὰ οὕτω δή τι τὰ εἴδη τῶν ἰχθύων ⟨ὡς⟩ σκιὰς μᾶλλον ἢ ἰχθῦς εἰκάσεις. καὶ ναῦς ἐστιν ἐν τῷ ποταμῷ καὶ ὁ πορθμεὺς ἐπὶ ταῖς κώπαις.", "st": "10.28"}, {"sp": "N", "t": "ἐπηκολούθησε δὲ ὁ Πολύγνωτος ἐμοὶ δοκεῖν ποιήσει Μινυάδι· ἔστι γὰρ δὴ ἐν τῇ Μινυάδι ἐς Θησέα ἔχοντα καὶ Πειρίθουν<br>ἔνθ’ ἤτοι νέα μὲν νεκυάμβατον, ἣν ὁ γεραιός<br>πορθμεὺς ἦγε Χάρων, οὐκ ἔλαβον ἔνδοθεν ὅρμου.<br>ἐπὶ τούτῳ οὖν καὶ Πολύγνωτος γέροντα ἔγραψεν ἤδη τῇ ἡλικίᾳ τὸν Χάρωνα.", "st": "10.28"}, {"sp": "N", "t": "οἱ δὲ ἐπιβεβηκότες τῆς νεὼς οὐκ ἐπιφανεῖς ἐς ἅπαν εἰσὶν οἷς προσήκουσι. Τέλλις μὲν ἡλικίαν ἐφήβου γεγονὼς φαίνεται, Κλεόβοια δὲ ἔτι παρθένος, ἔχει δὲ ἐν τοῖς γόνασι κιβωτὸν ὁποίας ποιεῖσθαι νομίζουσι Δήμητρι. ἐς μὲν δὴ τὸν Τέλλιν τοσοῦτον ἤκουσα ὡς ὁ ποιητὴς Ἀρχίλοχος ἀπόγονος εἴη τρίτος Τέλλιδος, Κλεόβοιαν δὲ ἐς Θάσον τὰ ὄργια τῆς Δήμητρος ἐνεγκεῖν πρώτην ἐκ Πάρου φασίν.", "st": "10.28"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ Ἀχέροντος τῇ ὄχθῃ μάλιστα ⟨θέας⟩ ἄξιον, ὅτι ὑπὸ τοῦ Χάρωνος τὴν ναῦν ἀνὴρ οὐ δίκαιος ἐς πατέρα ἀγχόμενός ἐστιν ὑπὸ τοῦ πατρός. περὶ πλείστου γὰρ δὴ ἐποιοῦντο οἱ πάλαι γονέας, ὥσπερ ἔστιν ἄλλοις τε τεκμήρασθαι καὶ ἐν Κατάνῃ τοῖς καλουμένοις Εὐσεβέσιν, οἵ, ἡνίκα ἐπέρρει τῇ Κατάνῃ πῦρ τὸ ἐκ τῆς Αἴτνης, χρυσὸν μὲν καὶ ἄργυρον ἐν οὐδενὸς μερίδι ἐποιήσαντο, οἱ δὲ ἔφευγον ὁ μὲν ἀράμενος μητέρα, ὁ δὲ αὐτῶν τὸν πατέρα· προϊόντας δὲ οὐ σὺν ῥᾳστώνῃ καταλαμβάνει σφᾶς τὸ πῦρ ἐπειγόμενον τῇ φλογί· καὶ —οὐ γὰρ κατετίθεντο οὐδ’ οὕτω τοὺς γονέας— διχῇ σχισθῆναι λέγεται τὸν ῥύακα, καὶ αὐτούς τε τοὺς νεανίσκους, σὺν δὲ αὐτοῖς τοὺς γονέας τὸ πῦρ οὐδέν σφισι λυμηνάμενον παρεξῆλθεν.", "st": "10.28"}, {"sp": "N", "t": "οὗτοι μὲν δὴ τιμὰς καὶ ἐς ἐμὲ ἔτι παρὰ Καταναίων ἔχουσιν, ἐν δὲ τῇ Πολυγνώτου γραφῇ πλησίον τοῦ ἀνδρός, ὃς τῷ πατρὶ ἐλυμαίνετο καὶ δι’ αὐτὸ ἐν Ἅιδου κακὰ ἀναπίμπλησι, τούτου πλησίον ἱερὰ σεσυληκὼς ἀνὴρ ὑπέσχε δίκην· γυνὴ δὲ ἡ κολάζουσα αὐτὸν φάρμακα ἄλλα τε καὶ ἐς αἰκίαν οἶδεν ἀνθρώπων.", "st": "10.28"}, {"sp": "N", "t": "περισσῶς δὲ ἄρα εὐσεβείᾳ θεῶν ἔτι προσέκειντο οἱ ἄνθρωποι, ὡς Ἀθηναῖοί τε δῆλα ἐποίησαν, ἡνίκα εἷλον Ὀλυμπίου Διὸς ἐν Συρακούσαις ἱερόν, οὔτε κινήσαντες τῶν ἀναθημάτων οὐδὲν τὸν ἱερέα τε τὸν Συρακούσιον φύλακα ἐπ’ αὐτοῖς ἐάσαντες· ἐδήλωσε δὲ καὶ ὁ Μῆδος Δᾶτις λόγοις τε οὓς εἶπε πρὸς Δηλίους καὶ τῷ ἔργῳ, ἡνίκα ἐν Φοινίσσῃ νηὶ ἄγαλμα εὑρὼν Ἀπόλλωνος ἀπέδωκεν αὖθις Ταναγραίοις ἐς Δήλιον. οὕτω μὲν τὸ θεῖον καὶ οἱ πάντες τότε ἦγον ἐν τιμῇ, καὶ ἐπὶ λόγῳ τοιούτῳ τὰ ἐς τὸν συλήσαντα ἱερὰ ἔγραψε Πολύγνωτος.", "st": "10.28"}, {"sp": "N", "t": "ἔστι δὲ ἀνωτέρω τῶν κατειλεγμένων Εὐρύνομος· δαίμονα εἶναι τῶν ἐν Ἅιδου φασὶν οἱ Δελφῶν ἐξηγηταὶ τὸν Εὐρύνομον, καὶ ὡς τὰς σάρκας περιεσθίει τῶν νεκρῶν, μόνα σφίσιν ἀπολείπων τὰ ὀστᾶ. ἡ δὲ Ὁμήρου ποίησις ἐς Ὀδυσσέα καὶ ἡ Μινυάς τε καλουμένη καὶ οἱ Νόστοι—μνήμη γὰρ δὴ ἐν ταύταις καὶ Ἅιδου καὶ τῶν ἐκεῖ δειμάτων ἐστὶν—ἴσασιν οὐδένα Εὐρύνομον δαίμονα. τοσοῦτο μέντοι δηλώσω, ὁποῖός τε ὁ Εὐρύνομος καὶ ἐπὶ ποίου γέγραπται τοῦ σχήματος· κυανοῦ τὴν χρόαν μεταξύ ἐστι καὶ μέλανος, ὁποῖαι καὶ τῶν μυιῶν αἱ πρὸς τὰ κρέα εἰσὶ προσιζάνουσαι, τοὺς δὲ ὀδόντας φαίνει, καθεζομένῳ δὲ ὑπέστρωταί οἱ δέρμα γυπός.", "st": "10.28"}, {"sp": "N", "t": "ἐφεξῆς δὲ μετὰ τὸν Εὐρύνομον ἥ τε ἐξ Ἀρκαδίας Αὔγη καὶ Ἰφιμέδειά ἐστι· καὶ ἡ μὲν παρὰ Τεύθραντα ἡ Αὔγη ἀφίκετο ἐς Μυσίαν, καὶ γυναικῶν ὁπόσαις ἐς τὸ αὐτὸ Ἡρακλέα ἀφικέσθαι λέγουσι, μάλιστα δὴ παῖδα ἐοικότα ἔτεκε τῷ πατρί· τῇ δ’ Ἰφιμεδείᾳ γέρα δέδοται μεγάλα ὑπὸ τῶν ἐν Μυλάσοις Καρῶν.", "st": "10.28"}, {"sp": "N", "t": "τῶν δὲ ἤδη μοι κατειλεγμένων εἰσὶν ἀνώτεροι τούτων ἱερεῖα [καὶ] οἱ ἑταῖροι τοῦ Ὀδυσσέως Περιμήδης καὶ Εὐρύλοχος φέροντες· τὰ δέ ἐστι μέλανες κριοὶ τὰ ἱερεῖα. μετὰ δὲ αὐτοὺς ἀνήρ ἐστι καθήμενος, ἐπίγραμμα δὲ Ὄκνον εἶναι λέγει τὸν ἄνθρωπον· πεποίηται μὲν πλέκων σχοινίον, παρέστηκε δὲ θήλεια ὄνος ἐπεσθίουσα τὸ πεπλεγμένον ἀεὶ τοῦ σχοινίου. τοῦτον εἶναι τὸν Ὄκνον φίλεργόν φασιν ἄνθρωπον, γυναῖκα δὲ ἔχειν δαπανηράν· καὶ ὁπόσα συλλέξαιτο ἐργαζόμενος, οὐ πολὺ δὴ ὕστερον ὑπὸ ἐκείνης ἀνήλωτο.", "st": "10.29"}, {"sp": "N", "t": "τὰ οὖν ἐς τοῦ Ὄκνου τὴν γυναῖκα ἐθέλουσιν αἰνίξασθαι τὸν Πολύγνωτον. οἶδα δὲ καὶ ὑπὸ Ἰώνων, ὁπότε ἴδοιέν τινα πονοῦντα ἐπὶ οὐδενὶ ὄνησιν φέροντι, ὑπὸ τούτων εἰρημένον ὡς ὁ ἀνὴρ οὗτος συνάγει τοῦ Ὄκνου τὴν θώμιγγα. ὄκνον δ’ οὖν καὶ μάντεων οἱ ὁρῶντες τοὺς οἰωνοὺς καλοῦσί τινα ὄρνιθα· καὶ ἔστιν οὗτος ὁ ὄκνος μέγιστος μὲν καὶ κάλλιστος ἐρωδιῶν, εἰ δὲ ἄλλος τις ὀρνίθων σπάνιός ἐστι καὶ οὗτος.", "st": "10.29"}, {"sp": "N", "t": "γέγραπται δὲ καὶ Τιτυὸς οὐ κολαζόμενος ἔτι, ἀλλὰ ὑπὸ τοῦ συνεχοῦς τῆς τιμωρίας ἐς ἅπαν ἐξανηλωμένος, ἀμυδρὸν καὶ οὐδὲ ὁλόκληρον εἴδωλον. ἐπιόντι δὲ ἐφεξῆς τὰ ἐν τῇ γραφῇ, ἔστιν ἐγγυτάτω τοῦ στρέφοντος τὸ καλῴδιον Ἀριάδνη· κάθηται μὲν ἐπὶ πέτρας, ὁρᾷ δὲ ἐς τὴν ἀδελφὴν Φαίδραν, τό τε ἄλλο αἰωρουμένην σῶμα ἐν σειρᾷ καὶ ταῖς χερσὶν ἀμφοτέραις ἑκατέρωθεν τῆς σειρᾶς ἐχομένην· παρεῖχε δὲ τὸ σχῆμα καίπερ ἐς τὸ εὐπρεπέστερον πεποιημένον συμβάλλεσθαι τὰ ἐς τῆς Φαίδρας τὴν τελευτήν.", "st": "10.29"}, {"sp": "N", "t": "τὴν δὲ Ἀριάδνην ἢ κατά τινα ἐπιτυχὼν δαίμονα ἢ καὶ ἐπίτηδες αὐτὴν λοχήσας ἀφείλετο Θησέα ἐπιπλεύσας Διόνυσος στόλῳ μείζονι, οὐκ ἄλλος κατὰ ἐμὴν δόξαν, ἀλλὰ ὁ πρῶτος μὲν ἐλάσας ἐπὶ Ἰνδοὺς στρατείᾳ, πρῶτος δὲ Εὐφράτην γεφυρώσας ποταμόν· Ζεῦγμά τε ὠνομάσθη πόλις καθ’ ὅ τι ἐζεύχθη τῆς χώρας ὁ Εὐφράτης, καὶ ἔστιν ἐνταῦθα ὁ κάλως καὶ ἐς ἡμᾶς ἐν ᾧ τὸν ποταμὸν ἔζευξεν, ἀμπελίνοις ὁμοῦ πεπλεγμένος καὶ κισσοῦ κλήμασι.", "st": "10.29"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐς Διόνυσον πολλὰ ὑπό τε Ἑλλήνων λεγόμενα καὶ ὑπὸ Αἰγυπτίων ἐστίν· ὑπὸ δὲ τὴν Φαίδραν ἐστὶν ἀνακεκλιμένη Χλῶρις ἐπὶ τῆς Θυίας γόνασιν. οὐχ ἁμαρτήσεται μὲν δὴ οὐδὲ ὅστις φησὶ φιλίαν εἶναι ἐς ἀλλήλας, ἡνίκα ἔτυχον αἱ γυναῖκες ζῶσαι· ἦσαν γὰρ δὴ ἡ μὲν ἐξ Ὀρχομενοῦ τοῦ ἐν Βοιωτίᾳ ἡ Χλῶρις, ἡ δὲ ⟨Κασταλίου θυγάτηρ ἀπὸ τοῦ Παρνασσοῦ.⟩ εἶπον δ’ ἂν καὶ ἄλλοι τὸν ἐς αὐτὰς λόγον, τῇ μὲν συγγενέσθαι Ποσειδῶνα τῇ Θυίᾳ, Χλῶριν δὲ Ποσειδῶνος παιδὶ Νηλεῖ συνοικῆσαι.", "st": "10.29"}, {"sp": "N", "t": "παρὰ δὲ τὴν Θυίαν Πρόκρις τε ἕστηκεν ἡ Ἐρεχθέως καὶ μετ’ αὐτὴν Κλυμένη· ἐπιστρέφει δὲ αὐτῇ τὰ νῶτα ἡ Κλυμένη. ἔστι δὲ πεποιημένα ἐν Νόστοις Μινύου μὲν τὴν Κλυμένην θυγατέρα εἶναι, γήμασθαι δὲ αὐτὴν Κεφάλῳ τῷ Δηίονος καὶ γενέσθαι σφίσιν Ἴφικλον παῖδα. τὰ δὲ ἐς τὴν Πρόκριν καὶ οἱ πάντες ᾄδουσιν, ὡς προτέρα Κεφάλῳ ἢ Κλυμένη συνῴκησε καὶ ὃν τρόπον ἐτελεύτησεν ὑπὸ τοῦ ἀνδρός.", "st": "10.29"}, {"sp": "N", "t": "ἐσωτέρω δὲ τῆς Κλυμένης Μεγάραν τὴν ἐκ Θηβῶν ὄψει· ταύτην γυναῖκα ἔσχεν Ἡρακλῆς τὴν Μεγάραν καὶ ἀπεπέμψατο ἀνὰ χρόνον, ἅτε παίδων τε ἐστερημένος τῶν ἐξ αὐτῆς καὶ αὐτὴν ἡγούμενος οὐκ ἐπὶ ἀμείνονι τῷ δαίμονι ⟨γῆμαι⟩. γυναικῶν ⟨δὲ⟩ τῶν κατειλεγμένων ὑπὲρ τῆς κεφαλῆς ἥ τε Σαλμωνέως θυγάτηρ ἐστὶν ἐπὶ πέτρας καθεζομένη καὶ Ἐριφύλη παρ’ αὐτὴν [ἐστιν] ἑστῶσα, διὰ μὲν τοῦ χιτῶνος ἀνέχουσα ἄκρους παρὰ τὸν τράχηλον τοὺς δακτύλους, τοῦ χιτῶνος δὲ ἐν τοῖς κοίλοις εἰκάσεις τῶν χειρῶν ⟨τῇ ἑτέρᾳ⟩ ἐκεῖνον τὸν ὅρμον αὐτὴν ἔχειν.", "st": "10.29"}, {"sp": "N", "t": "ὑπὲρ δὲ τὴν Ἐριφύλην ἔγραψεν Ἐλπήνορά τε καὶ Ὀδυσσέα ὀκλάζοντα ἐπὶ τοῖς ποσίν, ἔχοντα ὑπὲρ τοῦ βόθρου τὸ ξίφος· καὶ ὁ μάντις Τειρεσίας πρόεισιν ἐπὶ τὸν βόθρον. μετὰ δὲ τὸν Τειρεσίαν ἐπὶ πέτρας ἡ Ὀδυσσέως μήτηρ Ἀντίκλειά ἐστιν· ὁ δὲ Ἐλπήνωρ ἀμπέχεται φορμὸν ἀντὶ ἐσθῆτος, σύνηθες τοῖς ναύταις φόρημα.", "st": "10.29"}, {"sp": "N", "t": "κατωτέρω δὲ τοῦ Ὀδυσσέως ἐπὶ θρόνων καθεζόμενοι Θησεὺς μὲν τὰ ξίφη τό τε Πειρίθου καὶ τὸ ἑαυτοῦ ταῖς χερσὶν ἀμφοτέραις ἔχει, ὁ δὲ ἐς τὰ ξίφη βλέπων ἐστὶν ὁ Πειρίθους· εἰκάσαις ἂν ἄχθεσθαι τοῖς ξίφεσιν αὐτὸν ὡς ἀχρείοις καὶ ὄφελός σφισιν οὐ γεγενημένοις ἐς τὰ τολμήματα. Πανύασσις δὲ ἐποίησεν ὡς Θησεὺς καὶ Πειρίθους ἐπὶ τῶν θρόνων παράσχοιντο σχῆμα οὐ κατὰ δεσμώτας, προσφύεσθαι δὲ ἀπὸ τοῦ χρωτὸς ἀντὶ δεσμῶν σφισιν ἔφη τὴν πέτραν.", "st": "10.29"}, {"sp": "N", "t": "Θησέως δὲ καὶ Πειρίθου τὴν λεγομένην φιλίαν ἐν ἀμφοτέραις ἐδήλωσεν Ὅμηρος ταῖς ποιήσεσι, καὶ Ὀδυσσεὺς μὲν πρὸς Φαίακας λέγων ἐστὶ<br>καί νύ κ’ ἔτι προτέρους ἴδον ἀνέρας οὓς ἔθελόν περ,<br>Θησέα Πειρίθοόν τε, θεῶν ἐρικυδέα τέκνα·<br>πεποίηται δὲ αὐτῷ καὶ ἐν Ἰλιάδι ὁ Νέστωρ ἄλλα τε ἐπὶ Ἀγαμέμνονος καὶ Ἀχιλλέως νουθεσίᾳ καὶ ἔπη τάδε εἰρηκώς·<br>οὐ γάρ πω τοίους ἴδον ἀνέρας οὐδὲ ἴδωμαι<br>οἷον Πειρίθοόν τε Δρύαντά τε ποιμένα λαῶν<br>Καινέα τ’ Ἐξάδιόν τε καὶ ἀντίθεον Πολύφημον<br>Θησέα τ’ Αἰγείδην ἐπιείκελον ἀθανάτοισιν.", "st": "10.29"}, {"sp": "N", "t": "ἐφεξῆς δὲ τὰς Πανδάρεω θυγατέρας ἔγραψεν ὁ Πολύγνωτος. Ὁμήρῳ δὲ ἐν Πηνελόπης λόγοις ἐστὶν ὡς ἀποθάνοιεν μὲν ταῖς παρθένοις οἱ γεινάμενοι κατὰ μήνιμα ἐκ θεῶν, αὐτὰς δὲ ὀρφανὰς τραφῆναι μὲν ὑπὸ Ἀφροδίτης, λαβεῖν δὲ καὶ παρ’ ἄλλων θεῶν, Ἥρας μὲν φρονεῖν τε ἱκανὰς εἶναι καὶ εἶδος καλάς, μῆκος δὲ τοῦ σώματος Ἄρτεμίν φησιν αὐταῖς δωρήσασθαι, ἔργα δὲ γυναιξὶν ἁρμόζοντα ὑπὸ Ἀθηνᾶς διδαχθῆναι.", "st": "10.30"}, {"sp": "N", "t": "Ἀφροδίτην μὲν οὖν ἐς οὐρανὸν ἀνέρχεσθαι, παρὰ Διὸς γάμον εὐδαίμονα ἐθέλουσαν ταῖς παισὶν εὕρασθαι, τὰς δὲ ἀπούσης ἐκείνης ἁρπασθῆναί τε ὑπὸ Ἁρπυιῶν καὶ Ἐρινύσιν ὑπ’ αὐτῶν δοθῆναι. τάδε μέν ἐστιν ἐς αὐτὰς Ὁμήρῳ πεποιημένα, Πολύγνωτος δὲ κόρας τε ἐστεφανωμένας ἄνθεσι καὶ παιζούσας ἔγραψεν ἀστραγάλοις, ὄνομα δὲ αὐταῖς Καμειρώ τε καὶ Κλυτίη. τὸν δὲ Πανδάρεων Μιλήσιόν τε ἐκ Μιλήτου τῆς Κρητικῆς ὄντα ἴστω τις καὶ ἀδικήματος ἐς τὴν κλοπὴν Ταντάλῳ καὶ τοῦ ἐπὶ τῷ ὅρκῳ μετασχόντα σοφίσματος.", "st": "10.30"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Πανδάρεω τὰς κόρας Ἀντίλοχος τὸν μὲν ἕτερον ἐπὶ πέτρας τῶν ποδῶν, τὸ δὲ πρόσωπον καὶ τὴν κεφαλὴν ἐπὶ ταῖς χερσὶν ἀμφοτέραις ἔχων ἐστίν, Ἀγαμέμνων δὲ μετὰ τὸν Ἀντίλοχον σκήπτρῳ τε ὑπὸ τὴν ἀριστερὰν μασχάλην ἐρειδόμενος καὶ ταῖς χερσὶν ἐπανέχων ῥάβδον· Πρωτεσίλαος δὲ πρὸς Ἀχιλλέα ἀφορᾷ καθεζόμενος. καὶ ὁ Πρωτεσίλαος ⟨τοιοῦτον⟩ παρέχεται σχῆμα, ὑπὲρ δὲ τὸν Ἀχιλλέα Πάτροκλός ἐστιν ἑστηκώς. οὗτοι πλὴν τοῦ Ἀγαμέμνονος οὐκ ἔχουσι γένεια οἱ ἄλλοι.", "st": "10.30"}, {"sp": "N", "t": "γέγραπται δὲ ὑπὲρ αὐτοὺς Φῶκός τε ἡλικίαν μειράκιον καὶ Ἰασεὺς γενείων μὲν εὖ ἔχων, δακτύλιον δὲ ἐκ τῆς ἀριστερᾶς τοῦ Φώκου περιαιρούμενος χειρὸς ἐπὶ τοιῷδέ ἐστι λόγῳ. Φώκῳ τῷ Αἰακοῦ διαβάντι ἐξ Αἰγίνης ἐς τὴν νῦν καλουμένην Φωκίδα, καὶ ἀνθρώπων τε ἀρχὴν τῶν ἐν τῇ ἠπείρῳ ταύτῃ κτήσασθαι καὶ αὐτῷ θέλοντι ἐνταῦθα οἰκῆσαι, ἀφίκετο ἐπὶ πλεῖστον ὁ Ἰασεὺς φιλίας, καί οἱ δῶρα ἄλλα τε ὡς τὸ εἰκὸς ἐδωρήσατο καὶ λίθου σφραγῖδα ἐνδεδεμένην χρυσῷ· Φώκῳ δὲ οὐ μετὰ πολὺν χρόνον ἀνακομισθέντι ἐς Αἴγιναν Πηλεὺς αὐτίκα ἐβούλευσε τοῦ βίου τὴν τελευτήν. καὶ τοῦδε ἕνεκα ἐν τῇ γραφῇ ἐς ἀνάμνησιν ἐκείνης τῆς φιλίας ὅ τε Ἰασεὺς τὴν σφραγῖδά ἐστιν ἐθέλων θεάσασθαι καὶ ὁ Φῶκος παρεὶς λαβεῖν αὐτήν.", "st": "10.30"}, {"sp": "N", "t": "ὑπὲρ τούτους Μαῖρά ἐστιν ἐπὶ πέτρᾳ καθεζομένη· περὶ δὲ αὐτῆς πεποιημένα ἐστὶν ἐν Νόστοις ἀπελθεῖν μὲν παρθένον ἔτι ἐξ ἀνθρώπων, θυγατέρα δὲ αὐτὴν εἶναι Προίτου τοῦ Θερσάνδρου, τὸν δὲ εἶναι Σισύφου. ἐφεξῆς δὲ τῆς Μαίρας Ἀκταίων ἐστὶν ὁ Ἀρισταίου καὶ ἡ τοῦ Ἀκταίωνος μήτηρ, νεβρὸν ἐν ταῖς χερσὶν ἔχοντες ἐλάφου καὶ ἐπὶ δέρματι ἐλάφου καθεζόμενοι· κύων τε θηρευτικὴ παρακατάκειταί σφισι βίου τοῦ Ἀκταίωνος ἕνεκα καὶ τοῦ ἐς τὴν τελευτὴν τρόπου.", "st": "10.30"}, {"sp": "N", "t": "ἀποβλέψαντι δὲ αὖθις ἐς τὰ κάτω τῆς γραφῆς, ἔστιν ἐφεξῆς μετὰ τὸν Πάτροκλον οἷα ἐπὶ λόφου τινὸς Ὀρφεὺς καθεζόμενος, ἐφάπτεται δὲ καὶ τῇ ἀριστερᾷ κιθάρας, τῇ δὲ ἑτέρᾳ χειρὶ ἰτέας ψαύει· κλῶνές εἰσιν ὧν ψαύει, προσανακέκλιται δὲ τῷ δένδρῳ. τὸ δὲ ἄλσος ἔοικεν εἶναι τῆς Περσεφόνης, ἔνθα αἴγειροι καὶ ἰτέαι δόξῃ τῇ Ὁμήρου πεφύκασιν· Ἑλληνικὸν δὲ τὸ σχῆμά ἐστι τῷ Ὀρφεῖ, καὶ οὔτε ἡ ἐσθὴς οὔτε ἐπίθημά ἐστιν ἐπὶ τῇ κεφαλῇ Θρᾴκιον.", "st": "10.30"}, {"sp": "N", "t": "τῷ δένδρῳ δὲ τῇ ἰτέᾳ κατὰ τὸ ἕτερον μέρος προσανακεκλιμένος ἐστὶν αὐτῇ Προμέδων. εἰσὶ μὲν δὴ οἳ νομίζουσι καθάπερ ἐς ποίησιν ἐπεσῆχθαι τὸ Προμέδοντος ὄνομα ὑπὸ τοῦ Πολυγνώτου· τοῖς δὲ εἰρημένον ἐστὶν ἄνδρα Ἕλληνα ἔς τε τὴν ἄλλην ἅπασαν γενέσθαι φιλήκοον μουσικὴν καὶ ἐπὶ τῇ ᾠδῇ μάλιστα τῇ Ὀρφέως.", "st": "10.30"}, {"sp": "N", "t": "κατὰ τοῦτο τῆς γραφῆς Σχεδίος ὁ Φωκεῦσιν ἡγησάμενος ἐς Τροίαν καὶ μετὰ τοῦτον Πελίας ἐστὶν ἐν θρόνῳ καθεζόμενος, τὰ γένεια ὁμοίως καὶ τὴν κεφαλὴν πολιός, ἐνορᾷ δὲ ἐς τὸν Ὀρφέα· ὁ δὲ Σχεδίος ἐγχειρίδιόν τε ἔχων καὶ ἄγρωστίν ἐστιν ἐστεφανωμένος. Θαμύριδι δὲ ἐγγὺς καθεζομένῳ τοῦ Πελίου διεφθαρμέναι αἱ ὄψεις καὶ ταπεινὸν ἐς ἅπαν σχῆμά ἐστι καὶ ἡ κόμη πολλὴ μὲν ἐπὶ τῆς κεφαλῆς, πολλὴ δὲ αὐτῷ καὶ ἐν τοῖς γενείοις· λύρα δὲ ἔρριπται πρὸς τοῖς ποσί, κατεαγότες αὐτῆς οἱ πήχεις καὶ αἱ χορδαὶ κατερρωγυῖαι.", "st": "10.30"}, {"sp": "N", "t": "ὑπὲρ τούτου ἐστὶν ἐπὶ πέτρας καθεζόμενος Μαρσύας, καὶ Ὄλυμπος παρ’ αὐτὸν παιδός ἐστιν ὡραίου καὶ αὐλεῖν διδασκομένου σχῆμα ἔχων. οἱ δὲ ἐν Κελαιναῖς Φρύγες ἐθέλουσι μὲν τὸν ποταμὸν ὃς διέξεισιν αὐτοῖς διὰ τῆς πόλεως ἐκεῖνόν ποτε εἶναι τὸν αὐλητήν, ἐθέλουσι δὲ καὶ εὕρημα εἶναι τοῦ Μαρσύου τὸ Μητρῷον αὔλημα· φασὶ δὲ ὡς καὶ τὴν Γαλατῶν ἀπώσαιντο στρατείαν τοῦ Μαρσύου σφίσιν ἐπὶ τοὺς βαρβάρους ὕδατί τε ἐκ τοῦ ποταμοῦ καὶ μέλει τῶν αὐλῶν ἀμύναντος.", "st": "10.30"}, {"sp": "N", "t": "εἰ δὲ ἀπίδοις πάλιν ἐς τὸ ἄνω τῆς γραφῆς, ἔστιν ἐφεξῆς τῷ Ἀκταίωνι Αἴας ὁ ἐκ Σαλαμῖνος, καὶ Παλαμήδης τε καὶ Θερσίτης κύβοις χρώμενοι παιδιᾷ, τοῦ Παλαμήδους τῷ εὑρήματι· Αἴας δὲ ὁ ἕτερος ἐς αὐτοὺς ὁρᾷ παίζοντας. τούτῳ τῷ Αἴαντι τὸ χρῶμά ἐστιν οἷον ⟨ἂν⟩ ἀνδρὶ ναυαγῷ γένοιτο ἐπανθούσης τῷ χρωτὶ ἔτι τῆς ἅλμης.", "st": "10.31"}, {"sp": "N", "t": "ἐς δὲ τὸ αὐτὸ ἐπίτηδες τοῦ Ὀδυσσέως τοὺς ἐχθροὺς ἤγαγεν ὁ Πολύγνωτος· ἀφίκετο δὲ ἐς Ὀδυσσέως δυσμένειαν ὁ τοῦ Ὀιλέως Αἴας, ὅτι τοῖς Ἕλλησιν Ὀδυσσεὺς παρῄνει καταλιθῶσαι τὸν Αἴαντα ἐπὶ τῷ ἐς Κασσάνδραν τολμήματι· Παλαμήδην δὲ ἀποπνιγῆναι προελθόντα ἐπὶ ἰχθύων θήραν, Διομήδην δὲ τὸν ἀποκτείναντα εἶναι καὶ Ὀδυσσέα ἐπιλεξάμενος ἐν ἔπεσιν οἶδα τοῖς Κυπρίοις.", "st": "10.31"}, {"sp": "N", "t": "Μελέαγρος δὲ ὁ Οἰνέως ἀνωτέρω μὲν ἢ ὁ τοῦ Ὀιλέως Αἴας ἐστὶν ἐν τῇ γραφῇ, ἔοικε δὲ ὁρῶντι ἐς τὸν Αἴαντα. τούτοις πλὴν τῷ Παλαμήδει γένειά ἐστι τοῖς ἄλλοις. ἐς δὲ τοῦ Μελεάγρου τὴν τελευτὴν Ὁμήρῳ μέν ἐστιν εἰρημένα ὡς Ἐρινὺς καταρῶν ἀκούσαι τῶν Ἀλθαίας καὶ ἀποθάνοι κατὰ ταύτην ὁ Μελέαγρος τὴν αἰτίαν, αἱ δὲ Ἠοῖαί τε καλούμεναι καὶ ἡ Μινυὰς ὡμολογήκασιν ἀλλήλαις· Ἀπόλλωνα [γὰρ] δὴ αὗταί φασιν αἱ ποιήσεις ἀμῦναι Κούρησιν ἐπὶ τοὺς Αἰτωλοὺς καὶ ἀποθανεῖν Μελέαγρον ὑπὸ Ἀπόλλωνος.", "st": "10.31"}, {"sp": "N", "t": "τὸν δὲ ἐπὶ τῷ δαλῷ λόγον, ὡς δοθείη μὲν ὑπὸ Μοιρῶν τῇ Ἀλθαίᾳ, Μελεάγρῳ δὲ οὐ πρότερον ἔδει τὴν τελευτὴν συμβῆναι πρὶν ἢ ὑπὸ πυρὸς ἀφανισθῆναι τὸν δαλὸν καὶ ὡς ὑπὸ τοῦ θυμοῦ καταπρήσειεν αὐτὸν ἡ Ἀλθαία, τοῦτον τὸν λόγον Φρύνιχος ὁ Πολυφράδμονος πρῶτος ἐν δράματι ἔδειξε Πλευρωνίαις·<br>κρυερὸν γὰρ οὐκ<br>ἤλυξεν μόρον, ὠκεῖα δέ νιν φλὸξ κατεδαίσατο,<br>δαλοῦ περθομένου ματρὸς ὑπ’ αἰνᾶς κακομηχάνου.<br>οὐ μὴν φαίνεταί γε ὁ Φρύνιχος προαγαγὼν τὸν λόγον ἐς πλέον ὡς εὕρημα ἄν τις οἰκεῖον, προσαψάμενος δὲ αὐτοῦ μόνον ἅτε ἐς ἅπαν ἤδη διαβεβοημένου τὸ Ἑλληνικόν.", "st": "10.31"}, {"sp": "N", "t": "ἐν δὲ τοῖς κάτω τῆς γραφῆς μετὰ τὸν Θρᾷκά εἰσι Θάμυριν Ἕκτωρ μὲν καθεζόμενος—ἀμφοτέρας ἔχει τὰς χεῖρας περὶ τὸ ἀριστερὸν γόνυ, ἀνιωμένου σχῆμα ἐμφαίνων—, μετὰ δὲ αὐτὸν Μέμνων ἐστὶν ἐπὶ πέτρᾳ καθεζόμενος καὶ Σαρπηδὼν συνεχὴς τῷ Μέμνονι· ἐπικέκλιται δὲ τὸ πρόσωπον ἐπὶ τὰς χεῖρας ἀμφοτέρας ὁ Σαρπηδών, ἡ δὲ ἑτέρα τῶν χειρῶν τοῦ Μέμνονος ἐπὶ τῷ ὤμῳ τοῦ Σαρπηδόνος κεῖται.", "st": "10.31"}, {"sp": "N", "t": "γένεια μὲν πᾶσίν ἐστιν αὐτοῖς, ἐν δὲ τοῦ Μέμνονος τῇ χλαμύδι καὶ ὄρνιθές εἰσιν ἐπειργασμέναι· Μεμνονίδες ταῖς ὄρνισίν ἐστιν ὄνομα, κατὰ δὲ ἔτος οἱ Ἑλλησπόντιοί φασιν αὐτὰς ἐν εἰρημέναις ἡμέραις ἰέναι τε ἐπὶ τοῦ Μέμνονος τὸν τάφον, καὶ ὁπόσον τοῦ μνήματος δένδρων ἐστὶν ἢ πόας ψιλόν, τοῦτο καὶ σαίρουσιν ⟨αἱ⟩ ὄρνιθες καὶ ὑγροῖς τοῖς πτεροῖς τοῦ Αἰσήπου τῷ ὕδατι ῥαίνουσι.", "st": "10.31"}, {"sp": "N", "t": "παρὰ δὲ τῷ Μέμνονι καὶ παῖς Αἰθίοψ πεποίηται γυμνός, ὅτι ὁ Μέμνων βασιλεὺς ἦν τοῦ Αἰθιόπων γένους. ἀφίκετο μέντοι ἐς Ἴλιον οὐκ ἀπ’ Αἰθιοπίας ἀλλὰ ἐκ Σούσων τῶν Περσικῶν καὶ ἀπὸ τοῦ Χοάσπου ποταμοῦ, τὰ ἔθνη πάντα ὅσα ᾤκει μεταξὺ ὑποχείρια πεποιημένος· Φρύγες δὲ καὶ τὴν ὁδὸν ἔτι ἀποφαίνουσι δι’ ἧς τὴν στρατιὰν ἤγαγε τὰ ἐπίτομα ἐκλεγόμενος τῆς χώρας· τέτμηται δὲ διὰ τῶν μονῶν ἡ ὁδός.", "st": "10.31"}, {"sp": "N", "t": "ὑπὲρ δὲ τὸν Σαρπηδόνα τε καὶ Μέμνονα, ἔστιν ὑπὲρ αὐτοὺς ὁ Πάρις οὐκ ἔχων πω γένεια· κροτεῖ δὲ ταῖς χερσίν, οἷος ἂν γένοιτο ἀνδρὸς ἀγροίκου κρότος· ἐοικέναι τὸν Πάριν φήσεις τῷ ψόφῳ τῶν χειρῶν Πενθεσίλειαν παρ’ αὑτὸν καλοῦντι. ἔστι δὲ καὶ ἡ Πενθεσίλεια ὁρῶσα ἐς τὸν Πάριν, τοῦ προσώπου δὲ ἔοικε τῷ νεύματι ὑπερορᾶν τε αὐτὸν καὶ ἐν οὐδενὸς τίθεσθαι λόγῳ· τὸ δὲ σχῆμά ἐστι τῇ Πενθεσιλείᾳ παρθένος τόξον ἔχουσα τοῖς Σκυθικοῖς ἐμφερὲς καὶ παρδάλεως δέρμα ἐπὶ τῶν ὤμων.", "st": "10.31"}, {"sp": "N", "t": "αἱ δὲ ὑπὲρ τὴν Πενθεσίλειαν φέρουσαι μέν εἰσιν ὕδωρ ἐν κατεαγόσιν ὀστράκοις, πεποίηται δὲ ἡ μὲν ἔτι ὡραία τὸ εἶδος, ἡ δὲ ἤδη τῆς ἡλικίας προήκουσα· ἰδίᾳ μὲν δὴ οὐδὲν ἐπίγραμμα ἐπὶ ἑκατέρᾳ τῶν γυναικῶν, ἐν κοινῷ δέ ἐστιν ἐπὶ ἀμφοτέραις εἶναι σφᾶς τῶν οὐ μεμυημένων γυναικῶν.", "st": "10.31"}, {"sp": "N", "t": "ἀνωτέρω τούτων ἐστὶν ἡ Λυκάονος Καλλιστὼ καὶ Νομία τε καὶ ἡ Νηλέως Πηρώ· ταύτης ἕδνα τῶν γάμων βοῦς ὁ Νηλεὺς ᾔτει τὰς Ἰφίκλου. τῇ Καλλιστοῖ δὲ ἀντὶ μὲν στρωμνῆς ἐστιν αὐτῇ δέρμα ἄρκτου, τοὺς πόδας δὲ ἐν τοῖς Νομίας γόνασιν ἔχει κειμένους. ἐδήλωσε δέ μοι τὰ πρότερα τοῦ λόγου φάναι τοὺς Ἀρκάδας Νομίαν εἶναι [φασὶν] ἐπιχώριον νύμφην· τὰς νύμφας δὲ εἶναι πολὺν μέν τινα ἀριθμὸν βιούσας ἐτῶν, οὐ μέντοι παράπαν γε ἀπηλλαγμένας θανάτου, ποιητῶν ἐστιν ἐς αὐτὰς λόγος. μετὰ δὲ τὴν Καλλιστὼ καὶ ὅσαι σὺν ἐκείνῃ γυναῖκες, κρημνοῦ τε σχῆμά ἐστι καὶ ὁ Αἰόλου Σίσυφος ἀνῶσαι πρὸς τὸν κρημνὸν βιαζόμενος τὴν πέτραν.", "st": "10.31"}, {"sp": "N", "t": "ἔστι δὲ καὶ πίθος ἐν τῇ γραφῇ, πρεσβύτης δὲ ἄνθρωπος, ὁ δὲ ἔτι παῖς, καὶ γυναῖκες, νέα μὲν ὑπὸ τῇ πέτρᾳ, παρὰ δὲ τὸν πρεσβύτην ἐοικυῖα ἐκείνῳ τὴν ἡλικίαν· οἱ μὲν δὴ ἄλλοι φέρουσιν ὕδωρ, τῇ δὲ γραῒ κατεᾶχθαι τὴν ὑδρίαν εἰκάσεις· ὅσον δὲ ἐν τῷ ὀστράκῳ λοιπόν ἦν τοῦ ὕδατος, ἐκχέουσά ἐστιν αὖθις ἐς τὸν πίθον. ἐτεκμαιρόμεθα δ’ εἶναι καὶ τούτους τῶν τὰ δρώμενα Ἐλευσῖνι ἐν οὐδενὶ θεμένων λόγῳ· οἱ γὰρ ἀρχαιότεροι τῶν Ἑλλήνων τελετὴν τὴν Ἐλευσινίαν πάντων ὁπόσα ἐς εὐσέβειαν ἥκει τοσούτῳ ἦγον ἐντιμότερον ὅσῳ καὶ θεοὺς ἐπίπροσθεν ἡρώων.", "st": "10.31"}, {"sp": "N", "t": "ὑπὸ τούτῳ δὲ τῷ πίθῳ Τάνταλος καὶ ἄλλα ἔχων ἐστὶν ἀλγεινὰ ὁπόσα Ὅμηρος ἐπ’ αὐτῷ πεποίηκεν, ἐπὶ δὲ αὐτοῖς πρόσεστίν οἱ καὶ τὸ ἐκ τοῦ ἐπηρτημένου λίθου δεῖμα. Πολύγνωτος μὲν δῆλός ἐστιν ἐπακολουθήσας τῷ Ἀρχιλόχου λόγῳ· Ἀρχίλοχος δὲ οὐκ οἶδα εἴτε ἐδιδάχθη παρὰ ἄλλων τὰ ἐς τὸν λίθον εἴτε καὶ αὐτὸς ἐς τὴν ποίησιν ἐσηνέγκατο. τοσαύτη μὲν πλῆθος καὶ εὐπρεπείας ἐς τοσοῦτόν ἐστιν ἥκουσα ἡ τοῦ Θασίου γραφή·", "st": "10.31"}, {"sp": "N", "t": "τοῦ περιβόλου δὲ τοῦ ἱεροῦ θέατρον ἔχεται θέας ἄξιον, ἐπαναβάντι δὲ ἐκ τοῦ περιβόλου … Διονύσου δὲ ἄγαλμα ἐνταῦθα Κνιδίων ἐστὶν ἀνάθημα. στάδιον δέ σφισιν ἀνωτάτω τῆς πόλεως τοῦτό ἐστιν· ἐπεποίητο δὲ ἐκ τῆς πέτρας ὁποῖαι περὶ τὸν Παρνασσόν εἰσιν αἱ πολλαί, ἄχρις Ἀθηναῖος Ἡρώδης λίθῳ τῷ Πεντελῆσιν αὐτὸ μετεκόσμησεν. τὰ μὲν δὴ ἀνήκοντα ἐς συγγραφὴν τοσαῦτά τε καὶ τοιαῦτα κατ’ ἐμὲ ἦν τὰ [δὲ] λειπόμενα ἐν Δελφοῖς·", "st": "10.32"}, {"sp": "N", "t": "ἰόντι δὲ ἐκ Δελφῶν ἐπὶ τὰ ἄκρα τοῦ Παρνασσοῦ, σταδίοις μὲν ὅσον ἑξήκοντα ἀπωτέρω Δελφῶν ἐστιν ἄγαλμα χαλκοῦν, καὶ ῥᾴων εὐζώνῳ ἀνδρὶ ἢ ἡμιόνοις τε καὶ ἵπποις ἐπὶ τὸ ἄντρον ἐστὶν ἄνοδος τὸ Κωρύκιον. τούτῳ δὲ τῷ ἄντρῳ γενέσθαι τὸ ὄνομα ἀπὸ νύμφης Κωρυκίας ἐδήλωσα ὀλίγον τι ἔμπροσθεν· σπηλαίων δὲ ὧν εἶδον θέας ἄξιον μάλιστα ἐφαίνετο εἶναί μοι.", "st": "10.32"}, {"sp": "N", "t": "ὅσα μὲν γὰρ ἐπί τε αἰγιαλοῖς καὶ ἀγχιβαθεῖ τῇ θαλάσσῃ, τούτων μὲν οὐδὲ ἀριθμὸν ἄν τις ἐθέλων ἐξεύροι, ὀνομαστότατα δὲ ἔν τε Ἕλλησι καὶ ἐν γῇ τῇ βαρβάρων ἐστί· Φρύγες οἱ ἐπὶ ποταμῷ Πεγκέλᾳ, τὰ δὲ ἄνωθεν ἐξ Ἀρκαδίας καὶ Ἀζάνων ἐς ταύτην ἀφικόμενοι τὴν χώραν, δεικνύουσιν ἄντρον καλούμενον Στεῦνος περιφερές τε καὶ ὕψους ἔχον εὐπρεπῶς· Μητρὸς δέ ἐστιν ἱερόν, καὶ ἄγαλμα Μητρὸς πεποίηται.", "st": "10.32"}, {"sp": "N", "t": "Θεμισώνιον δὲ τὸ ὑπὲρ Λαοδικείας Φρύγες μὲν καὶ τοῦτο οἰκοῦσιν· ὅτε δὲ ὁ Γαλατῶν στρατὸς ἔφερε καὶ ἦγεν Ἰωνίαν καὶ Ἰωνίας τὰ ὅμορα, οἱ Θεμισωνεῖς φασιν αὑτοῖς Ἡρακλέα βοηθὸν καὶ Ἀπόλλωνα γενέσθαι καὶ Ἑρμῆν· τούτους γὰρ τοῖς τὰς ἀρχὰς ἔχουσιν ἄντρον τε δι’ ὀνειράτων δεῖξαι καὶ ἀποκρυφθῆναι Θεμισωνεῦσι καὶ γυναιξὶν αὐτῶν καὶ παισὶν ἐς τοῦτο προστάξαι τὸ ἄντρον.", "st": "10.32"}, {"sp": "N", "t": "καὶ ἐπὶ τούτῳ πρὸ τοῦ σπηλαίου σφίσιν ἀγάλματα οὐ μεγάλα ἐστὶν Ἡρακλέους καὶ Ἑρμοῦ τε καὶ Ἀπόλλωνος, Σπηλαῗται καλούμενοι· τὸ δὲ ἀπέχει ὅσον τριάκοντα τοῦ ἄστεως σταδίους, ὕδατος δέ εἰσιν ἐν αὐτῷ πηγαί· οὔτε δὲ ἔσοδος ἐς αὐτὸ φέρει οὔτε ἐπὶ πολὺ ἡ αὐγὴ δίεισι τοῦ ἡλίου, τοῦ τε ὀρόφου τὰ πλείονα ἐγγυτάτω τοῦ ἐδάφους γίνεται.", "st": "10.32"}, {"sp": "N", "t": "ἔστι δὲ καὶ τοῖς ἐπὶ ποταμῷ Ληθαίῳ Μάγνησιν Αὐλαὶ καλούμενον χωρίον· ἐνταῦθα Ἀπόλλωνι ἀνεῖται σπήλαιον, μεγέθους μὲν εἵνεκα οὐ πολλοῦ θαύματος, τὸ δὲ ἄγαλμα τοῦ Ἀπόλλωνος τὰ μάλιστα ἀρχαῖον καὶ ἰσχὺν ἐπὶ ἔργῳ παρέχεται παντί· καὶ αὐτῷ ἄνδρες ἱεροὶ κατὰ κρημνῶν τε ἀποτόμων καὶ πετρῶν πηδῶσιν ὑψηλῶν καὶ ὑπερμήκη δένδρα ἐριπόντες ἐκ ῥιζῶν κατὰ τὰ στενώτατα τῶν ἀτραπῶν ὁμοῦ τοῖς ἄχθεσιν ὁδεύουσι.", "st": "10.32"}, {"sp": "N", "t": "τὸ δὲ ἄντρον τὸ Κωρύκιον μεγέθει τε ὑπερβάλλει τὰ εἰρημένα καὶ ἔστιν ἐπὶ πλεῖστον ὁδεῦσαι δι’ αὐτοῦ καὶ ἄνευ λαμπτήρων· ὅ τε ὄροφος ἐς αὔταρκες ἀπὸ τοῦ ἐδάφους ἀνέστηκε, καὶ ὕδωρ τὸ μὲν ἀνερχόμενον ἐκ πηγῶν, πλέον δὲ ἔτι ἀπὸ τοῦ ὀρόφου στάζει, ὥστε καὶ δῆλα ἐν τῷ ἐδάφει σταλαγμῶν τὰ ἴχνη διὰ παντός ἐστι τοῦ ἄντρου. ἱερὸν δὲ αὐτὸ οἱ περὶ τὸν Παρνασσὸν Κωρυκίων τε εἶναι Νυμφῶν καὶ Πανὸς μάλιστα ἥγηνται. ἀπὸ δὲ τοῦ Κωρυκίου χαλεπὸν ἤδη καὶ ἀνδρὶ εὐζώνῳ πρὸς τὰ ἄκρα ἀφικέσθαι τοῦ Παρνασσοῦ· τὰ δὲ νεφῶν τέ ἐστιν ἀνωτέρω τὰ ἄκρα καὶ αἱ Θυιάδες ἐπὶ τούτοις τῷ Διονύσῳ καὶ τῷ Ἀπόλλωνι μαίνονται.", "st": "10.32"}, {"sp": "N", "t": "Τιθορέα δὲ ἀπωτέρω Δελφῶν ὀγδοήκοντα ὡς εἰκάσαι σταδίοις ἐστὶ ⟨καὶ ἑκατὸν⟩ ἰόντι τὴν διὰ τοῦ Παρνασσοῦ· τὴν δὲ οὐ πάντα ὀρεινήν, ἀλλὰ καὶ ὀχήμασιν ἐπιτήδειον πλεόνων ἔτι ἐλέγετο εἶναι σταδίων. διάφορα ἐς τὸ ὄνομα οἶδα τῆς πόλεως Ἡροδότῳ τε εἰρημένα ἐν ἐπιστρατείᾳ τοῦ Μήδου καὶ Βάκιδι ἐν χρησμοῖς.", "st": "10.32"}, {"sp": "N", "t": "Βάκις μέν γε Τιθορέας τοὺς ἐνθάδε ἐκάλεσεν ἀνθρώπους· Ἡροδότου δὲ ὁ ἐς αὐτοὺς λόγος ἐπιόντος φησὶ τοῦ βαρβάρου τοὺς ἐνταῦθα οἰκοῦντας ἀναφυγεῖν ἐς τὴν κορυφήν, ὄνομα δὲ Νεῶνα μὲν τῇ πόλει, Τιθορέαν δὲ εἶναι τοῦ Παρνασσοῦ τῇ ἄκρᾳ. ἔοικεν οὖν ἀνὰ χρόνον πρῶτα μὲν δὴ τῇ ἁπάσῃ χώρᾳ, μετὰ δὲ ταῦτα, ἐπειδὴ ἀνῳκίσθησαν ἀπὸ τῶν κωμῶν, ἐκνικῆσαι καὶ ἐπὶ τῇ πόλει Τιθορέαν μηδὲ ἔτι Νεῶνα ὀνομάζεσθαι· Τιθορέᾳ δὲ οἱ ἐπιχώριοι τεθῆναί φασιν ἀπὸ Τιθορέας νύμφης, οἷαι τὸ ἀρχαῖον λόγῳ τῷ ποιητῶν ἐφύοντο ἀπό τε ἄλλων δένδρων καὶ μάλιστα ἀπὸ τῶν δρυῶν.", "st": "10.32"}, {"sp": "N", "t": "γενεᾷ δὲ ἤ με γενέσθαι μιᾷ πρότερον ἐς τὸ χεῖρον ἔτρεψεν ὁ δαίμων τὰ ἐν τῇ Τιθορέᾳ. θεάτρου μὲν δὴ [καὶ] κατασκευὴ καὶ περίβολός ἐστιν ἀγορᾶς ἀρχαιοτέρας· τὰ δὲ τῶν ἐν τῇ πόλει μάλιστα ⟨ἐς μνήμην⟩ ἥκοντα Ἀθηνᾶς ἐστιν ἄλσος καὶ ναός τε καὶ ἄγαλμα· καὶ [ἐς μνήμην] Ἀντιόπης μνῆμά ἐστι καὶ Φώκου. καί μοι τοῦ λόγου τὰ ἔχοντα ἐς Θηβαίους ἐδήλωσε μὲν ὡς ἡ Ἀντιόπη δι’ ὀργὴν ἐκ Διονύσου μανείη, καὶ κατὰ αἰτίαν ἥντινα ἐπεσπάσατο ἐκ τοῦ θεοῦ τὸ μήνιμα, ἐδήλωσε δὲ καὶ ὡς ἐρασθέντι Φώκῳ", "st": "10.32"}, {"sp": "N", "t": "τῷ Ὀρνυτίωνος συνῴκησε καὶ τέθαπται ὁμοῦ τῷ Φώκῳ, καὶ Βάκιδι ὁποῖά ἐστι τῷ χρησμολόγῳ κοινὰ ἐς τοῦτον τὸν τάφον καὶ ἐς τὸν Ζήθου τε ἐν Θήβαις καὶ Ἀμφίονος. τὰ μὲν δὴ ἐς συγγραφὴν τῶν ἐν τῷ πολίσματι ὅτι μὴ τὰ εἰρημένα ἄλλο ἦν οὐδέν, ποταμὸς δὲ παρὰ τῶν Τιθορέων ῥέων τὴν πόλιν ποτόν σφισι γίνεται καταβαίνουσί τε ἐπὶ τὴν ὄχθην καὶ ἀρυομένοις τὸ ὕδωρ· ὄνομα δέ ἐστιν αὐτῷ Καχάλης.", "st": "10.32"}, {"sp": "N", "t": "σταδίοις δὲ ἀπωτέρω Τιθορέας ἑβδομήκοντα ναός ἐστιν Ἀσκληπιοῦ, καλεῖται δὲ Ἀρχαγέτας· τιμὰς δὲ παρὰ αὐτῶν ἔχει Τιθορέων καὶ ἐπ’ ἴσης παρὰ Φωκέων τῶν ἄλλων. ἐντὸς μὲν δὴ τοῦ περιβόλου τοῖς τε ἱκέταις καὶ ὅσοι τοῦ θεοῦ δοῦλοι, τούτοις μὲν ἐνταῦθά εἰσι καὶ οἰκήσεις· ἐν μέσῳ δὲ ὅ τε ναὸς καὶ ἄγαλμα λίθου πεποιημένον, γένεια ἔχον μέγεθος καὶ ὑπὲρ δύο πόδας· κλίνη δὲ ἐν δεξιᾷ κεῖται τοῦ ἀγάλματος, θύειν δὲ αὐτῷ τὰ πάντα ὁμοίως νομίζουσι πλὴν αἰγῶν.", "st": "10.32"}, {"sp": "N", "t": "τοῦ δὲ Ἀσκληπιοῦ περὶ τεσσαράκοντα ἀπέχει σταδίους περίβολος καὶ ἄδυτον ἱερὸν Ἴσιδος, ἁγιώτατον ὁπόσα Ἕλληνες θεῷ τῇ Αἰγυπτίᾳ πεποίηνται· οὔτε γὰρ περιοικεῖν ἐνταῦθα οἱ Τιθορεεῖς νομίζουσιν οὔτε ἔσοδος ἐς τὸ ἄδυτον ἄλλοις γε ἢ ἐκείνοις ἐστὶν οὓς ἂν αὐτὴ προτιμήσασα ἡ Ἶσις καλέσῃ σφᾶς δι’ ἐνυπνίων. τὸ δὲ αὐτὸ καὶ ἐν ταῖς ὑπὲρ Μαιάνδρου πόλεσι θεοὶ ποιοῦσιν οἱ καταχθόνιοι· οὓς γὰρ ἂν ἐς τὰ ἄδυτα ἐσιέναι θελήσωσιν, ἀποστέλλουσιν αὐτοῖς ὀνειράτων ὄψεις.", "st": "10.32"}, {"sp": "N", "t": "ἐν δὲ τῇ Τιθορέων καὶ δὶς ἑκάστου τοῦ ἔτους τῇ Ἴσιδι πανήγυριν ἄγουσι, τὴν μὲν τῷ ἦρι, τὴν δὲ μετοπωρινήν· τρίτῃ δὲ ἡμέρᾳ πρότερον κατὰ ἑκατέραν τῶν πανηγύρεων, ὅσοις ἐστὶν ἐσελθεῖν ἄδεια, τὸ ἄδυτον ἐκκαθαίρουσι τρόπον τινὰ ἀπόρρητον, καὶ δὴ καὶ τῶν ἱερείων ἃ ἐπὶ τῆς προτέρας ἐνεβλήθη πανηγύρεως, τούτων ὁπόσα ἂν ὑπολειπόμενα εὕρωσι κομίζουσιν ἐς τὸ αὐτὸ ἀεὶ χωρίον καὶ κατορύσσουσιν ἐνταῦθα· δύο τε ἀπὸ τοῦ ἀδύτου στάδια ἐτεκμαιρόμεθα ἐς τοῦτο εἶναι τὸ χωρίον.", "st": "10.32"}, {"sp": "N", "t": "ταύτῃ μὲν δὴ τῇ ἡμέρᾳ τοσαῦτα περὶ τὸ ἱερὸν δρῶσι, τῇ δὲ ἐπιούσῃ σκηνὰς οἱ καπηλεύοντες ποιοῦνται καλάμου τε καὶ ἄλλης ὕλης αὐτοσχεδίου· τῇ τελευταίᾳ δὲ τῶν τριῶν πανηγυρίζουσι πιπράσκοντες καὶ ἀνδράποδα καὶ κτήνη τὰ πάντα, ἔτι δὲ ἐσθῆτας καὶ ἄργυρον καὶ χρυσόν·", "st": "10.32"}, {"sp": "N", "t": "μετὰ δὲ μεσοῦσαν τὴν ἡμέραν τρέπονται πρὸς θυσίαν. θύουσι δὲ καὶ βοῦς καὶ ἐλάφους οἱ εὐδαιμονέστεροι, ὅσοι δέ εἰσιν ἀποδέοντες πλούτῳ, καὶ χῆνας καὶ ὄρνιθας τὰς μελεαγρίδας· οἰσὶ δὲ ἐς τὴν θυσίαν οὐ νομίζουσιν οὐδὲ ὑσὶ χρῆσθαι καὶ αἰξίν. ὅσοις μὲν δὴ καθαγίσασι τὰ ἱερεῖα ἐς τὸ ἄδυτον ἀποστεῖλαι … πεποιημένους ἀρχήν, καθελίξαι δεῖ σφᾶς τὰ ἱερεῖα λίνου τελαμῶσιν ἢ βύσσου· τρόπος δὲ τῆς σκευασίας ἐστὶν ὁ Αἰγύπτιος.", "st": "10.32"}, {"sp": "N", "t": "πομπεύει τε δὴ πάντα ὅσα ἔθυσαν καὶ οἱ μὲν ἐς τὸ ἄδυτον τὰ ἱερεῖα ἐσπέμπουσιν, οἱ δὲ ἔμπροσθε τοῦ ἀδύτου καθαγίζουσι τὰς σκηνὰς καὶ ἀποχωροῦσιν αὐτοὶ σπουδῇ. καί φασί ποτε ἄνθρωπον οὐ τῶν καταβαινόντων ἐς τὸ ἄδυτον, βέβηλον δέ, ἡνίκα ἤρχετο ἡ πυρὰ καίεσθαι, τηνικαῦτα ἐσελθεῖν ἐς τὸ ἄδυτον ὑπὸ πολυπραγμοσύνης τε καὶ τόλμης· καί οἱ πάντα ἀνάπλεα εἰδώλων φαίνεσθαι, καὶ ἀναστρέψαι μὲν αὐτὸν ἐς τὴν Τιθορέαν, διηγησάμενον δὲ ἃ ἐθεάσατο ἀφεῖναι τὴν ψυχήν.", "st": "10.32"}, {"sp": "N", "t": "ἐοικότα δὲ ἀνδρὸς ἤκουσα Φοίνικος, ἄγειν τῇ Ἴσιδι Αἰγυπτίους τὴν ἑορτήν, ὅτε αὐτὴν τὸν Ὄσιριν πενθεῖν λέγουσι· τηνικαῦτα δὲ καὶ ὁ Νεῖλος ἀναβαίνειν σφίσιν ἄρχεται, καὶ τῶν ἐπιχωρίων πολλοῖς ἐστιν εἰρημένα ὡς τὰ αὔξοντα τὸν ποταμὸν καὶ ἄρδειν τὰς ἀρούρας ποιοῦντα δάκρυά ἐστι τῆς Ἴσιδος. τότε οὖν τὸν Ῥωμαῖον, ὃς ἐπετέτραπτο Αἴγυπτον, ἄνδρα ἔφη χρήμασιν ἀναπείσαντα ἐς τὸ ἄδυτον καταπέμψαι τῆς Ἴσιδος τὸ ἐν Κόπτῳ· καὶ ὁ ἐσπεμφθεὶς ἀνέστρεψε μὲν ἐκ τοῦ ἀδύτου, διηγησάμενον δὲ ὁπόσα ἐθεάσατο καὶ τοῦτον αὐτίκα ἐπυνθανόμην τελευτῆσαι. τὸ ἔπος οὖν ἀληθεύειν ἔοικε τὸ Ὁμήρου, σὺν οὐδενὶ αἰσίῳ τοὺς θεοὺς τῷ γένει τῶν ἀνθρώπων ἐναργῶς ὁρᾶσθαι.", "st": "10.32"}, {"sp": "N", "t": "τὸ δὲ ἔλαιον τὸ ἐν τῇ Τιθορέων ἀποδεῖ μὲν πλήθει τοῦ τε Ἀττικοῦ καὶ τοῦ Σικυωνίου, χρόᾳ δὲ ὑπερβάλλει καὶ ἡδονῇ ⟨τὸ⟩ Ἰβηρικὸν καὶ τὸ ἐκ τῆς νήσου τῆς Ἰστρίας· καὶ μύρα τε ἀπ’ αὐτοῦ παντοῖα ἑψοῦσι καὶ τὸ ἔλαιον ὡς βασιλέα ἄγουσιν.", "st": "10.32"}, {"sp": "N", "t": "ἑτέρα δὲ ἐκ Τιθορέας ὁδὸς ἡ ἐπὶ Λέδοντά ἐστιν· πόλις δέ ποτε ἐνομίζετο καὶ αὕτη, κατ’ ἐμὲ δὲ ὑπὸ ἀσθενείας ἐξελελοίπεσαν οἱ Λεδόντιοι τὴν πόλιν, καὶ ἄνθρωποι περὶ ἑβδομήκοντα οἱ οἰκοῦντες ἦσαν ἐπὶ τῷ Κηφισῷ· Λέδων δ’ οὖν ὄνομα ταῖς οἰκήσεσίν ἐστιν αὐτῶν, καὶ ἐς τὸν Φωκέων σύλλογον κοινὸν τελεῖν ἠξίωνται καὶ οὗτοι, καθάπερ γε καὶ οἱ Πανοπεῖς. τῶν δὲ ἀνθρώπων οἳ οἰκοῦσιν ἐπὶ τῷ Κηφισῷ τεσσαράκοντά ἐστιν ἀνωτέρω σταδίοις Λέδοντος τῆς ἀρχαίας τὰ ἐρείπια, καὶ τὸ ὄνομα ἀπὸ ἀνδρὸς λαβεῖν τὴν πόλιν φασὶν αὐτόχθονος.", "st": "10.33"}, {"sp": "N", "t": "κακῶν δὲ ἀπέλαυσαν μὲν ἀνιάτων καὶ ἄλλαι πόλεις δι’ ἀδικίαν ἐπιχωρίων ἀνδρῶν· ἐς τελέαν δὲ ἀπώλειαν ὤλισθον Ἴλιον μὲν διὰ τὴν ἐς Μενέλαον ὕβριν τοῦ Ἀλεξάνδρου, Μιλήσιοι δὲ διὰ τὸ ἐς τὰς ἐπιθυμίας Ἑστιαίου πρόχειρον καὶ ἔρωτα ἄλλοτε μὲν τῆς ἐν Ἠδωνοῖς πόλεως, τοτὲ δὲ εἶναι Δαρείου σύμβουλον, ἄλλοτε δὲ ἐπανήκειν ἐς Ἰωνίαν· καὶ δὴ καὶ Λεδοντίοις Φιλόμηλος ἀσέβειαν τὴν ἑαυτοῦ δημοσίᾳ παρέσχε σφίσιν ἀναμάξασθαι.", "st": "10.33"}, {"sp": "N", "t": "Λίλαια δὲ ἡμέρας μὲν ὁδὸν καὶ ὥρᾳ χειμῶνος ἀπέχει Δελφῶν κατιοῦσι διὰ τοῦ Παρνασσοῦ, στάδια δὲ ἐτεκμαιρόμεθα ὀγδοήκοντα εἶναι τῆς ὁδοῦ καὶ ἑκατόν. τοὺς δὲ ἐνταῦθα ἀνθρώπους, καὶ ἐπειδὴ ἀνῳκίσθη αὐτοῖς ἡ πόλις, ἀτύχημα ἐκ Μακεδονίας δεύτερον σφᾶς ἔμελλεν ἐπιλήψεσθαι. πολιορκηθέντες γὰρ ὑπὸ Φιλίππου τοῦ Δημητρίου παρέστησαν κατὰ συνθήκας, καὶ ἐσήχθη φρουρά σφισιν ἐς τὴν πόλιν, ἕως οὗ ἀνὴρ ἐπιχώριος—ὄνομα δέ οἱ ἦν Πάτρων—τούς τε ἐν ἡλικίᾳ τῶν πολιτῶν συνέστησεν ἐπὶ τὴν φρουρὰν καὶ κρατήσας τοὺς Μακεδόνας μάχῃ ἠνάγκασεν ἀπελθεῖν σφᾶς ὑποσπόνδους· Λιλαιεῖς δὲ αὐτὸν ἀντὶ τῆς εὐεργεσίας ταύτης ἀνέθεσαν ἐς Δελφούς.", "st": "10.33"}, {"sp": "N", "t": "ἔστι δὲ ἐν Λιλαίᾳ θέατρον καὶ ἀγορά τε καὶ λουτρά· ἔστι δὲ καὶ θεῶν ἱερὰ Ἀπόλλωνος, τὸ δὲ Ἀρτέμιδος· ἀγάλματα δὲ ὀρθὰ ἐργασίας τε τῆς Ἀττικῆς καὶ τῆς Πεντελῆσι λιθοτομίας. Λίλαιαν δὲ τῶν καλουμένων Ναΐδων καὶ θυγατέρα εἶναι τοῦ Κηφισοῦ καὶ ἀπὸ τῆς νύμφης τὸ ὄνομα τεθῆναι τῇ πόλει φασί.", "st": "10.33"}, {"sp": "N", "t": "καὶ ὁ ποταμὸς ἐνταῦθα ἔχει τὰς πηγάς· ἄνεισι δὲ ἐκ τῆς γῆς οὐ τὰ πάντα μεθ’ ἡσυχίας, ἀλλ’ ὡς τὰ πλείω συμβαίνειν μεσούσης μάλιστα τῆς ἡμέρας παρέχεται φωνὴν ἀνερχόμενος· εἰκάσαις ἂν μυκωμένῳ ταύρῳ τὸν ἦχον τοῦ ὕδατος. ἔχει δὲ ἡ Λίλαια καὶ πρὸς τὰς τοῦ ἔτους ὥρας μετοπώρου καὶ ἐν θέρει καὶ ἦρος ἐπιτηδείως· τὸν δὲ χειμῶνα μὴ ὁμοίως ἤπιον γίνεσθαι κωλύει τὸ ὄρος ὁ Παρνασσός.", "st": "10.33"}, {"sp": "N", "t": "Χαράδρα δὲ εἴκοσιν ἀπωτέρω σταδίοις ἐστὶν ὑπὲρ ὑψηλοῦ κειμένη κρημνοῦ, καὶ ὕδατος οἱ ἐνταῦθα σπανίζουσιν ἄνθρωποι, ποτὸν δέ σφισι ποταμός ἐστι Χάραδρος κατερχομένοις ὅσον τρία ἐπ’ αὐτὸν στάδια· ἐκδίδωσι δὲ ἐς τὸν Κηφισόν, καί μοι τὸ ὄνομα ἀπὸ τοῦ ποταμοῦ φαίνεται τεθῆναι τοῦ Χαράδρου τῇ πόλει. Χαραδραίοις δὲ Ἡρώων καλουμένων εἰσὶν ἐν τῇ ἀγορᾷ βωμοί, καὶ αὐτοὺς οἱ μὲν Διοσκούρων, οἱ δὲ ἐπιχωρίων εἶναί φασιν ἡρώων.", "st": "10.33"}, {"sp": "N", "t": "γῆ δὲ διακεκριμένη ἀρίστη τῆς Φωκίδος ἐστὶν ἡ παρὰ τὸν Κηφισὸν καὶ φυτεῦσαι καὶ σπείρειν καὶ ἀνεῖναι νομάς· καὶ γεωργεῖται ταῦτα μάλιστα τῆς χώρας, ὥστε καὶ λόγος ἐστὶ πόλιν μὲν Παραποταμίους μὴ ὀνομασθῆναι, ἐπὶ δὲ τῶν παρὰ τὸν Κηφισὸν γεωργούντων πεποιῆσθαι τὸ ἔπος,<br>οἵ τ’ ἄρα πὰρ ποταμὸν Κηφισὸν δῖον ἔναιον.", "st": "10.33"}, {"sp": "N", "t": "τούτῳ τῷ λόγῳ διάφορα μὲν ἐν τῇ Ἡροδότου συγγραφῇ, διάφορα δέ ἐστιν αὐτῷ καὶ ὅσα ἐπὶ ταῖς νίκαις ταῖς Πυθικαῖς μνημονεύουσιν· Ἀμφικτύονες γὰρ Πύθια ἐτίθεσαν πρῶτον, καὶ Αἰχμέας Παραποτάμιος πυγμὴν ἐνίκησεν ἐν παισίν· ὡσαύτως δὲ Ἡρόδοτος καταλέγων τὰς πόλεις, ὅσας βασιλεὺς Ξέρξης τῶν ἐν Φωκεῦσιν ἐνέπρησε, καὶ Παραποταμίους κατείλοχεν ἐν αὐταῖς πόλιν. οὐ μέντοι οἱ Παραποτάμιοί γε ὑπὸ Ἀθηναίων καὶ Βοιωτῶν ἀνῳκίσθησαν, ἀλλὰ ἐς τὰς ἄλλας πόλεις οἱ ἄνθρωποι κατενεμήθησαν ὑπό τε ἀσθενείας καὶ σπάνει χρημάτων. Παραποταμίων μὲν δὴ οὔτε ἐρείπια ἔτι ἦν οὔτε ἔνθα τῆς χώρας ᾠκίσθη ἡ πόλις μνημονεύουσιν·", "st": "10.33"}, {"sp": "N", "t": "ὁδὸς δὲ ἡ ἐς Ἀμφίκλειαν σταδίων ἐκ Λιλαίας ἐστὶν ἑξήκοντα. ταύτην τὴν Ἀμφίκλειαν ἐλυμήναντο οἱ [τε] ἐπιχώριοι τῷ ὀνόματι, καὶ Ἡρόδοτος μὲν Ἀμφίκαιαν ἐκάλεσεν ἑπόμενος τῷ ἀρχαιοτάτῳ τῶν λόγων, Ἀμφικτύονες δὲ δόγμα ἐπὶ τῇ τῶν πόλεων ἀπωλείᾳ τῶν ἐν Φωκεῦσιν ἐξενεγκόντες ὄνομα ἔθεντο αὐτῇ Ἀμφίκλειαν. οἱ δὲ ἐπιχώριοι τοιάδε ἐπ’ αὐτῇ λέγουσι· δυνάστην ἄνδρα ἐπιβουλὴν ἐχθρῶν ὑποπτεύσαντα ἐς νήπιον παῖδα καταθέσθαι τὸν παῖδα ἐς ἀγγεῖον, καὶ ἀποκρύψαι τῆς χώρας ἔνθα οἱ ἄδειαν ἔσεσθαι πλείστην ἠπίστατο. λύκον μὲν δὴ ἐπιχειρεῖν τῷ παιδί, δράκοντα δὲ ἰσχυρὰν ἔχειν τὴν φρουρὰν ἐσπειραμένον περὶ τὸ ἀγγεῖον.", "st": "10.33"}, {"sp": "N", "t": "ὡς δὲ ὁ πατὴρ ἦλθε τοῦ παιδός, τὸν δράκοντα ἐπιβουλεῦσαι τῷ παιδὶ ἐλπίζων ἀφίησι τὸ ἀκόντιον, καὶ ἐκεῖνόν τε καὶ ὁμοῦ τῷ δράκοντι τὸν παῖδα ἀπέκτεινε· διδαχθεὶς δὲ ὑπὸ τῶν ποιμαινόντων ὡς εὐεργέτην καὶ φύλακα τοῦ παιδὸς ἀπεκτονὼς εἴη, πυρὰν τῷ δράκοντι καὶ τῷ παιδὶ ἐποίησεν ἐν κοινῷ. τό τε δὴ χωρίον ἐοικέναι καὶ ἐς τόδε καιομένῃ πυρᾷ φασι καὶ ἀπὸ τοῦ δράκοντος ἐκείνου τὴν πόλιν ἐθέλουσιν Ὀφιτείαν ὀνομασθῆναι.", "st": "10.33"}, {"sp": "N", "t": "†ἃ μάλιστα ἄξιον Διονύσῳ δρῶσιν ὄργια, ἔσοδος δὲ ἐς τὸ ἄδυτον οὐδὲ ἐν φανερῷ σφισιν †ἄγαλμα οὐκ ἔστι. λέγεται δὲ ὑπὸ τῶν Ἀμφικλειέων μάντιν τέ σφισι τὸν θεὸν τοῦτον καὶ βοηθὸν νόσων καθεστηκέναι· τὰ μὲν δὴ νοσήματα αὐτοῖς Ἀμφικλειεῦσι καὶ τοῖς προσοικοῦσιν ἰᾶται δι’ ὀνειράτων, πρόμαντις δὲ ὁ ἱερεύς ἐστι, χρῷ δὲ ἐκ τοῦ θεοῦ κάτοχος.", "st": "10.33"}, {"sp": "N", "t": "Ἀμφικλείας δὲ ἀπωτέρω σταδίοις πεντεκαίδεκά ἐστι Τιθρώνιον ἐν πεδίῳ κειμένη· παρέχεται δὲ οὐδὲν ἐς μνήμην. ἐκ Τιθρωνίου δὲ εἴκοσιν ἐς Δρυμαίαν στάδιοι· καθ’ ὅ τι δὲ αὕτη ἡ ὁδὸς καὶ ἡ ἐς Δρυμαίαν ἐξ Ἀμφικλείας ἡ εὐθεῖα περὶ τὸν Κηφισὸν συμμίσγουσιν, ἔστιν Ἀπόλλωνος Τιθρωνεῦσιν ἐνταῦθα ἄλσος τε καὶ βωμοί. πεποίηται δὲ καὶ ναός· ἄγαλμα δὲ οὐκ ἔστιν. ἀπέχει δὲ Ἀμφικλείας ἡ Δρυμαία σταδίους ὀγδοήκοντα ἀποτραπέντι ἐς ἀριστερά … κατὰ Ἡροδότου τοὺς λόγους, Ναυβολεῖς δὲ τὰ ἀρχαιότερα· καὶ οἰκιστὴν οἱ ἐνταῦθα γενέσθαι σφίσι Φώκου παῖδά φασι τοῦ Αἰακοῦ. Δήμητρος δὲ Θεσμοφόρου Δρυμαίοις ἱερόν ἐστιν ἀρχαῖον, καὶ ἄγαλμα ὀρθὸν λίθου πεποίηται, καὶ αὐτῇ Θεσμοφόρια ἑορτὴν ἄγουσιν ἐπέτειον.", "st": "10.33"}, {"sp": "N", "t": "Ἐλάτεια δὲ τῶν ἐν Φωκεῦσι μεγίστη πόλεών ἐστι τῶν ἄλλων μετά γε τοὺς Δελφούς· κεῖται δὲ κατὰ Ἀμφίκλειαν, καὶ ἐς αὐτὴν ὀγδοήκοντα καὶ ἑκατὸν ὁδός ἐστιν ἐξ Ἀμφικλείας σταδίων, πεδιὰς ἡ πολλὴ καὶ αὖθις οὐκ ἐπὶ πολὺ ἀνάντης ἡ ἐγγυτάτω τοῦ Ἐλατέων ἄστεως. ῥεῖ δὲ ἐν τῇ πεδιάδι ὁ Κηφισός· αἱ δὲ ὠτίδες καλούμεναι παρὰ τὸν Κηφισὸν νέμονται μάλιστα ὀρνίθων.", "st": "10.34"}, {"sp": "N", "t": "Ἐλατεῦσι δὲ ἐξεγένετο μὲν Κάσσανδρον καὶ τὴν Μακεδόνων ἀπώσασθαι στρατιάν, ὑπῆρξε δὲ καὶ Ταξίλου Μιθριδάτῃ στρατηγοῦντος τὸν πόλεμόν σφισιν ἐκφυγεῖν· ἀντὶ τούτου δὲ τοῦ ἔργου Ῥωμαῖοι δεδώκασιν αὐτοῖς ἐλευθέρους ὄντας ἀτελῆ νέμεσθαι τὴν χώραν. ἀμφισβητοῦσι δὲ οὗτοι ξενικοῦ γένους, καὶ Ἀρκάδες φασὶν εἶναι τὸ ἀρχαῖον· Ἔλατον γὰρ τὸν Ἀρκάδος, ἡνίκα ἐπὶ τὸ ἱερὸν Φλεγύαι τὸ ἐν Δελφοῖς ἐστρατεύσαντο, ἀμῦναί τε τῷ θεῷ καὶ ἐν τῇ Φωκίδι ὁμοῦ τῷ στρατεύματι αὐτὸν καταμείναντα Ἐλατείας οἰκιστὴν γενέσθαι.", "st": "10.34"}, {"sp": "N", "t": "ἐν δὲ ταῖς Φωκέων πόλεσιν ἃς ὁ Μῆδος ἐνέπρησεν, ἀριθμῆσαι καὶ τὴν Ἐλάτειαν ἔστιν ἐν ταύταις. συμφοραὶ δὲ αἱ μὲν πρὸς Φωκέας τοὺς ἄλλους γεγόνασί σφισιν ἐν κοινῷ, τὰς δὲ καὶ ἰδίᾳ τοῖς Ἐλατεῦσιν ἐκ Μακεδόνων παρεσκεύασεν ὁ δαίμων. καὶ ἐπὶ μὲν Κασσάνδρου πολεμήσαντος Ὀλυμπιόδωρος κατέστη μάλιστα αἴτιος ἄπρακτον τοῖς Μακεδόσι γενέσθαι πολιορκίαν· Φίλιππος δὲ ὁ Δημητρίου τόν τε ἐν Ἐλατείᾳ δῆμον πρὸς τὸ ἔσχατον δέους ἤγαγε καὶ ὑπηγάγετο ἅμα τοὺς δυνατωτέρους δωρεᾷ.", "st": "10.34"}, {"sp": "N", "t": "Τίτος μὲν δὴ ὁ ἄρχων ὁ Ῥωμαίων—τὸ γὰρ δὴ Ἑλληνικὸν ἅπαν ἐλευθερώσων ἀπέσταλτο ἐκ Ῥώμης—πολιτείαν τε Ἐλατεῦσιν ἀποδώσειν τὴν ἀρχαίαν ἐπηγγέλλετο καὶ δι’ ἀγγέλων ἐπεκηρυκεύετό σφισιν ἀπὸ Μακεδόνων ἀφίστασθαι· οἱ δὲ ὑπὸ ἀγνωμοσύνης ὁ δῆμος ἢ οἱ ἔχοντες τὰς ἀρχὰς Φιλίππῳ τε ἦσαν πιστοὶ καὶ ὑπὸ τοῦ Ῥωμαίου πολιορκίᾳ παρέστησαν. χρόνῳ δὲ οἱ Ἐλατεῖς ὕστερον Ταξίλου τε Μιθριδάτῃ στρατηγοῦντος καὶ τῶν ἐκ τοῦ Πόντου βαρβάρων ἀντέσχον τῇ πολιορκίᾳ· ἐπὶ τούτῳ δὲ ἐλευθέρους εἶναι τῷ ἔργῳ δέδοταί σφισιν ὑπὸ Ῥωμαίων.", "st": "10.34"}, {"sp": "N", "t": "τὸ δὲ Κοστοβώκων [τε] τῶν λῃστικῶν τὸ κατ’ ἐμὲ τὴν Ἑλλάδα ἐπιδραμὸν ἀφίκετο καὶ ἐπὶ τὴν Ἐλάτειαν· ἔνθα δὴ ἀνὴρ Μνησίβουλος λόχον τε περὶ αὑτὸν ἀνδρῶν συνέστησε καὶ καταφονεύσας πολλοὺς τῶν βαρβάρων ἔπεσεν ἐν τῇ μάχῃ. οὗτος ὁ Μνησίβουλος δρόμου νίκας καὶ ἄλλας ἀνείλετο καὶ Ὀλυμπιάδι πέμπτῃ πρὸς ταῖς τριάκοντά τε καὶ διακοσίαις σταδίου καὶ τοῦ σὺν τῇ ἀσπίδι διαύλου· ἐν Ἐλατείᾳ δὲ κατὰ τὴν ὁδὸν τοῦ δρομέως Μνησιβούλου χαλκοῦς ἕστηκεν ἀνδριάς.", "st": "10.34"}, {"sp": "N", "t": "ἡ δὲ ἀγορὰ αὐτή τέ ἐστι θέας ἀξία καὶ ὁ Ἔλατος ἐπειργασμένος στήλῃ· σαφῶς δὲ οὐκ οἶδα εἴτε τιμῶντες οἷα οἰκιστὴν εἴτε καὶ μνήματος ἐπίθημα ἐποιήσαντο τὴν στήλην. τῷ δὲ Ἀσκληπιῷ ναὸς ᾠκοδόμηται καὶ ἄγαλμα γένεια ἔχον ἐστί· τοῖς ἐργασαμένοις τὸ ἄγαλμα ὀνόματα μὲν Τιμοκλῆς καὶ Τιμαρχίδης, γένους δέ εἰσι τοῦ Ἀττικοῦ. ἐπὶ τῷ πέρατι ⟨δὲ⟩ τῷ ἐν δεξιᾷ τῆς πόλεως θέατρόν τέ ἐστι καὶ χαλκοῦν Ἀθηνᾶς ἄγαλμα ἀρχαῖον· ταύτην τὴν θεὸν λέγουσιν ἀμῦναί σφισιν ἐπὶ τοὺς ὁμοῦ Ταξίλῳ βαρβάρους.", "st": "10.34"}, {"sp": "N", "t": "Ἐλατείας δὲ ὅσον σταδίους εἴκοσιν ἀφέστηκεν Ἀθηνᾶς ἐπίκλησιν Κραναίας ἱερόν· ἡ δὲ ὁδὸς ἐπὶ τοσοῦτον ἀναντεστέρα ὡς ἀνιᾶν τὸ μηδὲν καὶ λεληθέναι μᾶλλον αὐτῆς τὸ ἄναντες. λόφος δὲ ἐπὶ τῆς ὁδοῦ τῷ πέρατι τὰ πλείω μὲν ἀπότομος, οὐ μέντοι ἄγαν ἢ μεγέθους ἔχων ἐστὶν ἢ ὕψους· ἐπὶ τούτῳ τῷ λόφῳ τὸ ἱερὸν πεποίηται, καὶ στοαί τέ εἰσι καὶ οἰκήσεις διὰ τῶν στοῶν, ἔνθα οἰκοῦσιν οἷς τὴν θεὸν θεραπεύειν καθέστηκε, καὶ ἄλλοις καὶ μάλιστα τῷ ἱερωμένῳ.", "st": "10.34"}, {"sp": "N", "t": "τὸν δὲ ἱερέα ἐκ παίδων αἱροῦνται τῶν ἀνήβων, πρόνοιαν ποιούμενοι πρότερον τῆς ἱερωσύνης ἐξήκειν οἱ τὸν χρόνον πρὶν ἢ ἡβῆσαι· ἱερᾶται δὲ ἔτη συνεχῆ πέντε, ἐν οἷς τήν τε ἄλλην δίαιταν ἔχει παρὰ τῇ θεῷ καὶ λουτρὰ αἱ ἀσάμινθοι κατὰ τρόπον εἰσὶν αὐτῷ τὸν ἀρχαῖον. τὸ δὲ ἄγαλμα ἐποίησαν μὲν καὶ τοῦτο οἱ Πολυκλέους παῖδες, ἔστι δὲ ἐσκευασμένον ὡς ἐς μάχην· καὶ ἐπείργασται τῇ ἀσπίδι τῶν Ἀθήνῃσι μίμημα ἐπὶ τῇ ἀσπίδι τῆς καλουμένης ὑπὸ Ἀθηναίων Παρθένου.", "st": "10.34"}, {"sp": "N", "t": "ἐς Ἄβας δὲ ἀφικέσθαι καὶ ἐς Ὑάμπολιν ἔστι μὲν καὶ ἐξ Ἐλατείας ὀρεινὴν ὁδὸν ἐν δεξιᾷ τοῦ Ἐλατέων ἄστεως, ἡ δὲ ἐπὶ Ὀποῦντα λεωφόρος ἡ ἐξ Ὀρχομενοῦ καὶ ἐς ταύτας φέρει τὰς πόλεις. ἰόντι οὖν ἐς Ὀποῦντα ἐξ Ὀρχομενοῦ καὶ ἐκτραπέντι οὐ πολὺ ἐπ’ ἀριστερὰν ὁδός ⟨ἐστιν⟩ ἡ ἐς Ἄβας. οἱ δὲ ἐν ταῖς Ἄβαις ἐς γῆν τὴν Φωκίδα ἀφικέσθαι λέγουσιν ἐξ Ἄργους καὶ τὸ ὄνομα ἀπὸ Ἄβαντος τοῦ οἰκιστοῦ λαβεῖν τὴν πόλιν, τὸν δὲ Λυγκέως τε καὶ Ὑπερμήστρας τῆς Δαναοῦ παῖδα εἶναι. Ἀπόλλωνος δὲ ἱερὰς νενομίκασιν εἶναι τὰς Ἄβας ἐκ παλαιοῦ, καὶ χρηστήριον καὶ αὐτόθι ἦν Ἀπόλλωνος.", "st": "10.35"}, {"sp": "N", "t": "θεῷ δὲ τῷ ἐν Ἄβαις οὐχ ὁμοίως Ῥωμαῖοί τε ἀπένειμαν τὰ ἐς τιμὴν καὶ ὁ Πέρσης· ἀλλὰ Ῥωμαῖοι μὲν εὐσεβείᾳ τῇ ἐς τὸν Ἀπόλλωνα Ἀβαίοις δεδώκασιν αὐτονόμους σφᾶς εἶναι, στρατιὰ δὲ ἡ μετὰ Ξέρξου κατέπρησε καὶ τὸ ἐν Ἄβαις ἱερόν. Ἑλλήνων δὲ τοῖς ἀντιστᾶσι τῷ βαρβάρῳ τὰ κατακαυθέντα ἱερὰ μὴ ἀνιστάναι σφίσιν ἔδοξεν, ἀλλὰ ἐς τὸν πάντα ὑπολείπεσθαι χρόνον τοῦ ἔχθους ὑπομνήματα· καὶ τοῦδε ἕνεκα οἵ τε ἐν τῇ Ἁλιαρτίᾳ ναοὶ καὶ Ἀθηναίοις τῆς Ἥρας ἐπὶ ὁδῷ τῇ Φαληρικῇ καὶ ὁ ἐπὶ Φαληρῷ τῆς Δήμητρος καὶ κατ’ ἐμὲ ἔτι ἡμίκαυτοι μένουσι.", "st": "10.35"}, {"sp": "N", "t": "τοιαύτην θέαν καὶ τοῦ ἐν Ἄβαις ἱεροῦ τότε γε εἶναι δοκῶ, ἐς ὃ ἐν τῷ πολέμῳ τῷ Φωκικῷ βιασθέντας μάχῃ Φωκέων ἄνδρας καὶ ἐς Ἄβας ἐκπεφευγότας αὐτούς τε οἱ Θηβαῖοι τοὺς ἱκέτας καὶ τὸ ἱερόν, δεύτερον δὴ οὗτοι μετὰ Μήδους, ἔδοσαν πυρί· εἱστήκει δ’ οὖν καὶ ἐς ἐμὲ ἔτι οἰκοδομημάτων ἀσθενέστατον ὁπόσα δὴ ἡ φλὸξ ἐλυμήνατο, ἅτε ἐπὶ τῷ Μηδικῷ προλωβησαμένῳ πυρὶ αὖθις ὑπὸ τοῦ Βοιωτίου πυρὸς κατειργασμένον.", "st": "10.35"}, {"sp": "N", "t": "παρὰ δὲ τὸν ναὸν τὸν μέγαν ἐστὶν ἄλλος ναός, ἀποδέων ἐκείνου μέγεθος· βασιλεὺς δὲ Ἀδριανὸς ἐποίησε τῷ Ἀπόλλωνι· τὰ δὲ ἀγάλματα ἀρχαιότερα καὶ αὐτῶν ἐστιν Ἀβαίων ἀνάθημα, χαλκοῦ δὲ εἴργασται καὶ ὁμοίως ἐστὶν ὀρθά, Ἀπόλλων καὶ Λητώ τε καὶ Ἄρτεμις. Ἀβαίοις δὲ ἔστι μὲν θέατρον, ἔστι δὲ καὶ ἀγορά σφισι, κατασκευῆς ἀμφότερα ἀρχαίας.", "st": "10.35"}, {"sp": "N", "t": "ἐπανελθόντα δὲ ἐς τὴν ὁδὸν τὴν ἐς Ὀποῦντα εὐθεῖαν Ὑάμπολις τὸ ἀπὸ τούτου σε ἐκδέξεται. τῶν δὲ ἐνταῦθα ἀνθρώπων καὶ αὐτὸ κατηγορεῖ τὸ ὄνομα οἵτινες ἦσαν ἐξ ἀρχῆς καὶ ὁπόθεν ἐξαναστάντες ἀφίκοντο ἐς ταύτην τὴν χώραν· Ὕαντες γὰρ οἱ ἐκ Θηβῶν Κάδμον καὶ τὸν σὺν ἐκείνῳ φυγόντες στρατὸν ἀφίκοντο ἐνταῦθα. τὰ μὲν δὴ ἀρχαιότερα ὑπὸ τῶν προσχώρων ἐκαλοῦντο Ὑάντων πόλις, χρόνῳ μέντοι ὕστερον Ὑάμπολιν ἐξενίκησεν ὀνομασθῆναι.", "st": "10.35"}, {"sp": "N", "t": "ἅτε δὲ καὶ βασιλέως Ξέρξου καταπρήσαντος τὴν πόλιν καὶ αὖθις Φιλίππου κατασκάψαντος, ὅμως τὰ ὑπολειπόμενα ἦν ἀγορᾶς τε ἀρχαίας κατασκευὴ καὶ βουλευτήριον, οἴκημα οὐ μέγα, καὶ θέατρον οὐ πόρρω τῶν πυλῶν. Ἀδριανὸς δὲ βασιλεὺς στοὰν ᾠκοδομήσατο, καὶ ἐπώνυμος ἡ στοὰ τοῦ ἀναθέντος βασιλέως ἐστί. φρέαρ δέ σφισίν ἐστιν ἕν· ἀπὸ τούτου μόνου καὶ πίνουσι καὶ λούονται, ἀπ’ ἄλλου δὲ ἔχουσιν οὐδενὸς πλήν γε δὴ ὥρᾳ χειμῶνος τὸ ἐκ τοῦ θεοῦ.", "st": "10.35"}, {"sp": "N", "t": "σέβονται δὲ μάλιστα Ἄρτεμιν, καὶ ναὸς Ἀρτέμιδός ἐστιν αὐτοῖς· τὸ δὲ ἄγαλμα ὁποῖόν τί ἐστιν οὐκ ἐδήλωσα· δὶς γὰρ καὶ οὐ πλέον ἑκάστου ἐνιαυτοῦ τὸ ἱερὸν ἀνοιγνύναι νομίζουσιν. ὁπόσα δ’ ἂν τῶν βοσκημάτων ἱερὰ ἐπονομάσωσιν εἶναι τῇ Ἀρτέμιδι, ἄνευ νόσου ταῦτα καὶ πιότερα τῶν ἄλλων ἐκτρέφεσθαι λέγουσιν.", "st": "10.35"}, {"sp": "N", "t": "ἐσβολὴ δὲ ἐκ Χαιρωνείας ἐς γῆν τὴν Φωκίδα οὐ μόνον ἡ εὐθεῖά ἐστιν ἐς Δελφοὺς ἡ διά τε Πανοπέως καὶ παρὰ τὴν Δαυλίδα καὶ ὁδὸν τὴν Σχιστήν· φέρει δὲ ἐκ Χαιρωνείας καὶ ἑτέρα τραχεῖά τε ὁδὸς καὶ ὀρεινὴ τὰ πλέονα ἐς πόλιν Φωκέων Στῖριν· μῆκος δὲ εἴκοσι στάδιοι τῆς ὁδοῦ καὶ ἑκατόν. οἱ δὲ ἐνταῦθά φασιν οὐ Φωκεῖς, Ἀθηναῖοι δὲ εἶναι τὰ ἄνωθεν, καὶ ἐκ τῆς Ἀττικῆς ὁμοῦ Πετεῷ τῷ Ὀρνέως ἀφικέσθαι διωχθέντι ὑπὸ Αἰγέως ἐξ Ἀθηνῶν· ὅτι δὲ τῷ Πετεῷ τὸ πολὺ ἐκ τοῦ δήμου τοῦ Στιρέων ἠκολούθησεν, ἐπὶ τούτῳ κληθῆναι τὴν πόλιν Στῖριν.", "st": "10.35"}, {"sp": "N", "t": "Στιρίταις δέ ἐστιν ἐπὶ ὑψηλοῦ καὶ πετρώδους ἡ οἴκησις· σπανίζουσιν οὖν κατὰ τοῦτο ὕδατος θέρους ὥρᾳ· φρέατα γὰρ αὐτόθι οὔτε πολλὰ οὔτε ὕδωρ παρεχόμενά ἐστιν ἐπιτήδειον. ταῦτα μὲν δὴ λουτρά σφισι καὶ ὑποζυγίοις ποτὸν γίνεται, τὸ δὲ ὕδωρ οἱ ἄνθρωποι τὸ πότιμον ὅσον στάδια τέσσαρα ὑποκαταβαίνοντες λαμβάνουσιν ἐκ πηγῆς· ἡ δὲ ἐν πέτραις ἐστὶν ὀρωρυγμένη, καὶ ἀρύονται κατιόντες ἐς τὴν πηγήν.", "st": "10.35"}, {"sp": "N", "t": "Δήμητρος δὲ ἐπίκλησιν Στιρίτιδος ἱερόν ἐστιν ἐν Στῖρι· πλίνθου μὲν τῆς ὠμῆς τὸ ἱερόν, λίθου δὲ τοῦ Πεντελῆσι τὸ ἄγαλμα, δᾷδας ἡ θεὸς ἔχουσα. παρὰ δὲ αὐτῇ κατειλημμένον ταινίαις ἄγαλμα ἀρχαῖόν ἐστιν ἄλλο ὁπόσα Δήμητρος ἐς τιμήν.", "st": "10.35"}, {"sp": "N", "t": "ἐς δὲ Ἄμβροσσον στάδιοι περὶ ἑξήκοντά εἰσιν ἐκ Στίρεως· πεδιὰς ἡ ὁδός, ὀρῶν ἐν μέσῳ πεδίον κείμενον. ἄμπελοι δὲ τὸ πολύ εἰσι τοῦ πεδίου, καὶ ἐν γῇ τῇ Ἀμβροσσέων ⟨οὐ⟩ συνεχεῖς μὲν ὥσπερ αἱ ἄμπελοι, πεφύκασι μέντοι καὶ αἱ θάμνοι· τὴν δὲ θάμνον ταύτην Ἴωνες μὲν καὶ τὸ ἄλλο Ἑλληνικὸν κόκκον, Γαλάται δὲ οἱ ὑπὲρ Φρυγίας φωνῇ τῇ ἐπιχωρίῳ σφίσιν ὀνομάζουσιν ὗς. γίνεται δὲ αὕτη μέγεθος μὲν ἡ κόκκος κατὰ τὴν ῥάμνον καλουμένην, φύλλα δὲ μελάντερα μὲν καὶ μαλακώτερα ἢ ἡ σχῖνος, τὰ μέντοι ἄλλα ἐοικότα ἔχει τῇ σχίνῳ.", "st": "10.36"}, {"sp": "N", "t": "ὁ δὲ αὐτῆς καρπὸς ὅμοιος τῷ καρπῷ τῆς στρύχνου, μέγεθος δέ ἐστι κατὰ ὄροβον. γίνεται δέ τι ἐν τῷ καρπῷ τῆς κόκκου βραχὺ ζῷον· τοῦτο εἰ ἀφίκοιτο ἐς τὸν ἀέρα πεπανθέντος τοῦ καρποῦ, πέτεταί τε αὐτίκα καὶ ἐοικὸς κώνωπι φαίνοιτο ἄν· νῦν δὲ πρότερον, πρὶν ἢ τὸ ζῷον κινηθῆναι, συλλέγουσι τῆς κόκκου τὸν καρπόν, καὶ ἔστι τοῖς ἐρίοις ἡ βαφὴ τὸ αἷμα τοῦ ζῴου.", "st": "10.36"}, {"sp": "N", "t": "ἡ δὲ Ἄμβροσσος κεῖται μὲν ὑπὸ τὸ ὄρος τὸν Παρνασσόν, τὰ ἐπέκεινα δὲ ἢ Δελφοί· τεθῆναι δὲ τὸ ὄνομα τῇ πόλει ἀπὸ ἥρωός φασιν Ἀμβρόσσου. Θηβαῖοι δὲ ἐς τὸν Μακεδόνων καὶ Φιλίππου καθιστάμενοι πόλεμον περιέβαλον τῇ Ἀμβρόσσῳ διπλοῦν τεῖχος· τὸ δέ ἐστιν ἐπιχωρίου λίθου, χρόαν μέλανος, ἐς τὰ μάλιστα ἰσχυροῦ· κύκλος δὲ ἑκάτερος τοῦ τείχους πλάτος μὲν ἀποδέων ὀλίγον ἐστὶν ὀργυιᾶς, τὸ δὲ ὕψος ἐς ἡμίσειάν τε καὶ δύο ὀργυιάς, ὅπου μὴ τὸ τεῖχος πεπόνηκε·", "st": "10.36"}, {"sp": "N", "t": "διάστημα δὲ ἀπὸ τοῦ προτέρου τῶν κύκλων ἐπὶ τὸν δεύτερόν ἐστιν ὀργυιά· κατασκευὴ δὲ πύργων ἢ ἐπάλξεων ἢ εἴ τι ἄλλο ἐς εὐπρέπειαν τείχους, παρεῖται τὰ πάντα σφίσιν ἅτε τειχίζουσιν ἐπὶ μόνῳ τῷ αὐτίκα ἀμύνεσθαι. ἔστι δὲ ἀγορά τε Ἀμβροσσεῦσιν οὐ μεγάλη καὶ ἀνδριάντων ἐν αὐτῇ λίθου πεποιημένων κατεάγασιν οἱ πολλοί.", "st": "10.36"}, {"sp": "N", "t": "τραπέντι δὲ ἐπὶ Ἀντίκυραν ἀνάντης τὰ πρῶτά ἐστιν ὁδός· ἀναβάντι δὲ ὅσον δύο στάδια ὁμαλές τε χωρίον καὶ ἐν δεξιᾷ τῆς ὁδοῦ Δικτυνναίας ἐπίκλησιν ἱερόν ἐστιν Ἀρτέμιδος. ταύτην οἱ Ἀμβροσσεῖς ἄγουσι μάλιστα ἐν τιμῇ· τῷ δὲ ἀγάλματι ἐργασία τέ ἐστιν Αἰγιναία καὶ μέλανος τοῦ λίθου πεποίηται. τὸ δὲ ἀπὸ τοῦ ἱεροῦ τῆς Δικτυνναίας κατάντης ὁδὸς ἐς Ἀντίκυραν πᾶσά ἐστι. τὰ δὲ ἀρχαιότερα ὄνομα εἶναι Κυπάρισσον τῇ πόλει φασί, καὶ Ὅμηρον ἐν Φωκέων καταλόγῳ τὸ ὄνομα θελῆσαι θέσθαι γε αὐτόν, ὅτι ἤδη τηνικαῦτα ἐκαλεῖτο Ἀντίκυρα· εἶναι γὰρ δὴ τὸν Ἀντικυρέα κατὰ Ἡρακλέα ἡλικίαν.", "st": "10.36"}, {"sp": "N", "t": "κεῖται μὲν δὴ ἡ πόλις κατὰ Μεδεῶνος τὰ ἐρείπια· ἐδήλωσα δὲ ἀρχομένης τῆς ἐς Φωκέας ⟨συγγραφῆς⟩ ἐς τὸ ἱερὸν ἀσεβῆσαι τὸ ἐν Δελφοῖς ⟨Ἀντικυρέας⟩. Ἀντικυρέας δὲ ἐποίησε μὲν ἀναστάτους καὶ ὁ Ἀμύντου Φίλιππος, ἐποίησε δὲ καὶ δεύτερα Ὀτίλιος ὁ Ῥωμαῖος, ὅτι ἦσαν ὑπήκοοι καὶ οὗτοι Φιλίππου τοῦ Δημητρίου βασιλεύοντος Μακεδόνων· ὁ δὲ ἐπὶ τὸν Φίλιππον ἀμύνειν Ἀθηναίοις ὁ Ὀτίλιος ἀπέσταλτο ἐκ Ῥώμης.", "st": "10.36"}, {"sp": "N", "t": "τὰ δὲ ὄρη τὰ ὑπὲρ τὴν Ἀντίκυραν πετρώδη τε ἄγαν ἐστὶ καὶ ἐν αὐτοῖς φύεται μάλιστα ὁ ἐλλέβορος. ὁ μὲν αὐτοῦ μέλας χωρεῖ τε ἀνθρώποις καὶ ἔστι γαστρὶ καθάρσιον, ὁ δὲ ἕτερος ⟨ὁ⟩ λευκὸς δι’ ἐμέτου καθαίρειν πέφυκε· τὸ δὲ φάρμακον τὸ ἐς τὴν κάθαρσιν ἡ τοῦ ἐλλεβόρου ῥίζα ἐστίν.", "st": "10.36"}, {"sp": "N", "t": "Ἀντικυρεῦσι δὲ εἰσὶ μὲν ἀνδριάντες ἐν τῇ ἀγορᾷ χαλκοῖ, ἔστι δέ σφισιν ἐπὶ τῷ λιμένι Ποσειδῶνος οὐ μέγα ἱερόν, λογάσιν ᾠκοδομημένον λίθοις· κεκονίαται δὲ τὰ ἐντός. τὸ δὲ ἄγαλμα ὀρθὸν χαλκοῦ πεποιημένον, βέβηκε δὲ ἐπὶ δελφῖνι τῷ ἑτέρῳ τῶν ποδῶν· κατὰ τοῦτο δὲ ἔχει καὶ τὴν χεῖρα ἐπὶ τῷ μηρῷ, ἐν δὲ τῇ ἑτέρᾳ χειρὶ τρίαινά ἐστιν αὐτῷ.", "st": "10.36"}, {"sp": "N", "t": "τοῦ γυμνασίου δὲ ἐν ᾧ καὶ τὰ λουτρά σφισι πεποίηται, τούτου πέραν ἄλλο γυμνάσιόν ἐστιν ἀρχαῖον· ἀνδριὰς δὲ ἕστηκεν ἐν αὐτῷ χαλκοῦς· φησὶ δ’ ἐπ’ αὐτῷ τὸ ἐπίγραμμα Ξενόδαμον παγκρατιαστὴν Ἀντικυρέα ἐν ἀνδράσιν Ὀλυμπικὴν ἀνῃρῆσθαι νίκην. εἰ δὲ ἀληθεύει τὸ ἐπίγραμμα, Ὀλυμπιάδι τῇ πρώτῃ μετὰ δέκα καὶ διακοσίας φαίνοιτο ἂν τὸν κότινον ὁ Ξενόδαμος εἰληφώς· αὕτη δὲ ἐν τοῖς Ἠλείων γράμμασι παρεῖται μόνη πασῶν ἡ Ὀλυμπιάς.", "st": "10.36"}, {"sp": "N", "t": "ἔστι δὲ ὑπὲρ τὴν ἀγορὰν ἐν φρέατι ὕδατος πηγή· σκέπη δὲ ἀπὸ ἡλίου τῷ φρέατι ὄροφός τε καὶ ἀνέχοντες τὸν ὄροφον κίονες. ἔστι δὲ οὐ πολὺ ἀνωτέρω τοῦ φρέατος λίθοις τοῖς ἐπιτυχοῦσιν ᾠκοδομημένον μνῆμα· ταφῆναι δέ φασιν ἐνταῦθα τοὺς Ἰφίτου παῖδας, τὸν μὲν ἀνασωθέντα ἐξ Ἰλίου καὶ ἀποθανόντα ἐν τῇ οἰκείᾳ, Σχεδίῳ δὲ ἐν μὲν γῇ τῇ Τρῳάδι τὴν τελευτὴν συμβῆναι λέγουσιν, ἀχθῆναι δὲ οἴκαδε καὶ τούτου τὰ ὀστᾶ.", "st": "10.36"}, {"sp": "N", "t": "τῆς πόλεως δὲ ἐν δεξιᾷ δύο μάλιστα προελθόντι ἀπ’ αὐτῆς σταδίους, πέτρα τέ ἐστιν ὑψηλὴ—μοῖρα ὄρους ἡ πέτρα—καὶ ἱερὸν ἐπ’ αὐτῆς πεποιημένον ἐστὶν Ἀρτέμιδος· ⟨ἡ Ἄρτεμις⟩ ἔργων τῶν Πραξιτέλους, δᾷδα ἔχουσα τῇ δεξιᾷ καὶ ὑπὲρ τῶν ὤμων φαρέτραν, παρὰ δὲ αὐτὴν κύων ἐν ἀριστερᾷ· μέγεθος δὲ ὑπὲρ τὴν μεγίστην γυναῖκα τὸ ἄγαλμα.", "st": "10.37"}, {"sp": "N", "t": "τῇ δὲ γῇ τῇ Φωκίδι ἐστὶν ὅμορος ἥ ὀνομάζεται μὲν ἀπὸ Βούλωνος ἀγαγόντος τὴν ἀποικίαν ἀνδρός, συνῳκίσθη δὲ ἐκ πόλεων τῶν ἐν τῇ ἀρχαίᾳ Δωρίδι. λέγονται δὲ οἱ Βούλιοι Φιλομήλου καὶ Φωκέων … σύλλογον τὸν κοινόν. ἐς δὲ τὴν Βοῦλιν ἐκ μὲν τῆς Βοιωτίας Θίσβης σταδίων ἐστὶν ὁδὸς ὀγδοήκοντα, ἐξ Ἀντικύρας δὲ τῆς Φωκέων δι’ ἠπείρου μὲν καὶ εἰ ἀρχήν ἐστιν οὐκ οἶδα· οὕτω δύσβατα ὄρη καὶ τραχέα τὰ μεταξὺ Ἀντικύρας τέ ἐστι καὶ Βούλιδος· ἐς δὲ τὸν λιμένα σταδίων ἐξ Ἀντικύρας ἐστὶν ἑκατόν, τὰ δὲ ἀπὸ τοῦ λιμένος στάδια ὁδοῦ τῆς πεζῆς τὰ ἐς Βοῦλιν ἑπτὰ εἶναι μάλιστα εἰκάζομεν.", "st": "10.37"}, {"sp": "N", "t": "κάτεισι δὲ καὶ ποταμὸς ἐς θάλασσαν ταύτῃ χείμαρρος, ὃν οἱ ἐπιχώριοι ὀνομάζουσιν Ἡράκλειον. κεῖται δὲ ἐπὶ ὑψηλοῦ τε ἡ Βοῦλις καὶ ἐν παράπλῳ περαιουμένοις ἐξ Ἀντικύρας ἐς Λέχαιον τὸ Κορινθίων· οἱ δὲ ἄνθρωποι οἱ ἐνταῦθα πλέον ἡμίσεις κόχλων ἐς βαφὴν πορφύρας εἰσὶν ἁλιεῖς. κατασκευὴ δὲ ἡ ἐν τῇ Βούλιδι οὔτε ἡ ἄλλη θαύματος πολλοῦ καὶ ἱερὰ θεῶν ἐστιν Ἀρτέμιδος, τὸ δὲ αὐτῶν Διονύσου· τὰ δὲ ἀγάλματα ξύλου μέν ἐστιν εἰργασμένα, ὅστις δὲ ἦν ὁ ποιήσας οὐχ οἷοί τε ἐγενόμεθα συμβαλέσθαι. θεῶν δὲ ὅντινα οἱ Βούλιοι σέβουσι μάλιστα, Μέγιστον μὲν ὀνομάζουσι, Διὸς δὲ κατὰ ἡμετέραν δόξαν ἐστὶν ἐπίκλησις. καὶ πηγὴ Βουλίοις ἐστὶ καλουμένη Σαύνιον.", "st": "10.37"}, {"sp": "N", "t": "ἐς δὲ Κίρραν τὸ ἐπίνειον Δελφῶν ὁδὸς μὲν σταδίων ἑξήκοντά ἐστιν ἐκ Δελφῶν· καταβάντι δὲ ἐς τὸ πεδίον ἱππόδρομός τέ ἐστι καὶ ἀγῶνα Πύθια ἄγουσιν ἐνταῦθα τὸν ἱππικόν. τὰ μὲν δὴ ἐς τὸν ἐν Ὀλυμπίᾳ Ταράξιππον ἐδήλωσέ μοι τὰ ἐς Ἠλείους τοῦ λόγου, ὁ δὲ ἱππόδρομος ἔοικε τοῦ Ἀπόλλωνος τάχα μέν που καὶ αὐτὸς τῶν ἱππευόντων τινὰ ἀνιᾶσαι, ἅτε ἀνθρώποις τοῦ δαίμονος ὁμοίως ἐπὶ ἔργῳ παντὶ καὶ ἀμείνω καὶ τὰ χείρω νέμοντος· οὐ μέντοι καὶ αὐτὸς ταραχὴν τοῖς ἵπποις ὁ ἱππόδρομος οὔτε κατὰ αἰτίαν ἥρωος οὔτε ἐπ’ ἄλλῃ πέφυκεν ἐργάζεσθαι προφάσει.", "st": "10.37"}, {"sp": "N", "t": "τὸ δὲ πεδίον τὸ ἀπὸ τῆς Κίρρας ψιλόν ἐστιν ἅπαν, καὶ φυτεύειν δένδρα οὐκ ἐθέλουσιν ἢ ἔκ τινος ἀρᾶς ἢ ἀχρεῖον τὴν γῆν ἐς δένδρων τροφὴν εἰδότες. λέγεται δὲ ἐς τὴν Κίρραν … καὶ ἀπὸ τῆς Κίρρας τὸ ὄνομα τὸ ἐφ’ ἡμῶν τεθῆναι τῷ χωρίῳ φασίν. Ὅμηρος μέντοι Κρῖσαν ἔν τε Ἰλιάδι ὁμοίως καὶ ὕμνῳ τῷ ἐς Ἀπόλλωνα ὀνόματι τῷ ἐξ ἀρχῆς καλεῖ τὴν πόλιν. χρόνῳ δὲ ὕστερον οἱ ἐν τῇ Κίρρᾳ ἄλλα τε ἠσέβησαν ἐς τὸν Ἀπόλλωνα καὶ ἀπέτεμνον τοῦ θεοῦ τῆς χώρας.", "st": "10.37"}, {"sp": "N", "t": "πολεμεῖν οὖν πρὸς τοὺς Κιρραίους ἔδοξεν Ἀμφικτύοσι, καὶ Κλεισθένην τε Σικυωνίων τυραννοῦντα προεστήσαντο ἡγεμόνα εἶναι καὶ Σόλωνα ἐξ Ἀθηνῶν ἐπηγάγοντο συμβουλεύειν· χρωμένοις δέ σφισιν ὑπὲρ νίκης ἀνεῖπεν ἡ Πυθία·<br>οὐ πρὶν τῆσδε πόληος ἐρείψετε πύργον ἑλόντες,<br>πρίν κεν ἐμῷ τεμένει κυανώπιδος Ἀμφιτρίτης<br>κῦμα ποτικλύζῃ κελαδοῦν ἐπὶ οἴνοπα πόντον.<br>ἔπεισεν οὖν ὁ Σόλων καθιερῶσαι τῷ θεῷ τὴν Κιρραίαν, ἵνα δὴ τῷ τεμένει τοῦ Ἀπόλλωνος γένηται γείτων ἡ θάλασσα.", "st": "10.37"}, {"sp": "N", "t": "εὑρέθη δὲ καὶ ἕτερον τῷ Σόλωνι σόφισμα ἐς τοὺς Κιρραίους· τοῦ γὰρ Πλείστου τὸ ὕδωρ ῥέον διὰ ὀχετοῦ σφισιν ἐς τὴν πόλιν ἀπέστρεψεν ἀλλαχόσε ὁ Σόλων. καὶ οἱ μὲν πρὸς τοὺς πολιορκοῦντας ἔτι ἀντεῖχον ἔκ τε φρεάτων καὶ ὕδωρ τὸ ἐκ τοῦ θεοῦ πίνοντες· ὁ δὲ τοῦ ἐλλεβόρου τὰς ῥίζας ἐμβαλὼν ἐς τὸν Πλεῖστον, ἐπειδὴ ἱκανῶς τοῦ φαρμάκου τὸ ὕδωρ ᾔσθετο ἔχον, ἀπέστρεψεν αὖθις ἐς τὸν ὀχετόν. καὶ—ἐνεφορήσαντο γὰρ ἀνέδην οἱ Κιρραῖοι τοῦ ὕδατος—[καὶ] οἱ μὲν ὑπὸ ἀπαύστου τῆς διαρροίας ἐξέλιπον οἱ ἐπὶ τοῦ τείχους τὴν φρουράν,", "st": "10.37"}, {"sp": "N", "t": "Ἀμφικτύονες δὲ ὡς εἷλον τὴν πόλιν, ἐπράξαντο ὑπὲρ τοῦ θεοῦ δίκας παρὰ Κιρραίων, καὶ ἐπίνειον Δελφῶν ἐστιν ἡ Κίρρα. παρέχεται δὲ καὶ ἐς θέαν Ἀπόλλωνος καὶ Ἀρτέμιδος καὶ Λητοῦς ναόν τε καὶ ἀγάλματα μεγέθει μεγάλα καὶ ἐργασίας Ἀττικῆς. ἡ δὲ Ἀδράστεια ἵδρυται μὲν ἐν τῷ αὐτῷ σφίσι, μεγέθει δὲ τῶν ἄλλων ἀποδέουσα ἀγαλμάτων ἐστίν.", "st": "10.37"}, {"sp": "N", "t": "ἡ δὲ γῆ ἡ Λοκρῶν τῶν καλουμένων Ὀζολῶν προσεχὴς τῇ Φωκίδι ἐστὶ κατὰ τὴν Κίρραν. ἐς δὲ τὴν ἐπίκλησιν τῶν Λοκρῶν τούτων διάφορα ἤκουσα, ὁμοίως δὲ ἅπαντα δηλώσω. Ὀρεσθεῖ τῷ Δευκαλίωνος βασιλεύοντι ἐν τῇ χώρᾳ κύων ἔτεκεν ἀντὶ σκύλακος ξύλον· κατορύξαντος δὲ τοῦ Ὀρεσθέως τὸ ξύλον ἅμα τῷ ἦρι φῦναι ἄμπελον ἀπ’ αὐτοῦ λέγουσι καὶ ἀπὸ τοῦ ξύλου τῶν ὄζων γενέσθαι τὸ ὄνομα τοῖς ἀνθρώποις.", "st": "10.38"}, {"sp": "N", "t": "οἱ δὲ Νέσσον πορθμεύοντα ἐπὶ τῷ Εὐήνῳ τρωθῆναι μὲν ὑπὸ Ἡρακλέους, οὐ μέντοι καὶ αὐτίκα γε ἀποθανεῖν ἀλλὰ ἐς τὴν γῆν ταύτην ἐκφυγεῖν νομίζουσι, καὶ ὡς ἀπέθανε σήπεσθαί τε ἄταφον καὶ ὀσμῆς τῷ ἐνταῦθα ἀέρι μεταδοῦναι δυσώδους. ὁ δὲ τρίτος τῶν λόγων καὶ ὁ τέταρτος, ὁ μὲν ποταμοῦ τινος ἄτοπον τήν τε ἀτμίδα καὶ αὐτό φησιν εἶναι τὸ ὕδωρ, ὁ δὲ τὸν ἀσφόδελον φύεσθαι πολὺν καὶ ἀνθοῦντα … ὑπὸ τῆς ὀσμῆς.", "st": "10.38"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὡς οἱ πρῶτοι τῶν ἐνταῦθα ἀνθρώπων ἦσαν αὐτόχθονες, ἐσθῆτα δὲ οὐκ ἐπιστάμενοί πω ὑφαίνεσθαι σκέπην πρὸς τὸ ῥῖγος θηρίων δέρματα ἐποιοῦντο ἀδέψητα, τὸ δασὺ τῶν δερμάτων ἐς τὸ ἐκτὸς ὑπὲρ εὐπρεπείας τρέποντες· ἔμελλεν οὖν κατὰ τὸ αὐτὸ ταῖς βύρσαις καὶ ὁ χρώς σφισιν ἔσεσθαι δυσώδης.", "st": "10.38"}, {"sp": "N", "t": "Δελφῶν δὲ ἀπωτέρω σταδίοις εἴκοσί τε καὶ ἑκατόν ἐστιν Ἄμφισσα μεγίστη καὶ ὀνομαστοτάτη πόλις τῶν Λοκρῶν. ἐσποιοῦσι δὲ αὑτοὺς ἐς τὸ Αἰτωλικὸν αἰσχύνῃ τῶν Ὀζολῶν τοῦ ὀνόματος· καὶ δὴ καὶ ἔχει λόγον εἰκότα, ὅτε βασιλεὺς ὁ Ῥωμαίων ἀναστάτους ἐς τὸν Νικοπόλεως συνοικισμὸν ἐποίησεν Αἰτωλούς, ἀποχωρῆσαι τοῦ δήμου τὸ πολὺ ἐς τὴν Ἄμφισσαν. τὸ μέντοι ἐξ ἀρχῆς γένους τοῦ Λοκρῶν εἰσι· τεθῆναι δὲ τῇ πόλει τὸ ὄνομα ἀπὸ Ἀμφίσσης τῆς Μάκαρος τοῦ Αἰόλου φασὶ καὶ Ἀπόλλωνα ἐραστὴν γενέσθαι τῆς Ἀμφίσσης.", "st": "10.38"}, {"sp": "N", "t": "κεκόσμηται δὲ ἡ πόλις κατασκευῇ τε τῇ ἄλλῃ καὶ τὰ μάλιστα ἥκοντα ἐς μνήμην ἔστι μὲν μνῆμα Ἀμφίσσης, ἔστι δὲ Ἀνδραίμονος· σὺν δὲ αὐτῷ ταφῆναι λέγουσι καὶ Γόργην τὴν Οἰνέως συνοικήσασαν τῷ Ἀνδραίμονι. ἐν δὲ τῇ ἀκροπόλει ναός σφισιν Ἀθηνᾶς καὶ ἄγαλμα ὀρθὸν χαλκοῦ πεποιημένον, κομισθῆναι δὲ ὑπὸ Θόαντός φασιν αὐτὴν ἐξ Ἰλίου καὶ εἶναι λαφύρων τῶν ἐκ Τροίας·", "st": "10.38"}, {"sp": "N", "t": "οὐ μὴν καὶ ἐμέ γε ἔπειθον. ἐδήλωσα δὲ ἐν τοῖς προτέροις τοῦ λόγου Σαμίους Ῥοῖκον Φιλαίου καὶ Θεόδωρον Τηλεκλέους εἶναι τοὺς εὑρόντας χαλκὸν ἐς τὸ ἀκριβέστατον τῆξαι· καὶ ἐχώνευσαν οὗτοι πρῶτοι. Θεοδώρου μὲν δὴ οὐδὲν ἔτι οἶδα ἐξευρών, ὅσα γε χαλκοῦ πεποιημένα· ἐν δὲ Ἀρτέμιδος τῆς Ἐφεσίας πρὸς τὸ οἴκημα ἐρχομένῳ τὸ ἔχον τὰς γραφὰς λίθου θριγκός ἐστιν ὑπὲρ τοῦ βωμοῦ τῆς Πρωτοθρονίης καλουμένης Ἀρτέμιδος· ἀγάλματα δὲ ἄλλα τε ἐπὶ τοῦ θριγκοῦ καὶ γυναικὸς εἰκὼν πρὸς τῷ πέρατι ἕστηκε, τέχνη τοῦ Ῥοίκου, Νύκτα δὲ οἱ Ἐφέσιοι καλοῦσι.", "st": "10.38"}, {"sp": "N", "t": "τοῦτο οὖν τὸ ἄγαλμα τῆς ἐν τῇ Ἀμφίσσῃ Ἀθηνᾶς καὶ ἰδεῖν ἔστιν ἀρχαιότερον καὶ ἀργότερον τὴν τέχνην. ἄγουσι δὲ καὶ τελετὴν οἱ Ἀμφισσεῖς Ἀνάκτων καλουμένων παίδων· οἵτινες δὲ θεῶν εἰσιν οἱ Ἄνακτες παῖδες, οὐ κατὰ ταὐτά ἐστιν εἰρημένον, ἀλλ’ οἱ μὲν εἶναι Διοσκούρους, οἱ δὲ Κούρητας, οἱ δὲ πλέον τι ἐπίστασθαι νομίζοντες Καβείρους λέγουσι.", "st": "10.38"}, {"sp": "N", "t": "τούτων δὲ τῶν Λοκρῶν τοσαίδε ἄλλαι πόλεις εἰσίν· ἄνω μὲν ὑπὲρ Ἀμφίσσης πρὸς ἤπειρον Μυονία σταδίοις ἀπωτέρω τριάκοντα Ἀμφίσσης· οὗτοι καὶ τῷ Διὶ ἐν Ὀλυμπίᾳ εἰσὶν οἱ ἀναθέντες Μυᾶνες τὴν ἀσπίδα. κεῖται δὲ τὸ πόλισμα ἐπὶ ὑψηλοῦ, καί σφισιν ἄλσος καὶ βωμὸς θεῶν Μειλιχίων ἐστί· νυκτεριναὶ δὲ αἱ θυσίαι θεοῖς τοῖς Μειλιχίοις εἰσὶ καὶ ἀναλῶσαι τὰ κρέα αὐτόθι πρὶν ἢ ἥλιον ἐπισχεῖν νομίζουσι. καὶ Ποσειδῶνός ἐστιν ὑπὲρ τὴν πόλιν τέμενος καλούμενον Ποσειδώνιον, ἐν δὲ αὐτῷ ναὸς Ποσειδῶνος· τὸ δὲ ἄγαλμα ἐς ἐμὲ οὐκ ἦν.", "st": "10.38"}, {"sp": "N", "t": "οὗτοι μὲν δὴ ὑπεροικοῦσιν Ἀμφίσσης· ἐπὶ θαλάσσης δὲ Οἰάνθεια καὶ ταύτῃ ὁμοροῦσά ἐστι Ναύπακτος. πλὴν δὲ Ἀμφίσσης ὑπ’ Ἀχαιῶν οἱ ἄλλοι Πατρέων ἄρχονται, βασιλέως σφίσι δόντος Αὐγούστου. ἐν Οἰανθείᾳ δὲ Ἀφροδίτης τε ἱερὸν καὶ ὀλίγον ὑπὲρ τὴν πόλιν κυπαρίσσου τε ἀναμὶξ καὶ τῆς πίτυός ἐστιν ἄλσος καὶ ναός τε Ἀρτέμιδος καὶ ἄγαλμα ἐν τῷ ἄλσει· γραφαὶ δὲ ἐπὶ τῶν τοίχων ἐξίτηλοί τε ἦσαν ὑπὸ τοῦ χρόνου καὶ οὐδὲν ἔτι ἐλείπετο ἐς θέαν αὐτῶν.", "st": "10.38"}, {"sp": "N", "t": "κληθῆναι δὲ ἀπὸ γυναικὸς ἢ νύμφης τεκμαίρομαι τὴν πόλιν, ἐπεὶ ἐπὶ Ναυπάκτῳ γε οἶδα εἰρημένον ὡς Δωριεῖς οἱ ὁμοῦ τοῖς Ἀριστομάχου παισὶ τὰ πλοῖα αὐτόθι ἐποιήσαντο, οἷς ἐς Πελοπόννησον ἐπεραιώθησαν· καὶ ἀντὶ τούτου γενέσθαι τὸ ὄνομα τῷ χωρίῳ φασί. τὰ δέ μοι Ναυπακτίων, ὡς τοῖς ἐς Ἰθώμην ἀποστᾶσιν ὁμοῦ τῷ σεισμῷ τῷ ἐν Λακεδαίμονι Ἀθηναῖοι Ναύπακτον ἐνοικῆσαί σφισιν ἔδοσαν ἀφελόμενοι τοὺς Λοκροὺς καὶ ὡς τοῦ Ἀθηναίων ὕστερον πταίσματος τοῦ ἐν Αἰγὸς ποταμοῖς Λακεδαιμόνιοι τοὺς Μεσσηνίους ἐδίωξαν καὶ ἐκ τῆς Ναυπάκτου, τάδε μὲν ἐπεξῆλθέ μοι καὶ ἐς πλέον ἡ Μεσσηνία συγγραφή· ἐκλιπόντων δὲ ὑπὸ ἀνάγκης τῶν Μεσσηνίων, οὕτως οἱ Λοκροὶ συνελέγχθησαν αὖθις ἐς τὴν Ναύπακτον.", "st": "10.38"}, {"sp": "N", "t": "τὰ δὲ ἔπη τὰ Ναυπάκτια ὀνομαζόμενα ὑπὸ Ἑλλήνων ἀνδρὶ ἐσποιοῦσιν οἱ πολλοὶ Μιλησίῳ· Χάρων δὲ ὁ Πύθεώ φησιν αὐτὰ ποιῆσαι Ναυπάκτιον Καρκίνον. ἑπόμεθα δὲ καὶ ἡμεῖς τῇ τοῦ Λαμψακηνοῦ δόξῃ· τίνα γὰρ καὶ λόγον ἔχοι ἂν ἔπεσιν ἀνδρὸς Μιλησίου πεποιημένοις ἐς γυναῖκας τεθῆναί σφισιν ὄνομα Ναυπάκτια;", "st": "10.38"}, {"sp": "N", "t": "ἐνταῦθα ἔστι μὲν ἐπὶ θαλάσσῃ ναὸς Ποσειδῶνος καὶ ἄγαλμα ὀρθὸν χαλκοῦ πεποιημένον, ἔστι δὲ καὶ ἱερὸν Ἀρτέμιδος καὶ ἄγαλμα λευκοῦ λίθου· σχῆμα δὲ ἀκοντιζούσης παρέχεται καὶ ἐπίκλησιν εἴληφεν Αἰτωλή. Ἀφροδίτη δὲ ἔχει μὲν ἐν σπηλαίῳ τιμάς· εὔχονται δὲ καὶ ἄλλων εἵνεκα καὶ αἱ γυναῖκες μάλιστα αἱ χῆραι γάμον αἰτοῦσι παρὰ τῆς θεοῦ.", "st": "10.38"}, {"sp": "N", "t": "τοῦ δὲ Ἀσκληπιοῦ τὸ ἱερὸν ἐρείπια ἦν, ἐξ ἀρχῆς δὲ ᾠκοδόμησεν αὐτὸ ἀνὴρ ἰδιώτης Φαλύσιος. νοσήσαντι γάρ οἱ τοὺς ὀφθαλμοὺς καὶ οὐ πολὺ ἀποδέον τυφλῷ ὁ ἐν Ἐπιδαύρῳ πέμπει θεὸς Ἀνύτην τὴν ποιήσασαν τὰ ἔπη φέρουσαν σεσημασμένην δέλτον. τοῦτο ἐφάνη τῇ γυναικὶ ὄψις ὀνείρατος, ὕπαρ μέντοι ἦν αὐτίκα· καὶ εὗρέ τε ἐν ταῖς χερσὶ ταῖς αὑτῆς σεσημασμένην δέλτον καὶ πλεύσασα ἐς τὴν Ναύπακτον ἐκέλευσεν ἀφελόντα τὴν σφραγῖδα Φαλύσιον ἐπιλέγεσθαι τὰ γεγραμμένα. τῷ δὲ ἄλλως μὲν οὐ δυνατὰ ἐφαίνετο ἰδεῖν τὰ γράμματα ἔχοντι οὕτω τῶν ὀφθαλμῶν· ἐλπίζων δέ τι ἐκ τοῦ Ἀσκληπιοῦ χρηστὸν ἀφαιρεῖ τὴν σφραγῖδα, καὶ ἰδὼν ἐς τὸν κηρὸν ὑγιής τε ἦν καὶ δίδωσι τῇ Ἀνύτῃ τὸ ἐν τῇ δέλτῳ γεγραμμένον, στατῆρας δισχιλίους χρυσοῦ.", "st": "10.38"}], []);})();
